--
-- Name: assert_customer_sellable_oms_order_line(); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.assert_customer_sellable_oms_order_line() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  order_status varchar(30);
  eligibility varchar(20);
BEGIN
  IF NEW.product_variant_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT o.status
    INTO order_status
  FROM oms.oms_orders AS o
  WHERE o.id = NEW.order_id
  FOR SHARE;

  IF order_status IN ('shipped', 'delivered', 'cancelled', 'refunded') THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(918424, NEW.product_variant_id);
  SELECT pv.sales_eligibility
    INTO eligibility
  FROM catalog.product_variants AS pv
  WHERE pv.id = NEW.product_variant_id;

  IF eligibility IS DISTINCT FROM 'sellable' THEN
    RAISE EXCEPTION 'Catalog variant % is not customer-sellable and cannot be inserted on an open OMS order', NEW.product_variant_id
      USING ERRCODE = '23514',
            CONSTRAINT = 'customer_sellable_order_line_required';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: assert_customer_sellable_oms_order_reopen(); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.assert_customer_sellable_oms_order_reopen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  internal_variant_id integer;
BEGIN
  IF NEW.status IN ('shipped', 'delivered', 'cancelled', 'refunded')
     OR NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(918424, variants.product_variant_id)
  FROM (
    SELECT DISTINCT ol.product_variant_id
    FROM oms.oms_order_lines AS ol
    WHERE ol.order_id = NEW.id
      AND ol.product_variant_id IS NOT NULL
    ORDER BY ol.product_variant_id
  ) AS variants;

  SELECT ol.product_variant_id
    INTO internal_variant_id
  FROM oms.oms_order_lines AS ol
  JOIN catalog.product_variants AS pv ON pv.id = ol.product_variant_id
  WHERE ol.order_id = NEW.id
    AND pv.sales_eligibility <> 'sellable'
  ORDER BY ol.product_variant_id
  LIMIT 1;

  IF internal_variant_id IS NOT NULL THEN
    RAISE EXCEPTION 'Catalog variant % is not customer-sellable and prevents OMS order % from reopening', internal_variant_id, NEW.id
      USING ERRCODE = '23514',
            CONSTRAINT = 'customer_sellable_order_line_required';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: assert_customer_sellable_variant(); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.assert_customer_sellable_variant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  variant_id integer;
  eligibility varchar(20);
BEGIN
  variant_id := NEW.product_variant_id;
  IF variant_id IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(918424, variant_id);
  SELECT pv.sales_eligibility
    INTO eligibility
  FROM catalog.product_variants AS pv
  WHERE pv.id = variant_id;

  IF eligibility IS DISTINCT FROM 'sellable' THEN
    RAISE EXCEPTION 'Catalog variant % is not customer-sellable and cannot be used by a customer-facing writer', variant_id
      USING ERRCODE = '23514',
            CONSTRAINT = 'customer_sellable_variant_required';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: assert_inventory_tracking_projection(); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.assert_inventory_tracking_projection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE family_id integer;
BEGIN
  IF TG_TABLE_NAME = 'products' THEN
    IF TG_OP = 'UPDATE' AND OLD.inventory_tracking_default IS NOT DISTINCT FROM NEW.inventory_tracking_default THEN RETURN NULL; END IF;
    family_id := NEW.id;
  ELSE
    IF TG_OP = 'UPDATE' AND ROW(OLD.product_id, OLD.requires_shipping, OLD.track_inventory, OLD.inventory_tracking_override)
      IS NOT DISTINCT FROM ROW(NEW.product_id, NEW.requires_shipping, NEW.track_inventory, NEW.inventory_tracking_override) THEN RETURN NULL; END IF;
    family_id := NEW.product_id;
  END IF;
  PERFORM id FROM catalog.products WHERE id = family_id FOR SHARE;
  IF EXISTS (
    SELECT 1 FROM catalog.product_variants variant JOIN catalog.products product ON product.id = variant.product_id
    WHERE product.id = family_id AND COALESCE(variant.track_inventory, true)
      IS DISTINCT FROM (variant.requires_shipping AND COALESCE(variant.inventory_tracking_override, product.inventory_tracking_default))
  ) THEN
    RAISE EXCEPTION 'INVENTORY_POLICY_PROJECTION_CONFLICT: product %', family_id USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: enqueue_variant_pack_metafields(text); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.enqueue_variant_pack_metafields(target_shopify_variant_id text) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  variant_gid TEXT;
  owner_found BOOLEAN := FALSE;
  owner_uom_type TEXT;
  owner_units INTEGER;
  pack_label TEXT;
  units_value JSONB;
  label_value JSONB;
BEGIN
  IF target_shopify_variant_id IS NULL OR target_shopify_variant_id !~ '^[0-9]+$' THEN
    RETURN 0;
  END IF;

  -- Only the shared production database has the club app's outbox.
  IF to_regclass('membership.shopify_metafield_outbox') IS NULL THEN
    RETURN 0;
  END IF;

  variant_gid := 'gid://shopify/ProductVariant/' || target_shopify_variant_id;

  -- Shopify already said this variant is gone; the worker would only be told
  -- again. Nested so the table is not read where it does not exist.
  IF to_regclass('membership.shopify_dead_owners') IS NOT NULL THEN
    IF EXISTS (
      SELECT 1
      FROM membership.shopify_dead_owners AS dead_owner
      WHERE dead_owner.target_type = 'productvariant'
        AND dead_owner.target_id = variant_gid
        AND dead_owner.cleared_at IS NULL
    ) THEN
      RETURN 0;
    END IF;
  END IF;

  -- One Shopify variant can be linked from more than one catalog row (a
  -- retired duplicate). The active row speaks for it, then the oldest.
  SELECT TRUE, variant_row.uom_type, variant_row.units_per_variant
  INTO owner_found, owner_uom_type, owner_units
  FROM catalog.product_variants AS variant_row
  WHERE variant_row.shopify_variant_id = target_shopify_variant_id
  ORDER BY (variant_row.is_active IS TRUE) DESC, variant_row.id ASC
  LIMIT 1;

  IF owner_found THEN
    -- Labels from shared/catalog/variant-uom.ts, with "Box / Inner Pack"
    -- shortened to "Box" so the card reads "Box of 500".
    pack_label := CASE owner_uom_type
      WHEN 'piece' THEN 'Piece'
      WHEN 'each' THEN 'Each'
      WHEN 'pack' THEN 'Pack'
      WHEN 'inner_pack' THEN 'Box'
      WHEN 'case' THEN 'Case'
      WHEN 'skid' THEN 'Skid'
    END;
    IF owner_units IS NOT NULL AND owner_units > 0 THEN
      units_value := to_jsonb(owner_units);
    END IF;
    IF pack_label IS NOT NULL THEN
      label_value := to_jsonb(pack_label);
    END IF;
  END IF;

  -- No catalog row links this Shopify variant any more: its values are no
  -- longer known, so both metafields are removed rather than left stale.
  INSERT INTO membership.shopify_metafield_outbox
    (target_type, target_id, namespace, key, value, operation, dedupe_key, scheduled_for)
  VALUES
    ('productvariant', variant_gid, 'cardshellz', 'units_per_variant',
     units_value, CASE WHEN units_value IS NULL THEN 'delete' ELSE 'set' END,
     'productvariant:' || variant_gid || ':cardshellz:units_per_variant', now()),
    ('productvariant', variant_gid, 'cardshellz', 'pack_type',
     label_value, CASE WHEN label_value IS NULL THEN 'delete' ELSE 'set' END,
     'productvariant:' || variant_gid || ':cardshellz:pack_type', now())
  ON CONFLICT (dedupe_key) WHERE status = 'pending'
  DO UPDATE SET
    value = EXCLUDED.value,
    operation = EXCLUDED.operation,
    scheduled_for = EXCLUDED.scheduled_for,
    attempts = 0,
    last_error = NULL;

  RETURN 2;
END;
$_$;


--
-- Name: FUNCTION enqueue_variant_pack_metafields(target_shopify_variant_id text); Type: COMMENT; Schema: catalog; Owner: -
--

COMMENT ON FUNCTION catalog.enqueue_variant_pack_metafields(target_shopify_variant_id text) IS 'Queues cardshellz.units_per_variant and cardshellz.pack_type for one Shopify variant id into membership.shopify_metafield_outbox. Returns the number of rows queued (0 when skipped).';


