--
-- Name: guard_forecast_identity_registration(); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.guard_forecast_identity_registration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE original jsonb;
BEGIN
  SELECT to_jsonb(p) INTO original FROM catalog.products p WHERE p.id=NEW.product_id FOR KEY SHARE;
  IF original IS NULL OR original IS DISTINCT FROM NEW.catalog_snapshot THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='FORECAST_IDENTITY_REQUIRES_EXACT_CURRENT_PRODUCT';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_internal_only_variant_transition(); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.guard_internal_only_variant_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.sales_eligibility IS NOT DISTINCT FROM OLD.sales_eligibility
     OR NEW.sales_eligibility <> 'internal_only' THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(918424, NEW.id);

  IF NEW.shopify_variant_id IS NOT NULL OR NEW.shopify_inventory_item_id IS NOT NULL THEN
    RAISE EXCEPTION 'Variant % still has a Shopify mapping', NEW.id
      USING ERRCODE = '23514', CONSTRAINT = 'internal_only_variant_has_customer_exposure';
  END IF;
  IF COALESCE(NEW.dropship_eligible, false) THEN
    RAISE EXCEPTION 'Variant % is still enabled for dropship', NEW.id
      USING ERRCODE = '23514', CONSTRAINT = 'internal_only_variant_has_customer_exposure';
  END IF;
  IF EXISTS (
    SELECT 1 FROM channels.channel_feeds f
    WHERE f.product_variant_id = NEW.id AND f.is_active = 1
  ) OR EXISTS (
    SELECT 1 FROM channels.channel_listings l
    WHERE l.product_variant_id = NEW.id
  ) OR EXISTS (
    SELECT 1 FROM channels.channel_reservations r
    WHERE r.product_variant_id = NEW.id
  ) OR EXISTS (
    SELECT 1 FROM channels.channel_variant_overrides o
    WHERE o.product_variant_id = NEW.id AND o.is_listed <> 0
  ) OR EXISTS (
    SELECT 1 FROM channels.channel_allocation_rules r
    WHERE r.product_variant_id = NEW.id
  ) OR EXISTS (
    SELECT 1 FROM channels.channel_variant_availability_sync a
    WHERE a.product_variant_id = NEW.id AND a.desired_active = true
  ) OR EXISTS (
    SELECT 1 FROM dropship.dropship_vendor_listings l
    WHERE l.product_variant_id = NEW.id
  ) OR EXISTS (
    SELECT 1 FROM dropship.dropship_vendor_variant_overrides o
    WHERE o.product_variant_id = NEW.id
  ) OR EXISTS (
    SELECT 1
    FROM marketplace.listing_publication_members m
    JOIN marketplace.listing_publications p ON p.id = m.publication_id
    WHERE m.product_variant_id = NEW.id
      AND m.disposition = 'included'
      AND p.status IN ('planned', 'staged', 'active')
  ) OR EXISTS (
    SELECT 1 FROM inventory.inventory_publication_outbox o
    WHERE o.product_variant_id = NEW.id
      AND o.state NOT IN ('verified', 'dead_letter', 'superseded', 'cancelled')
  ) OR EXISTS (
    SELECT 1
    FROM wms.order_items oi
    JOIN wms.orders o ON o.id = oi.order_id
    WHERE oi.sku = NEW.sku
      AND o.warehouse_status NOT IN ('shipped', 'completed', 'cancelled', 'voided')
      AND oi.status <> 'cancelled'
      AND oi.fulfilled_quantity < oi.quantity
  ) OR EXISTS (
    SELECT 1
    FROM oms.oms_order_lines ol
    JOIN oms.oms_orders o ON o.id = ol.order_id
    WHERE ol.product_variant_id = NEW.id
      AND o.status NOT IN ('shipped', 'delivered', 'cancelled', 'refunded')
  ) THEN
    RAISE EXCEPTION 'Variant % still has customer-facing channel, listing, allocation, or publication dependencies', NEW.id
      USING ERRCODE = '23514', CONSTRAINT = 'internal_only_variant_has_customer_exposure';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_product_cleanup_receipt(); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.guard_product_cleanup_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE original jsonb; permitted boolean;
BEGIN
  -- Administrative CLI only. A general app role cannot manufacture a receipt
  -- merely by acquiring INSERT via default privileges. The DB owner remains a
  -- trusted administrator, as it already can ALTER/DROP all database guards.
  IF current_user <> (SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid=TG_RELID)
     OR NEW.database_actor IS DISTINCT FROM current_user
     OR NEW.owner_transaction_id IS DISTINCT FROM pg_current_xact_id()::text
     OR current_setting('transaction_isolation') <> 'serializable'
     OR current_setting('transaction_read_only') <> 'off' THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='CATALOG_CLEANUP_ADMIN_TRANSACTION_REQUIRED';
  END IF;
  -- Lock all grant sources used for this decision, so account deactivation or
  -- a permission revocation cannot race a successful commit. No legacy role-name bypass.
  SELECT true INTO permitted FROM identity.users u
    JOIN identity.auth_user_roles ur ON ur.user_id=u.id
    JOIN identity.auth_roles r ON r.id=ur.role_id
    JOIN identity.auth_role_permissions rp ON rp.role_id=r.id
    JOIN identity.auth_permissions p ON p.id=rp.permission_id
    WHERE u.id=NEW.actor_id AND u.active=1 AND p.resource='inventory' AND p.action='delete'
      AND (rp.constraints IS NULL OR rp.constraints='{}'::jsonb)
    LIMIT 1 FOR SHARE OF u,ur,r,rp,p;
  IF permitted IS DISTINCT FROM true THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='CATALOG_CLEANUP_INVENTORY_DELETE_PERMISSION_REQUIRED';
  END IF;
  SELECT to_jsonb(p) INTO original FROM catalog.products p WHERE p.id=NEW.source_product_id FOR UPDATE;
  IF original IS NULL OR original IS DISTINCT FROM NEW.before_state->'sourceProduct' THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='CATALOG_CLEANUP_SOURCE_CHANGED';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.audit_events a WHERE a.id=NEW.audit_event_id
    AND a.actor=NEW.actor_id AND a.action='catalog.product_identity_removed'
    AND a.target='product:'||NEW.source_product_id::text
    AND a.timestamp=NEW.occurred_at AND a.context->>'requestHash'=NEW.request_hash) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='CATALOG_CLEANUP_AUDIT_REQUIRED';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_product_history_removal(); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.guard_product_history_removal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP='TRUNCATE' THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='CATALOG_PRODUCT_HISTORY_TRUNCATE_FORBIDDEN';
  END IF;
  IF EXISTS (SELECT 1 FROM catalog.forecast_product_identities WHERE product_id=OLD.id)
    AND NOT EXISTS (SELECT 1 FROM catalog.product_cleanup_receipts r
      WHERE r.source_product_id=OLD.id AND r.owner_transaction_id=pg_current_xact_id()::text
        AND r.before_state->'sourceProduct'=to_jsonb(OLD)) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='CATALOG_PRODUCT_REQUIRES_CLEANUP_RECEIPT';
  END IF;
  RETURN OLD;
END $$;


