--
-- Name: guard_tracking_stop_order_policy(); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.guard_tracking_stop_order_policy() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE variant_key integer; variant_row record;
BEGIN
  IF NEW.inventory_tracking IS FALSE THEN RETURN NEW; END IF;
  variant_key := (to_jsonb(NEW)->>TG_ARGV[0])::integer;
  FOR variant_row IN SELECT v.id,v.track_inventory FROM catalog.product_variants v
    WHERE v.id=variant_key OR (variant_key IS NULL AND v.sku=NEW.sku)
    ORDER BY v.id FOR SHARE
  LOOP
    IF variant_row.track_inventory IS FALSE AND EXISTS (
      SELECT 1 FROM inventory.tracking_stop_history WHERE product_variant_id=variant_row.id
    ) THEN
      RAISE EXCEPTION 'INVENTORY_TRACKING_STOPPED: resolve current order policy for variant %', variant_row.id USING ERRCODE='23514';
    END IF;
  END LOOP;
  RETURN NEW;
END $$;


--
-- Name: product_variants_enqueue_pack_metafields(); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.product_variants_enqueue_pack_metafields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM catalog.enqueue_variant_pack_metafields(OLD.shopify_variant_id);
    RETURN OLD;
  END IF;

  PERFORM catalog.enqueue_variant_pack_metafields(NEW.shopify_variant_id);

  -- A variant moved to another Shopify variant: the old one is recomputed too
  -- (another catalog row may still link it, or it loses both values).
  IF TG_OP = 'UPDATE' AND OLD.shopify_variant_id IS DISTINCT FROM NEW.shopify_variant_id THEN
    PERFORM catalog.enqueue_variant_pack_metafields(OLD.shopify_variant_id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: publication_image_mime(bytea); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.publication_image_mime(data bytea) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT CASE
    WHEN substring(data FROM 1 FOR 3) = decode('ffd8ff','hex') THEN 'image/jpeg'
    WHEN substring(data FROM 1 FOR 8) = decode('89504e470d0a1a0a','hex') THEN 'image/png'
    WHEN substring(data FROM 1 FOR 6) IN (decode('474946383761','hex'),decode('474946383961','hex')) THEN 'image/gif'
    WHEN substring(data FROM 1 FOR 4) = decode('52494646','hex')
      AND substring(data FROM 9 FOR 4) = decode('57454250','hex') THEN 'image/webp'
  END
$$;


--
-- Name: reject_publication_image_version_mutation(); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.reject_publication_image_version_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Published image versions are immutable and retained'
    USING ERRCODE='23514', CONSTRAINT='publication_image_versions_immutable';
END
$$;


--
-- Name: require_completed_product_cleanup(); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.require_completed_product_cleanup() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF EXISTS(SELECT 1 FROM catalog.products WHERE id=NEW.source_product_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='CATALOG_CLEANUP_NOT_COMPLETED';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: require_tracked_inventory_identity(); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.require_tracked_inventory_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE variant_id integer; tracked boolean;
BEGIN
  variant_id := (to_jsonb(NEW) ->> TG_ARGV[0])::integer;
  SELECT requires_shipping AND COALESCE(track_inventory, true) INTO tracked
    FROM catalog.product_variants WHERE id = variant_id FOR SHARE;
  IF tracked IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'INVENTORY_POLICY_NOT_TRACKED: variant %', variant_id USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: retain_product_asset_version(); Type: FUNCTION; Schema: catalog; Owner: -
--

CREATE FUNCTION catalog.retain_product_asset_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE asset catalog.product_assets;
BEGIN
  -- Capture the departing version as well: this also protects the first write
  -- to a pre-migration asset, in the same transaction as its source mutation.
  IF TG_OP IN ('UPDATE','DELETE') THEN
    asset := OLD;
    IF asset.asset_type='image' AND asset.storage_type IN ('file','both')
      AND octet_length(asset.file_data) BETWEEN 1 AND 10485760
      AND asset.mime_type = catalog.publication_image_mime(asset.file_data) THEN
      INSERT INTO catalog.product_asset_versions(asset_id,content_hash,file_data,mime_type)
      VALUES (asset.id,encode(sha256(asset.file_data),'hex'),asset.file_data,asset.mime_type)
      ON CONFLICT (asset_id,content_hash) DO NOTHING;
    END IF;
  END IF;
  IF TG_OP IN ('INSERT','UPDATE') THEN
    asset := NEW;
    IF asset.asset_type='image' AND asset.storage_type IN ('file','both')
      AND octet_length(asset.file_data) BETWEEN 1 AND 10485760
      AND asset.mime_type = catalog.publication_image_mime(asset.file_data) THEN
      INSERT INTO catalog.product_asset_versions(asset_id,content_hash,file_data,mime_type)
      VALUES (asset.id,encode(sha256(asset.file_data),'hex'),asset.file_data,asset.mime_type)
      ON CONFLICT (asset_id,content_hash) DO NOTHING;
    END IF;
  END IF;
  RETURN COALESCE(NEW,OLD);
END
$$;


--
-- Name: check_ebay_listing_mapping_repair_complete(); Type: FUNCTION; Schema: channels; Owner: -
--

CREATE FUNCTION channels.check_ebay_listing_mapping_repair_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF NEW.owner_transaction_id IS DISTINCT FROM pg_current_xact_id()
    OR NOT EXISTS(SELECT 1 FROM pg_locks WHERE pid=pg_backend_pid() AND locktype='advisory'
      AND classid=918427 AND objid=hashtext('listing:'||NEW.channel_id::text||':'||NEW.product_id::text)::oid
      AND objsubid=2 AND mode='ExclusiveLock' AND granted)
    OR NOT EXISTS(SELECT 1 FROM channels.ebay_listing_sync_commands command JOIN channels.ebay_listing_sync_jobs job ON job.id=command.job_id
      WHERE command.command_key=NEW.command_key AND command.job_id=NEW.job_id AND command.actor=NEW.actor
        AND job.identity=NEW.queued_identity AND job.channel_id=NEW.channel_id AND job.connection_id=NEW.connection_id
        AND job.product_id=NEW.product_id AND job.operation=NEW.operation)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.after_rows) final_row
      LEFT JOIN channels.channel_listings current_row ON current_row.channel_id=NEW.channel_id
        AND current_row.product_variant_id=(final_row->>'product_variant_id')::integer
      WHERE current_row.product_variant_id IS NULL OR to_jsonb(current_row) IS DISTINCT FROM final_row)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.before_rows) prior
      FULL JOIN jsonb_array_elements(NEW.after_rows) final_row ON prior->>'product_variant_id'=final_row->>'product_variant_id'
      WHERE prior IS NULL OR final_row IS NULL
        OR (prior-'external_sku'-'external_variant_id'-'external_product_id'-'external_url'-'updated_at')
          IS DISTINCT FROM (final_row-'external_sku'-'external_variant_id'-'external_product_id'-'external_url'-'updated_at')) THEN
    RAISE EXCEPTION 'Mapping repair must preserve local work and commit its exact owned follow-up and audit receipt together' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: check_ebay_publication_retry_requeued(); Type: FUNCTION; Schema: channels; Owner: -
--

CREATE FUNCTION channels.check_ebay_publication_retry_requeued() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF NEW.event IN ('publication_retry_authorized','withdrawal_retry_authorized') AND NOT EXISTS(SELECT 1 FROM channels.ebay_listing_sync_jobs job
    WHERE job.id=NEW.job_id AND job.revision=NEW.revision+1 AND job.state='queued' AND job.owner_token IS NULL
      AND job.claimed_revision IS NULL AND job.publication_accepted IS NULL AND job.error_code IS NULL) THEN
    RAISE EXCEPTION 'Listing retry acknowledgement and requeue must commit together' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: enqueue_mapped_variant_availability_sync(); Type: FUNCTION; Schema: channels; Owner: -
--

CREATE FUNCTION channels.enqueue_mapped_variant_availability_sync() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  current_active BOOLEAN;
BEGIN
  SELECT variant_row.is_active
  INTO current_active
  FROM catalog.product_variants AS variant_row
  JOIN channels.channels AS channel_row
    ON channel_row.id = NEW.channel_id
   AND lower(channel_row.provider) = 'ebay'
  WHERE variant_row.id = NEW.product_variant_id;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  -- markVariantAvailabilitySynced may restore a missing listing row inside the
  -- worker transaction. Do not supersede that worker's own matching claim.
  IF EXISTS (
    SELECT 1
    FROM channels.channel_variant_availability_sync AS availability
    WHERE availability.channel_id = NEW.channel_id
      AND availability.product_variant_id = NEW.product_variant_id
      AND availability.desired_active = current_active
      AND availability.status = 'processing'
  ) THEN
    RETURN NEW;
  END IF;

  INSERT INTO channels.channel_variant_availability_sync (
    channel_id,
    product_variant_id,
    desired_active,
    revision,
    status,
    attempt_count,
    next_attempt_at,
    created_at,
    updated_at
  ) VALUES (
    NEW.channel_id,
    NEW.product_variant_id,
    current_active,
    1,
    'pending',
    0,
    transaction_timestamp(),
    transaction_timestamp(),
    transaction_timestamp()
  )
  ON CONFLICT (channel_id, product_variant_id)
  DO UPDATE SET
    desired_active = EXCLUDED.desired_active,
    revision = channels.channel_variant_availability_sync.revision + 1,
    status = 'pending',
    attempt_count = 0,
    next_attempt_at = transaction_timestamp(),
    lease_token = NULL,
    lease_expires_at = NULL,
    completed_at = NULL,
    last_error = NULL,
    updated_at = transaction_timestamp();

  RETURN NEW;
END;
$$;


--
-- Name: enqueue_variant_availability_sync(); Type: FUNCTION; Schema: channels; Owner: -
--

CREATE FUNCTION channels.enqueue_variant_availability_sync() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.is_active IS NOT DISTINCT FROM OLD.is_active THEN
    RETURN NEW;
  END IF;

  INSERT INTO channels.channel_variant_availability_sync (
    channel_id,
    product_variant_id,
    desired_active,
    revision,
    status,
    attempt_count,
    next_attempt_at,
    created_at,
    updated_at
  )
  SELECT
    channel_row.id,
    NEW.id,
    NEW.is_active,
    1,
    'pending',
    0,
    transaction_timestamp(),
    transaction_timestamp(),
    transaction_timestamp()
  FROM channels.channels AS channel_row
  WHERE lower(channel_row.provider) = 'ebay'
    AND (
      EXISTS (
        SELECT 1
        FROM channels.channel_feeds AS feed_row
        WHERE feed_row.channel_id = channel_row.id
          AND feed_row.product_variant_id = NEW.id
      )
      OR EXISTS (
        SELECT 1
        FROM channels.channel_listings AS listing_row
        WHERE listing_row.channel_id = channel_row.id
          AND listing_row.product_variant_id = NEW.id
      )
    )
  ON CONFLICT (channel_id, product_variant_id)
  DO UPDATE SET
    desired_active = EXCLUDED.desired_active,
    revision = channels.channel_variant_availability_sync.revision + 1,
    status = 'pending',
    attempt_count = 0,
    next_attempt_at = transaction_timestamp(),
    lease_token = NULL,
    lease_expires_at = NULL,
    completed_at = NULL,
    last_error = NULL,
    updated_at = transaction_timestamp();

  RETURN NEW;
END;
$$;


--
-- Name: guard_ebay_listing_mapping_command_outcome(); Type: FUNCTION; Schema: channels; Owner: -
--

CREATE FUNCTION channels.guard_ebay_listing_mapping_command_outcome() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF NOT EXISTS(SELECT 1 FROM pg_locks WHERE pid=pg_backend_pid() AND locktype='advisory'
    AND classid=918427 AND objid=hashtext('command:'||NEW.command_key::text)::oid AND objsubid=2 AND mode='ExclusiveLock' AND granted)
    OR (TG_TABLE_NAME IN ('ebay_listing_mapping_repairs','ebay_listing_sync_commands','ebay_listing_sync_admission_failures') AND EXISTS(SELECT 1 FROM channels.ebay_listing_mapping_rejections WHERE command_key=NEW.command_key))
    OR (TG_TABLE_NAME='ebay_listing_mapping_rejections' AND (
      EXISTS(SELECT 1 FROM channels.ebay_listing_sync_commands WHERE command_key=NEW.command_key)
      OR EXISTS(SELECT 1 FROM channels.ebay_listing_sync_admission_failures WHERE command_key=NEW.command_key))) THEN
    RAISE EXCEPTION 'A mapping command must have one exclusively owned immutable result' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_ebay_listing_sync_job(); Type: FUNCTION; Schema: channels; Owner: -
--

CREATE FUNCTION channels.guard_ebay_listing_sync_job() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.verification_intent_hash IS NOT NULL OR NEW.verification_revision IS NOT NULL OR NEW.provider_identity IS NOT NULL OR NEW.publication_target IS NOT NULL OR NEW.publication_accepted IS NOT NULL THEN
      RAISE EXCEPTION 'New listing sync jobs cannot contain a verification checkpoint' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Saved listing sync jobs are retained permanently' USING ERRCODE='23514'; END IF;
  IF (NEW.id,NEW.channel_id,NEW.connection_id,NEW.product_id,NEW.identity,NEW.identity_hash,NEW.operation,NEW.requested_by,NEW.created_at)
    IS DISTINCT FROM (OLD.id,OLD.channel_id,OLD.connection_id,OLD.product_id,OLD.identity,OLD.identity_hash,OLD.operation,OLD.requested_by,OLD.created_at)
    OR OLD.state='completed'
    OR (OLD.state='needs_attention' AND NOT (
      (OLD.operation='publish' AND NEW.state='queued' AND NEW.revision=OLD.revision+1
        AND NEW.publication_accepted IS NULL AND EXISTS(SELECT 1 FROM channels.ebay_listing_sync_events e WHERE e.job_id=OLD.id
          AND e.event='publication_retry_authorized' AND e.revision=OLD.revision AND e.evidence->>'ownerTransactionId'=pg_current_xact_id()::text))
      OR channels.has_owned_ebay_publication_continuation(OLD,NEW)))
    OR NEW.revision NOT IN (OLD.revision,OLD.revision+1) THEN
    RAISE EXCEPTION 'Listing sync identity and terminal jobs are immutable' USING ERRCODE='23514';
  END IF;
  IF (NEW.state,NEW.owner_token,NEW.claimed_revision,NEW.verification_intent_hash,NEW.verification_revision,NEW.provider_identity,NEW.provider_identity_hash,NEW.publication_target,NEW.publication_target_hash,NEW.publication_accepted,NEW.publication_accepted_hash)
    IS DISTINCT FROM (OLD.state,OLD.owner_token,OLD.claimed_revision,OLD.verification_intent_hash,OLD.verification_revision,OLD.provider_identity,OLD.provider_identity_hash,OLD.publication_target,OLD.publication_target_hash,OLD.publication_accepted,OLD.publication_accepted_hash)
    AND NOT EXISTS(SELECT 1 FROM pg_locks WHERE pid=pg_backend_pid() AND locktype='advisory'
      AND classid=918427 AND objid=hashtext(OLD.id::text)::oid AND objsubid=2 AND mode='ExclusiveLock' AND granted) THEN
    RAISE EXCEPTION 'Listing sync transition requires its exact live session owner' USING ERRCODE='23514';
  END IF;
  IF (NEW.verification_intent_hash,NEW.verification_revision) IS DISTINCT FROM (OLD.verification_intent_hash,OLD.verification_revision)
    AND (OLD.state <> 'running' OR NEW.verification_revision IS DISTINCT FROM OLD.claimed_revision
      OR NOT EXISTS(SELECT 1 FROM channels.ebay_listing_sync_events e WHERE e.job_id=OLD.id
        AND e.revision=OLD.claimed_revision AND e.owner_token=OLD.owner_token AND e.event='stage_started'
        AND e.evidence->>'key'='verification' AND e.evidence->>'preparedIntentHash'=NEW.verification_intent_hash)) THEN
    RAISE EXCEPTION 'Verification checkpoint requires its exact owned stage evidence' USING ERRCODE='23514';
  END IF;
  IF (NEW.provider_identity,NEW.provider_identity_hash) IS DISTINCT FROM (OLD.provider_identity,OLD.provider_identity_hash)
    AND (OLD.provider_identity IS NOT NULL OR OLD.state<>'running' OR NEW.provider_identity IS NULL
      OR NEW.owner_token IS DISTINCT FROM OLD.owner_token OR NEW.claimed_revision IS DISTINCT FROM OLD.claimed_revision
      OR NOT EXISTS(SELECT 1 FROM channels.ebay_listing_sync_events e WHERE e.job_id=OLD.id
        AND e.revision=OLD.claimed_revision AND e.owner_token=OLD.owner_token AND e.event='stage_completed'
        AND e.evidence->>'key'='provider_identity' AND e.evidence->>'preparedIntentHash'=NEW.provider_identity_hash
        AND e.evidence->'identity'=NEW.provider_identity
        AND (OLD.operation<>'publish' OR (jsonb_typeof(e.evidence->'observation')='object'
          AND e.evidence->'observation'->>'isPublished'='true')))) THEN
    RAISE EXCEPTION 'Provider identity requires its immutable owned observation receipt' USING ERRCODE='23514';
  END IF;
  IF (NEW.publication_target,NEW.publication_target_hash) IS DISTINCT FROM (OLD.publication_target,OLD.publication_target_hash)
    AND (OLD.operation<>'publish' OR OLD.publication_target IS NOT NULL OR NEW.publication_target IS NULL
      OR NEW.owner_token IS DISTINCT FROM OLD.owner_token OR NEW.claimed_revision IS DISTINCT FROM OLD.claimed_revision
      OR NOT (
        (OLD.state='running' AND EXISTS(SELECT 1 FROM channels.ebay_listing_sync_events e WHERE e.job_id=OLD.id
          AND e.revision=OLD.claimed_revision AND e.owner_token=OLD.owner_token AND e.event='stage_completed'
          AND e.evidence->>'key'='publication_target' AND e.evidence->>'preparedIntentHash'=NEW.publication_target_hash
          AND e.evidence->'identity'=NEW.publication_target))
        OR (OLD.state IN ('queued','recovering','awaiting_evidence') AND OLD.owner_token IS NULL AND OLD.claimed_revision IS NULL
          AND NEW.state=OLD.state AND EXISTS(SELECT 1 FROM channels.ebay_listing_sync_events e
            JOIN channels.ebay_listing_sync_commands c ON c.command_key=(e.evidence->>'commandKey')::uuid AND c.job_id=e.job_id
            WHERE e.job_id=OLD.id AND e.revision=OLD.revision AND e.owner_token IS NULL AND e.event='requested'
              AND e.evidence->>'ownerTransactionId'=pg_current_xact_id()::text
              AND c.actor=e.evidence->>'actor' AND c.identity_hash=e.evidence->>'sourceIdentityHash'
              AND e.evidence->>'targetHash'=NEW.publication_target_hash
              AND e.evidence->'reviewedPublicationTarget'=NEW.publication_target
              AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY['listing:'||OLD.channel_id::text||':'||OLD.product_id::text,
                'enqueue:'||OLD.channel_id::text||':'||OLD.product_id::text,'command:'||c.command_key::text]) required_lock
                WHERE NOT EXISTS(SELECT 1 FROM pg_locks WHERE pid=pg_backend_pid() AND locktype='advisory' AND classid=918427
                  AND objid=hashtext(required_lock)::oid AND objsubid=2 AND mode='ExclusiveLock' AND granted)))))) THEN
    RAISE EXCEPTION 'Publication target requires its immutable owned preparation or reviewed admission receipt' USING ERRCODE='23514';
  END IF;
  IF (NEW.publication_accepted,NEW.publication_accepted_hash) IS DISTINCT FROM (OLD.publication_accepted,OLD.publication_accepted_hash)
    AND (OLD.operation<>'publish' OR OLD.publication_accepted IS NOT NULL OR OLD.state<>'running' OR NEW.publication_accepted IS NULL
      OR NEW.owner_token IS DISTINCT FROM OLD.owner_token OR NEW.claimed_revision IS DISTINCT FROM OLD.claimed_revision
      OR NOT EXISTS(SELECT 1 FROM channels.ebay_listing_sync_events e WHERE e.job_id=OLD.id
        AND e.revision=OLD.claimed_revision AND e.owner_token=OLD.owner_token AND e.event='stage_completed'
        AND e.evidence->>'key'='publication_accepted' AND e.evidence->>'preparedIntentHash'=NEW.publication_accepted_hash
        AND e.evidence->'response'=NEW.publication_accepted)) THEN
    RAISE EXCEPTION 'Publication response requires its immutable owned receipt' USING ERRCODE='23514';
  END IF;
  IF NEW.operation='publish' AND NEW.state='completed' AND (NEW.provider_identity IS NULL OR NEW.publication_target IS NULL
    OR OLD.verification_revision IS DISTINCT FROM OLD.claimed_revision
    OR NOT EXISTS(SELECT 1 FROM channels.ebay_listing_sync_events e WHERE e.job_id=OLD.id
      AND e.revision=OLD.claimed_revision AND e.owner_token=OLD.owner_token AND e.event='stage_completed'
      AND e.evidence->>'key'='verification' AND e.evidence->>'preparedIntentHash'=OLD.verification_intent_hash)) THEN
    RAISE EXCEPTION 'Publication completion requires observed provider identity and its pinned target' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_ebay_listing_sync_settlement(); Type: FUNCTION; Schema: channels; Owner: -
--

CREATE FUNCTION channels.guard_ebay_listing_sync_settlement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Listing work settlements are immutable' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(
    SELECT 1 FROM channels.ebay_listing_sync_jobs failed JOIN channels.ebay_listing_sync_jobs replacement
      ON replacement.id=NEW.replacement_job_id AND replacement.identity_hash=failed.identity_hash
      AND replacement.channel_id=failed.channel_id AND replacement.connection_id=failed.connection_id AND replacement.product_id=failed.product_id
    WHERE failed.id=NEW.failed_job_id AND failed.operation='sync' AND failed.state='needs_attention'
      AND replacement.operation='sync' AND replacement.state='completed' AND replacement.created_at>=failed.created_at
      AND to_jsonb(failed)=NEW.before_record
      AND EXISTS(SELECT 1 FROM channels.ebay_listing_sync_events e WHERE e.job_id=failed.id AND e.event='stage_started' AND e.evidence->>'key'='prepare_listing')
      AND NOT EXISTS(SELECT 1 FROM channels.ebay_listing_sync_events e WHERE e.job_id=failed.id AND e.event IN ('stage_started','stage_completed')
        AND (e.evidence->>'key' IS DISTINCT FROM 'prepare_listing' OR e.event='stage_completed'))
      AND EXISTS(SELECT 1 FROM channels.ebay_listing_sync_events e WHERE e.job_id=replacement.id AND e.revision=replacement.revision
        AND e.event='stage_completed' AND e.evidence->>'key'='verification'
        AND e.evidence->>'preparedIntentHash'=replacement.verification_intent_hash)
  ) THEN RAISE EXCEPTION 'Settlement requires an unsent failure and its exact verified replacement' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_ebay_publication_retry_authorization(); Type: FUNCTION; Schema: channels; Owner: -
--

CREATE FUNCTION channels.guard_ebay_publication_retry_authorization() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE job channels.ebay_listing_sync_jobs%ROWTYPE; operation_name text; stage_key text;
BEGIN
  IF NEW.event NOT IN ('publication_retry_authorized','withdrawal_retry_authorized') THEN RETURN NEW; END IF;
  operation_name := CASE WHEN NEW.event='withdrawal_retry_authorized' THEN 'withdraw' ELSE 'publish' END;
  stage_key := operation_name;
  SELECT * INTO job FROM channels.ebay_listing_sync_jobs WHERE id=NEW.job_id;
  IF job.operation<>operation_name OR job.state='completed'
    OR (operation_name='publish' AND (job.publication_target IS NULL OR job.publication_accepted IS NOT NULL
      OR NEW.evidence->'publicationTarget' IS DISTINCT FROM job.publication_target))
    OR (operation_name='withdraw' AND (job.provider_identity IS NULL OR job.state NOT IN ('queued','running','recovering','awaiting_evidence')
      OR NEW.evidence->'providerIdentity' IS DISTINCT FROM job.provider_identity))
    OR NEW.owner_token IS NOT NULL OR NEW.revision<>job.revision
    OR NEW.evidence->>'ownerTransactionId' IS DISTINCT FROM pg_current_xact_id()::text
    OR NEW.evidence->>'beforeRevision' IS DISTINCT FROM job.revision::text
    OR NEW.evidence->'identity' IS DISTINCT FROM job.identity
    OR NOT COALESCE(NEW.evidence->>'reviewHash' ~ '^[a-f0-9]{64}$',false)
    OR NOT COALESCE(NEW.evidence->>'requestHash' ~ '^[a-f0-9]{64}$',false)
    OR EXISTS(SELECT 1 FROM channels.ebay_listing_sync_events e WHERE e.job_id=job.id AND e.event='stage_completed' AND e.evidence->>'key'=stage_key)
    OR NOT EXISTS(SELECT 1 FROM channels.ebay_listing_sync_events e WHERE e.job_id=job.id AND e.event='stage_started' AND e.evidence->>'key'=stage_key
      AND e.id>COALESCE((SELECT max(a.id) FROM channels.ebay_listing_sync_events a WHERE a.job_id=job.id AND a.event=NEW.event),0))
    OR NOT EXISTS(SELECT 1 FROM channels.ebay_listing_sync_commands c WHERE c.command_key=(NEW.evidence->>'commandKey')::uuid
      AND c.job_id=job.id AND c.identity_hash=job.identity_hash AND c.actor=NEW.evidence->>'actor')
    OR EXISTS(SELECT 1 FROM unnest(ARRAY[job.id::text,'listing:'||job.channel_id::text||':'||job.product_id::text,
      'enqueue:'||job.channel_id::text||':'||job.product_id::text,'command:'||(NEW.evidence->>'commandKey')]) required_lock
      WHERE NOT EXISTS(SELECT 1 FROM pg_locks WHERE pid=pg_backend_pid() AND locktype='advisory' AND classid=918427
        AND objid=hashtext(required_lock)::oid AND objsubid=2 AND mode='ExclusiveLock' AND granted)) THEN
    RAISE EXCEPTION 'Listing retry requires its exact reviewed uncertainty and owned command' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $_$;


--
-- Name: guard_shopify_oauth_authorization(); Type: FUNCTION; Schema: channels; Owner: -
--

CREATE FUNCTION channels.guard_shopify_oauth_authorization() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'issued' THEN
      RAISE EXCEPTION 'Shopify authorization must start issued' USING ERRCODE = '23514';
    END IF;
    -- These IDs are immutable historical snapshots, not permanent foreign keys.
    -- Verify existence atomically at issuance without blocking normal later deletion
    -- or losing evidence needed to settle an already dispatched provider attempt.
    PERFORM 1 FROM identity.users WHERE id = NEW.actor_id FOR KEY SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Shopify authorization actor does not exist' USING ERRCODE = '23503';
    END IF;
    PERFORM 1 FROM channels.channel_connections
      WHERE id = NEW.connection_id AND channel_id = NEW.channel_id FOR KEY SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Shopify authorization connection does not belong to channel' USING ERRCODE = '23503';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.operation_id, NEW.state_hash, NEW.actor_id, NEW.session_hash, NEW.config_fingerprint,
      NEW.shop_domain, NEW.channel_id, NEW.connection_id, NEW.connection_fingerprint, NEW.created_at, NEW.expires_at)
    IS DISTINCT FROM ROW(OLD.operation_id, OLD.state_hash, OLD.actor_id, OLD.session_hash, OLD.config_fingerprint,
      OLD.shop_domain, OLD.channel_id, OLD.connection_id, OLD.connection_fingerprint, OLD.created_at, OLD.expires_at) THEN
    RAISE EXCEPTION 'Shopify authorization binding is immutable' USING ERRCODE = '23514';
  END IF;
  IF NOT ((OLD.status = 'issued' AND NEW.status IN ('exchanging','superseded'))
      OR (OLD.status = 'exchanging' AND NEW.status IN ('succeeded','exchange_unknown','failed','superseded'))) THEN
    RAISE EXCEPTION 'Invalid Shopify authorization transition' USING ERRCODE = '23514';
  END IF;
  IF OLD.status = 'exchanging' AND (NEW.attempt_id IS DISTINCT FROM OLD.attempt_id OR NEW.started_at IS DISTINCT FROM OLD.started_at) THEN
    RAISE EXCEPTION 'Shopify authorization attempt is immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


