SET default_table_access_method = heap;

--
-- Name: ebay_listing_sync_jobs; Type: TABLE; Schema: channels; Owner: -
--

CREATE TABLE channels.ebay_listing_sync_jobs (
    id uuid NOT NULL,
    channel_id integer NOT NULL,
    connection_id integer NOT NULL,
    product_id integer NOT NULL,
    identity jsonb NOT NULL,
    identity_hash text NOT NULL,
    state text DEFAULT 'queued'::text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    claimed_revision bigint,
    owner_token uuid,
    attempts integer DEFAULT 0 NOT NULL,
    requested_by text NOT NULL,
    error_code text,
    error_message text,
    result jsonb,
    next_attempt_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    verification_intent_hash text,
    verification_revision bigint,
    provider_identity jsonb,
    provider_identity_hash text,
    operation text DEFAULT 'sync'::text NOT NULL,
    publication_target jsonb,
    publication_target_hash text,
    publication_accepted jsonb,
    publication_accepted_hash text,
    read_failure_count integer DEFAULT 0 NOT NULL,
    read_retry_paused boolean DEFAULT false NOT NULL,
    CONSTRAINT ebay_listing_sync_jobs_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT ebay_listing_sync_jobs_check CHECK (((claimed_revision > 0) AND (claimed_revision <= revision))),
    CONSTRAINT ebay_listing_sync_jobs_check1 CHECK (((state = 'running'::text) = ((owner_token IS NOT NULL) AND (claimed_revision IS NOT NULL)))),
    CONSTRAINT ebay_listing_sync_jobs_check2 CHECK (((verification_revision > 0) AND (verification_revision <= revision))),
    CONSTRAINT ebay_listing_sync_jobs_error_code_check CHECK ((length(error_code) <= 100)),
    CONSTRAINT ebay_listing_sync_jobs_error_message_check CHECK ((length(error_message) <= 1000)),
    CONSTRAINT ebay_listing_sync_jobs_identity_check CHECK ((jsonb_typeof(identity) = 'object'::text)),
    CONSTRAINT ebay_listing_sync_jobs_identity_hash_check CHECK ((identity_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT ebay_listing_sync_jobs_operation_check CHECK ((operation = ANY (ARRAY['sync'::text, 'publish'::text, 'withdraw'::text]))),
    CONSTRAINT ebay_listing_sync_jobs_provider_identity_check CHECK ((jsonb_typeof(provider_identity) = 'object'::text)),
    CONSTRAINT ebay_listing_sync_jobs_provider_identity_hash_check CHECK ((provider_identity_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT ebay_listing_sync_jobs_publication_accepted_check CHECK ((jsonb_typeof(publication_accepted) = 'object'::text)),
    CONSTRAINT ebay_listing_sync_jobs_publication_accepted_hash_check CHECK ((publication_accepted_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT ebay_listing_sync_jobs_publication_target_check CHECK ((jsonb_typeof(publication_target) = 'object'::text)),
    CONSTRAINT ebay_listing_sync_jobs_publication_target_hash_check CHECK ((publication_target_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT ebay_listing_sync_jobs_read_failure_count_check CHECK ((read_failure_count >= 0)),
    CONSTRAINT ebay_listing_sync_jobs_requested_by_check CHECK (((length(btrim(requested_by)) >= 1) AND (length(btrim(requested_by)) <= 200))),
    CONSTRAINT ebay_listing_sync_jobs_revision_check CHECK ((revision > 0)),
    CONSTRAINT ebay_listing_sync_jobs_state_check CHECK ((state = ANY (ARRAY['queued'::text, 'running'::text, 'recovering'::text, 'awaiting_evidence'::text, 'completed'::text, 'needs_attention'::text]))),
    CONSTRAINT ebay_listing_sync_jobs_verification_intent_hash_check CHECK ((verification_intent_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT ebay_sync_provider_identity_pair CHECK (((provider_identity IS NULL) = (provider_identity_hash IS NULL))),
    CONSTRAINT ebay_sync_publication_accepted_pair CHECK (((publication_accepted IS NULL) = (publication_accepted_hash IS NULL))),
    CONSTRAINT ebay_sync_publication_accepted_target CHECK (((publication_accepted IS NULL) OR ((operation = 'publish'::text) AND (publication_target IS NOT NULL)))),
    CONSTRAINT ebay_sync_publication_target_operation CHECK (((publication_target IS NULL) OR (operation = 'publish'::text))),
    CONSTRAINT ebay_sync_publication_target_pair CHECK (((publication_target IS NULL) = (publication_target_hash IS NULL))),
    CONSTRAINT ebay_sync_verification_checkpoint_pair CHECK (((verification_intent_hash IS NULL) = (verification_revision IS NULL)))
);


--
-- Name: has_owned_ebay_publication_continuation(channels.ebay_listing_sync_jobs, channels.ebay_listing_sync_jobs); Type: FUNCTION; Schema: channels; Owner: -
--

CREATE FUNCTION channels.has_owned_ebay_publication_continuation(before_job channels.ebay_listing_sync_jobs, after_job channels.ebay_listing_sync_jobs) RETURNS boolean
    LANGUAGE sql
    AS $$
  SELECT before_job.operation='publish' AND before_job.state='needs_attention'
    AND after_job.state='queued' AND after_job.revision=before_job.revision+1
    AND before_job.owner_token IS NULL AND before_job.claimed_revision IS NULL
    AND after_job.owner_token IS NULL AND after_job.claimed_revision IS NULL
    AND (after_job.provider_identity,after_job.provider_identity_hash,after_job.publication_target,after_job.publication_target_hash,
      after_job.publication_accepted,after_job.publication_accepted_hash,after_job.verification_intent_hash,after_job.verification_revision)
      IS NOT DISTINCT FROM (before_job.provider_identity,before_job.provider_identity_hash,before_job.publication_target,before_job.publication_target_hash,
      before_job.publication_accepted,before_job.publication_accepted_hash,before_job.verification_intent_hash,before_job.verification_revision)
    AND EXISTS(SELECT 1 FROM channels.ebay_listing_sync_events e
      JOIN channels.ebay_listing_sync_commands c ON c.command_key::text=e.evidence->>'commandKey' AND c.job_id=e.job_id
      WHERE e.job_id=before_job.id AND e.revision=before_job.revision AND e.owner_token IS NULL AND e.event='requested'
        AND e.evidence->>'continuationOnly'='true' AND e.evidence->>'requestedOperation'='sync'
        AND e.evidence->>'ownerTransactionId'=pg_current_xact_id()::text
        AND e.evidence->>'beforeRevision'=before_job.revision::text AND e.evidence->'identity'=before_job.identity
        AND c.actor=e.evidence->>'actor' AND c.identity_hash=e.evidence->>'sourceIdentityHash'
        AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY[before_job.id::text,'listing:'||before_job.channel_id::text||':'||before_job.product_id::text,
          'enqueue:'||before_job.channel_id::text||':'||before_job.product_id::text,'command:'||c.command_key::text]) required_lock
          WHERE NOT EXISTS(SELECT 1 FROM pg_locks WHERE pid=pg_backend_pid() AND locktype='advisory' AND classid=918427
            AND objid=hashtext(required_lock)::oid AND objsubid=2 AND mode='ExclusiveLock' AND granted)));
$$;


--
-- Name: legacy_maintenance_replacement_sources(bigint, uuid, bigint); Type: FUNCTION; Schema: channels; Owner: -
--

CREATE FUNCTION channels.legacy_maintenance_replacement_sources(attempt_id bigint, current_job_id uuid, current_revision bigint) RETURNS TABLE(source jsonb)
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object(
    'job',jsonb_build_object('id',j.id::text,'operation',j.operation,'identity',COALESCE(j.provider_identity,j.identity)),
    'current',jsonb_build_object('id',c.id::text,'revision',c.claimed_revision::text,'identity',c.provider_identity),
    'attempt',jsonb_build_object('id',a.id::text,'startedAt',a.started_at::text,'scope',a.scope,'affectedScopes',a.affected_scopes),
    'stage',jsonb_build_object('id',s.id::text,'revision',s.revision::text,'event',s.event,'ownerToken',s.owner_token::text,'evidence',s.evidence,'createdAt',s.created_at::text),
    'next',jsonb_build_object('id',n.id::text,'revision',n.revision::text,'event',n.event,'ownerToken',n.owner_token::text,'evidence',n.evidence,'createdAt',n.created_at::text))
  FROM inventory.quantity_publication_attempts a
  JOIN channels.ebay_listing_sync_jobs c ON c.id=current_job_id AND c.state='running'
    AND c.claimed_revision=current_revision AND c.revision=current_revision AND c.owner_token IS NOT NULL AND c.provider_identity IS NOT NULL
    AND c.operation='sync' AND c.connection_id::text=a.scope->>'connectionId' AND c.identity->>'accountId'=a.scope->>'externalScopeId'
  JOIN channels.ebay_listing_sync_jobs j ON j.channel_id=c.channel_id AND j.connection_id=c.connection_id AND j.product_id=c.product_id
    AND j.created_at<=a.started_at AND j.identity->>'accountId'=a.scope->>'externalScopeId'
  CROSS JOIN LATERAL(SELECT e.* FROM channels.ebay_listing_sync_events e WHERE e.job_id=j.id AND e.created_at<=a.started_at ORDER BY e.id DESC LIMIT 1) s
  CROSS JOIN LATERAL(SELECT e.* FROM channels.ebay_listing_sync_events e WHERE e.job_id=j.id AND e.id>s.id ORDER BY e.id LIMIT 1) n
  WHERE a.id=attempt_id AND a.owner_kind='legacy' AND a.state IN ('running','uncertain') AND a.request_journal_contract IS NULL
    AND a.scope->>'providerKey'='ebay' AND n.created_at>=a.started_at
    AND EXISTS(SELECT 1 FROM channels.ebay_listing_sync_events e WHERE e.job_id=c.id AND e.revision=c.claimed_revision
      AND e.owner_token=c.owner_token AND e.event='stage_started' AND e.evidence->>'key'='recover_prior_requests')
  ORDER BY j.id LIMIT 2
$$;


--
-- Name: maintenance_resource_identity(jsonb); Type: FUNCTION; Schema: channels; Owner: -
--

CREATE FUNCTION channels.maintenance_resource_identity(target jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT jsonb_build_object('channelId',target->'channelId','connectionId',target->'connectionId','productId',target->'productId',
    'accountId',target->'accountId','marketplaceId',target->'marketplaceId','groupKey',target->'groupKey',
    'retainedGroupSkus',COALESCE((SELECT jsonb_agg(s ORDER BY s) FROM jsonb_array_elements(COALESCE(target->'retainedGroupSkus','[]')) s),'[]'::jsonb),
    'variants',(SELECT jsonb_agg(jsonb_build_object('variantId',m->'variantId','sku',m->'sku','externalSku',m->'externalSku',
      'offerId',m->'offerId','listingId',m->'listingId') ORDER BY m->>'variantId') FROM jsonb_array_elements(target->'variants') m))
$$;


