--
-- Name: dropship_cost_change_policies_guard(); Type: FUNCTION; Schema: dropship; Owner: -
--

CREATE FUNCTION dropship.dropship_cost_change_policies_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'dropship_cost_change_policies is append-only: rows cannot be deleted';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.version IS DISTINCT FROM OLD.version
     OR NEW.increase_notice_days IS DISTINCT FROM OLD.increase_notice_days
     OR NEW.decrease_timing IS DISTINCT FROM OLD.decrease_timing
     OR NEW.price_protection IS DISTINCT FROM OLD.price_protection
     OR NEW.retail_changes_get_notice IS DISTINCT FROM OLD.retail_changes_get_notice
     OR NEW.notify_by_email IS DISTINCT FROM OLD.notify_by_email
     OR NEW.notify_in_portal IS DISTINCT FROM OLD.notify_in_portal
     OR NEW.notify_on_decrease IS DISTINCT FROM OLD.notify_on_decrease
     OR NEW.notice_minimum_change_cents IS DISTINCT FROM OLD.notice_minimum_change_cents
     OR NEW.notice_minimum_change_bps IS DISTINCT FROM OLD.notice_minimum_change_bps
     OR NEW.rule_priced_listings IS DISTINCT FROM OLD.rule_priced_listings
     OR NEW.below_cost_fixed_listings IS DISTINCT FROM OLD.below_cost_fixed_listings
     OR NEW.detection_interval_minutes IS DISTINCT FROM OLD.detection_interval_minutes
     OR NEW.change_note IS DISTINCT FROM OLD.change_note
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.created_by_actor_type IS DISTINCT FROM OLD.created_by_actor_type
     OR NEW.created_by_actor_id IS DISTINCT FROM OLD.created_by_actor_id
  THEN
    RAISE EXCEPTION 'dropship_cost_change_policies is immutable: publish a new version instead of editing one';
  END IF;
  IF NOT (OLD.is_active AND NOT NEW.is_active) THEN
    RAISE EXCEPTION 'dropship_cost_change_policies rows may only be retired (active -> inactive)';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: dropship_cost_schedule_entries_guard(); Type: FUNCTION; Schema: dropship; Owner: -
--

CREATE FUNCTION dropship.dropship_cost_schedule_entries_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'dropship_cost_schedule_entries is append-only: rows cannot be deleted';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.vendor_id IS DISTINCT FROM OLD.vendor_id
     OR NEW.product_variant_id IS DISTINCT FROM OLD.product_variant_id
     OR NEW.kind IS DISTINCT FROM OLD.kind
     OR NEW.from_cents IS DISTINCT FROM OLD.from_cents
     OR NEW.effective_at IS DISTINCT FROM OLD.effective_at
     OR NEW.observed_at IS DISTINCT FROM OLD.observed_at
     OR NEW.policy_id IS DISTINCT FROM OLD.policy_id
     OR NEW.cost_source IS DISTINCT FROM OLD.cost_source
     OR NEW.plan_id IS DISTINCT FROM OLD.plan_id
     OR NEW.override_id IS DISTINCT FROM OLD.override_id
     OR NEW.retail_price_cents IS DISTINCT FROM OLD.retail_price_cents
     OR NEW.discount_bps IS DISTINCT FROM OLD.discount_bps
     OR NEW.recorded_by IS DISTINCT FROM OLD.recorded_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
  THEN
    RAISE EXCEPTION 'dropship_cost_schedule_entries is immutable: only withdrawn_at and a lowered unit_cost_cents may change';
  END IF;
  IF OLD.withdrawn_at IS NOT NULL THEN
    RAISE EXCEPTION 'dropship_cost_schedule_entries: a withdrawn entry cannot change';
  END IF;
  IF NEW.withdrawn_at IS NOT NULL THEN
    IF NEW.unit_cost_cents IS DISTINCT FROM OLD.unit_cost_cents THEN
      RAISE EXCEPTION 'dropship_cost_schedule_entries: a withdrawal cannot change the cost';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.kind <> 'increase' OR NEW.unit_cost_cents >= OLD.unit_cost_cents THEN
    RAISE EXCEPTION 'dropship_cost_schedule_entries: an entry may only be withdrawn, or lowered when it is an announced increase';
  END IF;
  RETURN NEW;
END;
$$;


