--
-- Name: guard_listing_price_setting_coherence(); Type: FUNCTION; Schema: dropship; Owner: -
--

CREATE FUNCTION dropship.guard_listing_price_setting_coherence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE revision dropship.dropship_listing_price_revisions%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Reset a listing price with a new revision, not deletion' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND (OLD.vendor_id IS DISTINCT FROM NEW.vendor_id
     OR OLD.store_connection_id IS DISTINCT FROM NEW.store_connection_id
     OR OLD.product_variant_id IS DISTINCT FROM NEW.product_variant_id) THEN
    RAISE EXCEPTION 'Listing price target identity cannot change' USING ERRCODE = '23514';
  END IF;
  SELECT * INTO revision FROM dropship.dropship_listing_price_revisions WHERE id = NEW.revision_id;
  IF NOT FOUND OR revision.vendor_id <> NEW.vendor_id
     OR revision.store_connection_id <> NEW.store_connection_id
     OR revision.product_variant_id <> NEW.product_variant_id
     OR revision.override_price_cents IS DISTINCT FROM NEW.override_price_cents
     OR revision.pricing_mode IS DISTINCT FROM NEW.pricing_mode
     OR revision.created_at IS DISTINCT FROM NEW.updated_at THEN
    RAISE EXCEPTION 'Listing price setting must match its exact revision' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
  IF revision.previous_revision_id IS DISTINCT FROM (
    SELECT revision_id FROM dropship.dropship_listing_price_settings
    WHERE store_connection_id = NEW.store_connection_id AND product_variant_id = NEW.product_variant_id
  ) THEN
    RAISE EXCEPTION 'Listing price revision predecessor does not match the current setting' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_listing_rule_conversion(); Type: FUNCTION; Schema: dropship; Owner: -
--

CREATE FUNCTION dropship.guard_listing_rule_conversion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Listing rule conversions are kept; they cannot be deleted' USING ERRCODE = '23514';
  END IF;
  IF (to_jsonb(NEW) - 'notice_seen_at' - 'notice_seen_by') IS DISTINCT FROM (to_jsonb(OLD) - 'notice_seen_at' - 'notice_seen_by') THEN
    RAISE EXCEPTION 'A listing rule conversion cannot change; only its notice can be marked seen' USING ERRCODE = '23514';
  END IF;
  IF OLD.actor_type <> 'system' OR OLD.notice_seen_at IS NOT NULL OR OLD.notice_seen_by IS NOT NULL
     OR NEW.notice_seen_at IS NULL OR NEW.notice_seen_by IS NULL THEN
    RAISE EXCEPTION 'A system conversion''s notice is marked seen once, and nothing else changes' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_managed_listing_intent_receipt(); Type: FUNCTION; Schema: dropship; Owner: -
--

CREATE FUNCTION dropship.guard_managed_listing_intent_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    IF OLD.requested_scope ? 'managedIntentScope' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='DROPSHIP_MANAGED_INTENT_RECEIPT_IMMUTABLE'; END IF;
    RETURN OLD;
  END IF;
  IF OLD.requested_scope ? 'managedIntentScope' AND
    (NEW.vendor_id,NEW.store_connection_id,NEW.idempotency_key,NEW.request_hash,NEW.requested_scope)
      IS DISTINCT FROM (OLD.vendor_id,OLD.store_connection_id,OLD.idempotency_key,OLD.request_hash,OLD.requested_scope)
  THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='DROPSHIP_MANAGED_INTENT_RECEIPT_IMMUTABLE'; END IF;
  RETURN NEW;
END; $$;


