--
-- Name: guard_pricing_profile_coherence(); Type: FUNCTION; Schema: dropship; Owner: -
--

CREATE FUNCTION dropship.guard_pricing_profile_coherence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE predecessor integer;
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Pricing profiles cannot be deleted' USING ERRCODE = '23514'; END IF;
  IF TG_OP = 'UPDATE' AND (OLD.vendor_id <> NEW.vendor_id OR OLD.store_connection_id <> NEW.store_connection_id) THEN
    RAISE EXCEPTION 'Pricing profile ownership cannot change' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
  SELECT previous_revision_id INTO predecessor FROM dropship.dropship_pricing_profile_revisions WHERE id = NEW.revision_id;
  IF predecessor IS DISTINCT FROM (SELECT revision_id FROM dropship.dropship_pricing_profiles WHERE store_connection_id = NEW.store_connection_id) THEN
    RAISE EXCEPTION 'Pricing profile predecessor conflict' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_product_category_seen(); Type: FUNCTION; Schema: dropship; Owner: -
--

CREATE FUNCTION dropship.guard_product_category_seen() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Category marks are kept; acknowledge to move them forward' USING ERRCODE = '23514';
  END IF;
  IF OLD.vendor_id <> NEW.vendor_id OR OLD.store_connection_id <> NEW.store_connection_id
     OR OLD.product_id <> NEW.product_id THEN
    RAISE EXCEPTION 'Category mark identity cannot change' USING ERRCODE = '23514';
  END IF;
  IF NEW.seen_at < OLD.seen_at THEN
    RAISE EXCEPTION 'A category mark cannot move back in time' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_product_listing_setting_coherence(); Type: FUNCTION; Schema: dropship; Owner: -
--

CREATE FUNCTION dropship.guard_product_listing_setting_coherence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE predecessor integer;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Reset product listing settings with a new revision, not deletion' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND (OLD.vendor_id <> NEW.vendor_id OR OLD.store_connection_id <> NEW.store_connection_id
     OR OLD.product_id <> NEW.product_id) THEN
    RAISE EXCEPTION 'Product listing setting identity cannot change' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
  -- PostgreSQL runs INSERT triggers before ON CONFLICT UPDATE triggers, so
  -- both forms check the predecessor against the current row.
  SELECT previous_revision_id INTO predecessor
    FROM dropship.dropship_product_listing_setting_revisions WHERE id = NEW.revision_id;
  IF predecessor IS DISTINCT FROM (SELECT revision_id FROM dropship.dropship_product_listing_settings
      WHERE store_connection_id = NEW.store_connection_id AND product_id = NEW.product_id) THEN
    RAISE EXCEPTION 'Product listing setting predecessor does not match the current setting' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


