--
-- Name: invalidate_listing_end_state_changes(); Type: FUNCTION; Schema: dropship; Owner: -
--

CREATE FUNCTION dropship.invalidate_listing_end_state_changes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE affected integer;
BEGIN
  FOR affected IN SELECT DISTINCT n.product_id FROM new_ends n JOIN old_ends o ON o.id = n.id
      WHERE o.state IS DISTINCT FROM n.state ORDER BY n.product_id
  LOOP PERFORM inventory.invalidate_publication_selection_product(affected); END LOOP;
  RETURN NULL;
END;
$$;


--
-- Name: invalidate_picked_products(); Type: FUNCTION; Schema: dropship; Owner: -
--

CREATE FUNCTION dropship.invalidate_picked_products() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE affected integer;
BEGIN
  FOR affected IN SELECT DISTINCT v.product_id FROM changed_picks c
      JOIN catalog.product_variants v ON v.id = c.product_variant_id ORDER BY v.product_id
  LOOP PERFORM inventory.invalidate_publication_selection_product(affected); END LOOP;
  RETURN NULL;
END;
$$;


