--
-- Name: assert_cutover_admission_fence_owner(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.assert_cutover_admission_fence_owner() RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE fence inventory.cutover_admission_fence%ROWTYPE;
BEGIN
  IF current_setting('transaction_isolation') <> 'read committed'
     OR current_setting('transaction_read_only') <> 'off' THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='CUTOVER_READ_COMMITTED_TRANSACTION_REQUIRED';
  END IF;
  SELECT * INTO fence FROM inventory.cutover_admission_fence WHERE singleton_key=true FOR UPDATE NOWAIT;
  IF NOT FOUND OR fence.epoch <= 0 OR fence.owner_transaction_id IS NULL
     OR fence.owner_transaction_id IS DISTINCT FROM pg_current_xact_id_if_assigned() THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='CUTOVER_EXCLUSIVE_ADMISSION_REQUIRED';
  END IF;
  RETURN fence.epoch;
END;
$$;


--
-- Name: assert_definition_head_coherence(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.assert_definition_head_coherence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  new_row jsonb;
  owner_integer integer;
  owner_text text;
BEGIN
  new_row := to_jsonb(NEW);
  IF TG_TABLE_NAME = 'location_promise_policy_versions' THEN
    owner_integer := NULLIF(new_row ->> 'warehouse_location_id', '')::integer;
    IF EXISTS (
      SELECT 1 FROM inventory.location_promise_policy_heads AS head
      JOIN inventory.location_promise_policy_versions AS active
        ON active.id = head.active_policy_id
      WHERE head.warehouse_location_id = owner_integer
        AND active.lifecycle_status <> 'sealed'
    ) OR EXISTS (
      SELECT 1 FROM inventory.location_promise_policy_heads AS head
      JOIN inventory.location_promise_policy_versions AS draft
        ON draft.id = head.draft_policy_id
      WHERE head.warehouse_location_id = owner_integer
        AND draft.lifecycle_status <> 'draft'
    ) THEN
      RAISE EXCEPTION 'location promise policy head is not coherent with definition lifecycle';
    END IF;
  ELSIF TG_TABLE_NAME = 'transformation_model_versions' THEN
    owner_integer := NULLIF(new_row ->> 'product_id', '')::integer;
    IF EXISTS (
      SELECT 1 FROM inventory.transformation_model_heads AS head
      JOIN inventory.transformation_model_versions AS active
        ON active.id = head.active_model_id
      WHERE head.product_id = owner_integer
        AND active.lifecycle_status <> 'sealed'
    ) OR EXISTS (
      SELECT 1 FROM inventory.transformation_model_heads AS head
      JOIN inventory.transformation_model_versions AS draft
        ON draft.id = head.draft_model_id
      WHERE head.product_id = owner_integer
        AND draft.lifecycle_status <> 'draft'
    ) THEN
      RAISE EXCEPTION 'transformation model head is not coherent with definition lifecycle';
    END IF;
  ELSIF TG_TABLE_NAME = 'promise_safety_policy_versions' THEN
    owner_text := new_row ->> 'scope_key';
    IF EXISTS (
      SELECT 1 FROM inventory.promise_safety_policy_heads AS head
      JOIN inventory.promise_safety_policy_versions AS active
        ON active.id = head.active_policy_id
      WHERE head.scope_key = owner_text
        AND active.lifecycle_status <> 'sealed'
    ) OR EXISTS (
      SELECT 1 FROM inventory.promise_safety_policy_heads AS head
      JOIN inventory.promise_safety_policy_versions AS draft
        ON draft.id = head.draft_policy_id
      WHERE head.scope_key = owner_text
        AND draft.lifecycle_status <> 'draft'
    ) THEN
      RAISE EXCEPTION 'safety policy head is not coherent with definition lifecycle';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: assert_ebay_operator_resume_locks(text[]); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.assert_ebay_operator_resume_locks(keys text[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE owned_key text; lock_key bigint;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM pg_locks WHERE pid=pg_backend_pid() AND locktype='advisory'
    AND classid=918419 AND objid=0 AND objsubid=2 AND mode='ShareLock' AND granted) THEN
    RAISE EXCEPTION 'eBay recovery requires the shared publication gate' USING ERRCODE='23514';
  END IF;
  FOREACH owned_key IN ARRAY keys LOOP
    lock_key:=hashtextextended(owned_key,918420);
    IF NOT EXISTS(SELECT 1 FROM pg_locks WHERE pid=pg_backend_pid() AND locktype='advisory'
      AND classid=((lock_key>>32)&4294967295)::oid AND objid=(lock_key&4294967295)::oid
      AND objsubid=1 AND mode='ExclusiveLock' AND granted) THEN
      RAISE EXCEPTION 'eBay recovery requires every exact scope lock' USING ERRCODE='23514';
    END IF;
  END LOOP;
END $$;


--
-- Name: assert_initial_publication_scope_complete(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.assert_initial_publication_scope_complete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actual_ids integer[]; expected_ids integer[];
BEGIN
  PERFORM inventory.assert_cutover_admission_fence_owner();
  SELECT COALESCE(array_agg(head.product_variant_id ORDER BY head.product_variant_id),'{}'::integer[]) INTO actual_ids
    FROM inventory.publication_membership_heads head WHERE head.publication_target_id=NEW.publication_target_id;
  SELECT COALESCE(array_agg(value ORDER BY value),'{}'::integer[]) INTO expected_ids
    FROM unnest(NEW.included_variant_ids || NEW.excluded_variant_ids) AS item(value);
  IF actual_ids IS DISTINCT FROM expected_ids
    OR NOT EXISTS(SELECT 1 FROM inventory.inventory_publication_targets WHERE id=NEW.publication_target_id
      AND membership_mode='explicit' AND state='preview' AND publication_authority='echelon' AND revision=NEW.previous_revision+1)
    OR NOT EXISTS(SELECT 1 FROM inventory.availability_runtime_authority WHERE singleton_key=true
      AND authority='legacy' AND activation_run_id IS NULL AND revision=NEW.authority_revision)
    OR EXISTS(SELECT 1 FROM inventory.availability_activation_freezes WHERE released_at IS NULL)
    OR EXISTS(SELECT 1 FROM inventory.publication_membership_heads head
      JOIN inventory.publication_membership_versions version ON version.id=head.active_version_id
      WHERE head.publication_target_id=NEW.publication_target_id AND
        (version.included IS DISTINCT FROM (head.product_variant_id=ANY(NEW.included_variant_ids))
          OR version.version<>1 OR version.review_hash<>NEW.review_hash
          OR version.created_by<>NEW.actor OR version.created_at<>NEW.occurred_at))
    OR NOT EXISTS(SELECT 1 FROM public.audit_events WHERE actor=NEW.actor
      AND action='inventory_availability.publication_scope.initialized'
      AND target='inventory.inventory_publication_target:'||NEW.publication_target_id::text
      AND context->>'requestHash'=NEW.request_hash) THEN
    RAISE EXCEPTION 'INITIAL_SCOPE_INCOMPLETE' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: assert_initial_scope_mapping_imports(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.assert_initial_scope_mapping_imports() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE expected_ids integer[];
BEGIN
  PERFORM inventory.assert_cutover_admission_fence_owner();
  SELECT COALESCE(array_agg((item->>'productVariantId')::integer ORDER BY (item->>'productVariantId')::integer),'{}'::integer[])
    INTO expected_ids FROM jsonb_array_elements(COALESCE(NEW.evidence->'review'->'mappingImports','[]'::jsonb)) item;
  IF COALESCE(NEW.receipt->'importedVariantIds','[]'::jsonb) IS DISTINCT FROM to_jsonb(expected_ids)
    OR NOT expected_ids <@ NEW.included_variant_ids
    OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(COALESCE(NEW.evidence->'review'->'mappingImports','[]'::jsonb)) item
      LEFT JOIN inventory.publication_variant_mapping_heads head
        ON head.publication_target_id=NEW.publication_target_id AND head.product_variant_id=(item->>'productVariantId')::integer
      LEFT JOIN inventory.publication_variant_mapping_versions mapping ON mapping.id=head.draft_mapping_id
      WHERE mapping.id IS NULL OR mapping.version<>1 OR mapping.lifecycle_status<>'draft'
        OR head.active_mapping_id IS NOT NULL OR head.revision<>1
        OR mapping.external_inventory_item_id IS DISTINCT FROM item->>'externalInventoryItemId'
        OR mapping.external_sku IS DISTINCT FROM item->>'externalSku'
        OR mapping.request_hash IS DISTINCT FROM NEW.request_hash
        OR mapping.idempotency_key IS DISTINCT FROM 'initial-scope-map:'||NEW.request_hash||':'||(item->>'productVariantId')
        OR mapping.created_by IS DISTINCT FROM NEW.actor OR mapping.created_at IS DISTINCT FROM NEW.occurred_at
    ) THEN
    RAISE EXCEPTION 'INITIAL_SCOPE_MAPPING_IMPORT_INCOMPLETE' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: assert_quantity_projection(integer, integer); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.assert_quantity_projection(lot_id integer, level_id integer) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actual record; expected record;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM inventory.quantity_ledger_opening) THEN RETURN; END IF;
  IF lot_id IS NOT NULL THEN
    SELECT lot.qty_on_hand AS on_hand, lot.qty_reserved AS reserved, lot.qty_picked AS picked, lot.qty_packed AS packed,
      lot.product_variant_id, lot.warehouse_location_id INTO actual FROM inventory.inventory_lots lot WHERE id = lot_id;
    IF FOUND THEN
      SELECT coalesce(sum(on_hand_delta),0) AS on_hand, coalesce(sum(reserved_delta),0) AS reserved,
        coalesce(sum(picked_delta),0) AS picked, coalesce(sum(packed_delta),0) AS packed
        INTO expected FROM inventory.quantity_entries WHERE inventory_lot_id = lot_id;
      IF (actual.on_hand, actual.reserved, actual.picked, actual.packed)
         IS DISTINCT FROM (expected.on_hand, expected.reserved, expected.picked, expected.packed)
        OR EXISTS (SELECT 1 FROM inventory.quantity_entries WHERE inventory_lot_id = lot_id
          AND (product_variant_id <> actual.product_variant_id OR warehouse_location_id <> actual.warehouse_location_id)) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'QUANTITY_LOT_PROJECTION_ONLY';
      END IF;
    END IF;
  END IF;
  IF level_id IS NOT NULL THEN
    SELECT variant_qty AS on_hand, reserved_qty AS reserved, picked_qty AS picked, packed_qty AS packed,
      product_variant_id, warehouse_location_id INTO actual FROM inventory.inventory_levels WHERE id = level_id;
    IF FOUND THEN
      SELECT coalesce(sum(on_hand_delta),0) AS on_hand, coalesce(sum(reserved_delta),0) AS reserved,
        coalesce(sum(picked_delta),0) AS picked, coalesce(sum(packed_delta),0) AS packed
        INTO expected FROM inventory.quantity_entries WHERE inventory_level_id = level_id;
      IF (actual.on_hand, actual.reserved, actual.picked, actual.packed)
         IS DISTINCT FROM (expected.on_hand, expected.reserved, expected.picked, expected.packed)
        OR EXISTS (SELECT 1 FROM inventory.quantity_entries WHERE inventory_level_id = level_id
          AND (product_variant_id <> actual.product_variant_id OR warehouse_location_id <> actual.warehouse_location_id)) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'QUANTITY_LEVEL_PROJECTION_ONLY';
      END IF;
    END IF;
  END IF;
END;
$$;


--
-- Name: assert_transformation_model_supersession_coherence(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.assert_transformation_model_supersession_coherence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.lifecycle_status = 'superseded' AND OLD.lifecycle_status = 'draft'
     AND NOT EXISTS (
       SELECT 1 FROM inventory.transformation_model_versions successor
       JOIN inventory.transformation_model_heads head
         ON head.product_id = successor.product_id AND head.draft_model_id = successor.id
       WHERE successor.supersedes_model_id = NEW.id
         AND successor.product_id = NEW.product_id AND successor.version = NEW.version + 1
         AND successor.lifecycle_status = 'draft'
         AND successor.created_at >= NEW.superseded_at
         -- Generated refresh must never replace an operator-authored definition.
         AND (OLD.origin = 'phase3_backfill' OR successor.origin = 'operator')
         AND (successor.origin <> 'operator' OR successor.operator_input_hash IS NOT NULL)
     ) THEN
    RAISE EXCEPTION 'superseded draft % requires a current, source-bound successor', NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: assert_version_predecessor(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.assert_version_predecessor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  predecessor_owner text;
  predecessor_version integer;
  expected_owner text;
  predecessor_id integer;
  version_number integer;
  new_row jsonb;
BEGIN
  new_row := to_jsonb(NEW);
  version_number := NULLIF(new_row ->> 'version', '')::integer;
  IF version_number = 1 THEN
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'location_promise_policy_versions' THEN
    expected_owner := new_row ->> 'warehouse_location_id';
    predecessor_id := NULLIF(new_row ->> 'supersedes_policy_id', '')::integer;
    SELECT warehouse_location_id::text, version
      INTO predecessor_owner, predecessor_version
      FROM inventory.location_promise_policy_versions
      WHERE id = predecessor_id
      FOR KEY SHARE;
  ELSIF TG_TABLE_NAME = 'transformation_model_versions' THEN
    expected_owner := new_row ->> 'product_id';
    predecessor_id := NULLIF(new_row ->> 'supersedes_model_id', '')::integer;
    SELECT product_id::text, version
      INTO predecessor_owner, predecessor_version
      FROM inventory.transformation_model_versions
      WHERE id = predecessor_id
      FOR KEY SHARE;
  ELSIF TG_TABLE_NAME = 'promise_safety_policy_versions' THEN
    expected_owner := new_row ->> 'scope_key';
    predecessor_id := NULLIF(new_row ->> 'supersedes_policy_id', '')::integer;
    SELECT scope_key, version
      INTO predecessor_owner, predecessor_version
      FROM inventory.promise_safety_policy_versions
      WHERE id = predecessor_id
      FOR KEY SHARE;
  ELSE
    RAISE EXCEPTION 'unsupported versioned definition table %', TG_TABLE_NAME;
  END IF;

  IF predecessor_owner IS DISTINCT FROM expected_owner
     OR predecessor_version IS DISTINCT FROM version_number - 1 THEN
    RAISE EXCEPTION
      '% version % must supersede version % owned by the same scope',
      TG_TABLE_NAME, version_number, version_number - 1;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: check_channel_exposure_policy_head_coherence(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_channel_exposure_policy_head_coherence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  checked_scope_key VARCHAR(200) := CASE
    WHEN TG_TABLE_NAME = 'channel_exposure_policy_heads' THEN NEW.scope_key
    ELSE NEW.scope_key
  END;
BEGIN
  IF EXISTS (
    SELECT 1
    FROM inventory.channel_exposure_policy_heads AS head
    LEFT JOIN inventory.channel_exposure_policy_versions AS active ON active.id = head.active_policy_id
    LEFT JOIN inventory.channel_exposure_policy_versions AS draft ON draft.id = head.draft_policy_id
    WHERE head.scope_key = checked_scope_key
      AND (
        (active.id IS NOT NULL AND (active.lifecycle_status <> 'sealed' OR active.channel_id <> head.channel_id))
        OR (draft.id IS NOT NULL AND (draft.lifecycle_status <> 'draft' OR draft.channel_id <> head.channel_id))
      )
  ) THEN
    RAISE EXCEPTION 'channel exposure policy head lifecycle or channel is incoherent';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: check_cutover_history_batch_complete(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_cutover_history_batch_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF jsonb_typeof(NEW.review_payload->'decisions') IS DISTINCT FROM 'array'
    OR jsonb_array_length(NEW.review_payload->'decisions')=0
    OR (SELECT count(*) FROM inventory.cutover_history_retirements WHERE batch_id=NEW.id)
        <> jsonb_array_length(NEW.review_payload->'decisions') THEN
    RAISE EXCEPTION 'CUTOVER_HISTORY_AUDIT_INCOMPLETE';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: check_ebay_automatic_publication_recovery(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_ebay_automatic_publication_recovery() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM inventory.quantity_publication_attempts a WHERE a.id=NEW.attempt_id
    AND a.state='superseded_unknown' AND (to_jsonb(a)-'state')=(NEW.before_record-'state')) THEN
    RAISE EXCEPTION 'Automatic recovery evidence and the preserved unknown transition must commit together' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: check_ebay_operator_resume_complete(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_ebay_operator_resume_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE retained_ids jsonb; reviewed_ids jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(member.attempt_id::text ORDER BY member.attempt_id),'[]'::jsonb) INTO retained_ids
    FROM inventory.quantity_publication_operator_resume_attempts member WHERE member.resume_id=NEW.id;
  SELECT COALESCE(jsonb_agg(reviewed->>'attemptId' ORDER BY (reviewed->>'attemptId')::bigint),'[]'::jsonb) INTO reviewed_ids
    FROM jsonb_array_elements(NEW.review_payload->'attempts') reviewed;
  IF retained_ids IS NULL OR retained_ids IS DISTINCT FROM NEW.result_payload->'attemptIds' OR retained_ids IS DISTINCT FROM reviewed_ids
    OR EXISTS(SELECT 1 FROM inventory.quantity_publication_operator_resume_attempts member
      JOIN inventory.quantity_publication_attempts attempt ON attempt.id=member.attempt_id WHERE member.resume_id=NEW.id
        AND (attempt.state<>'superseded_unknown' OR (to_jsonb(attempt)-'state') IS DISTINCT FROM (member.before_record-'state'))) THEN
    RAISE EXCEPTION 'Publication recovery decision and every preserved attempt must commit together' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: check_publication_no_request_recovery_complete(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_publication_no_request_recovery_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF NOT EXISTS(SELECT 1 FROM inventory.quantity_publication_attempts a WHERE a.id=NEW.attempt_id
    AND a.state='not_sent' AND a.resolution_basis='owner_preflight_no_request' AND a.outcome_hash=NEW.evidence_hash) THEN
    RAISE EXCEPTION 'No-request recovery receipt and transition must commit together' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: check_publication_reconciliation_complete(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_publication_reconciliation_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE retained_ids jsonb; reviewed_ids jsonb;
BEGIN
  SELECT jsonb_agg(member.attempt_id::text ORDER BY member.attempt_id) INTO retained_ids
    FROM inventory.quantity_publication_reconciliation_attempts member WHERE member.reconciliation_id=NEW.id;
  SELECT jsonb_agg(reviewed->>'attemptId' ORDER BY (reviewed->>'attemptId')::bigint) INTO reviewed_ids
    FROM jsonb_array_elements(NEW.review_payload->'attempts') reviewed;
  IF retained_ids IS NULL OR retained_ids IS DISTINCT FROM NEW.result_payload->'supersededAttemptIds'
      OR retained_ids IS DISTINCT FROM reviewed_ids
      OR EXISTS(SELECT 1 FROM inventory.quantity_publication_reconciliation_attempts member
        JOIN inventory.quantity_publication_attempts attempt ON attempt.id=member.attempt_id
        WHERE member.reconciliation_id=NEW.id AND (attempt.state<>'superseded_unknown'
          OR (to_jsonb(attempt)-'state') IS DISTINCT FROM (member.before_record-'state'))) THEN
    RAISE EXCEPTION 'Reconciliation receipt and every retained attempt must commit together' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: check_publication_response_recovery_complete(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_publication_response_recovery_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF NOT EXISTS(SELECT 1 FROM inventory.quantity_publication_attempts a WHERE a.id=NEW.attempt_id AND a.state='resolved'
    AND a.resolution_basis='provider_response_terminal' AND a.outcome_hash=NEW.evidence_hash) THEN
    RAISE EXCEPTION 'Response recovery receipt and transition must commit together' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: check_publication_source_binding_head_coherence(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_publication_source_binding_head_coherence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  checked_target_id INTEGER := NEW.publication_target_id;
BEGIN
  IF EXISTS (
    SELECT 1
    FROM inventory.publication_source_binding_heads AS head
    LEFT JOIN inventory.publication_source_binding_versions AS active ON active.id = head.active_binding_id
    LEFT JOIN inventory.publication_source_binding_versions AS draft ON draft.id = head.draft_binding_id
    WHERE head.publication_target_id = checked_target_id
      AND (
        (active.id IS NOT NULL AND active.lifecycle_status <> 'sealed')
        OR (draft.id IS NOT NULL AND draft.lifecycle_status <> 'draft')
      )
  ) THEN
    RAISE EXCEPTION 'publication source binding head lifecycle is incoherent';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: check_publication_variant_mapping_head_coherence(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_publication_variant_mapping_head_coherence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  checked_target_id INTEGER := NEW.publication_target_id;
  checked_variant_id INTEGER := NEW.product_variant_id;
BEGIN
  IF EXISTS (
    SELECT 1
    FROM inventory.publication_variant_mapping_heads AS head
    LEFT JOIN inventory.publication_variant_mapping_versions AS active
      ON active.id = head.active_mapping_id
    LEFT JOIN inventory.publication_variant_mapping_versions AS draft
      ON draft.id = head.draft_mapping_id
    WHERE head.publication_target_id = checked_target_id
      AND head.product_variant_id = checked_variant_id
      AND (
        (active.id IS NOT NULL AND active.lifecycle_status <> 'sealed')
        OR (draft.id IS NOT NULL AND draft.lifecycle_status <> 'draft')
      )
  ) THEN
    RAISE EXCEPTION 'publication variant mapping head lifecycle is incoherent';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM inventory.publication_variant_mapping_versions AS mapping
    LEFT JOIN inventory.publication_variant_mapping_heads AS head
      ON head.publication_target_id = mapping.publication_target_id
     AND head.product_variant_id = mapping.product_variant_id
     AND head.draft_mapping_id = mapping.id
    WHERE mapping.publication_target_id = checked_target_id
      AND mapping.product_variant_id = checked_variant_id
      AND mapping.lifecycle_status = 'draft'
      AND head.draft_mapping_id IS NULL
  ) THEN
    RAISE EXCEPTION 'a draft publication variant mapping must be owned by its exact head';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM inventory.publication_variant_mapping_heads AS head
    JOIN inventory.publication_variant_mapping_versions AS mapping
      ON mapping.id = COALESCE(head.draft_mapping_id, head.active_mapping_id)
    WHERE head.publication_target_id = checked_target_id
    GROUP BY mapping.external_inventory_item_id
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'one provider inventory item cannot map to multiple SKUs in the same publication target';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_pick_movement_cost_total(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.enforce_pick_movement_cost_total() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.total_cost_mills::numeric = NEW.unit_cost_mills::numeric * NEW.quantity::numeric THEN
    RETURN NEW;
  END IF;
  -- Pick rows link a positive cost row; unpick rows link its negative reversal.
  IF EXISTS (
    SELECT 1 FROM oms.order_item_costs cost
    WHERE cost.id = NEW.order_item_cost_id
      AND cost.cost_quantity_allocation_id IS NOT NULL
      AND abs(cost.qty::numeric) = NEW.quantity::numeric
      AND abs(cost.total_cost_mills::numeric) = NEW.total_cost_mills::numeric
  ) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'availability_claim_pick_movements_cost_chk',
    MESSAGE = 'Pick movement cost must equal unit cost times quantity, or exactly mirror its quantity-allocated order item cost.';
END;
$$;


--
-- Name: gate_publication_selection_change(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.gate_publication_selection_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  -- Fail/retry rather than invert locks held by an existing multi-step owner.
  -- ACK/projection writes do not take this exclusive gate: some occur inside an
  -- admitted provider request that already owns its shared side.
  IF NOT pg_try_advisory_xact_lock(918419,0) THEN
    RAISE EXCEPTION USING ERRCODE='55P03', MESSAGE='PUBLICATION_SELECTION_BUSY';
  END IF;
  IF TG_LEVEL='ROW' THEN RETURN NEW; END IF;
  RETURN NULL;
END;
$$;


--
-- Name: guard_availability_activation_freeze_update(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_availability_activation_freeze_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF OLD.activation_run_id IS DISTINCT FROM NEW.activation_run_id
     OR OLD.source_dry_run_id IS DISTINCT FROM NEW.source_dry_run_id
     OR OLD.evidence_hash IS DISTINCT FROM NEW.evidence_hash
     OR OLD.acquired_by IS DISTINCT FROM NEW.acquired_by
     OR OLD.acquired_at IS DISTINCT FROM NEW.acquired_at THEN
    RAISE EXCEPTION 'activation freeze acquisition evidence is immutable';
  END IF;
  IF OLD.released_at IS NOT NULL THEN
    RAISE EXCEPTION 'a released activation freeze is immutable';
  END IF;
  IF NEW.released_at IS NULL
     OR NEW.released_by IS NULL OR btrim(NEW.released_by) = ''
     OR NEW.release_reason IS NULL OR btrim(NEW.release_reason) = '' THEN
    RAISE EXCEPTION 'activation freeze release evidence is incomplete';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_availability_activation_run_update(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_availability_activation_run_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.mode IS DISTINCT FROM OLD.mode
     OR NEW.scope IS DISTINCT FROM OLD.scope
     OR NEW.source_dry_run_id IS DISTINCT FROM OLD.source_dry_run_id
     OR NEW.provider_publication_required IS DISTINCT FROM OLD.provider_publication_required
     OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
     OR NEW.expected_catalog_input_hash IS DISTINCT FROM OLD.expected_catalog_input_hash
     OR NEW.expected_catalog_result_hash IS DISTINCT FROM OLD.expected_catalog_result_hash
     OR NEW.captured_catalog_input_hash IS DISTINCT FROM OLD.captured_catalog_input_hash
     OR NEW.captured_catalog_result_hash IS DISTINCT FROM OLD.captured_catalog_result_hash
     OR NEW.evidence_payload IS DISTINCT FROM OLD.evidence_payload
     OR NEW.blocker_codes IS DISTINCT FROM OLD.blocker_codes
     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.reason IS DISTINCT FROM OLD.reason
     OR NEW.requested_by IS DISTINCT FROM OLD.requested_by
     OR NEW.started_at IS DISTINCT FROM OLD.started_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'activation run request and captured evidence are immutable';
  END IF;

  IF OLD.mode = 'dry_run' THEN
    RAISE EXCEPTION 'dry-run activation evidence is append-only';
  END IF;

  IF OLD.runtime_authority_changed AND NOT NEW.runtime_authority_changed THEN
    RAISE EXCEPTION 'runtime authority evidence cannot be cleared';
  END IF;
  IF OLD.provider_write_attempted AND NOT NEW.provider_write_attempted THEN
    RAISE EXCEPTION 'provider-write evidence cannot be cleared';
  END IF;
  IF OLD.outbox_enqueued AND NOT NEW.outbox_enqueued THEN
    RAISE EXCEPTION 'outbox evidence cannot be cleared';
  END IF;

  IF NEW.state IS DISTINCT FROM OLD.state AND NOT (
    (OLD.state = 'validating' AND NEW.state IN ('blocked', 'ready_for_publication', 'failed'))
    OR (OLD.state = 'blocked' AND NEW.state = 'validating')
    OR (OLD.state = 'ready_for_publication' AND NEW.state IN ('validating', 'publishing', 'failed'))
    OR (OLD.state = 'publishing' AND NEW.state IN ('publication_verified', 'failed'))
    OR (OLD.state = 'publication_verified' AND NEW.state IN ('activating', 'failed'))
    OR (OLD.state = 'activating' AND NEW.state IN ('active', 'failed'))
  ) THEN
    RAISE EXCEPTION 'invalid activation state transition from % to %', OLD.state, NEW.state;
  END IF;

  IF NEW.provider_publication_required
     AND NEW.state IN ('publishing', 'publication_verified', 'activating', 'active')
     AND NOT NEW.outbox_enqueued THEN
    RAISE EXCEPTION 'publication states require durable outbox evidence';
  END IF;
  IF NEW.provider_publication_required
     AND NEW.state IN ('publication_verified', 'activating', 'active')
     AND NOT NEW.provider_write_attempted THEN
    RAISE EXCEPTION 'verified publication states require provider-attempt evidence';
  END IF;
  IF NEW.state = 'active' AND NOT NEW.runtime_authority_changed THEN
    RAISE EXCEPTION 'active state requires canonical runtime authority evidence';
  END IF;

  IF NEW.prepared_at IS DISTINCT FROM OLD.prepared_at AND OLD.prepared_at IS NOT NULL THEN
    RAISE EXCEPTION 'prepared milestone is immutable once recorded';
  END IF;
  IF NEW.publication_verified_at IS DISTINCT FROM OLD.publication_verified_at
     AND OLD.publication_verified_at IS NOT NULL THEN
    RAISE EXCEPTION 'publication verified milestone is immutable once recorded';
  END IF;
  IF NEW.activated_at IS DISTINCT FROM OLD.activated_at AND OLD.activated_at IS NOT NULL THEN
    RAISE EXCEPTION 'activation milestone is immutable once recorded';
  END IF;
  IF NEW.failed_at IS DISTINCT FROM OLD.failed_at AND OLD.failed_at IS NOT NULL THEN
    RAISE EXCEPTION 'failure milestone is immutable once recorded';
  END IF;

  NEW.updated_at := transaction_timestamp();
  RETURN NEW;
END;
$$;


--
-- Name: guard_availability_runtime_authority_update(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_availability_runtime_authority_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  activation_state VARCHAR(40);
BEGIN
  IF OLD.singleton_key IS DISTINCT FROM NEW.singleton_key THEN
    RAISE EXCEPTION 'runtime authority singleton identity is immutable';
  END IF;
  IF NEW.revision <> OLD.revision + 1 THEN
    RAISE EXCEPTION 'runtime authority revision must increment by 1';
  END IF;
  IF OLD.authority = 'canonical' AND NEW.authority <> 'canonical' THEN
    RAISE EXCEPTION 'the first canonical cutover cannot return to legacy authority';
  END IF;
  IF OLD.authority = 'legacy' AND NEW.authority = 'canonical' THEN
    SELECT state INTO activation_state
    FROM inventory.availability_activation_runs
    WHERE id = NEW.activation_run_id
    FOR SHARE;
    IF activation_state <> 'activating' THEN
      RAISE EXCEPTION 'canonical authority requires its activation run to be activating';
    END IF;
  ELSIF NEW.authority IS DISTINCT FROM OLD.authority
     OR NEW.activation_run_id IS DISTINCT FROM OLD.activation_run_id THEN
    RAISE EXCEPTION 'invalid runtime authority transition';
  END IF;
  NEW.changed_at := transaction_timestamp();
  RETURN NEW;
END;
$$;


--
-- Name: guard_build_order_transformation_authority(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_build_order_transformation_authority() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.transformation_authority = 'canonical'
     AND ROW(
       NEW.transformation_authority,
       NEW.transformation_authority_revision,
       NEW.transformation_activation_run_id,
       NEW.transformation_model_head_revision,
       NEW.transformation_model_id,
       NEW.transformation_model_version,
       NEW.transformation_model_definition_hash,
       NEW.transformation_recipe_binding_id,
       NEW.transformation_recipe_definition_hash,
       NEW.transformation_authorized_at,
       NEW.transformation_authorized_by
     ) IS DISTINCT FROM ROW(
       OLD.transformation_authority,
       OLD.transformation_authority_revision,
       OLD.transformation_activation_run_id,
       OLD.transformation_model_head_revision,
       OLD.transformation_model_id,
       OLD.transformation_model_version,
       OLD.transformation_model_definition_hash,
       OLD.transformation_recipe_binding_id,
       OLD.transformation_recipe_definition_hash,
       OLD.transformation_authorized_at,
       OLD.transformation_authorized_by
     ) THEN
    RAISE EXCEPTION 'canonical build transformation authority evidence is immutable'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_channel_definition_application(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_channel_definition_application() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Channel definition receipts are immutable' USING ERRCODE='55000'; END IF;
  PERFORM inventory.assert_cutover_admission_fence_owner();
  RETURN NEW;
END $$;


--
-- Name: guard_channel_exposure_draft_update(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_channel_exposure_draft_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION '% is append-only', TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME;
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.scope_key IS DISTINCT FROM OLD.scope_key
     OR NEW.channel_id IS DISTINCT FROM OLD.channel_id
     OR NEW.scope_type IS DISTINCT FROM OLD.scope_type
     OR NEW.product_id IS DISTINCT FROM OLD.product_id
     OR NEW.product_variant_id IS DISTINCT FROM OLD.product_variant_id
     OR NEW.version IS DISTINCT FROM OLD.version
     OR NEW.supersedes_policy_id IS DISTINCT FROM OLD.supersedes_policy_id
     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'channel exposure policy identity and request evidence are immutable';
  END IF;
  IF OLD.lifecycle_status = 'draft' AND NEW.lifecycle_status IN ('draft', 'sealed')
     AND NOT EXISTS (
    SELECT 1 FROM inventory.channel_exposure_policy_heads AS head
    WHERE head.scope_key = OLD.scope_key AND head.draft_policy_id = OLD.id
  ) THEN
    RAISE EXCEPTION 'only the policy referenced by the draft head may be edited';
  END IF;
  IF NEW.lifecycle_status <> 'draft' AND (
    NEW.allocation_semantics IS DISTINCT FROM OLD.allocation_semantics
    OR NEW.eligible IS DISTINCT FROM OLD.eligible
    OR NEW.share_bps IS DISTINCT FROM OLD.share_bps
    OR NEW.holdback_sellable_units IS DISTINCT FROM OLD.holdback_sellable_units
    OR NEW.max_publish_mode IS DISTINCT FROM OLD.max_publish_mode
    OR NEW.max_publish_sellable_units IS DISTINCT FROM OLD.max_publish_sellable_units
    OR NEW.min_publish_sellable_units IS DISTINCT FROM OLD.min_publish_sellable_units
    OR NEW.definition_hash IS DISTINCT FROM OLD.definition_hash
    OR NEW.change_reason IS DISTINCT FROM OLD.change_reason
  ) THEN
    RAISE EXCEPTION 'sealed channel exposure definition is immutable';
  END IF;
  IF OLD.lifecycle_status = 'draft' AND NEW.lifecycle_status = 'sealed'
     AND NEW.scope_type = 'channel'
     AND (NEW.allocation_semantics IS NULL OR NEW.eligible IS NULL OR NEW.share_bps IS NULL
       OR NEW.holdback_sellable_units IS NULL OR NEW.max_publish_mode IS NULL
       OR NEW.min_publish_sellable_units IS NULL) THEN
    RAISE EXCEPTION 'a channel default must resolve every exposure field before sealing';
  END IF;
  IF NOT (
    (OLD.lifecycle_status = 'draft' AND NEW.lifecycle_status IN ('draft', 'sealed'))
    OR (OLD.lifecycle_status = 'sealed' AND NEW.lifecycle_status = 'retired')
  ) THEN
    RAISE EXCEPTION 'invalid channel exposure lifecycle transition from % to %',
      OLD.lifecycle_status, NEW.lifecycle_status;
  END IF;
  NEW.updated_at := transaction_timestamp();
  RETURN NEW;
END;
$$;


--
-- Name: guard_channel_exposure_policy_head_write(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_channel_exposure_policy_head_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'channel exposure policy heads cannot be deleted';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.revision <> 1 THEN
    RAISE EXCEPTION 'new channel exposure policy head revision must be 1';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.scope_key IS DISTINCT FROM OLD.scope_key
    OR NEW.channel_id IS DISTINCT FROM OLD.channel_id
    OR NEW.revision <> OLD.revision + 1
  ) THEN
    RAISE EXCEPTION 'channel exposure policy head identity is immutable and revision must increment by 1';
  END IF;
  NEW.updated_at := transaction_timestamp();
  RETURN NEW;
END;
$$;


--
-- Name: guard_channel_policy_source_references(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_channel_policy_source_references() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='TRUNCATE' OR pg_trigger_depth()<>2 THEN
    RAISE EXCEPTION 'Channel supply references are maintained by their policy version' USING ERRCODE='55000';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_channel_policy_supply(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_channel_policy_supply() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='UPDATE' AND (OLD.lifecycle_status<>'draft' OR NEW.lifecycle_status<>'draft')
    AND (NEW.source_fulfillment_node_ids IS DISTINCT FROM OLD.source_fulfillment_node_ids
      OR NEW.inherit_all IS DISTINCT FROM OLD.inherit_all) THEN
    RAISE EXCEPTION 'Sealed channel supply and inheritance are immutable' USING ERRCODE='55000';
  END IF;
  -- Retiring historical definitions must remain possible after a source retires.
  -- Their FK references stay intact; only draft/sealed usability is checked here.
  IF NEW.lifecycle_status<>'retired' AND NEW.source_fulfillment_node_ids IS NOT NULL AND (
    (SELECT count(DISTINCT warehouse_id) FROM warehouse.fulfillment_nodes
      WHERE id=ANY(NEW.source_fulfillment_node_ids) AND lifecycle_status<>'retired')
      <> cardinality(NEW.source_fulfillment_node_ids)
  ) THEN
    RAISE EXCEPTION 'Channel supply must reference distinct usable warehouses' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_cutover_admission_owner_write(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_cutover_admission_owner_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE authority_row inventory.availability_runtime_authority%ROWTYPE;
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='CUTOVER_ADMISSION_SINGLETON_IMMUTABLE';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed'
     OR current_setting('transaction_read_only') <> 'off' THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='CUTOVER_READ_COMMITTED_TRANSACTION_REQUIRED';
  END IF;
  SELECT * INTO authority_row FROM inventory.availability_runtime_authority
    WHERE singleton_key=true FOR UPDATE NOWAIT;
  IF NOT FOUND OR authority_row.authority IS NULL OR authority_row.authority NOT IN ('legacy','canonical')
     OR authority_row.revision IS NULL OR authority_row.revision <= 0
     OR (authority_row.authority='legacy' AND authority_row.activation_run_id IS NOT NULL)
     OR (authority_row.authority='canonical' AND authority_row.activation_run_id IS NULL) THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='CUTOVER_AUTHORITY_INVALID';
  END IF;
  IF NEW.singleton_key IS DISTINCT FROM OLD.singleton_key
     OR NEW.epoch IS DISTINCT FROM OLD.epoch + 1
     OR NEW.owner_transaction_id IS DISTINCT FROM pg_current_xact_id()
     OR NEW.changed_at IS DISTINCT FROM transaction_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='CUTOVER_ADMISSION_OWNER_INVALID';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_cutover_commit_receipt_insert(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_cutover_commit_receipt_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  -- Function is installed by the later admission migration; PostgreSQL resolves
  -- this PL/pgSQL body when the command runs, not while creating the empty table.
  PERFORM inventory.assert_cutover_admission_fence_owner();
  IF NOT EXISTS (SELECT 1 FROM inventory.availability_runtime_authority authority
    JOIN inventory.availability_activation_runs activation ON activation.id=authority.activation_run_id
    WHERE authority.singleton_key=true AND authority.authority='canonical'
      AND authority.activation_run_id=NEW.activation_run_id AND authority.revision=NEW.authority_revision
      AND activation.state='active') THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='CUTOVER_RECEIPT_AUTHORITY_MISMATCH';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_cutover_configuration_write(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_cutover_configuration_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE owner_xid xid8; frozen_run_id bigint; field_path text;
        old_row jsonb; new_row jsonb; semantic_changed boolean;
BEGIN
  -- The statement trigger already pinned admission SHARE. Therefore the freeze
  -- cannot change until this statement's transaction completes.
  SELECT owner_transaction_id INTO owner_xid FROM inventory.cutover_admission_fence WHERE singleton_key=true;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='CUTOVER_ADMISSION_SINGLETON_MISSING';
  END IF;
  IF owner_xid IS NOT NULL AND owner_xid = pg_current_xact_id_if_assigned() THEN
    IF TG_LEVEL='STATEMENT' THEN RETURN NULL; END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  SELECT activation_run_id INTO frozen_run_id FROM inventory.availability_activation_freezes WHERE released_at IS NULL;
  IF frozen_run_id IS NULL THEN
    IF TG_LEVEL='STATEMENT' THEN RETURN NULL; END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  semantic_changed := TG_OP <> 'UPDATE';
  IF TG_OP='UPDATE' THEN
    old_row := to_jsonb(OLD); new_row := to_jsonb(NEW);
    FOREACH field_path IN ARRAY TG_ARGV LOOP
      IF field_path='*' THEN
        semantic_changed := (old_row - 'updated_at') IS DISTINCT FROM (new_row - 'updated_at');
      ELSE
        semantic_changed := (old_row #> string_to_array(field_path,'.'))
          IS DISTINCT FROM (new_row #> string_to_array(field_path,'.'));
      END IF;
      EXIT WHEN semantic_changed;
    END LOOP;
  END IF;
  IF semantic_changed THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='CUTOVER_CONFIGURATION_FROZEN',
      DETAIL=format('activation_run_id=%s table=%I.%I',frozen_run_id,TG_TABLE_SCHEMA,TG_TABLE_NAME);
  END IF;
  IF TG_LEVEL='STATEMENT' THEN RETURN NULL; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_cutover_control_write(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_cutover_control_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM inventory.assert_cutover_admission_fence_owner();
  RETURN NULL;
END;
$$;


--
-- Name: guard_cutover_history_audit(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_cutover_history_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE batch inventory.cutover_history_batches%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'CUTOVER_HISTORY_AUDIT_IMMUTABLE'; END IF;
  PERFORM inventory.assert_cutover_admission_fence_owner();
  IF TG_TABLE_NAME='cutover_history_batches' THEN
    IF NEW.created_xid <> pg_current_xact_id() OR NEW.occurred_at <> transaction_timestamp() THEN
      RAISE EXCEPTION 'CUTOVER_HISTORY_AUDIT_TRANSACTION_MISMATCH';
    END IF;
  ELSE
    SELECT * INTO STRICT batch FROM inventory.cutover_history_batches WHERE id=NEW.batch_id;
    IF batch.created_xid <> pg_current_xact_id()
      OR NEW.decision_payload->>'kind' IS DISTINCT FROM NEW.kind
      OR NEW.decision_payload->>'id' IS DISTINCT FROM COALESCE(NEW.receipt_id,NEW.shipment_id::bigint)::text
      OR NOT (batch.review_payload->'decisions' @> jsonb_build_array(NEW.decision_payload)) THEN
      RAISE EXCEPTION 'CUTOVER_HISTORY_AUDIT_MEMBERSHIP_MISMATCH';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_cutover_opening_snapshot_insert(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_cutover_opening_snapshot_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE current_revision bigint; current_configuration_run_id bigint; freeze_count bigint;
BEGIN
  -- Recording a verification uses the same drained, exclusive admission as the
  -- eventual cutover. The evidence capture and this insert share that fence.
  PERFORM inventory.assert_cutover_admission_fence_owner();
  SELECT revision INTO current_revision FROM inventory.availability_runtime_authority
    WHERE singleton_key = true AND authority = 'legacy' AND activation_run_id IS NULL;
  IF NOT FOUND OR current_revision IS DISTINCT FROM NEW.authority_revision THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='CUTOVER_OPENING_AUTHORITY_CHANGED';
  END IF;
  SELECT count(*), max(activation_run_id) INTO freeze_count, current_configuration_run_id
    FROM inventory.availability_activation_freezes WHERE released_at IS NULL;
  IF freeze_count > 1 OR current_configuration_run_id IS DISTINCT FROM NEW.configuration_run_id THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='CUTOVER_OPENING_CONFIGURATION_CHANGED';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_definition_head_write(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_definition_head_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  active_id integer;
  draft_id integer;
  active_status varchar(20);
  draft_status varchar(20);
  old_row jsonb := '{}'::jsonb;
  new_row jsonb := '{}'::jsonb;
  old_revision bigint;
  new_revision bigint;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    old_row := to_jsonb(OLD);
  END IF;
  IF TG_OP <> 'DELETE' THEN
    new_row := to_jsonb(NEW);
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF TG_TABLE_NAME = 'location_promise_policy_heads'
       AND new_row -> 'warehouse_location_id'
         IS DISTINCT FROM old_row -> 'warehouse_location_id' THEN
      RAISE EXCEPTION '% owner key is immutable', TG_TABLE_NAME;
    ELSIF TG_TABLE_NAME = 'transformation_model_heads'
       AND new_row -> 'product_id' IS DISTINCT FROM old_row -> 'product_id' THEN
      RAISE EXCEPTION '% owner key is immutable', TG_TABLE_NAME;
    ELSIF TG_TABLE_NAME = 'promise_safety_policy_heads'
       AND new_row -> 'scope_key' IS DISTINCT FROM old_row -> 'scope_key' THEN
      RAISE EXCEPTION '% owner key is immutable', TG_TABLE_NAME;
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION '% heads cannot be deleted', TG_TABLE_NAME;
  END IF;

  IF TG_TABLE_NAME = 'location_promise_policy_heads' THEN
    PERFORM pg_advisory_xact_lock(
      918421,
      NULLIF(new_row ->> 'warehouse_location_id', '')::integer
    );
  ELSIF TG_TABLE_NAME = 'transformation_model_heads' THEN
    PERFORM pg_advisory_xact_lock(918422, NULLIF(new_row ->> 'product_id', '')::integer);
  ELSIF TG_TABLE_NAME = 'promise_safety_policy_heads' THEN
    PERFORM pg_advisory_xact_lock(918423, hashtext(new_row ->> 'scope_key'));
  END IF;

  old_revision := NULLIF(old_row ->> 'revision', '')::bigint;
  new_revision := NULLIF(new_row ->> 'revision', '')::bigint;
  IF TG_OP = 'INSERT' AND new_revision <> 0 THEN
    RAISE EXCEPTION '% initial revision must be zero', TG_TABLE_NAME;
  ELSIF TG_OP = 'UPDATE' AND new_revision <> old_revision + 1 THEN
    RAISE EXCEPTION '% revision must advance exactly once', TG_TABLE_NAME;
  END IF;

  IF TG_TABLE_NAME = 'location_promise_policy_heads' THEN
    active_id := NULLIF(new_row ->> 'active_policy_id', '')::integer;
    draft_id := NULLIF(new_row ->> 'draft_policy_id', '')::integer;
    IF active_id IS NOT NULL THEN
      SELECT lifecycle_status INTO active_status
      FROM inventory.location_promise_policy_versions
      WHERE id = active_id FOR KEY SHARE;
    END IF;
    IF draft_id IS NOT NULL THEN
      SELECT lifecycle_status INTO draft_status
      FROM inventory.location_promise_policy_versions
      WHERE id = draft_id FOR KEY SHARE;
    END IF;
  ELSIF TG_TABLE_NAME = 'transformation_model_heads' THEN
    active_id := NULLIF(new_row ->> 'active_model_id', '')::integer;
    draft_id := NULLIF(new_row ->> 'draft_model_id', '')::integer;
    IF active_id IS NOT NULL THEN
      SELECT lifecycle_status INTO active_status
      FROM inventory.transformation_model_versions
      WHERE id = active_id FOR KEY SHARE;
    END IF;
    IF draft_id IS NOT NULL THEN
      SELECT lifecycle_status INTO draft_status
      FROM inventory.transformation_model_versions
      WHERE id = draft_id FOR KEY SHARE;
    END IF;
  ELSIF TG_TABLE_NAME = 'promise_safety_policy_heads' THEN
    active_id := NULLIF(new_row ->> 'active_policy_id', '')::integer;
    draft_id := NULLIF(new_row ->> 'draft_policy_id', '')::integer;
    IF active_id IS NOT NULL THEN
      SELECT lifecycle_status INTO active_status
      FROM inventory.promise_safety_policy_versions
      WHERE id = active_id FOR KEY SHARE;
    END IF;
    IF draft_id IS NOT NULL THEN
      SELECT lifecycle_status INTO draft_status
      FROM inventory.promise_safety_policy_versions
      WHERE id = draft_id FOR KEY SHARE;
    END IF;
  ELSE
    RAISE EXCEPTION 'unsupported definition head table %', TG_TABLE_NAME;
  END IF;

  IF active_id IS NOT NULL AND active_status IS DISTINCT FROM 'sealed' THEN
    RAISE EXCEPTION '% active pointer must reference a sealed definition', TG_TABLE_NAME;
  END IF;
  IF draft_id IS NOT NULL AND draft_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION '% draft pointer must reference a draft definition', TG_TABLE_NAME;
  END IF;
  RETURN NEW;
END;
$$;


