--
-- Name: guard_ebay_automatic_publication_recovery(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_ebay_automatic_publication_recovery() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE attempt inventory.quantity_publication_attempts%ROWTYPE; actual jsonb; request_count integer; legacy_proven boolean := false; source_count integer; source jsonb; old_target jsonb; new_target jsonb; expected_skus text[];
BEGIN
  SELECT * INTO attempt FROM inventory.quantity_publication_attempts WHERE id=NEW.attempt_id;
  PERFORM inventory.assert_ebay_operator_resume_locks(NEW.scope_keys);
  IF NEW.owner_transaction_id IS DISTINCT FROM pg_current_xact_id()
    OR attempt.state NOT IN ('running','uncertain') OR attempt.owner_kind NOT IN ('legacy','outbox')
    OR attempt.scope->>'providerKey' IS DISTINCT FROM 'ebay'
    OR attempt.scope->>'providerScopeType' IS DISTINCT FROM 'account'
    OR NOT attempt.affected_scope_keys <@ NEW.scope_keys
    OR to_jsonb(attempt) IS DISTINCT FROM NEW.before_record
    OR NOT EXISTS(SELECT 1 FROM inventory.ebay_publication_reconciliation_watches watch WHERE watch.id=NEW.watch_id
      AND watch.scope_hash=NEW.scope_hash AND watch.state='pending') THEN
    RAISE EXCEPTION 'Automatic replacement requires exact unresolved ownership and durable recurring reconciliation' USING ERRCODE='23514';
  END IF;

  IF NEW.legacy_maintenance_source IS NOT NULL THEN
    SELECT count(*),jsonb_agg(s.source)->0 INTO source_count,source
      FROM channels.legacy_maintenance_replacement_sources(NEW.attempt_id,NEW.sync_job_id,NEW.sync_revision) s;
    old_target := source->'job'->'identity'; new_target := source->'current'->'identity';
    IF source_count IS DISTINCT FROM 1 OR source IS DISTINCT FROM NEW.legacy_maintenance_source
      OR attempt.owner_kind<>'legacy' OR attempt.request_journal_contract IS NOT NULL
      OR source#>>'{job,operation}' IS DISTINCT FROM 'sync'
      OR source#>>'{stage,event}' IS DISTINCT FROM 'stage_started'
      OR source#>>'{next,event}' NOT IN ('recovering','awaiting_evidence','needs_attention')
      OR source#>>'{stage,revision}' IS DISTINCT FROM source#>>'{next,revision}'
      OR source#>>'{stage,ownerToken}' IS NULL
      OR source#>>'{stage,ownerToken}' IS DISTINCT FROM source#>>'{next,ownerToken}'
      OR COALESCE(source#>>'{stage,evidence,preparedIntentHash}','') !~ '^[a-f0-9]{64}$'
      OR source#>>'{next,evidence,code}' IS DISTINCT FROM 'EBAY_LISTING_SYNC_FAILED'
      OR COALESCE(source#>>'{next,evidence,message}','') !~ '^eBay API (GET|PUT) /sell/inventory/v1/(inventory_item|inventory_item_group|offer)(/[^[:space:]?#]+|\?[^[:space:]#]+) failed \([45][0-9]{2}\): '
      OR channels.maintenance_resource_identity(old_target) IS DISTINCT FROM channels.maintenance_resource_identity(new_target)
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(old_target->'variants') m WHERE
        COALESCE(m->>'offerId','')='' OR COALESCE(m->>'listingId','')='' OR m->>'externalSku' IS DISTINCT FROM m->>'sku') THEN
      RAISE EXCEPTION 'Legacy replacement requires uniquely attributable failed maintenance and the same verified resources' USING ERRCODE='23514';
    END IF;
    IF old_target->>'groupKey' IS NOT NULL AND source#>>'{stage,evidence,key}'='group:'||(old_target->>'groupKey') THEN
      expected_skus := ARRAY(SELECT m->>'sku' FROM jsonb_array_elements(old_target->'variants') m) || ARRAY['group:'||(old_target->>'groupKey')];
      legacy_proven := attempt.scope->>'externalInventoryItemId'='group:'||(old_target->>'groupKey');
    ELSE
      SELECT ARRAY[m->>'sku'] INTO expected_skus FROM jsonb_array_elements(old_target->'variants') m
        WHERE source#>>'{stage,evidence,key}' IN ('item:'||(m->>'sku'),'offer:'||(m->>'offerId'));
      legacy_proven := cardinality(expected_skus)=1 AND attempt.scope->>'externalInventoryItemId'=expected_skus[1];
    END IF;
    IF legacy_proven IS DISTINCT FROM true OR cardinality(expected_skus)<>jsonb_array_length(attempt.affected_scopes)
      OR ARRAY(SELECT DISTINCT s->>'externalInventoryItemId' FROM jsonb_array_elements(attempt.affected_scopes) s ORDER BY 1)
        IS DISTINCT FROM ARRAY(SELECT unnest(expected_skus) ORDER BY 1)
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(attempt.affected_scopes) s WHERE
        s->>'connectionId' IS DISTINCT FROM old_target->>'connectionId' OR s->>'externalScopeId' IS DISTINCT FROM old_target->>'accountId'
        OR s->>'providerKey' IS DISTINCT FROM 'ebay' OR s->>'providerScopeType' IS DISTINCT FROM 'account'
        OR s->>'destinationKind' IS DISTINCT FROM 'channel_connection')
      OR NOT EXISTS(SELECT 1 FROM inventory.ebay_publication_reconciliation_watches w WHERE w.id=NEW.watch_id
        AND w.connection_id=(new_target->>'connectionId')::integer AND w.product_id=(new_target->>'productId')::integer
        AND w.external_scope_id=new_target->>'accountId'
        AND jsonb_array_length(w.scopes)=jsonb_array_length(new_target->'variants')+CASE WHEN new_target->>'groupKey' IS NULL THEN 0 ELSE 1 END
        AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(w.scopes) s WHERE
          s->>'connectionId' IS DISTINCT FROM new_target->>'connectionId' OR s->>'externalScopeId' IS DISTINCT FROM new_target->>'accountId'
          OR s->>'productId' IS DISTINCT FROM new_target->>'productId' OR s->>'providerKey' IS DISTINCT FROM 'ebay'
          OR s->>'providerScopeType' IS DISTINCT FROM 'account' OR s->>'destinationKind' IS DISTINCT FROM 'channel_connection'
          OR NOT ((s->>'externalInventoryItemId'='group:'||(new_target->>'groupKey') AND s->>'productVariantId' IS NULL)
            OR EXISTS(SELECT 1 FROM jsonb_array_elements(new_target->'variants') m
              WHERE m->>'sku'=s->>'externalInventoryItemId' AND m->>'variantId'=s->>'productVariantId')))) THEN
      RAISE EXCEPTION 'Legacy replacement must cover every exact old effect and current catalog resource' USING ERRCODE='23514';
    END IF;
  END IF;
  SELECT count(*),COALESCE(jsonb_agg(jsonb_build_object('request_record',to_jsonb(q),'result_record',to_jsonb(r)) ORDER BY q.ordinal),'[]'::jsonb)
    INTO request_count,actual FROM inventory.quantity_provider_requests q LEFT JOIN inventory.quantity_provider_request_results r ON r.request_id=q.id
    WHERE q.attempt_id=NEW.attempt_id;
  IF actual IS DISTINCT FROM NEW.request_evidence OR EXISTS(
    SELECT 1 FROM (SELECT q.*,row_number() OVER(ORDER BY q.ordinal) AS expected FROM inventory.quantity_provider_requests q WHERE q.attempt_id=NEW.attempt_id) q
    WHERE q.ordinal<>q.expected OR NOT (
      (q.method='POST' AND q.path='/sell/inventory/v1/bulk_update_price_quantity')
      OR (q.method='PUT' AND q.path ~ '^/sell/inventory/v1/(inventory_item|inventory_item_group|offer)/[^/?#[:space:]]+$')))
    OR (request_count=0 AND NOT (legacy_proven OR (attempt.owner_kind='outbox' AND cardinality(attempt.affected_scope_keys)=1 AND EXISTS(
      SELECT 1 FROM inventory.inventory_publication_outbox o WHERE o.id=attempt.outbox_id
        AND o.provider_key_snapshot='ebay' AND o.provider_scope_type_snapshot='account'
        AND o.destination_kind_snapshot=attempt.scope->>'destinationKind'
        AND COALESCE(o.channel_connection_id_snapshot,o.dropship_store_connection_id_snapshot)::text=attempt.scope->>'connectionId'
        AND o.external_scope_id_snapshot=attempt.scope->>'externalScopeId'
        AND o.external_inventory_item_id_snapshot=attempt.scope->>'externalInventoryItemId'
        AND o.product_variant_id::text=attempt.scope->>'productVariantId')))) THEN
    RAISE EXCEPTION 'Automatic replacement must preserve every request and prove supported synchronous intent' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $_$;


--
-- Name: guard_ebay_operator_resume(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_ebay_operator_resume() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM inventory.assert_ebay_operator_resume_locks(NEW.scope_keys);
  IF NEW.owner_transaction_id IS DISTINCT FROM pg_current_xact_id()
    OR NEW.review_payload->>'previewHash' IS DISTINCT FROM NEW.preview_hash
    OR NEW.result_payload->>'providerWriteAttempted' IS DISTINCT FROM 'false'
    OR NEW.result_payload->>'replayed' IS DISTINCT FROM 'false'
    OR jsonb_typeof(NEW.result_payload->'attemptIds') IS DISTINCT FROM 'array'
    OR jsonb_array_length(NEW.result_payload->'attemptIds') NOT BETWEEN 0 AND 100 THEN
    RAISE EXCEPTION 'Publication recovery requires the exact reviewed decision' USING ERRCODE='23514';
  END IF;
  IF jsonb_array_length(NEW.result_payload->'attemptIds')=0 THEN
    IF NEW.review_payload->>'canResume' IS DISTINCT FROM 'false'
      OR NEW.review_payload->>'blockReason' IS DISTINCT FROM 'no_pending_attempts'
      OR NEW.review_payload->'attempts' IS DISTINCT FROM '[]'::jsonb
      OR EXISTS(SELECT 1 FROM inventory.quantity_publication_attempts pending
        WHERE pending.state IN ('running','uncertain') AND pending.affected_scope_keys && NEW.scope_keys) THEN
      RAISE EXCEPTION 'Empty recovery must preserve the exact no-pending-attempt review' USING ERRCODE='23514';
    END IF;
  ELSIF NEW.review_payload->>'canResume' IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'Recovery requires an authorized complete review' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_ebay_operator_resume_attempt(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_ebay_operator_resume_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE command inventory.quantity_publication_operator_resumes%ROWTYPE;
  attempt inventory.quantity_publication_attempts%ROWTYPE; actual jsonb;
BEGIN
  SELECT * INTO command FROM inventory.quantity_publication_operator_resumes WHERE id=NEW.resume_id;
  SELECT * INTO attempt FROM inventory.quantity_publication_attempts WHERE id=NEW.attempt_id;
  PERFORM inventory.assert_ebay_operator_resume_locks(command.scope_keys);
  IF command.owner_transaction_id IS DISTINCT FROM pg_current_xact_id()
    OR attempt.state NOT IN ('running','uncertain') OR attempt.owner_kind NOT IN ('legacy','outbox')
    OR COALESCE(attempt.scope->>'providerKey','') NOT IN ('ebay','shopify','walmart')
    OR cardinality(attempt.affected_scope_keys)<1
    OR NOT attempt.affected_scope_keys <@ command.scope_keys
    OR to_jsonb(attempt) IS DISTINCT FROM NEW.before_record
    OR NOT command.result_payload->'attemptIds' @> jsonb_build_array(NEW.attempt_id::text)
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(command.review_payload->'attempts') reviewed
      WHERE reviewed->>'attemptId'=NEW.attempt_id::text) THEN
    RAISE EXCEPTION 'Publication recovery requires the exact unresolved attempt and every affected scope' USING ERRCODE='23514';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('request_record',to_jsonb(q),'result_record',to_jsonb(r)) ORDER BY q.ordinal),'[]'::jsonb)
    INTO actual FROM inventory.quantity_provider_requests q LEFT JOIN inventory.quantity_provider_request_results r ON r.request_id=q.id
    WHERE q.attempt_id=NEW.attempt_id;
  IF actual IS DISTINCT FROM NEW.request_evidence THEN
    RAISE EXCEPTION 'Publication recovery must preserve every recorded request and response' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_ebay_publication_readiness_command(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_ebay_publication_readiness_command() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('ebay-stock:' || NEW.command_key::text,0));
  IF (TG_TABLE_NAME='ebay_publication_readiness_applications' AND EXISTS(SELECT 1 FROM inventory.ebay_publication_readiness_rejections WHERE command_key=NEW.command_key))
    OR (TG_TABLE_NAME='ebay_publication_readiness_rejections' AND EXISTS(SELECT 1 FROM inventory.ebay_publication_readiness_applications WHERE command_key=NEW.command_key)) THEN
    RAISE EXCEPTION 'eBay stock publication command already has an immutable outcome' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_ebay_publication_reconciliation_watch(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_ebay_publication_reconciliation_watch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF TG_OP='DELETE' OR (NEW.id,NEW.product_id,NEW.connection_id,NEW.external_scope_id,NEW.scope_hash,NEW.scopes,NEW.created_at)
    IS DISTINCT FROM (OLD.id,OLD.product_id,OLD.connection_id,OLD.external_scope_id,OLD.scope_hash,OLD.scopes,OLD.created_at)
    OR NEW.revision<OLD.revision OR NEW.cycle<OLD.cycle THEN
    RAISE EXCEPTION 'Recurring recovery identity and history cannot be removed or rewound' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_initial_listing_quantity_evidence(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_initial_listing_quantity_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF NEW.listing_setup_intent IS DISTINCT FROM OLD.listing_setup_intent THEN
    RAISE EXCEPTION 'Initial listing quantity evidence is immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_initial_publication_scope_receipt(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_initial_publication_scope_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE expected_ids integer[]; expected_excluded_ids integer[];
BEGIN
  PERFORM inventory.assert_cutover_admission_fence_owner();
  SELECT COALESCE(array_agg(DISTINCT value ORDER BY value),'{}'::integer[]) INTO expected_ids
    FROM unnest(NEW.included_variant_ids) AS item(value);
  SELECT COALESCE(array_agg(DISTINCT value ORDER BY value),'{}'::integer[]) INTO expected_excluded_ids
    FROM unnest(NEW.excluded_variant_ids) AS item(value);
  IF NEW.owner_transaction_id IS DISTINCT FROM pg_current_xact_id()
    OR NEW.included_variant_ids IS DISTINCT FROM expected_ids
    OR NEW.excluded_variant_ids IS DISTINCT FROM expected_excluded_ids
    OR NEW.included_variant_ids && NEW.excluded_variant_ids
    OR EXISTS(SELECT 1 FROM unnest(expected_ids) AS item(value) WHERE value<=0)
    OR EXISTS(SELECT 1 FROM unnest(expected_excluded_ids) AS item(value) WHERE value<=0)
    OR NOT EXISTS(SELECT 1 FROM inventory.availability_runtime_authority
      WHERE singleton_key=true AND authority='legacy' AND activation_run_id IS NULL AND revision=NEW.authority_revision)
    OR EXISTS(SELECT 1 FROM inventory.availability_activation_freezes WHERE released_at IS NULL)
    OR NOT EXISTS(SELECT 1 FROM inventory.inventory_publication_targets WHERE id=NEW.publication_target_id
      AND revision=NEW.previous_revision AND state='preview' AND publication_authority='echelon' AND membership_mode='whole_product')
    OR EXISTS(SELECT 1 FROM inventory.publication_membership_heads WHERE publication_target_id=NEW.publication_target_id)
    OR EXISTS(SELECT 1 FROM inventory.publication_membership_versions WHERE publication_target_id=NEW.publication_target_id)
    OR NEW.evidence->'review'->'ready' IS DISTINCT FROM 'true'::jsonb
    OR NEW.evidence->'review'->>'reviewHash' IS DISTINCT FROM NEW.review_hash
    OR NEW.evidence->'review'->'includedVariantIds' IS DISTINCT FROM to_jsonb(expected_ids)
    OR NEW.excluded_variant_ids IS DISTINCT FROM ARRAY(
      SELECT (value->>'productVariantId')::integer
      FROM jsonb_array_elements(COALESCE(NEW.evidence->'review'->'excludedVariants','[]'::jsonb))
      ORDER BY (value->>'productVariantId')::integer)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(NEW.evidence->'review'->'excludedVariants','[]'::jsonb))
      WHERE value->>'reason' IS NULL OR value->>'reason' NOT IN
        ('unsupported_bundle','legacy_inactive_catalog','legacy_quarantined','legacy_missing_inventory_identity'))
    OR COALESCE(NEW.receipt->'excludedVariants','[]'::jsonb)
      IS DISTINCT FROM COALESCE(NEW.evidence->'review'->'excludedVariants','[]'::jsonb)
    OR NEW.receipt->>'publicationTargetId' IS DISTINCT FROM NEW.publication_target_id::text
    OR NEW.receipt->>'previousRevision' IS DISTINCT FROM NEW.previous_revision::text
    OR NEW.receipt->>'revision' IS DISTINCT FROM (NEW.previous_revision+1)::text
    OR NEW.receipt->>'reviewHash' IS DISTINCT FROM NEW.review_hash
    OR NEW.receipt->>'preparedBy' IS DISTINCT FROM NEW.actor
    OR (NEW.receipt->>'preparedAt')::timestamptz IS DISTINCT FROM NEW.occurred_at
    OR NEW.receipt->'includedVariantIds' IS DISTINCT FROM to_jsonb(expected_ids)
    OR NEW.receipt->'alreadyApplied' IS DISTINCT FROM 'false'::jsonb
    OR NEW.receipt->'runtimeAuthorityChanged' IS DISTINCT FROM 'false'::jsonb
    OR NEW.receipt->'providerWriteAttempted' IS DISTINCT FROM 'false'::jsonb
    OR NEW.receipt->'outboxEnqueued' IS DISTINCT FROM 'false'::jsonb THEN
    RAISE EXCEPTION 'INITIAL_SCOPE_RECEIPT_INVALID' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_interwarehouse_transfer_event(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_interwarehouse_transfer_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(NEW.transfer_id,NEW.event_type,NEW.command_key,NEW.request_hash,NEW.quantity,
         NEW.damaged_quantity,NEW.inventory_transaction_id,NEW.adjustment_transaction_id,NEW.actor,NEW.detail,NEW.occurred_at)
     IS DISTINCT FROM
     ROW(OLD.transfer_id,OLD.event_type,OLD.command_key,OLD.request_hash,OLD.quantity,
         OLD.damaged_quantity,OLD.inventory_transaction_id,OLD.adjustment_transaction_id,OLD.actor,OLD.detail,OLD.occurred_at) THEN
    RAISE EXCEPTION 'Inter-warehouse transfer event evidence is immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.effects_completed_at IS NOT NULL AND NEW.effects_completed_at IS DISTINCT FROM OLD.effects_completed_at THEN
    RAISE EXCEPTION 'Completed inter-warehouse transfer effects are immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_inventory_publication_attempt_insert(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_inventory_publication_attempt_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  latest_attempt INTEGER;
BEGIN
  PERFORM pg_advisory_xact_lock(NEW.outbox_id);
  SELECT max(attempt_number)
  INTO latest_attempt
  FROM inventory.inventory_publication_attempts
  WHERE outbox_id = NEW.outbox_id;
  IF NEW.attempt_number <> COALESCE(latest_attempt, 0) + 1 THEN
    RAISE EXCEPTION 'publication attempt number must follow existing attempt %',
      COALESCE(latest_attempt, 0);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_inventory_publication_outbox_insert(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_inventory_publication_outbox_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  latest_revision BIGINT;
  target_exists BOOLEAN;
  target_destination_kind VARCHAR(30);
  target_channel_connection_id INTEGER;
  target_dropship_store_connection_id INTEGER;
  target_channel_id INTEGER;
  target_provider_key VARCHAR(60);
  target_policy_channel_provider VARCHAR(60);
  target_provider_scope_type VARCHAR(30);
  target_revision BIGINT;
  target_scope_id VARCHAR(240);
BEGIN
  PERFORM pg_advisory_xact_lock(NEW.publication_target_id, NEW.product_variant_id);

  SELECT true, target.destination_kind, target.channel_connection_id,
         target.dropship_store_connection_id, target.channel_id,
         lower(policy_channel.provider),
         target.provider_scope_type, target.revision, target.external_scope_id
  INTO target_exists, target_destination_kind, target_channel_connection_id,
       target_dropship_store_connection_id, target_channel_id,
       target_policy_channel_provider, target_provider_scope_type, target_revision,
       target_scope_id
  FROM inventory.inventory_publication_targets AS target
  JOIN channels.channels AS policy_channel ON policy_channel.id = target.channel_id
  WHERE target.id = NEW.publication_target_id
  FOR SHARE OF target, policy_channel;

  IF target_exists IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'publication target does not exist';
  END IF;
  IF target_destination_kind = 'dropship_store_connection' THEN
    SELECT lower(platform)
    INTO target_provider_key
    FROM dropship.dropship_store_connections
    WHERE id = target_dropship_store_connection_id
    FOR SHARE;
  ELSE
    target_provider_key := target_policy_channel_provider;
  END IF;
  IF NEW.destination_kind_snapshot IS DISTINCT FROM target_destination_kind
     OR NEW.channel_connection_id_snapshot IS DISTINCT FROM target_channel_connection_id
     OR NEW.dropship_store_connection_id_snapshot
       IS DISTINCT FROM target_dropship_store_connection_id
     OR (NEW.activation_run_id IS NOT NULL AND (
       NEW.channel_id_snapshot IS DISTINCT FROM target_channel_id
       OR lower(NEW.provider_key_snapshot) IS DISTINCT FROM target_provider_key
       OR NEW.provider_scope_type_snapshot IS DISTINCT FROM target_provider_scope_type
       OR NEW.publication_target_revision_snapshot IS DISTINCT FROM target_revision
     ))
     OR NEW.external_scope_id_snapshot IS DISTINCT FROM target_scope_id THEN
    RAISE EXCEPTION 'publication identity snapshot differs from its target';
  END IF;

  SELECT max(desired_revision)
  INTO latest_revision
  FROM inventory.inventory_publication_outbox
  WHERE publication_target_id = NEW.publication_target_id
    AND product_variant_id = NEW.product_variant_id;

  IF latest_revision IS NOT NULL AND NEW.desired_revision <= latest_revision THEN
    RAISE EXCEPTION 'publication revision must be greater than existing revision %', latest_revision;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_inventory_publication_outbox_update(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_inventory_publication_outbox_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.activation_run_id IS DISTINCT FROM OLD.activation_run_id
     OR NEW.publication_target_id IS DISTINCT FROM OLD.publication_target_id
     OR NEW.product_variant_id IS DISTINCT FROM OLD.product_variant_id
     OR NEW.desired_revision IS DISTINCT FROM OLD.desired_revision
     OR NEW.desired_quantity IS DISTINCT FROM OLD.desired_quantity
     OR NEW.destination_kind_snapshot IS DISTINCT FROM OLD.destination_kind_snapshot
     OR NEW.channel_connection_id_snapshot IS DISTINCT FROM OLD.channel_connection_id_snapshot
     OR NEW.dropship_store_connection_id_snapshot
       IS DISTINCT FROM OLD.dropship_store_connection_id_snapshot
     OR NEW.external_scope_id_snapshot IS DISTINCT FROM OLD.external_scope_id_snapshot
     OR NEW.external_inventory_item_id_snapshot IS DISTINCT FROM OLD.external_inventory_item_id_snapshot
     OR NEW.publication_phase IS DISTINCT FROM OLD.publication_phase
     OR NEW.channel_id_snapshot IS DISTINCT FROM OLD.channel_id_snapshot
     OR NEW.provider_key_snapshot IS DISTINCT FROM OLD.provider_key_snapshot
     OR NEW.provider_scope_type_snapshot IS DISTINCT FROM OLD.provider_scope_type_snapshot
     OR NEW.external_sku_snapshot IS DISTINCT FROM OLD.external_sku_snapshot
     OR NEW.publication_target_revision_snapshot IS DISTINCT FROM OLD.publication_target_revision_snapshot
     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.payload_hash IS DISTINCT FROM OLD.payload_hash
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'publication outbox desired state and identity are immutable';
  END IF;

  IF NEW.state IS DISTINCT FROM OLD.state AND NOT (
    (OLD.state = 'desired' AND NEW.state IN ('queued', 'cancelled', 'superseded'))
    OR (OLD.state = 'queued' AND NEW.state IN ('leased', 'cancelled', 'superseded'))
    OR (OLD.state = 'leased' AND NEW.state IN (
      'acknowledged', 'retryable', 'dead_letter', 'cancelled', 'superseded'
    ))
    OR (OLD.state = 'retryable' AND NEW.state IN ('queued', 'dead_letter', 'cancelled', 'superseded'))
    OR (OLD.state = 'acknowledged' AND NEW.state IN ('verified', 'drifted'))
    OR (OLD.state = 'drifted' AND NEW.state IN ('queued', 'dead_letter', 'cancelled', 'superseded'))
  ) THEN
    RAISE EXCEPTION 'invalid publication state transition from % to %', OLD.state, NEW.state;
  END IF;
  NEW.updated_at := transaction_timestamp();
  RETURN NEW;
END;
$$;


--
-- Name: guard_inventory_publication_readback_insert(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_inventory_publication_readback_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  desired_quantity bigint;
  desired_target_id integer;
  desired_variant_id integer;
BEGIN
  IF NEW.outbox_id IS NULL THEN RETURN NEW; END IF;
  SELECT outbox.desired_quantity,outbox.publication_target_id,outbox.product_variant_id
    INTO desired_quantity,desired_target_id,desired_variant_id
    FROM inventory.inventory_publication_outbox outbox WHERE outbox.id=NEW.outbox_id FOR SHARE;
  IF desired_quantity IS NULL THEN RAISE EXCEPTION 'publication outbox row does not exist'; END IF;
  IF NEW.publication_target_id<>desired_target_id OR NEW.product_variant_id<>desired_variant_id THEN
    RAISE EXCEPTION 'readback identity differs from its publication outbox row';
  END IF;
  IF NEW.matches_desired IS DISTINCT FROM (COALESCE(NEW.quantity_consistent,true) AND NEW.observed_quantity=desired_quantity) THEN
    RAISE EXCEPTION 'readback match flag does not match provider consistency and desired quantity';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_inventory_publication_readback_run_update(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_inventory_publication_readback_run_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF OLD.state <> 'running' OR NEW.state NOT IN ('completed', 'partial') THEN
    RAISE EXCEPTION 'invalid inventory publication readback run transition';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
     OR NEW.requested_by IS DISTINCT FROM OLD.requested_by
     OR NEW.reason IS DISTINCT FROM OLD.reason
     OR NEW.started_at IS DISTINCT FROM OLD.started_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'inventory publication readback request evidence is immutable';
  END IF;
  NEW.updated_at := transaction_timestamp();
  RETURN NEW;
END;
$$;


--
-- Name: guard_inventory_publication_target_update(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_inventory_publication_target_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.destination_kind IS DISTINCT FROM OLD.destination_kind
     OR NEW.channel_id IS DISTINCT FROM OLD.channel_id OR NEW.channel_connection_id IS DISTINCT FROM OLD.channel_connection_id
     OR NEW.dropship_store_connection_id IS DISTINCT FROM OLD.dropship_store_connection_id
     OR NEW.fulfillment_node_id IS DISTINCT FROM OLD.fulfillment_node_id
     OR NEW.provider_scope_type IS DISTINCT FROM OLD.provider_scope_type OR NEW.external_scope_id IS DISTINCT FROM OLD.external_scope_id
     OR NEW.publication_authority IS DISTINCT FROM OLD.publication_authority OR NEW.change_reason IS DISTINCT FROM OLD.change_reason
     OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'inventory publication target identity and creation evidence are immutable';
  END IF;
  IF NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'inventory publication target revision must increment by 1'; END IF;
  IF OLD.state='live' AND NEW.state NOT IN ('live','disabled') THEN
    RAISE EXCEPTION 'a live publication target can only remain live or enter the scoped disabled stop state';
  END IF;
  IF NEW.state='live' AND OLD.state='disabled' THEN
    -- Direct enable must own the same exclusive admission fence as setup promotion.
    PERFORM inventory.assert_cutover_admission_fence_owner();
  ELSIF NEW.state='live' AND OLD.state NOT IN ('preview','live') THEN
    RAISE EXCEPTION 'a publication target must be previewed before it becomes live';
  END IF;
  NEW.updated_at:=transaction_timestamp(); RETURN NEW;
END $$;


--
-- Name: guard_listing_recreation_stock_receipt(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_listing_recreation_stock_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF NEW.observed_at > NEW.created_at OR NOT EXISTS (
    SELECT 1 FROM inventory.publication_listing_setup_scopes s
    JOIN inventory.inventory_publication_outbox o ON o.id=NEW.outbox_id
      AND o.publication_target_id=s.publication_target_id AND o.product_variant_id=s.product_variant_id
      AND o.external_inventory_item_id_snapshot=s.external_inventory_item_id
    JOIN inventory.inventory_publication_targets t ON t.id=s.publication_target_id
      AND t.revision=o.publication_target_revision_snapshot
    WHERE s.id=NEW.setup_scope_id AND s.recreation_evidence IS NOT NULL
      AND o.state='queued' AND o.publication_phase='full'
      AND NOT EXISTS(SELECT 1 FROM inventory.inventory_publication_outbox newer
        WHERE newer.publication_target_id=o.publication_target_id AND newer.product_variant_id=o.product_variant_id
          AND newer.desired_revision>o.desired_revision)
  ) THEN RAISE EXCEPTION 'Recreation stock receipt requires its exact current queued publication' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_listing_setup_attempt_identity(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_listing_setup_attempt_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF NEW.listing_setup_operation_id IS DISTINCT FROM OLD.listing_setup_operation_id THEN
    RAISE EXCEPTION 'Initial listing operation identity is immutable' USING ERRCODE='23514';
  END IF; RETURN NEW;
END $$;


--
-- Name: guard_model_inventory_behavior(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_model_inventory_behavior() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_id integer;
  selected_mode varchar(30);
  promise_builds boolean;
  selected_validation varchar(20);
BEGIN
  IF TG_TABLE_NAME = 'transformation_model_versions' THEN
    target_id := COALESCE(NEW.id, OLD.id);
  ELSE
    target_id := COALESCE(NEW.model_id, OLD.model_id);
  END IF;
  SELECT inventory_behavior, build_to_promise_enabled, validation_state
    INTO selected_mode, promise_builds, selected_validation
    FROM inventory.transformation_model_versions WHERE id = target_id;
  IF selected_mode IS NULL OR selected_validation <> 'valid' THEN RETURN NULL; END IF;

  IF selected_mode <> 'build_managed' AND (promise_builds OR EXISTS (
    SELECT 1 FROM inventory.transformation_recipe_bindings WHERE model_id = target_id
  )) THEN
    RAISE EXCEPTION 'model % inventory behavior does not permit recipes', target_id
      USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1 FROM inventory.transformation_model_paths
    WHERE model_id = target_id AND authority_state = 'allowed' AND (
      selected_mode = 'physical_only'
      OR (selected_mode = 'package_hierarchy' AND
        (operation_type NOT IN ('break_pack', 'assemble_pack') OR transformation_recipe_binding_id IS NOT NULL))
      OR (selected_mode = 'build_managed' AND
        (operation_type <> 'directed_conversion' OR transformation_recipe_binding_id IS NULL))
    )
  ) THEN
    RAISE EXCEPTION 'model % inventory behavior conflicts with allowed paths', target_id
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: guard_planner_shadow_evidence_write(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_planner_shadow_evidence_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'planner shadow evidence is append-only';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_product_definition_application(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_product_definition_application() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Product definition receipts are immutable' USING ERRCODE='55000';
  END IF;
  PERFORM inventory.assert_cutover_admission_fence_owner();
  IF NOT EXISTS (
    SELECT 1 FROM inventory.transformation_model_heads head
    JOIN inventory.transformation_model_versions model ON model.id=head.active_model_id
    WHERE head.product_id=NEW.product_id AND model.product_id=NEW.product_id
      AND model.id=NEW.model_id AND model.lifecycle_status='sealed'
  ) THEN
    RAISE EXCEPTION 'Receipt must identify the active sealed product model' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_publication_membership_evidence(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_publication_membership_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  RAISE EXCEPTION 'Publication membership evidence is append-only' USING ERRCODE='23514';
END $$;


--
-- Name: guard_publication_membership_head(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_publication_membership_head() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Publication membership must be excluded by an audited version' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM inventory.inventory_publication_targets WHERE id=NEW.publication_target_id AND membership_mode='explicit') THEN
    RAISE EXCEPTION 'Only explicit targets accept selected membership' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND (NEW.publication_target_id<>OLD.publication_target_id OR NEW.product_variant_id<>OLD.product_variant_id
    OR (SELECT version FROM inventory.publication_membership_versions WHERE id=NEW.active_version_id)
       <=(SELECT version FROM inventory.publication_membership_versions WHERE id=OLD.active_version_id)) THEN
    RAISE EXCEPTION 'Publication membership heads must advance within one target and variant' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_publication_membership_mode(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_publication_membership_mode() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP='INSERT' THEN
    -- Exactly the existing new-Walmart default, not a migration of older rows.
    IF NEW.destination_kind='channel_connection' AND EXISTS(
      SELECT 1 FROM channels.channels WHERE id=NEW.channel_id AND lower(provider)='walmart'
    ) THEN NEW.membership_mode:='explicit'; END IF;
  ELSIF NEW.membership_mode IS DISTINCT FROM OLD.membership_mode THEN
    PERFORM inventory.assert_cutover_admission_fence_owner();
    IF OLD.membership_mode<>'whole_product' OR NEW.membership_mode<>'explicit'
      OR OLD.state<>'preview' OR NEW.state<>'preview' OR OLD.publication_authority<>'echelon'
      OR NOT EXISTS(SELECT 1 FROM inventory.publication_initial_scope_receipts receipt
        WHERE receipt.publication_target_id=OLD.id AND receipt.previous_revision=OLD.revision
          AND receipt.owner_transaction_id=pg_current_xact_id()) THEN
      RAISE EXCEPTION 'Publication membership mode requires a current audited initial-scope command' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_publication_no_request_recovery(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_publication_no_request_recovery() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE attempt inventory.quantity_publication_attempts%ROWTYPE; evidence jsonb; first_sku text; encoded_first_sku text; member_skus jsonb;
BEGIN
  SELECT * INTO attempt FROM inventory.quantity_publication_attempts WHERE id=NEW.attempt_id;
  PERFORM inventory.assert_ebay_operator_resume_locks(attempt.affected_scope_keys);
  IF NEW.owner_transaction_id IS DISTINCT FROM pg_current_xact_id()
    OR attempt.state NOT IN ('running','uncertain') OR attempt.scope->>'providerKey' IS DISTINCT FROM 'ebay'
    OR to_jsonb(attempt) IS DISTINCT FROM NEW.before_record
    OR EXISTS(SELECT 1 FROM inventory.quantity_provider_requests WHERE attempt_id=NEW.attempt_id) THEN
    RAISE EXCEPTION 'No-request recovery requires exact inactive ownership and an empty durable mutation journal' USING ERRCODE='23514';
  END IF;
  IF NEW.proof->>'source'='request_journal_contract' THEN
    IF attempt.request_journal_contract IS NULL OR NEW.proof->'contract' IS DISTINCT FROM attempt.request_journal_contract THEN
      RAISE EXCEPTION 'No-request recovery must retain its admission-time journal contract' USING ERRCODE='23514';
    END IF;
  ELSIF NEW.proof->>'source'='legacy_publish_preflight' THEN
    -- The channels owner supplies its validated immutable stage/event sequence.
    -- Inventory independently checks exact owned membership, first-member read,
    -- attempt timing and the absence of even a started mutation request.
    evidence:=NEW.proof->'evidence';
    SELECT jsonb_agg(item->>'externalInventoryItemId' ORDER BY (item->>'externalInventoryItemId') COLLATE "C"),
      min((item->>'externalInventoryItemId') COLLATE "C") INTO member_skus,first_sku
      FROM jsonb_array_elements(attempt.affected_scopes) item
      WHERE item->>'externalInventoryItemId' IS DISTINCT FROM attempt.scope->>'externalInventoryItemId';
    -- Match encodeURIComponent used by the protocol without treating encoded
    -- slashes, spaces or non-ASCII SKU bytes as a different first member.
    SELECT string_agg(CASE WHEN byte BETWEEN 48 AND 57 OR byte BETWEEN 65 AND 90 OR byte BETWEEN 97 AND 122
      OR byte IN (33,39,40,41,42,45,46,95,126) THEN chr(byte)
      ELSE '%'||upper(lpad(to_hex(byte),2,'0')) END,'' ORDER BY ordinal) INTO encoded_first_sku
      FROM (SELECT ordinal,get_byte(convert_to(first_sku,'UTF8'),ordinal) AS byte
        FROM generate_series(0,octet_length(first_sku)-1) ordinal) bytes;
    IF attempt.request_journal_contract IS NOT NULL OR attempt.owner_kind<>'legacy'
      OR jsonb_typeof(evidence) IS DISTINCT FROM 'object'
      OR attempt.scope->>'externalInventoryItemId' IS DISTINCT FROM 'group:'||(evidence->>'groupKey')
      OR member_skus IS NULL OR member_skus IS DISTINCT FROM evidence->'memberSkus'
      OR evidence#>>'{failedRequest,method}' IS DISTINCT FROM 'GET'
      OR evidence#>>'{failedRequest,httpStatus}' IS DISTINCT FROM '500'
      OR evidence#>'{failedRequest,errorCodes}' IS DISTINCT FROM '["25001"]'::jsonb
      OR evidence#>>'{failedRequest,path}' IS DISTINCT FROM '/sell/inventory/v1/offer?sku='||encoded_first_sku||'&marketplace_id='||(evidence->>'marketplaceId')
      OR (evidence->>'sourceEvidenceHash' ~ '^[a-f0-9]{64}$') IS DISTINCT FROM true
      OR (evidence->>'jobId' ~ '^[a-f0-9-]{36}$') IS DISTINCT FROM true
      OR (evidence->>'revision' ~ '^[1-9][0-9]*$') IS DISTINCT FROM true
      OR (evidence->>'stageEventId' ~ '^[1-9][0-9]*$') IS DISTINCT FROM true
      OR (evidence->>'failureEventId' ~ '^[1-9][0-9]*$') IS DISTINCT FROM true
      OR evidence->>'stageStartedAt' IS NULL OR evidence->>'failureAt' IS NULL
      OR (evidence->>'stageEventId')::bigint >= (evidence->>'failureEventId')::bigint
      OR attempt.started_at < (evidence->>'stageStartedAt')::timestamptz
      OR attempt.started_at > (evidence->>'failureAt')::timestamptz
      OR NOT (evidence ?& ARRAY['jobId','revision','stageEventId','stageStartedAt','failureEventId','failureAt',
        'groupKey','marketplaceId','memberSkus','failedRequest','sourceEvidenceHash']) THEN
      RAISE EXCEPTION 'Historical no-request recovery needs the exact first-member publish preflight evidence' USING ERRCODE='23514';
    END IF;
  ELSE
    RAISE EXCEPTION 'Unsupported no-request recovery evidence' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $_$;


--
-- Name: guard_publication_reconciled_insert(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_publication_reconciled_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF NEW.state='superseded_unknown' THEN
    RAISE EXCEPTION 'Reconciliation must retain an existing attempt' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_publication_reconciliation_command(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_publication_reconciliation_command() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Publication reconciliation evidence is append-only' USING ERRCODE='23514';
  END IF;
  PERFORM inventory.assert_cutover_admission_fence_owner();
  -- The application must first TRY the exclusive publication lock. Requiring
  -- ownership here cannot wait for, or falsely terminate, a live provider owner.
  IF NOT EXISTS(SELECT 1 FROM pg_locks WHERE pid=pg_backend_pid() AND locktype='advisory'
      AND classid=918419 AND objid=0 AND objsubid=2 AND mode='ExclusiveLock' AND granted)
    OR NEW.owner_transaction_id IS DISTINCT FROM pg_current_xact_id()
    OR NOT EXISTS(SELECT 1 FROM inventory.availability_activation_runs run
      JOIN inventory.quantity_publication_gate gate ON gate.activation_run_id=run.id AND gate.singleton=true
      JOIN inventory.availability_activation_freezes frozen_window ON frozen_window.activation_run_id=run.id AND frozen_window.released_at IS NULL
      CROSS JOIN inventory.availability_runtime_authority authority
      WHERE run.id=NEW.activation_run_id AND run.mode='activation' AND run.state='publishing'
        AND run.provider_write_attempted=false AND authority.singleton_key=true AND authority.authority='legacy'
        AND gate.epoch=NEW.gate_epoch) THEN
    RAISE EXCEPTION 'Reconciliation requires exclusive prepared legacy publication ownership' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_publication_reconciliation_member(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_publication_reconciliation_member() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Publication reconciliation snapshots are append-only' USING ERRCODE='23514';
  END IF;
  PERFORM inventory.assert_cutover_admission_fence_owner();
  IF NOT EXISTS(SELECT 1 FROM inventory.quantity_publication_reconciliations command
      JOIN inventory.quantity_publication_attempts attempt ON attempt.id=NEW.attempt_id
      WHERE command.id=NEW.reconciliation_id AND command.owner_transaction_id=pg_current_xact_id()
        AND attempt.owner_kind='legacy' AND attempt.state IN ('running','uncertain') AND attempt.gate_epoch < command.gate_epoch
        AND to_jsonb(attempt)=NEW.before_record
        AND command.result_payload->'supersededAttemptIds' @> jsonb_build_array(attempt.id::text)
        AND EXISTS(SELECT 1 FROM jsonb_array_elements(command.review_payload->'attempts') reviewed
          WHERE reviewed->>'attemptId'=attempt.id::text)) THEN
    RAISE EXCEPTION 'Reconciliation requires the exact reviewed unresolved attempt snapshot' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_publication_response_recovery(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_publication_response_recovery() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE actual jsonb;owned_keys text[];scope_key text;lock_key bigint;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM pg_locks WHERE pid=pg_backend_pid() AND locktype='advisory'
    AND classid=918419 AND objid=0 AND objsubid=2 AND mode='ShareLock' AND granted)
    OR NEW.owner_transaction_id IS DISTINCT FROM pg_current_xact_id()
    OR NOT EXISTS(SELECT 1 FROM inventory.quantity_publication_attempts a WHERE a.id=NEW.attempt_id
      AND a.owner_kind IN ('legacy','outbox') AND a.state IN ('running','uncertain') AND a.scope->>'providerKey'='ebay'
      AND to_jsonb(a)=NEW.before_record) THEN
    RAISE EXCEPTION 'Response recovery requires exclusive exact unresolved ownership' USING ERRCODE='23514';
  END IF;
  SELECT affected_scope_keys INTO owned_keys FROM inventory.quantity_publication_attempts WHERE id=NEW.attempt_id;
  IF cardinality(owned_keys)<1 THEN RAISE EXCEPTION 'Response recovery requires every exact owned scope' USING ERRCODE='23514';END IF;
  FOREACH scope_key IN ARRAY owned_keys LOOP
    -- The identical 64-bit advisory key used by existing inventory admission.
    lock_key:=hashtextextended(scope_key,918420);
    IF NOT EXISTS(SELECT 1 FROM pg_locks WHERE pid=pg_backend_pid() AND locktype='advisory'
      AND classid=((lock_key>>32)&4294967295)::oid AND objid=(lock_key&4294967295)::oid
      AND objsubid=1 AND mode='ExclusiveLock' AND granted) THEN
      RAISE EXCEPTION 'Response recovery requires exclusive exact-scope ownership' USING ERRCODE='23514';
    END IF;
  END LOOP;
  SELECT jsonb_agg(jsonb_build_object('requestId',q.id::text,'ordinal',q.ordinal,'method',q.method,'path',q.path,
    'requestHash',q.request_hash,'outcome',r.outcome,'httpStatus',r.http_status,'responseHash',r.response_hash,
    'requestTerminated',r.request_terminated,'errorCodes',COALESCE(r.error_codes,'{}'::text[]),'recordedAt',
    CASE WHEN r.recorded_at IS NULL THEN NULL ELSE to_char(r.recorded_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END) ORDER BY q.ordinal)
    INTO actual FROM inventory.quantity_provider_requests q LEFT JOIN inventory.quantity_provider_request_results r ON r.request_id=q.id
    WHERE q.attempt_id=NEW.attempt_id;
  IF actual IS NULL OR actual IS DISTINCT FROM NEW.request_receipts THEN
    RAISE EXCEPTION 'Response recovery must retain every immutable request receipt' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


