--
-- Name: guard_versioned_definition_update(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_versioned_definition_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  requires_owner_lock boolean := true;
  old_row jsonb := '{}'::jsonb;
  new_row jsonb := '{}'::jsonb;
  old_status varchar(20);
  new_status varchar(20);
  old_id integer;
  new_id integer;
  new_product_id integer;
  new_build_to_promise_enabled boolean;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    old_row := to_jsonb(OLD);
  END IF;
  IF TG_OP <> 'DELETE' THEN
    new_row := to_jsonb(NEW);
  END IF;
  old_status := old_row ->> 'lifecycle_status';
  new_status := new_row ->> 'lifecycle_status';
  old_id := NULLIF(old_row ->> 'id', '')::integer;
  new_id := NULLIF(new_row ->> 'id', '')::integer;
  new_product_id := NULLIF(new_row ->> 'product_id', '')::integer;
  new_build_to_promise_enabled := COALESCE(
    NULLIF(new_row ->> 'build_to_promise_enabled', '')::boolean,
    false
  );

  IF TG_OP = 'DELETE' AND old_status = 'draft' THEN
    requires_owner_lock := false;
  ELSIF TG_OP = 'UPDATE' AND old_status = 'draft' AND new_status = 'draft' THEN
    requires_owner_lock := false;
  END IF;

  IF requires_owner_lock AND TG_TABLE_NAME = 'location_promise_policy_versions' THEN
    PERFORM pg_advisory_xact_lock(
      918421,
      COALESCE(
        NULLIF(new_row ->> 'warehouse_location_id', '')::integer,
        NULLIF(old_row ->> 'warehouse_location_id', '')::integer
      )
    );
  ELSIF requires_owner_lock AND TG_TABLE_NAME = 'transformation_model_versions' THEN
    PERFORM pg_advisory_xact_lock(
      918422,
      COALESCE(new_product_id, NULLIF(old_row ->> 'product_id', '')::integer)
    );
  ELSIF requires_owner_lock AND TG_TABLE_NAME = 'promise_safety_policy_versions' THEN
    PERFORM pg_advisory_xact_lock(
      918423,
      hashtext(COALESCE(new_row ->> 'scope_key', old_row ->> 'scope_key'))
    );
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF new_status <> 'draft' THEN
      RAISE EXCEPTION '% must be inserted as a draft', TG_TABLE_NAME;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF old_status = 'draft' THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION '% sealed definitions are append-only', TG_TABLE_NAME;
  END IF;

  IF old_status = 'draft' AND new_status = 'draft' THEN
    IF TG_TABLE_NAME = 'location_promise_policy_versions'
       AND (
         new_row -> 'id' IS DISTINCT FROM old_row -> 'id'
         OR new_row -> 'warehouse_location_id' IS DISTINCT FROM old_row -> 'warehouse_location_id'
         OR new_row -> 'version' IS DISTINCT FROM old_row -> 'version'
         OR new_row -> 'supersedes_policy_id' IS DISTINCT FROM old_row -> 'supersedes_policy_id'
         OR new_row -> 'idempotency_key' IS DISTINCT FROM old_row -> 'idempotency_key'
         OR new_row -> 'created_by' IS DISTINCT FROM old_row -> 'created_by'
         OR new_row -> 'created_at' IS DISTINCT FROM old_row -> 'created_at'
       ) THEN
      RAISE EXCEPTION 'location policy draft identity is immutable';
    ELSIF TG_TABLE_NAME = 'transformation_model_versions'
       AND (
         new_row -> 'id' IS DISTINCT FROM old_row -> 'id'
         OR new_row -> 'product_id' IS DISTINCT FROM old_row -> 'product_id'
         OR new_row -> 'version' IS DISTINCT FROM old_row -> 'version'
         OR new_row -> 'supersedes_model_id' IS DISTINCT FROM old_row -> 'supersedes_model_id'
         OR new_row -> 'idempotency_key' IS DISTINCT FROM old_row -> 'idempotency_key'
         OR new_row -> 'created_by' IS DISTINCT FROM old_row -> 'created_by'
         OR new_row -> 'created_at' IS DISTINCT FROM old_row -> 'created_at'
       ) THEN
      RAISE EXCEPTION 'transformation model draft identity is immutable';
    ELSIF TG_TABLE_NAME = 'promise_safety_policy_versions'
       AND (
         new_row -> 'id' IS DISTINCT FROM old_row -> 'id'
         OR new_row -> 'scope_key' IS DISTINCT FROM old_row -> 'scope_key'
         OR new_row -> 'scope_type' IS DISTINCT FROM old_row -> 'scope_type'
         OR new_row -> 'product_variant_id' IS DISTINCT FROM old_row -> 'product_variant_id'
         OR new_row -> 'warehouse_id' IS DISTINCT FROM old_row -> 'warehouse_id'
         OR new_row -> 'version' IS DISTINCT FROM old_row -> 'version'
         OR new_row -> 'supersedes_policy_id' IS DISTINCT FROM old_row -> 'supersedes_policy_id'
         OR new_row -> 'idempotency_key' IS DISTINCT FROM old_row -> 'idempotency_key'
         OR new_row -> 'created_by' IS DISTINCT FROM old_row -> 'created_by'
         OR new_row -> 'created_at' IS DISTINCT FROM old_row -> 'created_at'
       ) THEN
      RAISE EXCEPTION 'safety policy draft identity is immutable';
    END IF;
    RETURN NEW;
  END IF;

  IF old_status = 'draft' AND new_status = 'sealed' THEN
    IF (
      new_row - ARRAY['lifecycle_status', 'sealed_by', 'sealed_at', 'updated_at']
    ) IS DISTINCT FROM (
      old_row - ARRAY['lifecycle_status', 'sealed_by', 'sealed_at', 'updated_at']
    ) THEN
      RAISE EXCEPTION '% definition fields cannot change while sealing', TG_TABLE_NAME;
    END IF;

    IF TG_TABLE_NAME = 'transformation_model_versions' AND (
      EXISTS (
        SELECT 1
        FROM inventory.transformation_model_paths AS path
        JOIN catalog.product_variants AS source_variant
          ON source_variant.id = path.source_variant_id
        JOIN catalog.product_variants AS destination_variant
          ON destination_variant.id = path.destination_variant_id
        WHERE path.model_id = new_id
          AND (
            path.validation_state <> 'valid'
            OR source_variant.product_id <> new_product_id
            OR destination_variant.product_id <> new_product_id
            OR source_variant.units_per_variant <> path.source_units_per_variant
            OR destination_variant.units_per_variant <> path.destination_units_per_variant
          )
      )
      OR EXISTS (
        SELECT 1
        FROM inventory.transformation_recipe_bindings AS binding
        JOIN inventory.build_recipes AS recipe ON recipe.id = binding.recipe_id
        WHERE binding.model_id = new_id
          AND (
            binding.validation_state <> 'valid'
            OR recipe.status <> 'active'
            OR recipe.output_product_id <> new_product_id
            OR recipe.code <> binding.recipe_code_snapshot
            OR recipe.version <> binding.recipe_version_snapshot
            OR recipe.output_product_id <> binding.output_product_id_snapshot
            OR recipe.output_variant_id <> binding.output_variant_id_snapshot
            OR recipe.output_units_per_variant <> binding.output_units_per_variant_snapshot
            OR recipe.output_qty <> binding.output_qty_snapshot
          )
      )
      OR EXISTS (
        SELECT 1
        FROM inventory.transformation_recipe_bindings AS binding
        WHERE binding.model_id = new_id
          AND (
            NOT EXISTS (
              SELECT 1
              FROM inventory.transformation_recipe_component_snapshots AS snapshot
              WHERE snapshot.transformation_recipe_binding_id = binding.id
            )
            OR EXISTS (
              (
                SELECT component_variant_id, component_product_id,
                       component_units_per_variant, qty
                FROM inventory.build_recipe_components
                WHERE recipe_id = binding.recipe_id
              )
              EXCEPT
              (
                SELECT component_variant_id, component_product_id,
                       component_units_per_variant, component_qty
                FROM inventory.transformation_recipe_component_snapshots
                WHERE transformation_recipe_binding_id = binding.id
              )
            )
            OR EXISTS (
              (
                SELECT component_variant_id, component_product_id,
                       component_units_per_variant, component_qty
                FROM inventory.transformation_recipe_component_snapshots
                WHERE transformation_recipe_binding_id = binding.id
              )
              EXCEPT
              (
                SELECT component_variant_id, component_product_id,
                       component_units_per_variant, qty
                FROM inventory.build_recipe_components
                WHERE recipe_id = binding.recipe_id
              )
            )
          )
      )
      OR (
        new_build_to_promise_enabled
        AND NOT EXISTS (
          SELECT 1
          FROM inventory.transformation_recipe_bindings AS binding
          WHERE binding.model_id = new_id
            AND binding.relationship_role = 'component_build'
            AND binding.validation_state = 'valid'
        )
      )
      OR EXISTS (
        SELECT 1
        FROM inventory.transformation_model_paths AS path
        JOIN inventory.transformation_recipe_bindings AS binding
          ON binding.id = path.transformation_recipe_binding_id
         AND binding.model_id = path.model_id
        WHERE path.model_id = new_id
          AND (
            binding.output_variant_id_snapshot <> path.destination_variant_id
            OR binding.output_units_per_variant_snapshot <> path.destination_units_per_variant
            OR (
              path.operation_type = 'directed_conversion'
              AND (
                binding.relationship_role <> 'directional_conversion'
                OR binding.output_qty_snapshot <> path.output_qty
                OR (
                  SELECT count(*)
                  FROM inventory.build_recipe_components AS component
                  WHERE component.recipe_id = binding.recipe_id
                ) <> 1
                OR NOT EXISTS (
                  SELECT 1
                  FROM inventory.build_recipe_components AS component
                  WHERE component.recipe_id = binding.recipe_id
                    AND component.component_variant_id = path.source_variant_id
                    AND component.component_units_per_variant = path.source_units_per_variant
                    AND component.qty = path.input_qty
                )
              )
            )
          )
      )
    ) THEN
      RAISE EXCEPTION
        'transformation model % contains invalid or ownership-mismatched members',
        new_id;
    END IF;
    RETURN NEW;
  END IF;

  IF old_status = 'sealed' AND new_status = 'retired' THEN
    IF (
      new_row - ARRAY['lifecycle_status', 'retired_by', 'retired_at', 'updated_at']
    ) IS DISTINCT FROM (
      old_row - ARRAY['lifecycle_status', 'retired_by', 'retired_at', 'updated_at']
    ) THEN
      RAISE EXCEPTION '% definition fields cannot change while retiring', TG_TABLE_NAME;
    END IF;

    IF TG_TABLE_NAME = 'location_promise_policy_versions'
       AND EXISTS (
         SELECT 1 FROM inventory.location_promise_policy_heads
         WHERE active_policy_id = old_id
       ) THEN
      RAISE EXCEPTION 'active location policy % cannot be retired', old_id;
    ELSIF TG_TABLE_NAME = 'transformation_model_versions'
       AND EXISTS (
         SELECT 1 FROM inventory.transformation_model_heads
         WHERE active_model_id = old_id
       ) THEN
      RAISE EXCEPTION 'active transformation model % cannot be retired', old_id;
    ELSIF TG_TABLE_NAME = 'promise_safety_policy_versions'
       AND EXISTS (
         SELECT 1 FROM inventory.promise_safety_policy_heads
         WHERE active_policy_id = old_id
       ) THEN
      RAISE EXCEPTION 'active safety policy % cannot be retired', old_id;
    END IF;
    RETURN NEW;
  END IF;

  RAISE EXCEPTION '% lifecycle transition % -> % is not allowed',
    TG_TABLE_NAME, old_status, new_status;
END;
$$;


--
-- Name: invalidate_publication_selection_product(integer); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.invalidate_publication_selection_product(affected_product integer) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  -- Unenrolled products cannot send stock. Mapping activation emits the same
  -- invalidation; it will read current selection when enrollment becomes real.
  IF affected_product IS NULL OR NOT EXISTS (
    SELECT 1 FROM inventory.publication_variant_mapping_heads h
    JOIN catalog.product_variants v ON v.id=h.product_variant_id
    WHERE v.product_id=affected_product AND h.active_mapping_id IS NOT NULL
  ) THEN RETURN; END IF;
  INSERT INTO inventory.publication_selection_work(product_id,next_boundary_at)
    VALUES(affected_product,inventory.next_publication_selection_boundary(transaction_timestamp()))
  ON CONFLICT(product_id) DO UPDATE SET
    revision=CASE WHEN publication_selection_work.last_invalidating_xid=pg_current_xact_id()
      THEN publication_selection_work.revision ELSE publication_selection_work.revision+1 END,
    last_invalidating_xid=pg_current_xact_id(), next_attempt_at=transaction_timestamp(),
    next_boundary_at=inventory.next_publication_selection_boundary(transaction_timestamp()),
    attempt_count=0,last_error_code=NULL,updated_at=transaction_timestamp();
END;
$$;


--
-- Name: invalidate_transformation_model_after_member_write(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.invalidate_transformation_model_after_member_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  parent_model_id integer;
BEGIN
  parent_model_id := CASE
    WHEN TG_OP = 'DELETE' THEN OLD.model_id
    ELSE NEW.model_id
  END;

  UPDATE inventory.transformation_model_versions
  SET
    validation_state = 'invalid',
    validation_errors = jsonb_build_array(
      jsonb_build_object(
        'code', 'members_changed',
        'member_table', TG_TABLE_NAME
      )
    ),
    updated_at = transaction_timestamp()
  WHERE id = parent_model_id
    AND lifecycle_status = 'draft';

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: next_publication_selection_boundary(timestamp with time zone); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.next_publication_selection_boundary(observed_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT min(boundary) FROM dropship.dropship_catalog_rules r
    CROSS JOIN LATERAL (VALUES(r.starts_at),(r.ends_at)) deadlines(boundary)
    WHERE r.is_active=true AND boundary>observed_at
$$;


--
-- Name: notify_publication_selection_change(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.notify_publication_selection_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE before_row jsonb; after_row jsonb; field_name text; changed boolean := TG_OP<>'UPDATE'; affected integer;
BEGIN
  IF TG_OP<>'INSERT' THEN before_row:=to_jsonb(OLD); END IF;
  IF TG_OP<>'DELETE' THEN after_row:=to_jsonb(NEW); END IF;
  IF TG_OP='UPDATE' THEN
    FOREACH field_name IN ARRAY string_to_array(TG_ARGV[1],',') LOOP
      IF before_row->field_name IS DISTINCT FROM after_row->field_name THEN changed:=true; EXIT; END IF;
    END LOOP;
  END IF;
  IF NOT changed THEN RETURN NULL; END IF;
  IF TG_ARGV[0]='all' THEN
    FOR affected IN SELECT DISTINCT v.product_id FROM inventory.publication_variant_mapping_heads h
      JOIN catalog.product_variants v ON v.id=h.product_variant_id WHERE h.active_mapping_id IS NOT NULL
    LOOP PERFORM inventory.invalidate_publication_selection_product(affected); END LOOP;
  ELSIF TG_ARGV[0]='variant' THEN
    FOR affected IN SELECT DISTINCT product_id FROM catalog.product_variants WHERE id IN
      ((before_row->>'product_variant_id')::integer,(after_row->>'product_variant_id')::integer)
    LOOP PERFORM inventory.invalidate_publication_selection_product(affected); END LOOP;
  ELSE
    -- The field is an explicit literal supplied by the migration manifest.
    PERFORM inventory.invalidate_publication_selection_product((before_row->>TG_ARGV[0])::integer);
    PERFORM inventory.invalidate_publication_selection_product((after_row->>TG_ARGV[0])::integer);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: omission_source_posted_quantity(integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.omission_source_posted_quantity(expected_order_id integer, expected_order_item_id integer, expected_shipment_id integer, expected_source_item_id integer, expected_variant_id integer, expected_source_quantity integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  posting record;
  posted_quantity bigint := 0;
  canonical_valid boolean;
BEGIN
  FOR posting IN
    SELECT ledger.*,
      COUNT(*) OVER () AS posting_count,
      receipt.id AS receipt_id,
      receipt.quantity AS receipt_quantity,
      receipt.order_id AS receipt_order_id,
      receipt.order_item_id AS receipt_order_item_id,
      receipt.outbound_shipment_id AS receipt_shipment_id,
      receipt.source_shipment_item_id AS receipt_source_item_id,
      receipt.product_variant_id AS receipt_variant_id,
      receipt.warehouse_location_id AS receipt_location_id,
      receipt.warehouse_id AS receipt_warehouse_id,
      receipt.physical_shipment_id AS receipt_physical_id,
      receipt.physical_shipment_item_id AS receipt_physical_item_id,
      journal.quantity AS movement_quantity,
      journal.invalid_count
    FROM inventory.inventory_transactions ledger
    LEFT JOIN inventory.availability_claim_dispatch_receipts receipt
      ON receipt.inventory_transaction_id = ledger.id
    LEFT JOIN LATERAL (
      SELECT SUM(movement.quantity) AS quantity,
        COUNT(*) FILTER (WHERE pick.id IS NULL OR pick.movement_type <> 'pick'
          OR movement.quantity <= 0 OR movement.quantity > pick.quantity
          OR movement.claim_id <> receipt.claim_id OR movement.claim_line_id <> receipt.claim_line_id
          OR pick.claim_id <> receipt.claim_id OR pick.claim_line_id <> receipt.claim_line_id) AS invalid_count
      FROM inventory.availability_claim_dispatch_movements movement
      LEFT JOIN inventory.availability_claim_pick_movements pick ON pick.id = movement.pick_movement_id
      WHERE movement.receipt_id = receipt.id
    ) journal ON true
    WHERE ledger.transaction_type = 'ship'
      AND ledger.shipment_id = expected_shipment_id
      AND ledger.order_item_id = expected_order_item_id
      AND ledger.product_variant_id = expected_variant_id
      AND ledger.voided_at IS NULL
      AND (ledger.shipment_item_id IS NULL OR ledger.shipment_item_id = expected_source_item_id)
    ORDER BY ledger.id
  LOOP
    IF posting.posting_count > 1000
       OR (posting.order_id IS NOT NULL AND posting.order_id <> expected_order_id) THEN
      RAISE EXCEPTION 'Omission source % has invalid or unbounded shipment evidence', expected_source_item_id
        USING ERRCODE = '23514', CONSTRAINT = 'outbound_shipment_items_omission_inventory_proof_chk';
    END IF;
    IF posting.reference_type = 'availability_claim_dispatch' OR posting.receipt_id IS NOT NULL THEN
      canonical_valid := posting.posting_count = 1
        AND posting.reference_type = 'availability_claim_dispatch'
        AND posting.receipt_id IS NOT NULL
        AND posting.variant_qty_delta = 0 AND posting.reserved_qty_delta = 0
        AND posting.source_state = 'picked' AND posting.target_state = 'shipped'
        AND posting.order_id = expected_order_id AND posting.receipt_order_id = posting.order_id
        AND posting.receipt_order_item_id = posting.order_item_id
        AND posting.receipt_shipment_id = posting.shipment_id
        AND posting.shipment_item_id = expected_source_item_id
        AND posting.receipt_source_item_id = posting.shipment_item_id
        AND posting.receipt_variant_id = posting.product_variant_id
        AND posting.from_location_id > 0 AND posting.receipt_location_id = posting.from_location_id
        AND posting.receipt_warehouse_id > 0
        AND ((posting.receipt_physical_id IS NULL AND posting.receipt_physical_item_id IS NULL)
          OR (posting.receipt_physical_id > 0 AND posting.receipt_physical_item_id > 0))
        AND posting.receipt_quantity = expected_source_quantity
        AND posting.movement_quantity = posting.receipt_quantity
        AND posting.invalid_count = 0;
      IF canonical_valid IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'Omission source % lacks exact canonical dispatch evidence', expected_source_item_id
          USING ERRCODE = '23514', CONSTRAINT = 'outbound_shipment_items_omission_inventory_proof_chk';
      END IF;
      posted_quantity := posting.receipt_quantity;
    ELSE
      IF posting.variant_qty_delta IS NULL OR posting.variant_qty_delta >= 0 THEN
        RAISE EXCEPTION 'Omission source % lacks a negative legacy shipment debit', expected_source_item_id
          USING ERRCODE = '23514', CONSTRAINT = 'outbound_shipment_items_omission_inventory_proof_chk';
      END IF;
      posted_quantity := posted_quantity - posting.variant_qty_delta::bigint;
    END IF;
    IF posted_quantity > 2147483647 THEN
      RAISE EXCEPTION 'Omission source % shipment quantity exceeds the supported bound', expected_source_item_id
        USING ERRCODE = '23514', CONSTRAINT = 'outbound_shipment_items_omission_inventory_proof_chk';
    END IF;
  END LOOP;
  RETURN posted_quantity::integer;
END;
$$;


--
-- Name: pin_cutover_writer_admission(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.pin_cutover_writer_admission() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE current_epoch bigint;
BEGIN
  -- Hold SHARE until commit. Never wait behind a cutover owner after obtaining
  -- order/graph/cost locks elsewhere. A stale RR row-lock read raises 40001.
  SELECT epoch INTO current_epoch FROM inventory.cutover_admission_fence
    WHERE singleton_key=true FOR SHARE NOWAIT;
  IF NOT FOUND OR current_epoch <= 0 THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='CUTOVER_ADMISSION_SINGLETON_MISSING';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: protect_supplier_return_transaction(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.protect_supplier_return_transaction() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM inventory.supplier_return_allocations WHERE inventory_transaction_id=OLD.id)
 THEN RAISE EXCEPTION 'Recorded supplier return stock transaction is immutable' USING ERRCODE='23514'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END; $$;


