--
-- Name: sync_channel_policy_source_references(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.sync_channel_policy_source_references() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='UPDATE' AND NEW.source_fulfillment_node_ids IS NOT DISTINCT FROM OLD.source_fulfillment_node_ids THEN
    RETURN NEW;
  END IF;
  DELETE FROM inventory.channel_policy_source_node_references WHERE policy_id=NEW.id;
  INSERT INTO inventory.channel_policy_source_node_references(policy_id,fulfillment_node_id)
    SELECT NEW.id,node_id FROM unnest(NEW.source_fulfillment_node_ids) AS node_id ORDER BY node_id;
  RETURN NEW;
END $$;


--
-- Name: validate_availability_claim_dispatch_journal(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.validate_availability_claim_dispatch_journal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  receipt_key bigint;
  receipt_quantity bigint;
  movement_quantity numeric;
  matching_command boolean;
BEGIN
  IF TG_TABLE_NAME = 'availability_claim_dispatch_receipts' THEN
    receipt_key := NEW.id;
  ELSE
    receipt_key := NEW.receipt_id;
    -- Every inserted row has a deferred callback. Only the last row needs the
    -- aggregate check, avoiding repeated full sums for a large split-lot pick.
    IF NEW.id <> (
      SELECT movement.id FROM inventory.availability_claim_dispatch_movements movement
      WHERE movement.receipt_id = receipt_key ORDER BY movement.id DESC LIMIT 1
    ) THEN
      RETURN NULL;
    END IF;
  END IF;

  SELECT receipt.quantity,
    command.command_type = 'dispatch' AND command.order_id = receipt.order_id
  INTO receipt_quantity, matching_command
  FROM inventory.availability_claim_dispatch_receipts receipt
  JOIN inventory.availability_claim_commands command
    ON command.id = receipt.command_id AND command.claim_id = receipt.claim_id
  WHERE receipt.id = receipt_key;
  IF receipt_quantity IS NULL OR matching_command IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'Dispatch receipt requires its exact dispatch command and order';
  END IF;

  SELECT COALESCE(sum(movement.quantity), 0) INTO movement_quantity
  FROM inventory.availability_claim_dispatch_movements movement
  WHERE movement.receipt_id = receipt_key;
  IF movement_quantity <> receipt_quantity THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'Dispatch receipt quantity must equal its exact pick movement quantities';
  END IF;
  IF EXISTS (
    SELECT 1 FROM inventory.availability_claim_dispatch_movements movement
    JOIN inventory.availability_claim_pick_movements pick ON pick.id = movement.pick_movement_id
    WHERE movement.receipt_id = receipt_key AND pick.movement_type <> 'pick'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'Dispatch movements must reference original pick movements';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: validate_availability_claim_replacement_lineage(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.validate_availability_claim_replacement_lineage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  predecessor_order_id INTEGER;
  predecessor_revision INTEGER;
  predecessor_status VARCHAR(30);
BEGIN
  IF TG_OP = 'UPDATE'
     AND (
       NEW.supersedes_claim_id IS DISTINCT FROM OLD.supersedes_claim_id
       OR NEW.order_id IS DISTINCT FROM OLD.order_id
       OR NEW.revision IS DISTINCT FROM OLD.revision
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      CONSTRAINT = 'availability_claims_replacement_lineage_immutable_chk',
      MESSAGE = 'canonical claim replacement lineage is immutable';
  END IF;

  IF NEW.supersedes_claim_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT predecessor.order_id, predecessor.revision, predecessor.status
    INTO predecessor_order_id, predecessor_revision, predecessor_status
  FROM inventory.availability_claims AS predecessor
  WHERE predecessor.id = NEW.supersedes_claim_id;

  IF NOT FOUND OR predecessor_order_id <> NEW.order_id THEN
    RAISE EXCEPTION USING
      ERRCODE = '23503',
      CONSTRAINT = 'availability_claims_supersedes_same_order_fk',
      MESSAGE = 'replacement claim predecessor must belong to the same order';
  END IF;
  IF predecessor_status <> 'superseded' THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      CONSTRAINT = 'availability_claims_supersedes_status_chk',
      MESSAGE = 'replacement claim predecessor must already be superseded in this transaction';
  END IF;
  IF predecessor_revision + 1 <> NEW.revision THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      CONSTRAINT = 'availability_claims_supersedes_revision_chk',
      MESSAGE = 'replacement claim must immediately follow its predecessor revision';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.status <> 'active' THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      CONSTRAINT = 'availability_claims_supersedes_status_chk',
      MESSAGE = 'replacement claim must begin in the active state';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_cost_origin_amendment(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.validate_cost_origin_amendment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM inventory.lot_cost_origins origin
    JOIN procurement.receipt_shipment_quantity_amendments amendment ON amendment.id=NEW.amendment_id
    JOIN procurement.inbound_shipment_lines line ON line.id=amendment.inbound_shipment_line_id
    WHERE origin.inventory_lot_id=NEW.inventory_lot_id
      AND origin.purchase_order_line_id=amendment.purchase_order_line_id
      AND line.purchase_order_line_id=amendment.purchase_order_line_id
      AND (origin.inbound_shipment_line_id IS NULL)=(NEW.shipment_start_base_piece IS NULL)
  ) THEN
    RAISE EXCEPTION 'Cost origin amendment must retain its original purchase and shipment ownership' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_cost_reconciliation_posting(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.validate_cost_reconciliation_posting() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE prior_after bigint;
BEGIN
  IF NEW.previous_posting_id IS NULL THEN
    IF NEW.before_mills<>0 THEN RAISE EXCEPTION 'Initial reconciliation balance must be zero'; END IF;
  ELSE
    SELECT after_mills INTO STRICT prior_after FROM inventory.cost_reconciliation_postings
    WHERE id=NEW.previous_posting_id AND destination=NEW.destination AND component=NEW.component
      AND inbound_shipment_line_id IS NOT DISTINCT FROM NEW.inbound_shipment_line_id
      AND purchase_order_line_id IS NOT DISTINCT FROM NEW.purchase_order_line_id;
    IF NEW.before_mills<>prior_after THEN RAISE EXCEPTION 'Reconciliation balance does not continue its predecessor'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_operational_shipment_dispatch_journal(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.validate_operational_shipment_dispatch_journal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  receipt_key bigint;
  evidence record;
BEGIN
  IF TG_TABLE_NAME = 'operational_shipment_dispatch_receipts' THEN
    receipt_key := NEW.id;
  ELSE
    receipt_key := NEW.receipt_id;
    -- Only the last lot's deferred callback needs the aggregate check, avoiding
    -- quadratic journal verification for large exact FIFO allocations.
    IF NEW.id <> (SELECT movement.id FROM inventory.operational_shipment_dispatch_lots movement
      WHERE movement.receipt_id=receipt_key ORDER BY movement.id DESC LIMIT 1) THEN
      RETURN NULL;
    END IF;
  END IF;
  SELECT receipt.*, journal.quantity AS lot_quantity, journal.total_cost_mills AS lot_cost,
    journal.invalid_count,
    ledger.transaction_type='ship' AND ledger.reference_type='operational_shipment'
      AND ledger.order_id=receipt.order_id AND ledger.order_item_id IS NULL
      AND ledger.shipment_id=receipt.outbound_shipment_id AND ledger.shipment_item_id=receipt.source_shipment_item_id
      AND ledger.product_variant_id=receipt.product_variant_id AND ledger.from_location_id=receipt.warehouse_location_id
      AND ledger.variant_qty_delta=-receipt.quantity AND ledger.reserved_qty_delta=0
      AND ledger.variant_qty_before-ledger.variant_qty_after=receipt.quantity
      AND ledger.source_state='on_hand' AND ledger.target_state='shipped'
      AND ledger.total_cost_mills=receipt.total_cost_mills AS ledger_valid,
    source.shipment_id=receipt.outbound_shipment_id AND source.product_variant_id=receipt.product_variant_id
      AND source.qty=receipt.quantity AND source.shipment_item_purpose=receipt.purpose
      AND source.order_item_id IS NULL AND source.correction_for_shipment_item_id IS NULL
      AND source.replacement_for_order_item_id IS NOT DISTINCT FROM receipt.replacement_for_order_item_id AS source_valid
  INTO evidence
  FROM inventory.operational_shipment_dispatch_receipts receipt
  JOIN inventory.inventory_transactions ledger ON ledger.id=receipt.inventory_transaction_id
  JOIN wms.outbound_shipment_items source ON source.id=receipt.source_shipment_item_id
  LEFT JOIN LATERAL (
    SELECT SUM(movement.quantity) AS quantity, SUM(movement.total_cost_mills) AS total_cost_mills,
      COUNT(*) FILTER (WHERE lot.id IS NULL OR lot.product_variant_id<>receipt.product_variant_id
        OR lot.warehouse_location_id<>receipt.warehouse_location_id) AS invalid_count
    FROM inventory.operational_shipment_dispatch_lots movement
    LEFT JOIN inventory.inventory_lots lot ON lot.id=movement.inventory_lot_id
    WHERE movement.receipt_id=receipt.id
  ) journal ON true
  WHERE receipt.id=receipt_key;
  IF evidence.id IS NULL OR evidence.ledger_valid IS DISTINCT FROM TRUE OR evidence.source_valid IS DISTINCT FROM TRUE
    OR evidence.lot_quantity IS DISTINCT FROM evidence.quantity::numeric
    OR evidence.lot_cost IS DISTINCT FROM evidence.total_cost_mills::numeric OR evidence.invalid_count IS DISTINCT FROM 0::bigint THEN
    RAISE EXCEPTION USING ERRCODE='23514',
      MESSAGE='Operational shipment requires exact source, on-hand debit, and complete FIFO quantity/cost journal';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: wake_publication_worker(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.wake_publication_worker() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM pg_notify('inventory_publication_work', '');
  RETURN NULL;
END;
$$;


--
-- Name: assert_provider_account_owner_verified(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.assert_provider_account_owner_verified() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  owner_verified BOOLEAN := FALSE;
BEGIN
  IF NEW.identity_scheme IS DISTINCT FROM 'provider_user_id' THEN
    RAISE EXCEPTION 'Provider account registration requires provider_user_id identity'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.owner_kind = 'channel' THEN
    SELECT token.external_account_verified_at = NEW.verified_at
      INTO owner_verified
    FROM ebay.ebay_oauth_tokens AS token
    JOIN channels.channels AS channel ON channel.id = token.channel_id
    WHERE token.channel_id = NEW.channel_id
      AND lower(channel.provider) = NEW.provider
      AND token.environment = NEW.account_namespace
      AND token.external_account_id = NEW.external_account_id
      AND token.external_account_identity_scheme = 'provider_user_id'
      AND token.external_account_verified_at IS NOT NULL
    FOR UPDATE OF token;
  ELSIF NEW.owner_kind = 'dropship' THEN
    SELECT connection.external_account_verified_at = NEW.verified_at
      INTO owner_verified
    FROM dropship.dropship_store_connections AS connection
    WHERE connection.id = NEW.store_connection_id
      AND lower(connection.platform) = NEW.provider
      AND connection.provider_environment = NEW.account_namespace
      AND connection.external_account_id = NEW.external_account_id
      AND connection.external_account_identity_scheme = 'provider_user_id'
      AND connection.external_account_verified_at IS NOT NULL
    FOR UPDATE;
  ELSE
    owner_verified := FALSE;
  END IF;

  IF owner_verified IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'Provider account owner does not contain matching stable provider_user_id evidence'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: capture_listing_intent_change(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.capture_listing_intent_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE prior jsonb; current_row jsonb; before_scope jsonb; after_scope jsonb; fields text[];
  actor_field text; actor_value text; provenance jsonb; actor_row jsonb;
BEGIN
  fields:=string_to_array(TG_ARGV[1],',');
  IF TG_OP<>'INSERT' THEN prior:=marketplace.listing_intent_row_projection(OLD,fields); END IF;
  IF TG_OP<>'DELETE' THEN current_row:=marketplace.listing_intent_row_projection(NEW,fields); END IF;
  IF prior IS NOT DISTINCT FROM current_row THEN RETURN NULL; END IF;
  -- Scope is a retained source fact, including OLD scope on deletes/moves.
  SELECT jsonb_object_agg(key,value) INTO before_scope FROM jsonb_each(prior)
    WHERE key=ANY(string_to_array(TG_ARGV[2],','));
  SELECT jsonb_object_agg(key,value) INTO after_scope FROM jsonb_each(current_row)
    WHERE key=ANY(string_to_array(TG_ARGV[2],','));
  -- Actor-only updates do not invalidate content. Capture available attribution
  -- separately after the desired-value comparison, without reading credentials.
  IF COALESCE(TG_ARGV[3],'')<>'' THEN
    IF TG_OP='DELETE' THEN actor_row:=marketplace.listing_intent_row_projection(OLD,string_to_array(TG_ARGV[3],','));
    ELSE actor_row:=marketplace.listing_intent_row_projection(NEW,string_to_array(TG_ARGV[3],',')); END IF;
  END IF;
  actor_field:=CASE WHEN actor_row?'updated_by' THEN 'updated_by'
    WHEN actor_row?'actor_id' THEN 'actor_id' WHEN actor_row?'created_by' THEN 'created_by' ELSE NULL END;
  actor_value:=actor_row->>actor_field;
  provenance:=jsonb_build_object('databasePrincipal',session_user,'humanActorKnown',false,
    'sourceActorField',actor_field,'sourceActorValue',actor_value,
    'sourceRevisionId',COALESCE(current_row,prior)->'revision_id');
  INSERT INTO marketplace.listing_intent_changes(source_relation,source_kind,changed_fields,operation,before_scope,after_scope,
    before_hash,after_hash,actor_provenance,source_transaction)
    VALUES(TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME,TG_ARGV[0],
      ARRAY(SELECT key FROM jsonb_object_keys(COALESCE(prior,'{}')||COALESCE(current_row,'{}')) key
        WHERE prior->key IS DISTINCT FROM current_row->key ORDER BY key),TG_OP,before_scope,after_scope,
      CASE WHEN prior IS NOT NULL THEN encode(sha256(convert_to(prior::text,'UTF8')),'hex') END,
      CASE WHEN current_row IS NOT NULL THEN encode(sha256(convert_to(current_row::text,'UTF8')),'hex') END,
      provenance,pg_current_xact_id());
  RETURN NULL;
END; $$;


--
-- Name: check_channel_sync_batch_members(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.check_channel_sync_batch_members() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.member_count<>(SELECT count(*) FROM marketplace.channel_sync_batch_members WHERE batch_id=NEW.id) THEN
    RAISE EXCEPTION 'Sync batch must save every selected product' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: check_listing_member_recovery_complete(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.check_listing_member_recovery_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM marketplace.listing_member_retirements r
    JOIN marketplace.listing_member_retirement_events e ON e.operation_id=r.id AND e.version=r.version
    WHERE r.id=NEW.operation_id AND r.dispatch_status='authorized' AND r.dispatch_key=NEW.command_key
      AND r.state='pending' AND NOT r.recovery_required AND r.version=(NEW.before_record->>'version')::int+1
      AND e.actor=NEW.actor AND e.after_state=to_jsonb(r)) THEN
    RAISE EXCEPTION 'Recovery authorization and audited scheduling must commit together' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: enforce_listing_replacement_publication_consistency(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.enforce_listing_replacement_publication_consistency() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  checked_operation_id BIGINT;
  operation_status TEXT;
  operation_phase TEXT;
  source_status TEXT;
  target_status TEXT;
  target_has_external_effect BOOLEAN;
  compensation_step_count INTEGER;
BEGIN
  IF TG_TABLE_NAME = 'listing_replacement_operations' THEN
    checked_operation_id := NEW.id;
  ELSE
    IF OLD.status = 'active' AND NEW.status = 'withdrawn' THEN
      IF EXISTS (
        SELECT 1
        FROM marketplace.listing_replacement_operations
        WHERE source_publication_id = NEW.id
          AND scope_id = NEW.scope_id
          AND status IN (
            'planned', 'running', 'compensating', 'manual_recovery_required'
          )
      ) THEN
        RAISE EXCEPTION 'An active replacement source cannot be withdrawn'
          USING ERRCODE = '23514';
      END IF;
      RETURN NULL;
    END IF;

    IF OLD.status = 'active' AND NEW.status = 'superseded' THEN
      SELECT operation.id INTO checked_operation_id
      FROM marketplace.listing_replacement_operations AS operation
      WHERE operation.source_publication_id = NEW.id
        AND operation.scope_id = NEW.scope_id
        AND operation.status = 'completed'
      ORDER BY operation.id DESC
      LIMIT 1;
      IF checked_operation_id IS NULL THEN
        RAISE EXCEPTION 'Publication supersession requires a completed replacement operation'
          USING ERRCODE = '23514';
      END IF;
    ELSE
      SELECT operation.id INTO checked_operation_id
      FROM marketplace.listing_replacement_operations AS operation
      WHERE operation.target_publication_id = NEW.id;
    END IF;

    IF checked_operation_id IS NULL THEN
      RETURN NULL;
    END IF;
  END IF;

  SELECT status, current_phase
    INTO operation_status, operation_phase
  FROM marketplace.listing_replacement_operations
  WHERE id = checked_operation_id;

  SELECT publication.status INTO source_status
  FROM marketplace.listing_publications AS publication
  JOIN marketplace.listing_replacement_operations AS operation
    ON operation.source_publication_id = publication.id
   AND operation.scope_id = publication.scope_id
  WHERE operation.id = checked_operation_id;

  SELECT
    publication.status,
    publication.provider_publication_key IS NOT NULL
      OR publication.external_listing_id IS NOT NULL
      OR publication.external_url IS NOT NULL
      OR publication.published_at IS NOT NULL
      OR EXISTS (
        SELECT 1
        FROM marketplace.listing_publication_members AS member
        WHERE member.publication_id = publication.id
          AND (
            member.external_variant_id IS NOT NULL
            OR member.external_offer_id IS NOT NULL
            OR member.external_inventory_item_id IS NOT NULL
          )
      )
    INTO target_status, target_has_external_effect
  FROM marketplace.listing_publications AS publication
  JOIN marketplace.listing_replacement_operations AS operation
    ON operation.target_publication_id = publication.id
   AND operation.scope_id = publication.scope_id
  WHERE operation.id = checked_operation_id;

  IF operation_status = 'planned' AND (
    source_status IS DISTINCT FROM 'active'
    OR target_status IS DISTINCT FROM 'planned'
    OR target_has_external_effect IS DISTINCT FROM FALSE
  ) THEN
    RAISE EXCEPTION 'Planned replacement publication state is inconsistent'
      USING ERRCODE = '23514';
  ELSIF operation_status = 'running' AND operation_phase IN ('preflight', 'cutover') AND (
    source_status IS DISTINCT FROM 'active'
    OR target_status IS DISTINCT FROM 'planned'
    OR target_has_external_effect IS DISTINCT FROM FALSE
  ) THEN
    RAISE EXCEPTION 'Pre-publication replacement state is inconsistent'
      USING ERRCODE = '23514';
  ELSIF operation_status = 'running' AND operation_phase = 'publish' AND (
    source_status IS DISTINCT FROM 'active'
    OR NOT (
      (target_status IS NOT DISTINCT FROM 'planned' AND target_has_external_effect IS FALSE)
      OR target_status IS NOT DISTINCT FROM 'staged'
    )
  ) THEN
    RAISE EXCEPTION 'Publishing replacement state is inconsistent'
      USING ERRCODE = '23514';
  ELSIF operation_status = 'running' AND operation_phase IN ('verify', 'switch_mapping') AND (
    source_status IS DISTINCT FROM 'active'
    OR target_status IS DISTINCT FROM 'staged'
  ) THEN
    RAISE EXCEPTION 'Verified replacement state is inconsistent'
      USING ERRCODE = '23514';
  ELSIF operation_status = 'compensating' AND (
    operation_phase IS DISTINCT FROM 'compensate'
    OR source_status IS DISTINCT FROM 'active'
    OR (
      target_status IS DISTINCT FROM 'planned'
      AND target_status IS DISTINCT FROM 'staged'
    )
  ) THEN
    RAISE EXCEPTION 'Compensating replacement publication state is inconsistent'
      USING ERRCODE = '23514';
  ELSIF operation_status = 'manual_recovery_required' AND (
    source_status IS DISTINCT FROM 'active'
    OR (
      operation_phase IN ('preflight', 'cutover')
      AND (
        target_status IS DISTINCT FROM 'planned'
        OR target_has_external_effect IS DISTINCT FROM FALSE
      )
    )
    OR (
      operation_phase = 'publish'
      AND NOT (
        (target_status IS NOT DISTINCT FROM 'planned' AND target_has_external_effect IS FALSE)
        OR target_status IS NOT DISTINCT FROM 'staged'
      )
    )
    OR (
      operation_phase IN ('verify', 'switch_mapping')
      AND target_status IS DISTINCT FROM 'staged'
    )
    OR (
      operation_phase = 'compensate'
      AND (
        target_status IS DISTINCT FROM 'planned'
        AND target_status IS DISTINCT FROM 'staged'
      )
    )
  ) THEN
    RAISE EXCEPTION 'Manual-recovery publication state is inconsistent'
      USING ERRCODE = '23514';
  ELSIF operation_status = 'completed' AND (
    operation_phase IS DISTINCT FROM 'complete'
    OR source_status IS DISTINCT FROM 'superseded'
    OR target_status IS DISTINCT FROM 'active'
  ) THEN
    RAISE EXCEPTION 'Completed replacement publication state is inconsistent'
      USING ERRCODE = '23514';
  ELSIF operation_status IN ('cancelled', 'failed') AND operation_phase = 'preflight' AND (
    source_status IS DISTINCT FROM 'active'
    OR target_status IS DISTINCT FROM 'failed'
    OR target_has_external_effect IS DISTINCT FROM FALSE
  ) THEN
    RAISE EXCEPTION 'Preflight terminal replacement publication state is inconsistent'
      USING ERRCODE = '23514';
  ELSIF operation_status = 'failed' AND operation_phase = 'compensate' THEN
    SELECT COUNT(*) INTO compensation_step_count
    FROM marketplace.listing_replacement_steps
    WHERE operation_id = checked_operation_id
      AND execution_path = 'compensation';
    IF source_status IS DISTINCT FROM 'active'
       OR target_status IS DISTINCT FROM 'failed'
       OR compensation_step_count = 0
       OR EXISTS (
         SELECT 1
         FROM marketplace.listing_replacement_steps
         WHERE operation_id = checked_operation_id
           AND execution_path = 'compensation'
           AND status <> 'succeeded'
       ) THEN
      RAISE EXCEPTION 'Compensated replacement publication state is inconsistent'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: enforce_listing_scope_owner_binding(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.enforce_listing_scope_owner_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  target_scope_id BIGINT;
  scope_kind TEXT;
  channel_bound BOOLEAN;
  dropship_bound BOOLEAN;
BEGIN
  -- The trigger is shared by tables with different row shapes. Branch before
  -- referencing table-specific fields because PL/pgSQL resolves every field in
  -- a CASE expression against the active trigger record at runtime.
  IF TG_TABLE_NAME = 'listing_scopes' THEN
    target_scope_id := NEW.id;
  ELSE
    target_scope_id := NEW.scope_id;
  END IF;

  SELECT owner_kind INTO scope_kind
  FROM marketplace.listing_scopes
  WHERE id = target_scope_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM marketplace.channel_listing_scopes WHERE scope_id = target_scope_id
  ) INTO channel_bound;
  SELECT EXISTS (
    SELECT 1 FROM marketplace.dropship_listing_scopes WHERE scope_id = target_scope_id
  ) INTO dropship_bound;

  IF (scope_kind = 'channel' AND (NOT channel_bound OR dropship_bound))
     OR (scope_kind = 'dropship' AND (NOT dropship_bound OR channel_bound)) THEN
    RAISE EXCEPTION 'Listing scope % must have exactly one matching owner binding', target_scope_id
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: guard_channel_listing_claim_transfer(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.guard_channel_listing_claim_transfer() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
  IF (NEW.account_key,NEW.external_sku,NEW.channel_id,NEW.product_variant_id,NEW.created_at)
    IS DISTINCT FROM (OLD.account_key,OLD.external_sku,OLD.channel_id,OLD.product_variant_id,OLD.created_at)
    OR NEW.operation_id=OLD.operation_id THEN
    RAISE EXCEPTION 'Listing claim identity is immutable';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM marketplace.channel_listing_operations o,
      jsonb_array_elements(o.progress->'items') i,
      jsonb_array_elements(o.progress->'batches') b
    WHERE o.id=OLD.operation_id AND i->>'variantId'=OLD.product_variant_id::text
      AND i->>'sku'=OLD.external_sku AND i->>'state'='needs_attention' AND i->>'canRetry'='true'
      AND b->>'state'='processed' AND b->'variantIds' @> to_jsonb(ARRAY[OLD.product_variant_id])
  ) AND NOT EXISTS (
    SELECT 1 FROM marketplace.channel_listing_operations old_op
    JOIN marketplace.channel_listing_operations next_op ON next_op.id=NEW.operation_id,
      jsonb_array_elements(old_op.progress->'items') i,
      jsonb_array_elements(old_op.progress->'batches') b,
      jsonb_array_elements(old_op.snapshot->'draft'->'items') old_d,
      jsonb_array_elements(old_op.snapshot->'catalog') old_c,
      jsonb_array_elements(next_op.snapshot->'recreations') r,
      jsonb_array_elements(next_op.snapshot->'draft'->'items') d,
      jsonb_array_elements(next_op.snapshot->'catalog') c,
      jsonb_array_elements(next_op.snapshot->'prepared') p
    WHERE old_op.id=OLD.operation_id AND old_op.channel_id=NEW.channel_id
      AND next_op.channel_id=NEW.channel_id AND next_op.account_key=NEW.account_key
      AND old_op.account_key=NEW.account_key AND next_op.snapshot->'account'->>'provider'='walmart'
      AND next_op.snapshot->'review'->>'canSubmit'='true'
      AND next_op.state='queued' AND old_op.lease_token IS NULL
      AND i->>'variantId'=NEW.product_variant_id::text AND i->>'sku'=NEW.external_sku
      AND i->>'state'='superseded' AND i->>'recreatedByOperationId'=NEW.operation_id::text
      AND b->>'state'='processed' AND b->'variantIds' @> to_jsonb(ARRAY[NEW.product_variant_id])
      AND r->>'operationId'=OLD.operation_id::text AND r->>'sku'=NEW.external_sku
      AND r->>'variantId'=NEW.product_variant_id::text
      AND (i->'externalProductId'='null'::jsonb OR r->'previousExternalProductId' IS NOT DISTINCT FROM i->'externalProductId')
      AND r->>'sourceHash' ~ '^[a-f0-9]{64}$'
      AND (r->>'checkedAt')::timestamptz <= next_op.created_at
      AND (r->>'checkedAt')::timestamptz >= next_op.created_at - interval '15 minutes'
      AND d->>'variantId'=NEW.product_variant_id::text AND d->>'method' IN ('create','match')
      AND d->>'recreateFromOperationId'=OLD.operation_id::text
      AND p->>'variantId'=NEW.product_variant_id::text AND p->>'sku'=NEW.external_sku
      AND p->>'feedType'=CASE d->>'method' WHEN 'match' THEN 'MP_ITEM_MATCH' ELSE 'MP_ITEM' END
      AND old_d->>'variantId'=NEW.product_variant_id::text
      AND old_c->>'variantId'=NEW.product_variant_id::text AND old_c->>'sku'=NEW.external_sku
      AND c->>'variantId'=NEW.product_variant_id::text AND c->>'sku'=NEW.external_sku
      AND jsonb_typeof(COALESCE(NULLIF(old_d->'identifier','null'::jsonb),old_c->'identifier'))='object'
      AND COALESCE(NULLIF(d->'identifier','null'::jsonb),c->'identifier')
        = COALESCE(NULLIF(old_d->'identifier','null'::jsonb),old_c->'identifier')
  ) THEN
    RAISE EXCEPTION 'Only a rejected claim or an explicitly reviewed missing listing may transfer';
  END IF;
  RETURN NEW;
END;
$_$;


