-- Name: guard_channel_listing_operation_intent(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.guard_channel_listing_operation_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.id, NEW.channel_id, NEW.account_key, NEW.command_key, NEW.request_hash, NEW.review_id, NEW.snapshot, NEW.created_by, NEW.created_at)
    IS DISTINCT FROM (OLD.id, OLD.channel_id, OLD.account_key, OLD.command_key, OLD.request_hash, OLD.review_id, OLD.snapshot, OLD.created_by, OLD.created_at) THEN
    RAISE EXCEPTION 'Listing publication intent is immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_channel_listing_scope(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.guard_channel_listing_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  scope_row marketplace.listing_scopes%ROWTYPE;
  channel_provider TEXT;
BEGIN
  SELECT * INTO scope_row
  FROM marketplace.listing_scopes
  WHERE id = NEW.scope_id;

  SELECT lower(provider) INTO channel_provider
  FROM channels.channels
  WHERE id = NEW.channel_id;

  IF scope_row.id IS NULL OR channel_provider IS NULL
     OR scope_row.owner_kind IS DISTINCT FROM 'channel'
     OR scope_row.product_id IS DISTINCT FROM NEW.product_id
     OR scope_row.marketplace_id IS DISTINCT FROM NEW.marketplace_id
     OR scope_row.provider IS DISTINCT FROM channel_provider THEN
    RAISE EXCEPTION 'Channel listing scope owner/provider/product does not match scope %', NEW.scope_id
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_channel_listing_update_intent(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.guard_channel_listing_update_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.id,NEW.channel_id,NEW.account_key,NEW.sku,NEW.review_hash,NEW.intent,NEW.created_by,NEW.created_at,NEW.expires_at)
    IS DISTINCT FROM (OLD.id,OLD.channel_id,OLD.account_key,OLD.sku,OLD.review_hash,OLD.intent,OLD.created_by,OLD.created_at,OLD.expires_at)
    OR (OLD.command_key IS NOT NULL AND NEW.command_key IS DISTINCT FROM OLD.command_key)
    OR (OLD.submission_id IS NOT NULL AND NEW.submission_id IS DISTINCT FROM OLD.submission_id) THEN
    RAISE EXCEPTION 'Listing update intent and receipts are immutable';
  END IF;
  IF NEW.state IS DISTINCT FROM OLD.state AND NOT (
    (OLD.state='reviewed' AND NEW.state='queued') OR
    (OLD.state='queued' AND NEW.state IN ('sending','needs_attention')) OR
    (OLD.state='sending' AND NEW.state IN ('processing','needs_attention','uncertain')) OR
    (OLD.state='processing' AND NEW.state IN ('accepted','needs_attention'))
  ) THEN RAISE EXCEPTION 'Invalid listing update transition'; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_channel_sync_batch(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.guard_channel_sync_batch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Sync batches are retained' USING ERRCODE='23514'; END IF;
  IF (NEW.id,NEW.channel_id,NEW.destination,NEW.actor,NEW.member_count,NEW.created_at,NEW.owner_transaction_id)
    IS DISTINCT FROM (OLD.id,OLD.channel_id,OLD.destination,OLD.actor,OLD.member_count,OLD.created_at,OLD.owner_transaction_id)
    OR OLD.admission_completed_at IS NOT NULL THEN
    RAISE EXCEPTION 'Sync batch selection and completed admission are immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_channel_sync_batch_member(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.guard_channel_sync_batch_member() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP<>'INSERT' OR NOT EXISTS(SELECT 1 FROM marketplace.channel_sync_batches b
    WHERE b.id=NEW.batch_id AND b.owner_transaction_id=pg_current_xact_id() AND b.admission_completed_at IS NULL) THEN
    RAISE EXCEPTION 'Sync selection must be saved atomically and cannot change' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


