-- Name: guard_listing_lifecycle_identity(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.guard_listing_lifecycle_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.id,NEW.channel_id,NEW.account_key,NEW.account,NEW.sku,NEW.title,NEW.requested_by,NEW.requested_at)
    IS DISTINCT FROM (OLD.id,OLD.channel_id,OLD.account_key,OLD.account,OLD.sku,OLD.title,OLD.requested_by,OLD.requested_at)
    OR (OLD.action='remove' AND NEW.action<>'remove') OR (OLD.state='retired' AND NEW.state<>'retired') THEN
    RAISE EXCEPTION 'Listing lifecycle identity and completed retirement are immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_listing_member_recovery_command(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.guard_listing_member_recovery_command() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM marketplace.listing_member_retirements r WHERE r.id=NEW.operation_id
    AND to_jsonb(r)=NEW.before_record AND (r.recovery_required OR r.state='retiring')
    AND r.state NOT IN ('retired','superseded') AND NEW.observation->'identity'=r.identity
    AND jsonb_typeof(NEW.observation->'retired')='boolean'
    AND NEW.owner_transaction_id=pg_current_xact_id()) THEN
    RAISE EXCEPTION 'Member recovery requires the exact retained state and fresh identity observation' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_listing_member_recovery_transition(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.guard_listing_member_recovery_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.dispatch_status='authorized' AND OLD.dispatch_status<>'authorized')
    OR (OLD.recovery_required AND NOT NEW.recovery_required AND NEW.state NOT IN ('retired','superseded')) THEN
    IF NOT EXISTS(SELECT 1 FROM marketplace.listing_member_recovery_commands c WHERE c.operation_id=OLD.id
      AND c.command_key=NEW.dispatch_key AND c.before_record=to_jsonb(OLD) AND c.owner_transaction_id=pg_current_xact_id()) THEN
      RAISE EXCEPTION 'Removal recovery requires its immutable authorization' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_listing_member_retirement(); Type: FUNCTION; Schema: marketplace; Owner: -
--

CREATE FUNCTION marketplace.guard_listing_member_retirement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Listing member retirement history is immutable'; END IF;
  IF (NEW.id,NEW.identity_key,NEW.identity,NEW.source_identity,NEW.source_revision,NEW.product_id,NEW.product_variant_id,NEW.created_at)
      IS DISTINCT FROM (OLD.id,OLD.identity_key,OLD.identity,OLD.source_identity,OLD.source_revision,OLD.product_id,OLD.product_variant_id,OLD.created_at)
      OR OLD.state IN ('retired','superseded') OR (OLD.state='failed' AND OLD.code='LISTING_MEMBER_IDENTITY_INVALID') THEN
    RAISE EXCEPTION 'Listing member retirement identity and terminal evidence are immutable';
  END IF;
  RETURN NEW;
END;
$$;


