--
-- Name: capture_oms_order_intake(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.capture_oms_order_intake() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_provider TEXT;
BEGIN
  SELECT provider INTO v_provider
  FROM channels.channels
  WHERE id = NEW.channel_id;

  PERFORM oms.record_channel_order_intake(
    p_provider => COALESCE(v_provider, 'unknown'),
    p_external_order_id => NEW.external_order_id,
    p_external_order_number => NEW.external_order_number,
    p_channel_id => NEW.channel_id,
    p_observation_method => 'oms_ingest',
    p_raw_payload => NEW.raw_payload,
    p_status => 'ingested',
    p_oms_order_id => NEW.id,
    p_source_ordered_at => NEW.ordered_at,
    p_observed_at => NEW.created_at,
    p_increment_observation => FALSE,
    p_is_source_observation => FALSE
  );

  RETURN NEW;
END;
$$;


--
-- Name: capture_order_webhook_intake(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.capture_order_webhook_intake() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_external_order_id TEXT;
  v_external_order_number TEXT;
  v_channel_id INTEGER;
  v_is_shippable BOOLEAN;
  v_source_ordered_at TIMESTAMPTZ;
  v_status TEXT;
BEGIN
  IF LOWER(NEW.provider) = 'shopify'
     AND LOWER(NEW.topic) IN ('orders/paid', 'orders/updated', 'orders/cancelled', 'orders/fulfilled') THEN
    v_external_order_id := NEW.payload->>'id';
    v_external_order_number := COALESCE(NEW.payload->>'name', NEW.payload->>'order_number');
    IF jsonb_typeof(NEW.payload->'line_items') = 'array' THEN
      SELECT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(NEW.payload->'line_items') item
        WHERE COALESCE((item->>'quantity')::INTEGER, 0) > 0
          AND LOWER(COALESCE(item->>'requires_shipping', 'true')) NOT IN ('false', 'f', '0')
      ) INTO v_is_shippable;
    END IF;
    BEGIN
      v_source_ordered_at := NULLIF(NEW.payload->>'created_at', '')::TIMESTAMPTZ;
    EXCEPTION WHEN OTHERS THEN
      v_source_ordered_at := NULL;
    END;

    SELECT c.id
    INTO v_channel_id
    FROM channels.channels c
    LEFT JOIN channels.channel_connections cc ON cc.channel_id = c.id
    WHERE c.provider = 'shopify'
      AND (
        (NEW.source_domain IS NOT NULL AND LOWER(BTRIM(cc.shop_domain)) = LOWER(BTRIM(NEW.source_domain)))
        OR c.is_default = 1
      )
    ORDER BY CASE
      WHEN NEW.source_domain IS NOT NULL AND LOWER(BTRIM(cc.shop_domain)) = LOWER(BTRIM(NEW.source_domain)) THEN 0
      ELSE 1
    END, c.priority DESC, c.id
    LIMIT 1;
  ELSIF LOWER(NEW.provider) = 'ebay'
        AND LOWER(NEW.topic) LIKE '%order%' THEN
    v_external_order_id := COALESCE(
      NEW.payload #>> '{notification,data,orderId}',
      NEW.payload->>'orderId'
    );
    v_external_order_number := v_external_order_id;
    v_is_shippable := TRUE;

    SELECT c.id
    INTO v_channel_id
    FROM channels.channels c
    WHERE c.provider = 'ebay'
    ORDER BY c.is_default DESC, c.priority DESC, c.id
    LIMIT 1;
  ELSE
    RETURN NEW;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_external_order_id, '')), '') IS NULL THEN
    RETURN NEW;
  END IF;

  v_status := CASE
    WHEN NEW.status = 'failed' THEN 'failed'
    WHEN NEW.status = 'processing' THEN 'processing'
    ELSE 'observed'
  END;

  PERFORM oms.record_channel_order_intake(
    p_provider => NEW.provider,
    p_external_order_id => v_external_order_id,
    p_external_order_number => v_external_order_number,
    p_channel_id => v_channel_id,
    p_observation_method => 'webhook',
    p_source_domain => NEW.source_domain,
    p_source_inbox_id => NEW.id,
    p_source_event_id => NEW.event_id,
    p_raw_payload => NEW.payload,
    p_is_shippable => v_is_shippable,
    p_status => v_status,
    p_last_error => NEW.last_error,
    p_source_ordered_at => v_source_ordered_at,
    p_observed_at => COALESCE(NEW.first_received_at, NEW.created_at, NOW()),
    p_increment_observation => TG_OP = 'INSERT'
  );

  RETURN NEW;
END;
$$;


--
-- Name: capture_shopify_raw_order_intake(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.capture_shopify_raw_order_intake() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_channel_id INTEGER;
  v_source_ordered_at TIMESTAMPTZ;
BEGIN
  SELECT c.id
  INTO v_channel_id
  FROM channels.channels c
  LEFT JOIN channels.channel_connections cc ON cc.channel_id = c.id
  WHERE c.provider = 'shopify'
    AND (
      (NEW.shop_domain IS NOT NULL AND LOWER(BTRIM(cc.shop_domain)) = LOWER(BTRIM(NEW.shop_domain)))
      OR c.is_default = 1
    )
  ORDER BY CASE
    WHEN NEW.shop_domain IS NOT NULL AND LOWER(BTRIM(cc.shop_domain)) = LOWER(BTRIM(NEW.shop_domain)) THEN 0
    ELSE 1
  END, c.priority DESC, c.id
  LIMIT 1;

  v_source_ordered_at := COALESCE(NEW.order_date, NEW.created_at, NOW());

  PERFORM oms.record_channel_order_intake(
    p_provider => 'shopify',
    p_external_order_id => NEW.id,
    p_external_order_number => NEW.order_number,
    p_channel_id => v_channel_id,
    p_observation_method => 'shopify_raw',
    p_source_domain => NEW.shop_domain,
    p_raw_payload => to_jsonb(NEW),
    p_status => 'observed',
    p_source_ordered_at => v_source_ordered_at,
    p_increment_observation => TRUE
  );

  RETURN NEW;
END;
$$;


--
-- Name: channel_fulfillment_push_update_guard(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.channel_fulfillment_push_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.oms_order_id IS DISTINCT FROM OLD.oms_order_id
     OR NEW.physical_shipment_id IS DISTINCT FROM OLD.physical_shipment_id
     OR NEW.channel_provider IS DISTINCT FROM OLD.channel_provider
     OR NEW.channel_fulfillment_scope_key IS DISTINCT FROM OLD.channel_fulfillment_scope_key
     OR NEW.command_key IS DISTINCT FROM OLD.command_key
     OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
     OR NEW.tracking_number IS DISTINCT FROM OLD.tracking_number
     OR NEW.carrier IS DISTINCT FROM OLD.carrier
     OR NEW.tracking_url IS DISTINCT FROM OLD.tracking_url
     OR NEW.shipped_at IS DISTINCT FROM OLD.shipped_at
     OR NEW.max_attempts IS DISTINCT FROM OLD.max_attempts
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Channel fulfillment command identity and request snapshot are immutable'
      USING ERRCODE = '23514';
  END IF;

  IF OLD.command_key LIKE 'fulfillment:v1:%'
     AND NEW.metadata IS DISTINCT FROM OLD.metadata THEN
    RAISE EXCEPTION 'Canonical channel fulfillment command metadata is immutable'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.attempt_count < OLD.attempt_count THEN
    RAISE EXCEPTION 'Channel fulfillment attempt count cannot decrease'
      USING ERRCODE = '23514';
  END IF;

  IF OLD.push_status IN ('success', 'ignored', 'dead')
     AND NEW.push_status IS DISTINCT FROM OLD.push_status THEN
    RAISE EXCEPTION 'Terminal channel fulfillment commands are immutable'
      USING ERRCODE = '23514';
  END IF;

  IF (OLD.push_status = 'shadow' AND NEW.push_status NOT IN ('shadow', 'pending', 'review', 'dead'))
     OR (OLD.push_status = 'pending' AND NEW.push_status NOT IN ('pending', 'processing', 'review', 'dead'))
     OR (OLD.push_status = 'processing' AND NEW.push_status NOT IN ('processing', 'retry', 'success', 'ignored', 'review', 'dead'))
     OR (OLD.push_status = 'retry' AND NEW.push_status NOT IN ('retry', 'processing', 'review', 'dead'))
     OR (OLD.push_status = 'failed' AND NEW.push_status NOT IN ('failed', 'retry', 'processing', 'review', 'dead'))
     OR (OLD.push_status = 'review' AND NEW.push_status NOT IN ('review', 'pending', 'retry', 'dead')) THEN
    RAISE EXCEPTION 'Invalid channel fulfillment command status transition: % -> %', OLD.push_status, NEW.push_status
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: channel_fulfillment_receipt_item_update_guard(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.channel_fulfillment_receipt_item_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'channel_fulfillment_receipt_items is permanent inbound evidence; DELETE is not allowed'
      USING ERRCODE = '55000';
  END IF;

  IF OLD.physical_shipment_item_id IS NULL
     AND NEW.physical_shipment_item_id IS NOT NULL
     AND NEW.receipt_id IS NOT DISTINCT FROM OLD.receipt_id
     AND NEW.source_fulfillment_line_id IS NOT DISTINCT FROM OLD.source_fulfillment_line_id
     AND NEW.channel_order_line_id IS NOT DISTINCT FROM OLD.channel_order_line_id
     AND NEW.quantity IS NOT DISTINCT FROM OLD.quantity
     AND NEW.oms_order_line_id IS NOT DISTINCT FROM OLD.oms_order_line_id
     AND NEW.wms_order_item_id IS NOT DISTINCT FROM OLD.wms_order_item_id
     AND NEW.legacy_wms_shipment_item_id IS NOT DISTINCT FROM OLD.legacy_wms_shipment_item_id
     AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Channel fulfillment receipt item evidence is immutable after lineage attachment'
    USING ERRCODE = '23514';
END;
$$;


--
-- Name: channel_fulfillment_receipt_retry_update_guard(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.channel_fulfillment_receipt_retry_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.retry_failure_count < OLD.retry_failure_count
     OR NEW.retry_failure_count > OLD.retry_failure_count + 1 THEN
    RAISE EXCEPTION 'Channel fulfillment receipt retry_failure_count must be monotonic'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.retry_failure_count = OLD.retry_failure_count + 1
     AND NOT (
       OLD.processing_status = 'processing'
       AND NEW.processing_status IN ('pending', 'review')
     ) THEN
    RAISE EXCEPTION 'A receipt retry failure can only finish an active processing attempt'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.processing_status <> 'pending'
     AND NEW.next_retry_at IS NOT NULL THEN
    RAISE EXCEPTION 'Only pending channel fulfillment receipts may have next_retry_at'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: channel_fulfillment_receipt_update_guard(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.channel_fulfillment_receipt_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'channel_fulfillment_receipts is permanent inbound evidence; DELETE is not allowed'
      USING ERRCODE = '55000';
  END IF;

  IF NEW.receipt_key IS DISTINCT FROM OLD.receipt_key
     OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
     OR NEW.source_provider IS DISTINCT FROM OLD.source_provider
     OR (
       NEW.source_channel_id IS DISTINCT FROM OLD.source_channel_id
       AND NOT (OLD.source_channel_id IS NULL AND NEW.source_channel_id IS NOT NULL)
     )
     OR NEW.source_order_id IS DISTINCT FROM OLD.source_order_id
     OR NEW.source_fulfillment_id IS DISTINCT FROM OLD.source_fulfillment_id
     OR NEW.source_event_id IS DISTINCT FROM OLD.source_event_id
     OR NEW.source_inbox_id IS DISTINCT FROM OLD.source_inbox_id
     OR NEW.event_kind IS DISTINCT FROM OLD.event_kind
     OR NEW.source IS DISTINCT FROM OLD.source
     OR NEW.tracking_number IS DISTINCT FROM OLD.tracking_number
     OR NEW.carrier IS DISTINCT FROM OLD.carrier
     OR NEW.tracking_url IS DISTINCT FROM OLD.tracking_url
     OR NEW.shipped_at IS DISTINCT FROM OLD.shipped_at
     OR NEW.raw_payload IS DISTINCT FROM OLD.raw_payload
     OR NEW.correlation_id IS DISTINCT FROM OLD.correlation_id
     OR NEW.causation_id IS DISTINCT FROM OLD.causation_id
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Channel fulfillment receipt identity and payload snapshot are immutable'
      USING ERRCODE = '23514';
  END IF;

  IF OLD.processing_status IN ('processed', 'ignored')
     AND NEW.processing_status IS DISTINCT FROM OLD.processing_status THEN
    RAISE EXCEPTION 'Processed channel fulfillment receipts are terminal'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.attempt_count < OLD.attempt_count
     OR NEW.attempt_count > OLD.attempt_count + 1 THEN
    RAISE EXCEPTION 'Channel fulfillment receipt attempt_count must be monotonic'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.attempt_count = OLD.attempt_count + 1
     AND NEW.processing_status <> 'processing' THEN
    RAISE EXCEPTION 'A channel fulfillment receipt attempt can only begin in processing state'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: customer_action_label_order_ids(bigint); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.customer_action_label_order_ids(label_id bigint) RETURNS bigint[]
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'wms', 'oms'
    AS $$
  SELECT array_agg(DISTINCT ids.order_id) FROM wms.shipping_provider_label_links link
  CROSS JOIN LATERAL unnest(oms.customer_action_physical_order_ids(link.physical_shipment_id)) ids(order_id)
  WHERE link.shipping_provider_label_id=label_id;
$$;


--
-- Name: customer_action_physical_order_ids(bigint); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.customer_action_physical_order_ids(physical_id bigint) RETURNS bigint[]
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'wms', 'oms'
    AS $$
  SELECT array_agg(DISTINCT COALESCE(line.order_id,oms.customer_action_wms_order_id(wi.order_id)))
  FROM wms.physical_shipment_items item
  LEFT JOIN wms.order_items wi ON wi.id=item.wms_order_item_id
  LEFT JOIN wms.fulfillment_plan_lines plan ON plan.id=item.fulfillment_plan_line_id
  LEFT JOIN oms.oms_order_lines line ON line.id=plan.oms_order_line_id
  WHERE item.physical_shipment_id=physical_id;
$$;


--
-- Name: customer_action_wms_order_id(integer); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.customer_action_wms_order_id(wms_id integer) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'wms'
    AS $_$
  SELECT CASE WHEN wo.source='oms' AND wo.oms_fulfillment_order_id ~ '^[0-9]+$'
    AND length(wo.oms_fulfillment_order_id)<=18 THEN wo.oms_fulfillment_order_id::bigint
    WHEN wo.source_table_id ~ '^[0-9]+$' AND length(wo.source_table_id)<=18 THEN wo.source_table_id::bigint END
  FROM wms.orders wo WHERE wo.id=wms_id;
$_$;


--
-- Name: customer_order_actions_source_changed(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.customer_order_actions_source_changed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'oms', 'wms', 'returns', 'channels'
    AS $_$
<<source_changed>>
DECLARE value jsonb; before_value jsonb; source jsonb; ids bigint[]; all_ids bigint[]:=ARRAY[]::bigint[]; identifier bigint; record_id bigint;
BEGIN
  IF TG_OP='UPDATE' AND (to_jsonb(OLD)-'updated_at')=(to_jsonb(NEW)-'updated_at') THEN RETURN NEW; END IF;
  -- UPDATE OF also fires when an ORM lists an unchanged weight alongside other
  -- changed fields. Only an actual weight change affects return inspection.
  IF TG_ARGV[0]='catalog_variant' AND TG_OP='UPDATE'
    AND (to_jsonb(OLD)->'weight_grams') IS NOT DISTINCT FROM (to_jsonb(NEW)->'weight_grams') THEN RETURN NEW; END IF;
  IF TG_OP<>'INSERT' THEN before_value=to_jsonb(OLD); END IF;
  IF TG_OP<>'DELETE' THEN value=to_jsonb(NEW); END IF;
  -- Invalidate BOTH parents if a record is relinked. No slow provider I/O and no
  -- eligibility or financial decision is made while the source transaction runs.
  FOR source IN SELECT DISTINCT item FROM unnest(ARRAY[before_value,value]) item WHERE item IS NOT NULL LOOP
    ids=NULL; record_id=CASE WHEN source_changed.source->>'id' ~ '^[0-9]{1,18}$' THEN (source_changed.source->>'id')::bigint END;
    CASE TG_ARGV[0]
      WHEN 'oms_order' THEN ids=ARRAY[record_id];
      WHEN 'oms_line' THEN ids=ARRAY[(source_changed.source->>'order_id')::bigint];
      WHEN 'direct' THEN ids=ARRAY[(source_changed.source->>'oms_order_id')::bigint];
      WHEN 'wms_order' THEN
        identifier=CASE WHEN source_changed.source->>'source'='oms' AND source_changed.source->>'oms_fulfillment_order_id' ~ '^[0-9]{1,18}$'
          THEN (source_changed.source->>'oms_fulfillment_order_id')::bigint
          WHEN source_changed.source->>'source_table_id' ~ '^[0-9]{1,18}$' THEN (source_changed.source->>'source_table_id')::bigint END;
        ids=ARRAY[identifier];
      WHEN 'wms_child' THEN ids=ARRAY[oms.customer_action_wms_order_id((source_changed.source->>'order_id')::integer)];
      WHEN 'return_item' THEN SELECT ARRAY[oms.customer_action_wms_order_id(r.order_id)] INTO ids FROM wms.returns r WHERE r.id=(source_changed.source->>'return_id')::bigint;
      WHEN 'authorization_child' THEN SELECT ARRAY[a.oms_order_id] INTO ids FROM returns.customer_return_authorizations a WHERE a.id=(source_changed.source->>'authorization_id')::bigint;
      WHEN 'receipt_child' THEN SELECT ARRAY[r.oms_order_id] INTO ids FROM oms.channel_fulfillment_receipts r WHERE r.id=(source_changed.source->>'receipt_id')::bigint;
      WHEN 'push_child' THEN SELECT ARRAY[p.oms_order_id] INTO ids FROM oms.channel_fulfillment_pushes p WHERE p.id=(source_changed.source->>'channel_fulfillment_push_id')::bigint;
      WHEN 'physical' THEN ids=oms.customer_action_physical_order_ids(record_id);
      WHEN 'physical_item' THEN
        ids=oms.customer_action_physical_order_ids((source_changed.source->>'physical_shipment_id')::bigint);
        SELECT array_append(ids,COALESCE(line.order_id,oms.customer_action_wms_order_id(wi.order_id))) INTO ids
        FROM (SELECT 1) seed LEFT JOIN wms.order_items wi ON wi.id=(source_changed.source->>'wms_order_item_id')::integer
        LEFT JOIN wms.fulfillment_plan_lines plan ON plan.id=(source_changed.source->>'fulfillment_plan_line_id')::bigint
        LEFT JOIN oms.oms_order_lines line ON line.id=plan.oms_order_line_id;
      WHEN 'physical_adjustment' THEN
        SELECT oms.customer_action_physical_order_ids(item.physical_shipment_id) INTO ids
        FROM wms.physical_shipment_items item WHERE item.id=(source_changed.source->>'physical_shipment_item_id')::bigint;
      WHEN 'label' THEN ids=oms.customer_action_label_order_ids(record_id);
      WHEN 'label_link' THEN ids=oms.customer_action_physical_order_ids((source_changed.source->>'physical_shipment_id')::bigint);
      WHEN 'carrier_match' THEN ids=oms.customer_action_label_order_ids((source_changed.source->>'shipping_provider_label_id')::bigint);
      WHEN 'carrier_state' THEN
        SELECT oms.customer_action_label_order_ids(m.shipping_provider_label_id) INTO ids FROM wms.carrier_tracking_event_matches m
        WHERE m.id=(source_changed.source->>'last_match_attempt_id')::bigint;
      WHEN 'carrier_event' THEN
        SELECT array_agg(DISTINCT linked.order_id) INTO ids FROM wms.carrier_tracking_event_matches m
        CROSS JOIN LATERAL unnest(oms.customer_action_label_order_ids(m.shipping_provider_label_id)) linked(order_id)
        WHERE m.carrier_tracking_event_id=record_id;
      WHEN 'catalog_variant' THEN SELECT array_agg(DISTINCT line.order_id) INTO ids FROM oms.oms_order_lines line WHERE line.product_variant_id=record_id;
      WHEN 'inventory_return' THEN
        IF source_changed.source->>'transaction_type'='return' THEN
          ids=ARRAY[oms.customer_action_wms_order_id((source_changed.source->>'order_id')::integer)];
          SELECT array_append(ids,line.order_id) INTO ids FROM (SELECT 1) seed
          LEFT JOIN wms.order_items wi ON wi.id=(source_changed.source->>'order_item_id')::integer
          LEFT JOIN oms.oms_order_lines line ON line.id=wi.oms_order_line_id;
        END IF;
      WHEN 'channel_record' THEN
        SELECT array_agg(p.oms_order_id) INTO ids FROM oms.customer_order_actions p JOIN oms.oms_orders o ON o.id=p.oms_order_id WHERE o.channel_id=record_id;
      WHEN 'channel' THEN
        SELECT array_agg(p.oms_order_id) INTO ids FROM oms.customer_order_actions p JOIN oms.oms_orders o ON o.id=p.oms_order_id
        WHERE o.channel_id=(source_changed.source->>'channel_id')::integer;
      WHEN 'connection' THEN
        SELECT array_agg(p.oms_order_id) INTO ids FROM oms.customer_order_actions p JOIN oms.oms_orders o ON o.id=p.oms_order_id
        JOIN channels.channel_connections cc ON cc.channel_id=o.channel_id WHERE cc.id=(source_changed.source->>'connection_id')::integer;
      WHEN 'policy' THEN
        SELECT array_agg(p.oms_order_id) INTO ids FROM oms.customer_order_actions p JOIN oms.oms_orders o ON o.id=p.oms_order_id
        WHERE source_changed.source->>'channel_id' IS NULL OR o.channel_id=(source_changed.source->>'channel_id')::integer;
      WHEN 'policy_shipping' THEN
        SELECT array_agg(p.oms_order_id) INTO ids FROM oms.customer_order_actions p JOIN oms.oms_orders o ON o.id=p.oms_order_id
        JOIN returns.return_policies policy ON policy.id=(source_changed.source->>'policy_id')::integer
        WHERE policy.channel_id IS NULL OR o.channel_id=policy.channel_id;
      ELSE RAISE EXCEPTION 'Unknown order action invalidation source';
    END CASE;
    all_ids=array_cat(all_ids,COALESCE(ids,ARRAY[]::bigint[]));
  END LOOP;
  PERFORM oms.invalidate_customer_order_actions(all_ids);
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$_$;


--
-- Name: guard_order_ship_to_country(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.guard_order_ship_to_country() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP='UPDATE' AND NEW.ship_to_country IS NOT DISTINCT FROM OLD.ship_to_country THEN RETURN NEW; END IF;
  NEW.ship_to_country := oms.normalize_order_country(NEW.ship_to_country);
  RETURN NEW;
END;
$$;


