CREATE FUNCTION oms.guard_order_shipping_country() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP='UPDATE' AND NEW.shipping_country IS NOT DISTINCT FROM OLD.shipping_country THEN RETURN NEW; END IF;
  NEW.shipping_country := oms.normalize_order_country(NEW.shipping_country);
  RETURN NEW;
END;
$$;


--
-- Name: guard_package_allocation_commercial_activation(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.guard_package_allocation_commercial_activation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Package-allocation commercial fulfillment activations are append-only'
    USING ERRCODE = '23514';
END;
$$;


--
-- Name: guard_silent_fulfillment_retry_claim(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.guard_silent_fulfillment_retry_claim() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.push_status = 'processing'
     AND NEW.notification_policy_attempt IS DISTINCT FROM NEW.attempt_count
     AND EXISTS (
       SELECT 1 FROM oms.channel_fulfillment_push_requeues audit
       WHERE audit.channel_fulfillment_push_id = NEW.id
         AND audit.previous_request_hash = NEW.request_hash
         AND audit.notify_customer_override = FALSE
     ) THEN
    RAISE EXCEPTION 'Silent fulfillment retry requires a notification-policy-aware worker'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: invalidate_customer_order_actions(bigint[]); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.invalidate_customer_order_actions(order_ids bigint[]) RETURNS void
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'oms', 'channels'
    AS $_$
  INSERT INTO oms.customer_order_action_invalidations(oms_order_id)
    SELECT DISTINCT o.id FROM oms.oms_orders o JOIN channels.channels c ON c.id=o.channel_id
    WHERE o.id=ANY(order_ids) AND c.provider='shopify' AND o.external_customer_id ~ '^[1-9][0-9]*$'
    ORDER BY o.id;
$_$;


--
-- Name: normalize_order_country(text); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.normalize_order_country(input text) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  cleaned TEXT;
  canonical TEXT;
BEGIN
  IF input IS NULL THEN RETURN NULL; END IF;
  IF char_length(input)>100 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='ORDER_COUNTRY_INVALID';
  END IF;
  -- Match JavaScript NFD/combining-mark removal and its explicit trim set.
  cleaned := btrim(regexp_replace(normalize(input,NFD), U&'[\0300-\036f]', '', 'g'), U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF');
  IF cleaned='' THEN RETURN NULL; END IF;
  -- Match the application's ASCII ISO-code branch, independent of database or
  -- caller collation. Unicode case folding must not turn confusables into codes.
  IF cleaned COLLATE "C" ~ '^[A-Za-z]{2}$' THEN
    SELECT code INTO canonical FROM oms.order_country_codes WHERE code=upper(cleaned COLLATE "C");
  END IF;
  IF canonical IS NULL THEN
    SELECT code INTO canonical FROM oms.order_country_aliases WHERE alias=lower(cleaned COLLATE "C");
  END IF;
  IF canonical IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='ORDER_COUNTRY_INVALID';
  END IF;
  RETURN canonical;
END;
$_$;


--
-- Name: protect_label_recovery_attempts(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.protect_label_recovery_attempts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Label recovery attempts are immutable' USING ERRCODE = '55000';
END; $$;


--
-- Name: protect_label_recovery_work(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.protect_label_recovery_work() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' OR OLD.state <> 'pending'
    OR ROW(NEW.provider_label_id, NEW.provider_order_id, NEW.tracking_number, NEW.created_at)
      IS DISTINCT FROM ROW(OLD.provider_label_id, OLD.provider_order_id, OLD.tracking_number, OLD.created_at) THEN
    RAISE EXCEPTION 'Label recovery identity and terminal evidence are immutable' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: protect_order_edit_paid_line(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.protect_order_edit_paid_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE protected_operation uuid; source_topic text; before_row jsonb; after_row jsonb;
BEGIN
  after_row := to_jsonb(NEW);
  source_topic := after_row->>'authority_source_topic';
  IF source_topic NOT IN ('orders/create','orders/paid','orders/updated','shopify/bridge','shopify/reconcile','reconciler/authorize')
    OR source_topic IS NULL THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' THEN
    before_row := to_jsonb(OLD);
    IF (after_row->'quantity',after_row->'paid_quantity',after_row->'authority_fulfillable_quantity',after_row->'product_variant_id',after_row->'paid_price_cents',after_row->'total_price_cents',after_row->'total_discount_cents',after_row->'plan_discount_cents',after_row->'coupon_discount_cents')
      IS NOT DISTINCT FROM
      (before_row->'quantity',before_row->'paid_quantity',before_row->'authority_fulfillable_quantity',before_row->'product_variant_id',before_row->'paid_price_cents',before_row->'total_price_cents',before_row->'total_discount_cents',before_row->'plan_discount_cents',before_row->'coupon_discount_cents') THEN RETURN NEW; END IF;
  END IF;
  -- The application guard owns OMS -> line locking. A row trigger already
  -- holds the line and must not invert that order by acquiring its OMS parent.
  SELECT operation_id INTO protected_operation FROM oms.order_edit_paid_projections WHERE oms_order_id=NEW.order_id;
  IF protected_operation IS NULL THEN RETURN NEW; END IF;
  IF current_setting('echelon.order_edit_ingress_allowed',true)=NEW.order_id::text THEN RETURN NEW; END IF;
  IF NOT EXISTS(SELECT 1 FROM wms.orders wo WHERE
    (CASE WHEN wo.source='oms' AND wo.oms_fulfillment_order_id ~ '^[0-9]+$' AND length(wo.oms_fulfillment_order_id)<=18 THEN wo.oms_fulfillment_order_id::bigint
      WHEN wo.source_table_id ~ '^[0-9]+$' AND length(wo.source_table_id)<=18 THEN wo.source_table_id::bigint ELSE NULL END)=NEW.order_id
    AND wo.started_at IS NULL AND wo.assigned_picker_id IS NULL AND wo.picked_count=0 AND wo.warehouse_status IN ('pending','ready','on_hold')) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Certified order edit requires projection-aware Shopify ingress' USING ERRCODE='23514';
END;
$_$;


--
-- Name: protect_package_reconciliation_command(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.protect_package_reconciliation_command() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' OR OLD.state = 'complete'
    OR (NEW.command_key, NEW.request_hash, NEW.operation_id, NEW.actor, NEW.reason, NEW.mode, NEW.evidence, NEW.plan, NEW.created_at)
      IS DISTINCT FROM (OLD.command_key, OLD.request_hash, OLD.operation_id, OLD.actor, OLD.reason, OLD.mode, OLD.evidence, OLD.plan, OLD.created_at)
    OR NOT ((OLD.state = 'applying' AND NEW.state = 'applied') OR (OLD.state = 'applied' AND NEW.state IN ('applied','complete')))
    OR (OLD.state = 'applied' AND (NEW.result, NEW.applied_at) IS DISTINCT FROM (OLD.result, OLD.applied_at))
    OR (OLD.state = 'applied' AND NEW.state = 'applied' AND (NEW.channel_readbacks,NEW.completed_at) IS DISTINCT FROM (OLD.channel_readbacks,OLD.completed_at))
    OR NEW.resume_attempt_count < OLD.resume_attempt_count
  THEN RAISE EXCEPTION 'Package reconciliation identity and applied evidence are immutable' USING ERRCODE = '55000'; END IF;
  RETURN NEW;
END; $$;


--
-- Name: protect_refund_merchandise_reduction(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.protect_refund_merchandise_reduction() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.merchandise_reduction_quantity IS NOT NULL
    AND NEW.merchandise_reduction_quantity IS DISTINCT FROM OLD.merchandise_reduction_quantity THEN
    RAISE EXCEPTION 'A recorded merchandise reduction is immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$$;


