--
-- Name: require_package_allocation_commercial_activation(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.require_package_allocation_commercial_activation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.push_status = 'shadow'
     AND NEW.push_status = 'pending'
     AND NOT EXISTS (
       SELECT 1
       FROM oms.package_allocation_commercial_fulfillment_activations AS activation
       WHERE activation.channel_fulfillment_push_id = OLD.id
     ) THEN
    RAISE EXCEPTION
      'Shadow channel fulfillment command % has no commercial activation evidence',
      OLD.id
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_channel_fulfillment_push_item(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.validate_channel_fulfillment_push_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  command_row oms.channel_fulfillment_pushes%ROWTYPE;
  physical_row RECORD;
BEGIN
  SELECT * INTO command_row
  FROM oms.channel_fulfillment_pushes
  WHERE id = NEW.channel_fulfillment_push_id;

  IF command_row.command_key LIKE 'fulfillment:v1:%' THEN
    IF NEW.physical_shipment_item_id IS NULL THEN
      RAISE EXCEPTION 'v1 channel fulfillment items require physical shipment item lineage'
        USING ERRCODE = '23514';
    END IF;

    SELECT
      item.physical_shipment_id,
      line.oms_order_line_id
    INTO physical_row
    FROM wms.physical_shipment_items AS item
    JOIN wms.fulfillment_plan_lines AS line
      ON line.id = item.fulfillment_plan_line_id
    WHERE item.id = NEW.physical_shipment_item_id
      AND item.shipment_item_purpose = 'customer_fulfillment';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'channel fulfillment item does not reference a customer-fulfillment physical item'
        USING ERRCODE = '23514';
    END IF;

    IF physical_row.physical_shipment_id IS DISTINCT FROM command_row.physical_shipment_id
       OR physical_row.oms_order_line_id IS DISTINCT FROM NEW.oms_order_line_id THEN
      RAISE EXCEPTION 'channel fulfillment item lineage does not match its command or OMS line'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_package_allocation_commercial_activation(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.validate_package_allocation_commercial_activation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  evidence RECORD;
BEGIN
  SELECT
    allocation_plan.plan_version,
    allocation_plan.outcome,
    allocation_group.current_version,
    channel_command.push_status,
    channel_command.metadata
  INTO evidence
  FROM wms.package_allocation_plans AS allocation_plan
  JOIN wms.package_allocation_groups AS allocation_group
    ON allocation_group.id = allocation_plan.package_allocation_group_id
  JOIN oms.channel_fulfillment_pushes AS channel_command
    ON channel_command.id = NEW.channel_fulfillment_push_id
  WHERE allocation_plan.id = NEW.package_allocation_plan_id
  FOR UPDATE OF allocation_plan, allocation_group, channel_command;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'Package-allocation commercial fulfillment activation lacks persisted plan or command evidence'
      USING ERRCODE = '23514';
  END IF;

  IF evidence.outcome <> 'proposed'
     OR evidence.current_version <> evidence.plan_version
     OR evidence.push_status <> 'shadow'
     OR evidence.metadata->>'materializationContract'
          IS DISTINCT FROM 'package-allocation-commercial-shadow-v1'
     OR evidence.metadata->>'packageAllocationPlanId'
          IS DISTINCT FROM NEW.package_allocation_plan_id::text
     OR NOT EXISTS (
       SELECT 1
       FROM oms.channel_fulfillment_push_items AS push_item
       JOIN wms.package_allocation_effect_intents AS intent
         ON intent.id = push_item.package_allocation_effect_intent_id
       WHERE push_item.channel_fulfillment_push_id = NEW.channel_fulfillment_push_id
         AND intent.package_allocation_plan_id = NEW.package_allocation_plan_id
         AND intent.effect_type = 'commercial_fulfillment'
         AND intent.executable IS FALSE
     )
     OR EXISTS (
       SELECT 1
       FROM oms.channel_fulfillment_push_items AS push_item
       WHERE push_item.channel_fulfillment_push_id = NEW.channel_fulfillment_push_id
         AND push_item.package_allocation_effect_intent_id IS NULL
     )
     OR EXISTS (
       SELECT 1
       FROM oms.channel_fulfillment_push_items AS push_item
       JOIN wms.package_allocation_effect_intents AS intent
         ON intent.id = push_item.package_allocation_effect_intent_id
       WHERE push_item.channel_fulfillment_push_id = NEW.channel_fulfillment_push_id
         AND intent.package_allocation_plan_id IS DISTINCT FROM NEW.package_allocation_plan_id
     )
     OR EXISTS (
       SELECT 1
       FROM wms.package_allocation_effect_intents AS intent
       WHERE intent.package_allocation_plan_id = NEW.package_allocation_plan_id
         AND intent.effect_type = 'commercial_fulfillment'
         AND (
           intent.executable IS DISTINCT FROM FALSE
           OR intent.quantity IS NULL
           OR intent.quantity IS DISTINCT FROM (
             SELECT COALESCE(SUM(push_item.quantity_pushed), 0)::integer
             FROM oms.channel_fulfillment_push_items AS push_item
             WHERE push_item.package_allocation_effect_intent_id = intent.id
           )
         )
     ) THEN
    RAISE EXCEPTION
      'Package-allocation commercial fulfillment activation lacks current exact shadow authority'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_package_allocation_commercial_fulfillment_item(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.validate_package_allocation_commercial_fulfillment_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  intent RECORD;
  lineage RECORD;
  already_materialized BIGINT;
  package_portion_proven BOOLEAN;
BEGIN
  IF NEW.package_allocation_effect_intent_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT effect.package_allocation_plan_id, effect.package_allocation_group_id,
    effect.package_allocation_source_line_id, effect.package_allocation_package_binding_id,
    effect.effect_type, effect.quantity, effect.executable
  INTO intent
  FROM wms.package_allocation_effect_intents AS effect
  WHERE effect.id = NEW.package_allocation_effect_intent_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Package-allocation commercial intent % does not exist',
      NEW.package_allocation_effect_intent_id USING ERRCODE = '23503';
  END IF;

  SELECT command.push_status, physical.package_allocation_entry_id,
    physical.quantity_shipped AS physical_quantity,
    entry.package_allocation_plan_id, entry.package_allocation_group_id,
    entry.package_allocation_source_line_id, entry.package_allocation_package_binding_id,
    source.source_wms_shipment_item_id, source.source_quantity,
    entry.allocation_kind, entry.target_kind, entry.quantity AS allocation_quantity
  INTO lineage
  FROM oms.channel_fulfillment_pushes AS command
  JOIN wms.physical_shipment_items AS physical
    ON physical.id = NEW.physical_shipment_item_id
   AND physical.physical_shipment_id = command.physical_shipment_id
  JOIN wms.package_allocation_entries AS entry ON entry.id = physical.package_allocation_entry_id
  JOIN wms.package_allocation_source_lines AS source ON source.id = entry.package_allocation_source_line_id
  WHERE command.id = NEW.channel_fulfillment_push_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Package-allocation commercial command item has incomplete physical lineage'
      USING ERRCODE = '23514';
  END IF;

  IF intent.effect_type <> 'commercial_fulfillment'
     OR intent.executable IS DISTINCT FROM FALSE
     OR intent.quantity IS NULL
     OR lineage.push_status <> 'shadow'
     OR lineage.allocation_kind <> 'primary_transfer'
     OR lineage.target_kind <> 'package'
     OR lineage.package_allocation_plan_id IS DISTINCT FROM intent.package_allocation_plan_id
     OR lineage.package_allocation_group_id IS DISTINCT FROM intent.package_allocation_group_id
     OR lineage.package_allocation_source_line_id IS DISTINCT FROM intent.package_allocation_source_line_id
     OR (intent.package_allocation_package_binding_id IS NOT NULL
       AND lineage.package_allocation_package_binding_id IS DISTINCT FROM intent.package_allocation_package_binding_id)
     OR lineage.allocation_quantity IS DISTINCT FROM lineage.physical_quantity
     OR NEW.quantity_pushed <= 0
     OR NEW.quantity_pushed > lineage.physical_quantity THEN
    RAISE EXCEPTION 'Channel fulfillment item does not match package-allocation commercial intent %',
      NEW.package_allocation_effect_intent_id USING ERRCODE = '23514';
  END IF;

  IF intent.package_allocation_package_binding_id IS NOT NULL THEN
    SELECT TRUE INTO package_portion_proven
    FROM wms.package_allocation_package_bindings AS binding
    JOIN wms.package_allocation_plans AS plan ON plan.id = intent.package_allocation_plan_id
    JOIN wms.shipping_provider_labels AS label
      ON label.provider = binding.provider
     AND label.provider_label_id = binding.provider_physical_shipment_id
    WHERE binding.id = intent.package_allocation_package_binding_id
      AND binding.package_allocation_group_id = intent.package_allocation_group_id
      AND label.provider = 'shipstation'
      AND label.label_direction = 'outbound'
      AND label.label_status = 'active'
      AND EXISTS (
        SELECT 1 FROM jsonb_array_elements(plan.state_snapshot->'packageSnapshots') AS snapshot
        WHERE snapshot->>'packageKey' = binding.package_key
          AND snapshot->>'membershipStatus' = 'proven'
          AND snapshot->>'splitContinuationEvidenceKey' LIKE 'shipstation-label-portion:v1:%'
      )
      AND EXISTS (
        SELECT 1 FROM wms.shipping_provider_label_events AS event
        WHERE event.shipping_provider_label_id = label.id
          AND event.sanitized_payload->'declaredContentsEvidence'->>'status' = 'authoritative'
          AND event.sanitized_payload->'declaredContentsEvidence'->'lines' @>
            jsonb_build_array(jsonb_build_object(
              'lineItemKey', 'wms-item-' || lineage.source_wms_shipment_item_id,
              'quantity', lineage.physical_quantity
            ))
      )
      AND (
        SELECT COALESCE(SUM(entry.quantity::bigint), 0)
        FROM wms.package_allocation_entries AS entry
        WHERE entry.package_allocation_plan_id = intent.package_allocation_plan_id
          AND entry.package_allocation_source_line_id = intent.package_allocation_source_line_id
          AND entry.allocation_kind = 'primary_transfer'
      ) <= lineage.source_quantity
    FOR SHARE OF binding, label, plan;

    IF package_portion_proven IS DISTINCT FROM TRUE THEN
      SELECT TRUE INTO package_portion_proven
      FROM wms.package_allocation_package_bindings AS binding
      JOIN wms.shipping_provider_labels AS label
        ON LOWER(BTRIM(label.provider)) = LOWER(BTRIM(binding.provider))
       AND BTRIM(label.provider_label_id) = BTRIM(binding.provider_physical_shipment_id)
      JOIN wms.shipping_provider_label_links AS link
        ON link.shipping_provider_label_id = label.id
       AND link.legacy_wms_shipment_id IS NOT NULL
       AND link.source = 'legacy_provider_physical_identity'
      JOIN wms.outbound_shipments AS split_shipment ON split_shipment.id = link.legacy_wms_shipment_id
      JOIN wms.outbound_shipment_items AS child ON child.shipment_id = split_shipment.id
      JOIN wms.outbound_shipment_items AS source_item ON source_item.id = child.split_root_shipment_item_id
      JOIN wms.outbound_shipments AS source_shipment ON source_shipment.id = source_item.shipment_id
      WHERE binding.id = intent.package_allocation_package_binding_id
        AND label.provider = 'shipstation'
        AND label.label_direction = 'outbound'
        AND split_shipment.source = 'shipstation_split'
        AND split_shipment.status = 'shipped'
        AND split_shipment.external_fulfillment_id = 'shipstation_shipment:' || label.provider_label_id
        AND BTRIM(COALESCE(split_shipment.tracking_number, '')) = BTRIM(label.tracking_number)
        AND child.provider_membership_state = 'authoritative'
        AND child.tracking_id = label.provider_label_id
        AND (child.id <> source_item.id OR EXISTS (
          SELECT 1 FROM wms.outbound_shipment_items AS sibling
          WHERE sibling.split_root_shipment_item_id = source_item.id AND sibling.id <> source_item.id
        ))
        AND child.qty = lineage.physical_quantity
        AND source_item.id = lineage.source_wms_shipment_item_id
        AND (source_item.split_root_shipment_item_id IS NULL OR source_item.split_root_shipment_item_id = source_item.id)
        AND source_shipment.order_id = split_shipment.order_id
        AND source_item.order_item_id IS NOT DISTINCT FROM child.order_item_id
        AND source_item.replacement_for_order_item_id IS NOT DISTINCT FROM child.replacement_for_order_item_id
        AND source_item.correction_for_shipment_item_id IS NOT DISTINCT FROM child.correction_for_shipment_item_id
        AND source_item.shipment_item_purpose IS NOT DISTINCT FROM child.shipment_item_purpose
        AND source_item.product_variant_id IS NOT DISTINCT FROM child.product_variant_id
      ORDER BY child.id LIMIT 1
      FOR SHARE OF binding, label, link, split_shipment, child, source_item, source_shipment;
    END IF;
    IF package_portion_proven IS DISTINCT FROM TRUE THEN
      RAISE EXCEPTION 'Package-scoped commercial intent % lacks exact package portion evidence',
        NEW.package_allocation_effect_intent_id USING ERRCODE = '23514';
    END IF;
  END IF;

  SELECT COALESCE(SUM(item.quantity_pushed::bigint), 0) INTO already_materialized
  FROM oms.channel_fulfillment_push_items AS item
  WHERE item.package_allocation_effect_intent_id = NEW.package_allocation_effect_intent_id;
  IF already_materialized + NEW.quantity_pushed > intent.quantity THEN
    RAISE EXCEPTION 'Package-allocation commercial intent % exceeds its immutable quantity',
      NEW.package_allocation_effect_intent_id USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_package_reconciliation(bigint); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.validate_package_reconciliation(command_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE command_row RECORD; source_row RECORD; target_row RECORD; actual_quantity bigint; expected_quantity bigint;
  source_capacity bigint; actual_ids bigint[]; expected_ids bigint[];
BEGIN
  SELECT * INTO command_row FROM oms.package_reconciliation_commands WHERE id = command_id;
  IF command_row.id IS NULL OR command_row.state NOT IN ('applied', 'complete') OR command_row.result IS NULL
    OR command_row.plan->>'outcome' NOT IN ('ready', 'unchanged') THEN
    RAISE EXCEPTION 'Package reconciliation must commit an applied planner receipt' USING ERRCODE = '23514';
  END IF;
  SELECT COALESCE(array_agg(value::bigint ORDER BY value::bigint), '{}'::bigint[]) INTO expected_ids
    FROM jsonb_array_elements_text(command_row.plan->'physicalItemIdsToRetire');
  SELECT COALESCE(array_agg(adjustment.physical_shipment_item_id ORDER BY adjustment.physical_shipment_item_id), '{}'::bigint[]) INTO actual_ids
    FROM wms.physical_shipment_item_quantity_adjustments adjustment
    WHERE adjustment.adjustment_kind = 'provider_package_reconciliation' AND adjustment.repair_run_id = command_row.operation_id;
  IF actual_ids IS DISTINCT FROM expected_ids THEN
    RAISE EXCEPTION 'Package reconciliation retirement set differs from its planner receipt' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM wms.physical_shipment_item_quantity_adjustments adjustment
    JOIN wms.physical_shipment_items item ON item.id = adjustment.physical_shipment_item_id
    WHERE adjustment.adjustment_kind = 'provider_package_reconciliation' AND adjustment.repair_run_id = command_row.operation_id
      AND (adjustment.quantity_delta <> -item.quantity_shipped OR (adjustment.metadata->>'reconciliationCommandId')::bigint IS DISTINCT FROM command_id))
  THEN RAISE EXCEPTION 'Package reconciliation must retire exact immutable quantities' USING ERRCODE = '23514'; END IF;
  IF EXISTS (
    SELECT 1 FROM wms.physical_shipment_item_quantity_adjustments adjustment
    JOIN wms.physical_shipment_items item ON item.id=adjustment.physical_shipment_item_id
    JOIN wms.physical_shipments package ON package.id=item.physical_shipment_id
    JOIN wms.shipping_provider_labels label ON label.provider=package.provider AND label.provider_label_id=package.provider_physical_shipment_id
    WHERE adjustment.adjustment_kind='provider_package_reconciliation' AND adjustment.repair_run_id=command_row.operation_id
      AND (label.label_status <> 'voided' OR EXISTS(SELECT 1 FROM wms.carrier_tracking_event_matches match
        JOIN wms.carrier_tracking_events event ON event.id=match.carrier_tracking_event_id
        WHERE match.shipping_provider_label_id=label.id AND match.match_status IN ('matched','voided_label') AND event.dispatch_evidence='confirmed'))
      AND NOT COALESCE((command_row.evidence->'correction'->>'kind'='confirmed_package_contents_correction'
        AND command_row.evidence->'correction'->>'actorId'=command_row.actor
        AND command_row.plan->'correctedPreviousLabelIds' @> to_jsonb(ARRAY[label.id])
        AND EXISTS(SELECT 1 FROM jsonb_array_elements(command_row.evidence->'relationships') AS relation(document)
          WHERE relation.document->'mergedProviderOrderIds' @> to_jsonb(ARRAY[label.provider_order_id])
            AND EXISTS(SELECT 1 FROM jsonb_array_elements(command_row.evidence->'labels') AS target(document)
              WHERE target.document->>'providerOrderId'=relation.document->>'providerOrderId'
                AND command_row.plan->'labelIdsToMaterialize' @> jsonb_build_array((target.document->>'labelId')::bigint)))),false)
  ) THEN RAISE EXCEPTION 'Carrier-owned or active contents require explicit authenticated merge correction evidence' USING ERRCODE='23514'; END IF;

  SELECT COALESCE(array_agg(value::bigint ORDER BY value::bigint), '{}'::bigint[]) INTO expected_ids
    FROM jsonb_array_elements_text(command_row.plan->'labelIdsToMaterialize');
  SELECT COALESCE(array_agg(work.shipping_provider_label_id ORDER BY work.shipping_provider_label_id), '{}'::bigint[]) INTO actual_ids
    FROM wms.ebay_label_replacement_work work WHERE work.package_reconciliation_command_id = command_id AND work.state = 'applied';
  IF actual_ids IS DISTINCT FROM expected_ids THEN
    RAISE EXCEPTION 'Package reconciliation target set differs from its planner receipt' USING ERRCODE = '23514';
  END IF;
  FOR source_row IN SELECT * FROM jsonb_to_recordset(command_row.plan->'sourceQuantities') AS s(
    "sourceItemId" integer, "sourceQuantity" integer, "preservedQuantity" integer, "retiredQuantity" integer,
    "materializedQuantity" integer, "additionalQuantity" integer, "finalQuantity" integer)
  LOOP
    SELECT COALESCE((SELECT MAX(source_quantity) FROM wms.package_allocation_source_lines WHERE source_wms_shipment_item_id = source_row."sourceItemId"),
      (SELECT SUM(qty) FROM wms.outbound_shipment_items WHERE id = source_row."sourceItemId" OR split_root_shipment_item_id = source_row."sourceItemId")) INTO source_capacity;
    SELECT COALESCE(SUM(item.quantity_shipped), 0) INTO actual_quantity
      FROM wms.effective_physical_shipment_items item
      LEFT JOIN wms.package_allocation_entries entry ON entry.id = item.package_allocation_entry_id
      LEFT JOIN wms.package_allocation_source_lines source ON source.id = entry.package_allocation_source_line_id
      WHERE COALESCE(item.legacy_wms_shipment_item_id, item.label_replacement_source_item_id, source.source_wms_shipment_item_id) = source_row."sourceItemId";
    IF source_capacity IS NULL OR source_row."sourceQuantity" IS DISTINCT FROM source_capacity
      OR actual_quantity IS DISTINCT FROM source_row."finalQuantity" OR actual_quantity > source_capacity
      OR source_row."additionalQuantity" < 0
      OR source_row."retiredQuantity" + source_row."additionalQuantity" <> source_row."materializedQuantity"
      OR source_row."preservedQuantity" + source_row."materializedQuantity" <> source_row."finalQuantity"
    THEN RAISE EXCEPTION 'Package reconciliation violates source % conservation', source_row."sourceItemId" USING ERRCODE = '23514'; END IF;
  END LOOP;
  FOR target_row IN SELECT work.physical_shipment_id, label.id AS label_id, label.provider_label_id, label.tracking_number,
      package.provider_physical_shipment_id, package.tracking_number AS package_tracking, label.label_status, label.label_direction
    FROM wms.ebay_label_replacement_work work JOIN wms.shipping_provider_labels label ON label.id = work.shipping_provider_label_id
    JOIN wms.physical_shipments package ON package.id = work.physical_shipment_id WHERE work.package_reconciliation_command_id = command_id
  LOOP
    IF target_row.label_status <> 'active' OR target_row.label_direction <> 'outbound'
      OR target_row.provider_label_id IS DISTINCT FROM target_row.provider_physical_shipment_id
      OR target_row.tracking_number IS DISTINCT FROM target_row.package_tracking THEN
      RAISE EXCEPTION 'Package reconciliation target identity is not current' USING ERRCODE = '23514';
    END IF;
    IF EXISTS (
      (SELECT (manifest_line.document->>'sourceItemId')::integer, (manifest_line.document->>'quantity')::bigint
        FROM jsonb_array_elements(command_row.evidence->'labels') AS pkg(document),
          jsonb_array_elements(pkg.document->'contents') AS manifest_line(document) WHERE (pkg.document->>'labelId')::bigint = target_row.label_id
       EXCEPT SELECT item.label_replacement_source_item_id, SUM(item.quantity_shipped)
         FROM wms.physical_shipment_items item WHERE item.physical_shipment_id = target_row.physical_shipment_id GROUP BY item.label_replacement_source_item_id)
      UNION ALL
      (SELECT item.label_replacement_source_item_id, SUM(item.quantity_shipped)
         FROM wms.physical_shipment_items item WHERE item.physical_shipment_id = target_row.physical_shipment_id GROUP BY item.label_replacement_source_item_id
       EXCEPT SELECT (manifest_line.document->>'sourceItemId')::integer, (manifest_line.document->>'quantity')::bigint
         FROM jsonb_array_elements(command_row.evidence->'labels') AS pkg(document),
           jsonb_array_elements(pkg.document->'contents') AS manifest_line(document) WHERE (pkg.document->>'labelId')::bigint = target_row.label_id)
    ) THEN RAISE EXCEPTION 'Package reconciliation target contents differ from verified evidence' USING ERRCODE = '23514'; END IF;
  END LOOP;
END; $$;


--
-- Name: validate_package_reconciliation_receipt(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.validate_package_reconciliation_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Validate allocation at its commit boundary. Later retry metadata records
  -- history; it must not reinterpret an earlier receipt as a current label.
  IF TG_OP='INSERT' OR OLD.state='applying' THEN PERFORM oms.validate_package_reconciliation(NEW.id); END IF;
  RETURN NEW;
END; $$;


--
-- Name: validate_shopify_label_void_scope(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.validate_shopify_label_void_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM wms.shipping_provider_labels label
    JOIN wms.physical_shipments package ON package.provider = label.provider
      AND package.provider_physical_shipment_id = label.provider_label_id
    JOIN oms.channel_fulfillment_pushes command ON command.physical_shipment_id = package.id
    WHERE label.id = NEW.shipping_provider_label_id AND package.id = NEW.physical_shipment_id
      AND command.oms_order_id = NEW.oms_order_id AND command.channel_provider = 'shopify'
      AND label.provider = 'shipstation' AND label.label_status = 'voided' AND label.label_direction = 'outbound'
  ) THEN
    RAISE EXCEPTION 'Shopify void work requires the exact voided label, package and order' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: webhook_retry_queue_retry_key_guard(); Type: FUNCTION; Schema: oms; Owner: -
--

CREATE FUNCTION oms.webhook_retry_queue_retry_key_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT'
     AND NEW.provider = 'shopify'
     AND NEW.topic IN ('fulfillments/create', 'fulfillments/update')
     AND NEW.retry_key IS NULL THEN
    NEW.retry_key := CONCAT(
      'legacy:',
      NEW.provider,
      ':',
      NEW.topic,
      ':',
      COALESCE(NULLIF(NEW.payload->>'shop_domain', ''), 'unknown-shop'),
      ':',
      COALESCE(NULLIF(NEW.payload->>'order_id', ''), 'unknown-order'),
      ':',
      COALESCE(
        NULLIF(NEW.payload->>'__echelon_source_event_id', ''),
        md5(NEW.payload::text)
      )
    );
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.retry_key IS DISTINCT FROM OLD.retry_key THEN
    RAISE EXCEPTION 'Webhook retry identity is immutable'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: reject_control_tower_observation_mutation(); Type: FUNCTION; Schema: operations; Owner: -
--

CREATE FUNCTION operations.reject_control_tower_observation_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'control tower observations are immutable'
    USING ERRCODE = '55000';
END;
$$;


--
-- Name: assert_shipment_billing_owner(integer); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.assert_shipment_billing_owner(p_cost_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  charge procurement.inbound_freight_costs%ROWTYPE;
  document procurement.vendor_invoices%ROWTYPE;
  owner_count integer;
  active_count integer;
  current_id integer;
  current_number text;
  visited integer[] := ARRAY[]::integer[];
BEGIN
  SELECT * INTO charge FROM procurement.inbound_freight_costs WHERE id=p_cost_id;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT count(DISTINCT line.vendor_invoice_id),
    count(DISTINCT line.vendor_invoice_id) FILTER (WHERE invoice.status <> 'voided'),
    min(line.vendor_invoice_id) FILTER (WHERE invoice.status <> 'voided')
    INTO owner_count, active_count, current_id
    FROM procurement.vendor_invoice_lines line
    LEFT JOIN procurement.vendor_invoices invoice ON invoice.id=line.vendor_invoice_id
    WHERE line.freight_cost_id=p_cost_id;
  IF owner_count=0 AND charge.vendor_invoice_id IS NULL THEN RETURN; END IF;
  IF owner_count=0 OR active_count>1 THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='shipment_invoice_owner_consistency',
      MESSAGE='A shipment charge must have exactly one current invoice owner, with explicit voided replacement history.';
  END IF;
  IF EXISTS (
    SELECT 1 FROM procurement.vendor_invoice_lines line
    LEFT JOIN procurement.vendor_invoices invoice ON invoice.id=line.vendor_invoice_id
    WHERE line.freight_cost_id=p_cost_id AND (
      invoice.id IS NULL OR invoice.vendor_id IS DISTINCT FROM charge.vendor_id
      OR invoice.inbound_shipment_id IS DISTINCT FROM charge.inbound_shipment_id
      OR invoice.currency IS DISTINCT FROM charge.currency OR invoice.currency<>'USD'
      OR invoice.status NOT IN ('draft','received','approved','disputed','partially_paid','paid','voided')
      OR line.purchase_order_line_id IS NOT NULL OR line.product_variant_id IS NOT NULL
      OR EXISTS (SELECT 1 FROM procurement.vendor_invoice_lines mixed WHERE mixed.vendor_invoice_id=invoice.id
        AND (mixed.purchase_order_line_id IS NOT NULL OR mixed.product_variant_id IS NOT NULL)))
  ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='shipment_invoice_owner_consistency',
      MESSAGE='Shipment invoice supplier, shipment, currency and freight source must agree.';
  END IF;
  current_id := COALESCE(current_id,charge.vendor_invoice_id);
  IF current_id IS NULL OR charge.vendor_invoice_id IS DISTINCT FROM current_id THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='shipment_invoice_owner_consistency',
      MESSAGE='Shipment charge invoice pointer must agree with its recorded source lines.';
  END IF;
  SELECT invoice_number INTO current_number FROM procurement.vendor_invoices WHERE id=current_id;
  WHILE current_id IS NOT NULL LOOP
    SELECT * INTO document FROM procurement.vendor_invoices WHERE id=current_id;
    IF NOT FOUND OR current_id=ANY(visited)
      OR document.invoice_number IS DISTINCT FROM current_number
      OR (cardinality(visited)>0 AND document.status<>'voided')
      OR (SELECT count(*) FROM procurement.vendor_invoice_lines WHERE freight_cost_id=p_cost_id AND vendor_invoice_id=current_id)<1 THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='shipment_invoice_owner_consistency',
        MESSAGE='Shipment invoice history must be one complete, noncompeting replacement chain.';
    END IF;
    visited := array_append(visited,current_id);
    current_id := document.replaces_invoice_id;
  END LOOP;
  IF cardinality(visited)<>owner_count THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='shipment_invoice_owner_consistency',
      MESSAGE='Every historical shipment invoice source must belong to the explicit replacement chain.';
  END IF;
END $$;


--
-- Name: assert_supplier_credit_receipt_source(integer, jsonb, jsonb); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.assert_supplier_credit_receipt_source(source_invoice_line_id integer, disposition jsonb, evidence jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE assignment jsonb;
BEGIN
 IF NOT (disposition ? 'receiptAllocation') THEN RETURN; END IF;
 PERFORM procurement.supplier_credit_line_source_key(disposition);
 assignment:=disposition->'receiptAllocation';
 IF evidence->'receiptAllocation' IS DISTINCT FROM assignment
 THEN RAISE EXCEPTION 'Receipt credit must retain its reviewed assignment' USING ERRCODE='23514'; END IF;
 PERFORM allocation.id FROM procurement.receipt_invoice_cost_allocations allocation
 JOIN procurement.vendor_invoice_lines invoice_line ON invoice_line.id=allocation.invoice_line_id
 JOIN procurement.purchase_order_lines po_line ON po_line.id=allocation.purchase_order_line_id
 JOIN procurement.receiving_lines receipt_line ON receipt_line.id=allocation.receiving_line_id
 WHERE allocation.invoice_line_id=source_invoice_line_id
  AND invoice_line.purchase_order_line_id=po_line.id AND po_line.receipt_costing_enabled=1
  AND receipt_line.purchase_order_line_id=po_line.id
  AND allocation.invoice_start_piece+allocation.pieces<=invoice_line.qty_invoiced::numeric
  AND allocation.receiving_line_id=(assignment->>'receivingLineId')::integer
  AND allocation.receipt_start_piece=(assignment->>'receiptStartPiece')::bigint
  AND allocation.invoice_start_piece=(assignment->>'invoiceStartPiece')::bigint
  AND allocation.pieces=(assignment->>'pieces')::bigint
 FOR SHARE OF allocation,invoice_line,po_line,receipt_line;
 IF NOT FOUND THEN RAISE EXCEPTION 'Receipt credit requires its exact saved invoice assignment' USING ERRCODE='23514'; END IF;
END $$;


--
-- Name: assert_supplier_return_complete(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.assert_supplier_return_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM procurement.supplier_return_lines WHERE supplier_return_id=NEW.id)
 OR NOT EXISTS(SELECT 1 FROM procurement.supplier_return_reporting_events WHERE supplier_return_id=NEW.id)
 OR EXISTS(SELECT 1 FROM procurement.supplier_return_lines line WHERE line.supplier_return_id=NEW.id
   AND NOT EXISTS(SELECT 1 FROM inventory.supplier_return_followups followup
     WHERE followup.supplier_return_id=NEW.id AND followup.product_variant_id=line.product_variant_id))
 OR EXISTS(SELECT 1 FROM procurement.supplier_return_lines line
  LEFT JOIN inventory.supplier_return_allocations allocation ON allocation.supplier_return_line_id=line.id
  WHERE line.supplier_return_id=NEW.id AND (allocation.id IS NULL OR
   (SELECT count(DISTINCT component) FROM inventory.supplier_return_cost_entries entry WHERE entry.return_allocation_id=allocation.id)<>3))
 THEN RAISE EXCEPTION 'A recorded supplier collection requires complete stock, component-value and reporting evidence' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END; $$;


--
-- Name: assert_supplier_tax_return_credit(integer, jsonb, jsonb, bigint, integer); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.assert_supplier_tax_return_credit(source_line_id integer, disposition jsonb, evidence jsonb, amount bigint, credit_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE source procurement.vendor_invoice_lines%ROWTYPE; original_tax numeric; expected_tax_key text; refunded numeric;
 scope jsonb; start_piece numeric; pieces numeric; conversion numeric; returned procurement.receiving_quarantine_dispositions%ROWTYPE;
 observation procurement.receiving_quarantine_observations%ROWTYPE; interval_amount numeric; tax_disposition jsonb;
BEGIN
 SELECT * INTO source FROM procurement.vendor_invoice_lines WHERE id=source_line_id FOR SHARE;
 tax_disposition:=CASE WHEN disposition->>'kind'='accepted_stock_return' THEN disposition->'taxRefund' ELSE disposition END;
 IF disposition->>'kind'='tax_reduction' OR disposition->>'kind'='accepted_stock_return' AND disposition ? 'taxRefund' THEN
  PERFORM procurement.supplier_credit_line_source_key(disposition);
  expected_tax_key:=tax_disposition->>'taxSourceKey';
  SELECT sum(value) INTO original_tax FROM (
   SELECT amount_mills::numeric AS value FROM procurement.vendor_invoice_line_taxes
    WHERE vendor_invoice_line_id=source_line_id AND tax_type_id=(tax_disposition->>'taxTypeId')::integer
     AND expected_tax_key='invoice_line:'||source_line_id::text||':'||(tax_disposition->>'taxTypeId')
   UNION ALL SELECT source.line_total_cents::numeric*100 FROM procurement.inbound_freight_costs charge
    WHERE charge.id=source.freight_cost_id AND charge.tax_type_id=(tax_disposition->>'taxTypeId')::integer
     AND expected_tax_key='shipment_charge:'||charge.id::text||':'||(tax_disposition->>'taxTypeId')
   UNION ALL SELECT amount_mills FROM procurement.current_supplier_invoice_header_shares(source.vendor_invoice_id)
    WHERE line_id=source_line_id AND destination='tax' AND tax_type_id=(tax_disposition->>'taxTypeId')::integer
     AND expected_tax_key='supplier_header:'||entry_key||':'||(tax_disposition->>'taxTypeId')
  ) sources;
  IF original_tax IS NULL OR original_tax<0 OR evidence->'taxCredit'->>'key' IS DISTINCT FROM expected_tax_key
   OR evidence->'taxCredit'->>'taxTypeId' IS DISTINCT FROM tax_disposition->>'taxTypeId'
   OR (evidence->'taxCredit'->>'sourceAmountMills')::numeric IS DISTINCT FROM original_tax
   OR (evidence->'taxCredit'->>'amountMills')::numeric IS DISTINCT FROM amount::numeric*100
  THEN RAISE EXCEPTION 'Tax refund must retain its exact original tax source and amount' USING ERRCODE='23514'; END IF;
  SELECT coalesce(sum(line.amount_cents),0)*100 INTO refunded FROM procurement.supplier_credit_lines line
   JOIN procurement.supplier_credits credit ON credit.id=line.supplier_credit_id
   WHERE line.invoice_line_id=source_line_id AND (line.disposition->>'kind'='tax_reduction' OR line.disposition->>'kind'='accepted_stock_return' AND line.disposition ? 'taxRefund')
    AND coalesce(line.disposition->>'taxSourceKey',line.disposition->'taxRefund'->>'taxSourceKey')=expected_tax_key AND (credit.status='approved' OR credit.id=credit_id);
  IF refunded>original_tax THEN RAISE EXCEPTION 'Cumulative refunds exceed the original tax charge' USING ERRCODE='23514'; END IF;
  IF disposition ? 'receiptAllocation' THEN
   scope:=disposition->'receiptAllocation'; start_piece:=(scope->>'invoiceStartPiece')::numeric; pieces:=(scope->>'pieces')::numeric;
   interval_amount:=floor(original_tax*(start_piece+pieces)/source.qty_invoiced)-floor(original_tax*start_piece/source.qty_invoiced);
   SELECT coalesce(sum(line.amount_cents),0)*100 INTO refunded FROM procurement.supplier_credit_lines line
    JOIN procurement.supplier_credits credit ON credit.id=line.supplier_credit_id
    WHERE line.invoice_line_id=source_line_id AND (line.disposition->>'kind'='tax_reduction' OR line.disposition->>'kind'='accepted_stock_return' AND line.disposition ? 'taxRefund')
     AND coalesce(line.disposition->>'taxSourceKey',line.disposition->'taxRefund'->>'taxSourceKey')=expected_tax_key AND line.disposition->'receiptAllocation'=scope
     AND (credit.status='approved' OR credit.id=credit_id);
   IF refunded>interval_amount THEN RAISE EXCEPTION 'Refund exceeds the tax assigned to this receipt' USING ERRCODE='23514'; END IF;
  END IF;
 END IF;
 IF disposition->>'kind'='accepted_stock_return' AND EXISTS(SELECT 1 FROM procurement.purchase_order_lines line
   WHERE line.id=source.purchase_order_line_id AND line.receipt_costing_enabled=1) THEN
  scope:=evidence->'acceptedReturnSource'->'invoiceAttribution';
  IF jsonb_typeof(scope) IS DISTINCT FROM 'object' OR jsonb_typeof(scope->'parts') IS DISTINCT FROM 'array'
   OR jsonb_array_length(scope->'parts') NOT BETWEEN 1 AND 10000
   OR (scope->>'invoiceLineId')::integer IS DISTINCT FROM source_line_id
   OR (scope->>'receivingLineId')::integer IS DISTINCT FROM (SELECT (accepted_line.source_snapshot->'sourceProof'->'origin'->>'receivingLineId')::integer
     FROM procurement.supplier_return_lines accepted_line WHERE accepted_line.id=(disposition->>'supplierReturnLineId')::integer)
   OR (scope->>'receiptId')::integer IS DISTINCT FROM (SELECT (accepted_line.source_snapshot->'sourceProof'->'origin'->>'receivingOrderId')::integer
     FROM procurement.supplier_return_lines accepted_line WHERE accepted_line.id=(disposition->>'supplierReturnLineId')::integer)
  THEN RAISE EXCEPTION 'Accepted return requires its exact original receipt invoice assignment' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(scope->'parts') part WHERE
    jsonb_typeof(part->'receiptStartPiece') IS DISTINCT FROM 'number' OR jsonb_typeof(part->'invoiceStartPiece') IS DISTINCT FROM 'number'
    OR jsonb_typeof(part->'pieces') IS DISTINCT FROM 'number' OR (part->>'pieces')::numeric<=0 OR (part->>'pieces')::numeric<>trunc((part->>'pieces')::numeric)
    OR (part->>'receivingLineId')::integer IS DISTINCT FROM (scope->>'receivingLineId')::integer
    OR NOT EXISTS(SELECT 1 FROM procurement.receipt_invoice_cost_allocations allocation
      WHERE allocation.invoice_line_id=source_line_id AND allocation.receiving_line_id=(scope->>'receivingLineId')::integer
       AND (part->>'receiptStartPiece')::numeric>=allocation.receipt_start_piece
       AND (part->>'receiptStartPiece')::numeric+(part->>'pieces')::numeric<=allocation.receipt_start_piece+allocation.pieces
       AND (part->>'invoiceStartPiece')::numeric=allocation.invoice_start_piece+(part->>'receiptStartPiece')::numeric-allocation.receipt_start_piece))
   OR EXISTS(SELECT 1 FROM (SELECT (part->>'receiptStartPiece')::numeric AS first,
      lag((part->>'receiptStartPiece')::numeric+(part->>'pieces')::numeric) OVER(ORDER BY (part->>'receiptStartPiece')::numeric) AS previous_end
      FROM jsonb_array_elements(scope->'parts') part) ordered WHERE first<previous_end)
   OR (SELECT sum((part->>'pieces')::numeric) FROM jsonb_array_elements(scope->'parts') part)>
     (evidence->'acceptedReturnSource'->>'quantity')::numeric*(evidence->'acceptedReturnSource'->>'unitsPerVariant')::numeric
  THEN RAISE EXCEPTION 'Returned invoice pieces must belong to their saved receipt assignment' USING ERRCODE='23514'; END IF;
  IF disposition ? 'taxRefund' THEN
   SELECT sum(floor(original_tax*((part->>'invoiceStartPiece')::numeric+(part->>'pieces')::numeric)/source.qty_invoiced)
     -floor(original_tax*(part->>'invoiceStartPiece')::numeric/source.qty_invoiced)) INTO interval_amount FROM jsonb_array_elements(scope->'parts') part;
   SELECT coalesce(sum(line.amount_cents),0)*100 INTO refunded FROM procurement.supplier_credit_lines line
    JOIN procurement.supplier_credits credit ON credit.id=line.supplier_credit_id
    WHERE line.invoice_line_id=source_line_id AND line.disposition->'taxRefund'->>'taxSourceKey'=expected_tax_key
     AND line.source_evidence->'acceptedReturnSource'->'invoiceAttribution'->'parts'=scope->'parts'
     AND (credit.status='approved' OR credit.id=credit_id);
   IF refunded>interval_amount THEN RAISE EXCEPTION 'Refund exceeds the original tax on returned invoice pieces' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN;
 END IF;
 IF disposition->>'kind'='quarantine_return' THEN scope:=disposition;
 ELSIF disposition->>'kind'='tax_reduction' AND disposition ? 'quarantineAllocation' THEN scope:=disposition->'quarantineAllocation';
 ELSE RETURN; END IF;
 IF NOT (scope ? 'invoiceStartPiece') THEN RETURN; END IF; -- previously approved legacy return evidence is unchanged
 start_piece:=(scope->>'invoiceStartPiece')::numeric;
 SELECT * INTO returned FROM procurement.receiving_quarantine_dispositions WHERE id=(scope->>'returnDispositionId')::integer FOR SHARE;
 SELECT * INTO observation FROM procurement.receiving_quarantine_observations WHERE id=returned.observation_id FOR SHARE;
 conversion:=observation.units_per_variant_snapshot; pieces:=(scope->>'quantity')::numeric*conversion;
 IF returned.id IS NULL OR returned.kind<>'return' OR returned.acceptance_id IS NOT NULL
  OR observation.purchase_order_line_id IS DISTINCT FROM source.purchase_order_line_id OR conversion IS NULL OR conversion<=0
  OR (scope->>'quantity')::numeric NOT BETWEEN 1 AND returned.observation_qty
  OR (scope->>'quantity')::numeric<>trunc((scope->>'quantity')::numeric) OR start_piece<0 OR start_piece<>trunc(start_piece)
  OR start_piece+pieces>source.qty_invoiced OR scope->>'evidenceReference' IS DISTINCT FROM returned.evidence_reference
  OR evidence->>'returnInvoiceStartPiece' IS DISTINCT FROM (start_piece::bigint)::text
  OR (evidence->'returnSource'->>'dispositionId')::integer IS DISTINCT FROM returned.id
  OR (evidence->'returnSource'->>'receivingLineId')::integer IS DISTINCT FROM observation.receiving_line_id
  OR (evidence->'returnSource'->>'unitsPerVariant')::numeric IS DISTINCT FROM conversion
  OR (evidence->'returnSource'->>'observationQuantity')::numeric IS DISTINCT FROM (scope->>'quantity')::numeric
 THEN RAISE EXCEPTION 'Returned credit must retain exact immutable receiving and billed-piece evidence' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM procurement.receipt_invoice_cost_allocations allocation WHERE invoice_line_id=source_line_id
   AND allocation.invoice_start_piece<start_piece+pieces AND start_piece<allocation.invoice_start_piece+allocation.pieces)
 THEN RAISE EXCEPTION 'Returned billed pieces overlap accepted receipt costs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM procurement.supplier_credit_lines line JOIN procurement.supplier_credits credit ON credit.id=line.supplier_credit_id
   WHERE line.invoice_line_id=source_line_id AND (credit.status='approved' OR credit.id=credit_id)
    AND line.source_evidence->'returnSource' IS NOT NULL AND line.source_evidence ? 'returnInvoiceStartPiece'
    AND (line.source_evidence->>'returnInvoiceStartPiece')::numeric<start_piece+pieces
    AND start_piece<(line.source_evidence->>'returnInvoiceStartPiece')::numeric
      +(line.source_evidence->'returnSource'->>'observationQuantity')::numeric*(line.source_evidence->'returnSource'->>'unitsPerVariant')::numeric
    AND ROW((line.source_evidence->'returnSource'->>'dispositionId')::numeric,(line.source_evidence->>'returnInvoiceStartPiece')::numeric,
      (line.source_evidence->'returnSource'->>'observationQuantity')::numeric)
      IS DISTINCT FROM ROW(returned.id::numeric,start_piece,(scope->>'quantity')::numeric))
 THEN RAISE EXCEPTION 'Distinct returns cannot credit the same billed pieces' USING ERRCODE='23514'; END IF;
 IF disposition->>'kind'='tax_reduction' THEN
  interval_amount:=floor(original_tax*(start_piece+pieces)/source.qty_invoiced)-floor(original_tax*start_piece/source.qty_invoiced);
  SELECT coalesce(sum(line.amount_cents),0)*100 INTO refunded FROM procurement.supplier_credit_lines line
   JOIN procurement.supplier_credits credit ON credit.id=line.supplier_credit_id
   WHERE line.invoice_line_id=source_line_id AND (line.disposition->>'kind'='tax_reduction' OR line.disposition->>'kind'='accepted_stock_return' AND line.disposition ? 'taxRefund')
    AND coalesce(line.disposition->>'taxSourceKey',line.disposition->'taxRefund'->>'taxSourceKey')=expected_tax_key AND line.disposition->'quarantineAllocation'=scope
    AND (credit.status='approved' OR credit.id=credit_id);
  IF refunded>interval_amount THEN RAISE EXCEPTION 'Refund exceeds the returned interval tax' USING ERRCODE='23514'; END IF;
 END IF;
END $$;


--
-- Name: check_receiving_quarantine_constraint(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.check_receiving_quarantine_constraint() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE checked_observation_id integer;
BEGIN
  IF TG_TABLE_NAME='receiving_quarantine_observations' THEN
    PERFORM procurement.check_receiving_quarantine_observation(NEW.id);
  ELSIF TG_TABLE_NAME IN ('receiving_quarantine_acceptances','receiving_quarantine_dispositions') THEN
    PERFORM procurement.check_receiving_quarantine_observation(NEW.observation_id);
  ELSIF TG_TABLE_NAME='receiving_lines' THEN
    FOR checked_observation_id IN SELECT id FROM procurement.receiving_quarantine_observations WHERE receiving_line_id=NEW.id
      UNION SELECT observation_id FROM procurement.receiving_quarantine_acceptances WHERE receiving_line_id=NEW.id
    LOOP PERFORM procurement.check_receiving_quarantine_observation(checked_observation_id); END LOOP;
  ELSIF TG_TABLE_NAME='receiving_orders' THEN
    FOR checked_observation_id IN SELECT id FROM procurement.receiving_quarantine_observations WHERE receiving_order_id=NEW.id
      UNION SELECT observation_id FROM procurement.receiving_quarantine_acceptances WHERE receiving_order_id=NEW.id
    LOOP PERFORM procurement.check_receiving_quarantine_observation(checked_observation_id); END LOOP;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: check_receiving_quarantine_observation(integer); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.check_receiving_quarantine_observation(p_observation_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  observation procurement.receiving_quarantine_observations%ROWTYPE;
  receipt procurement.receiving_orders%ROWTYPE;
  source_line procurement.receiving_lines%ROWTYPE;
  totals record;
  acceptance_totals record;
  acceptance record;
  prepared_count bigint;
  terminal_count bigint;
  terminal_kind text;
BEGIN
  SELECT * INTO STRICT observation FROM procurement.receiving_quarantine_observations WHERE id=p_observation_id;
  SELECT * INTO STRICT receipt FROM procurement.receiving_orders WHERE id=observation.receiving_order_id;
  IF receipt.warehouse_id IS DISTINCT FROM observation.warehouse_id
    OR NOT EXISTS (SELECT 1 FROM warehouse.warehouse_locations location
      WHERE location.id=observation.holding_location_id AND location.warehouse_id=observation.warehouse_id
        AND location.location_type IS DISTINCT FROM '3pl_virtual') THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receiving quarantine warehouse and physical location evidence disagree';
  END IF;
  IF observation.receiving_line_id IS NOT NULL THEN
    SELECT * INTO STRICT source_line FROM procurement.receiving_lines WHERE id=observation.receiving_line_id;
    IF source_line.receiving_order_id IS DISTINCT FROM observation.receiving_order_id
      OR source_line.product_id IS DISTINCT FROM observation.product_id
      OR source_line.product_variant_id IS DISTINCT FROM observation.product_variant_id
      OR source_line.units_per_variant_snapshot IS DISTINCT FROM observation.units_per_variant_snapshot
      OR source_line.purchase_order_line_id IS DISTINCT FROM observation.purchase_order_line_id
      OR source_line.inbound_shipment_line_id IS DISTINCT FROM observation.inbound_shipment_line_id
      OR NOT EXISTS (SELECT 1 FROM catalog.product_variants variant
        WHERE variant.id=observation.product_variant_id AND variant.product_id=observation.product_id) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receiving quarantine source line identity disagrees with its immutable observation';
    END IF;
  END IF;
  SELECT count(*) AS versions,coalesce(max(version_after),0) AS last_version,
    coalesce(sum(observation_qty::bigint) FILTER (WHERE kind='prepare_acceptance'),0) AS prepared,
    coalesce(sum(observation_qty::bigint) FILTER (WHERE kind='cancel_acceptance'),0) AS cancelled,
    coalesce(sum(observation_qty::bigint) FILTER (WHERE kind='receive'),0) AS received,
    coalesce(sum(observation_qty::bigint) FILTER (WHERE kind='return'),0) AS returned
    INTO totals FROM procurement.receiving_quarantine_dispositions WHERE observation_id=p_observation_id;
  IF totals.versions<>observation.version OR totals.last_version<>observation.version
    OR totals.prepared-totals.cancelled-totals.received<>observation.awaiting_receipt_qty
    OR totals.received<>observation.received_qty OR totals.returned<>observation.returned_qty THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receiving quarantine counters or version lack complete immutable disposition evidence';
  END IF;
  SELECT coalesce(sum(observation_qty::bigint) FILTER (WHERE status='awaiting_receipt'),0) AS awaiting,
    coalesce(sum(observation_qty::bigint) FILTER (WHERE status='received'),0) AS received
    INTO acceptance_totals FROM procurement.receiving_quarantine_acceptances WHERE observation_id=p_observation_id;
  IF acceptance_totals.awaiting<>observation.awaiting_receipt_qty OR acceptance_totals.received<>observation.received_qty THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receiving quarantine pending custody disagrees with its acceptance records';
  END IF;
  FOR acceptance IN SELECT a.*,line.receiving_order_id AS line_receipt_id,line.product_id AS line_product_id,line.product_variant_id AS line_variant_id,
      line.units_per_variant_snapshot AS line_units,line.received_qty AS line_received,line.expected_qty AS line_expected,
      line.damaged_qty AS line_damaged,line.putaway_complete AS line_putaway,line.putaway_location_id AS line_location_id,
      target.status AS target_status,target.warehouse_id AS target_warehouse_id,variant.product_id AS target_product_id
    FROM procurement.receiving_quarantine_acceptances a
    JOIN procurement.receiving_lines line ON line.id=a.receiving_line_id
    JOIN procurement.receiving_orders target ON target.id=a.receiving_order_id
    JOIN catalog.product_variants variant ON variant.id=a.product_variant_id
    WHERE a.observation_id=p_observation_id
  LOOP
    IF acceptance.line_receipt_id<>acceptance.receiving_order_id
      OR acceptance.target_warehouse_id IS DISTINCT FROM observation.warehouse_id
      OR acceptance.line_product_id IS DISTINCT FROM acceptance.product_id
      OR acceptance.line_variant_id IS DISTINCT FROM acceptance.product_variant_id
      OR acceptance.line_units IS DISTINCT FROM acceptance.units_per_variant_snapshot
      OR acceptance.line_damaged<>0
      OR (observation.product_id IS NOT NULL AND observation.product_id<>acceptance.target_product_id)
      OR (observation.units_per_variant_snapshot IS NOT NULL AND
        observation.units_per_variant_snapshot::bigint * acceptance.observation_qty::bigint
          <> acceptance.units_per_variant_snapshot::bigint * acceptance.accepted_variant_qty::bigint) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receiving quarantine acceptance source or exact unit conversion disagrees';
    END IF;
    SELECT count(*) INTO prepared_count FROM procurement.receiving_quarantine_dispositions
      WHERE acceptance_id=acceptance.id AND kind='prepare_acceptance' AND observation_id=p_observation_id
        AND observation_qty=acceptance.observation_qty;
    SELECT count(*),max(kind) INTO terminal_count,terminal_kind FROM procurement.receiving_quarantine_dispositions
      WHERE acceptance_id=acceptance.id AND kind IN ('receive','cancel_acceptance')
        AND observation_id=p_observation_id AND observation_qty=acceptance.observation_qty;
    IF prepared_count<>1 OR (acceptance.status='awaiting_receipt' AND terminal_count<>0)
      OR (acceptance.status='received' AND (terminal_count<>1 OR terminal_kind<>'receive'))
      OR (acceptance.status='cancelled' AND (terminal_count<>1 OR terminal_kind<>'cancel_acceptance')) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receiving quarantine acceptance lacks its matching immutable disposition';
    END IF;
    IF acceptance.status='cancelled' THEN
      IF acceptance.line_received<>0 OR acceptance.line_expected<>0 OR acceptance.line_putaway<>0 THEN
        RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Cancelled quarantine acceptance must retain an unposted zero-count source line';
      END IF;
    ELSE
      IF acceptance.line_received<>acceptance.accepted_variant_qty OR acceptance.line_expected<>acceptance.accepted_variant_qty THEN
        RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Quarantine acceptance counts cannot be changed outside its custody owner';
      END IF;
      IF acceptance.status='awaiting_receipt' AND (acceptance.target_status IN ('closed','cancelled') OR acceptance.line_putaway<>0) THEN
        RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Prepared quarantine acceptance must remain unposted until atomic receipt completion';
      END IF;
      IF acceptance.status='received' THEN
        IF acceptance.target_status<>'closed' OR acceptance.line_putaway<>1
          OR NOT EXISTS (SELECT 1 FROM inventory.inventory_transactions posted
            WHERE posted.receiving_order_id=acceptance.receiving_order_id AND posted.receiving_line_id=acceptance.receiving_line_id
              AND posted.transaction_type='receipt' AND posted.voided_at IS NULL
              AND posted.product_variant_id=acceptance.product_variant_id AND posted.to_location_id=acceptance.line_location_id
              AND posted.variant_qty_delta=acceptance.accepted_variant_qty) THEN
          RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Released quarantine custody requires the exact committed physical receipt';
        END IF;
      END IF;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM procurement.receiving_quarantine_dispositions d
    JOIN procurement.receiving_quarantine_acceptances a ON a.id=d.acceptance_id
    WHERE d.observation_id=p_observation_id AND (a.observation_id<>d.observation_id OR a.observation_qty<>d.observation_qty)) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receiving quarantine disposition refers to another custody observation';
  END IF;
END $$;


--
-- Name: check_shipment_billing_owner_change(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.check_shipment_billing_owner_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE affected_cost integer;
BEGIN
  IF TG_TABLE_NAME='vendor_invoice_lines' THEN
    IF NEW.freight_cost_id IS NOT NULL AND (TG_OP='INSERT' OR
      ROW(NEW.freight_cost_id,NEW.vendor_invoice_id,NEW.purchase_order_line_id,NEW.product_variant_id)
        IS DISTINCT FROM ROW(OLD.freight_cost_id,OLD.vendor_invoice_id,OLD.purchase_order_line_id,OLD.product_variant_id)) THEN
      PERFORM procurement.assert_shipment_billing_owner(NEW.freight_cost_id);
    ELSIF (NEW.purchase_order_line_id IS NOT NULL OR NEW.product_variant_id IS NOT NULL) AND (TG_OP='INSERT' OR
      ROW(NEW.vendor_invoice_id,NEW.purchase_order_line_id,NEW.product_variant_id)
        IS DISTINCT FROM ROW(OLD.vendor_invoice_id,OLD.purchase_order_line_id,OLD.product_variant_id)) THEN
      -- A separate product line on the same header also changes economic source.
      FOR affected_cost IN SELECT DISTINCT freight_cost_id FROM procurement.vendor_invoice_lines
        WHERE vendor_invoice_id=NEW.vendor_invoice_id AND freight_cost_id IS NOT NULL
      LOOP PERFORM procurement.assert_shipment_billing_owner(affected_cost); END LOOP;
    END IF;
  ELSIF TG_TABLE_NAME='inbound_freight_costs' THEN
    IF TG_OP='INSERT' OR ROW(NEW.vendor_invoice_id,NEW.vendor_id,NEW.inbound_shipment_id,NEW.currency)
      IS DISTINCT FROM ROW(OLD.vendor_invoice_id,OLD.vendor_id,OLD.inbound_shipment_id,OLD.currency) THEN
      PERFORM procurement.assert_shipment_billing_owner(NEW.id);
    END IF;
  ELSE
    IF TG_OP='UPDATE' THEN
      -- Voiding cannot add an active owner. Permit this isolated transition even
      -- for preexisting ambiguity; reads continue to show unresolved history.
      IF NEW.status='voided' AND ROW(NEW.vendor_id,NEW.inbound_shipment_id,NEW.currency,NEW.invoice_number,NEW.replaces_invoice_id)
        IS NOT DISTINCT FROM ROW(OLD.vendor_id,OLD.inbound_shipment_id,OLD.currency,OLD.invoice_number,OLD.replaces_invoice_id) THEN RETURN NULL; END IF;
      IF ROW(NEW.status,NEW.vendor_id,NEW.inbound_shipment_id,NEW.currency,NEW.invoice_number,NEW.replaces_invoice_id)
        IS NOT DISTINCT FROM ROW(OLD.status,OLD.vendor_id,OLD.inbound_shipment_id,OLD.currency,OLD.invoice_number,OLD.replaces_invoice_id) THEN RETURN NULL; END IF;
    END IF;
    FOR affected_cost IN SELECT id FROM procurement.inbound_freight_costs WHERE vendor_invoice_id=NEW.id
      UNION SELECT freight_cost_id FROM procurement.vendor_invoice_lines WHERE vendor_invoice_id=NEW.id AND freight_cost_id IS NOT NULL
    LOOP PERFORM procurement.assert_shipment_billing_owner(affected_cost); END LOOP;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: current_supplier_invoice_header_shares(integer); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.current_supplier_invoice_header_shares(source_invoice_id integer) RETURNS TABLE(line_id integer, entry_key text, destination text, amount_mills numeric, tax_type_id integer)
    LANGUAGE sql STABLE
    AS $$
 WITH review AS (SELECT entries_json FROM procurement.supplier_header_cost_reviews WHERE vendor_invoice_id=source_invoice_id ORDER BY id DESC LIMIT 1),
 entries AS (SELECT entry FROM review CROSS JOIN LATERAL jsonb_array_elements(entries_json) entry),
 candidates AS (
  SELECT entry,line.id,greatest(line.line_total_cents,0)::numeric AS basis,
   (entry->>'amountMills')::numeric/100 AS cents
  FROM entries CROSS JOIN procurement.vendor_invoice_lines line
  LEFT JOIN procurement.purchase_order_lines po_line ON po_line.id=line.purchase_order_line_id
  WHERE line.vendor_invoice_id=source_invoice_id AND (
   entry->>'destination'='excluded'
   OR entry->>'destination'='tax' AND (line.freight_cost_id IS NOT NULL OR po_line.line_type='product')
   OR entry->>'destination'='landed' AND line.freight_cost_id IS NOT NULL AND line.purchase_order_line_id IS NULL
   OR entry->>'destination' IN ('product','packaging') AND po_line.line_type='product' AND line.freight_cost_id IS NULL)
 ), weighted AS (
  SELECT *,sum(basis) OVER(PARTITION BY entry->>'key') AS total FROM candidates WHERE entry->>'method'='by_value'
 ), quotas AS (
  SELECT *,CASE WHEN total>0 THEN floor(abs(cents)*basis/total) ELSE 0 END AS floor_cents,
    CASE WHEN total>0 THEN mod(abs(cents)*basis,total) ELSE 0 END AS remainder FROM weighted
 ), ranked AS (
  SELECT *,row_number() OVER(PARTITION BY entry->>'key' ORDER BY remainder DESC,id) AS rank,
    abs(cents)-sum(floor_cents) OVER(PARTITION BY entry->>'key') AS residual FROM quotas
 ), shares AS (
  SELECT id,entry,sign(cents)*(floor_cents+CASE WHEN rank<=residual THEN 1 ELSE 0 END)*100 AS mills
  FROM ranked WHERE total>0 OR cents=0
  UNION ALL
  SELECT candidate.id,candidate.entry,(share->>'amountMills')::numeric
  FROM candidates candidate CROSS JOIN LATERAL jsonb_array_elements(candidate.entry->'shares') share
  WHERE candidate.entry->>'method'='manual' AND (share->>'lineId')::integer=candidate.id
 ) SELECT id,entry->>'key',entry->>'destination',mills,(entry->>'taxTypeId')::integer FROM shares WHERE mills<>0
$$;


--
-- Name: guard_ap_payment_application(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_ap_payment_application() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE payment procurement.ap_payments%ROWTYPE; invoice procurement.vendor_invoices%ROWTYPE; applied numeric;
BEGIN
  IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'AP payment applications are immutable; preserve their history' USING ERRCODE='23514'; END IF;
  SELECT * INTO payment FROM procurement.ap_payments WHERE id=NEW.ap_payment_id FOR UPDATE;
  SELECT * INTO invoice FROM procurement.vendor_invoices WHERE id=NEW.vendor_invoice_id FOR UPDATE;
  IF payment.id IS NULL OR invoice.id IS NULL OR payment.status <> 'completed' OR payment.currency <> 'USD'
    OR invoice.currency <> payment.currency OR invoice.vendor_id <> payment.vendor_id
    OR invoice.status NOT IN ('approved','partially_paid')
    OR NEW.applied_amount_cents <= 0 OR NEW.applied_amount_cents > 9007199254740991
    OR payment.total_amount_cents <= 0 OR payment.total_amount_cents > 9007199254740991 THEN
    RAISE EXCEPTION 'AP payment application requires compatible completed payment and approved invoice evidence' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM procurement.ap_payment_allocations a
    LEFT JOIN procurement.vendor_invoices i ON i.id=a.vendor_invoice_id
    WHERE a.ap_payment_id=payment.id AND (a.applied_amount_cents <= 0 OR a.applied_amount_cents > 9007199254740991
      OR i.id IS NULL OR i.vendor_id <> payment.vendor_id OR i.currency <> payment.currency
      OR i.status NOT IN ('approved','partially_paid','paid','disputed'))) THEN
    RAISE EXCEPTION 'Existing AP applications require review' USING ERRCODE='23514';
  END IF;
  SELECT COALESCE(SUM(applied_amount_cents),0) INTO applied FROM procurement.ap_payment_allocations WHERE ap_payment_id=payment.id;
  IF applied < 0 OR applied + NEW.applied_amount_cents > payment.total_amount_cents THEN
    RAISE EXCEPTION 'AP payment applications exceed the recorded payment' USING ERRCODE='23514';
  END IF;
  -- Do not net invalid historical rows into a plausible target-invoice sum.
  -- This protects both the new application owner and existing payment recording.
  IF invoice.invoiced_amount_cents IS NULL OR invoice.invoiced_amount_cents < 0
    OR invoice.invoiced_amount_cents > 9007199254740991
    OR EXISTS (SELECT 1 FROM procurement.ap_payment_allocations a
      LEFT JOIN procurement.ap_payments p ON p.id=a.ap_payment_id
      WHERE a.vendor_invoice_id=invoice.id AND (
        a.applied_amount_cents IS NULL OR a.applied_amount_cents <= 0 OR a.applied_amount_cents > 9007199254740991
        OR p.id IS NULL OR p.status IS NULL OR p.status NOT IN ('completed','voided')
        OR p.vendor_id IS DISTINCT FROM invoice.vendor_id OR p.currency IS DISTINCT FROM invoice.currency
        OR p.total_amount_cents IS NULL OR p.total_amount_cents <= 0 OR p.total_amount_cents > 9007199254740991)) THEN
    RAISE EXCEPTION 'Invoice payment application evidence requires review' USING ERRCODE='23514';
  END IF;
  SELECT COALESCE(SUM(a.applied_amount_cents),0) INTO applied
    FROM procurement.ap_payment_allocations a JOIN procurement.ap_payments p ON p.id=a.ap_payment_id
    WHERE a.vendor_invoice_id=invoice.id AND p.status='completed';
  IF applied + procurement.supplier_credit_invoice_amount(invoice.id) + NEW.applied_amount_cents > invoice.invoiced_amount_cents THEN
    RAISE EXCEPTION 'AP payment applications exceed the invoice amount' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_ap_payment_command_identity(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_ap_payment_command_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.command_name NOT IN ('ap.payment.record','ap.payment.apply','ap.payment.void','procurement.ap.payment') THEN RETURN NEW; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('procurement.ap-payment.command-key'), hashtext(NEW.idempotency_key));
  IF EXISTS (SELECT 1 FROM public.financial_command_results c WHERE c.idempotency_key=NEW.idempotency_key
    AND c.command_name IN ('ap.payment.record','ap.payment.apply','ap.payment.void','procurement.ap.payment')
    AND ROW(c.actor_type,c.actor_id,c.method,c.route_template,c.resource_key)
      IS DISTINCT FROM ROW(NEW.actor_type,NEW.actor_id,NEW.method,NEW.route_template,NEW.resource_key)) THEN
    RAISE EXCEPTION 'AP payment request key already belongs to another recorded command identity' USING ERRCODE='23514', CONSTRAINT='financial_command_ap_payment_identity_guard';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_ap_payment_history(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_ap_payment_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='TRUNCATE' OR TG_OP='DELETE' THEN
    RAISE EXCEPTION 'AP payment history cannot be erased' USING ERRCODE='23514';
  END IF;
  IF ROW(NEW.vendor_id, NEW.total_amount_cents, NEW.currency, NEW.payment_date, NEW.payment_calendar_date)
    IS DISTINCT FROM ROW(OLD.vendor_id, OLD.total_amount_cents, OLD.currency, OLD.payment_date, OLD.payment_calendar_date) THEN
    RAISE EXCEPTION 'Recorded payment amount, owner, currency and dates are immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.status='voided' AND NEW.status IS DISTINCT FROM OLD.status THEN
    RAISE EXCEPTION 'Voided payments cannot be restored' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_credited_invoice_line_source(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_credited_invoice_line_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM procurement.supplier_credit_lines WHERE invoice_line_id=OLD.id)
   AND (TG_OP='DELETE' OR ROW(NEW.vendor_invoice_id,NEW.purchase_order_line_id,NEW.freight_cost_id,NEW.product_variant_id,NEW.qty_invoiced,NEW.unit_cost_cents,NEW.unit_cost_mills,NEW.cost_component_evidence,NEW.line_total_cents)
     IS DISTINCT FROM ROW(OLD.vendor_invoice_id,OLD.purchase_order_line_id,OLD.freight_cost_id,OLD.product_variant_id,OLD.qty_invoiced,OLD.unit_cost_cents,OLD.unit_cost_mills,OLD.cost_component_evidence,OLD.line_total_cents)) THEN
   RAISE EXCEPTION 'Invoice source economics with supplier credit history are immutable' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_invoice_credit_source_history(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_invoice_credit_source_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF (TG_OP='DELETE' OR ROW(NEW.vendor_id,NEW.currency,NEW.invoiced_amount_cents) IS DISTINCT FROM ROW(OLD.vendor_id,OLD.currency,OLD.invoiced_amount_cents) OR NEW.status='voided')
   AND (EXISTS(SELECT 1 FROM procurement.supplier_credits WHERE source_invoice_id=OLD.id) OR EXISTS(SELECT 1 FROM procurement.supplier_credit_applications WHERE vendor_invoice_id=OLD.id)) THEN
   RAISE EXCEPTION 'Invoice with retained supplier credit history cannot be erased, voided or rewritten' USING ERRCODE='23514'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_invoice_replacement_lineage(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_invoice_replacement_lineage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE predecessor procurement.vendor_invoices%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.replaces_invoice_id IS NOT NULL OR EXISTS (
      SELECT 1 FROM procurement.vendor_invoices child WHERE child.replaces_invoice_id=OLD.id
    ) THEN
      RAISE EXCEPTION 'Invoice replacement history cannot be deleted' USING ERRCODE='23514';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.replaces_invoice_id IS DISTINCT FROM OLD.replaces_invoice_id THEN
      RAISE EXCEPTION 'Invoice replacement identity is immutable' USING ERRCODE='23514';
    END IF;
    IF OLD.replaces_invoice_id IS NOT NULL OR EXISTS (
      SELECT 1 FROM procurement.vendor_invoices child WHERE child.replaces_invoice_id=OLD.id
    ) THEN
      IF ROW(NEW.vendor_id,NEW.invoice_number,NEW.inbound_shipment_id,NEW.currency)
        IS DISTINCT FROM ROW(OLD.vendor_id,OLD.invoice_number,OLD.inbound_shipment_id,OLD.currency) THEN
        RAISE EXCEPTION 'Invoice replacement document identity is immutable' USING ERRCODE='23514';
      END IF;
    END IF;
    IF EXISTS(SELECT 1 FROM procurement.vendor_invoices child WHERE child.replaces_invoice_id=OLD.id)
      AND NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'A replaced invoice remains immutable historical evidence' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.replaces_invoice_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO predecessor FROM procurement.vendor_invoices WHERE id=NEW.replaces_invoice_id FOR UPDATE;
  IF NOT FOUND OR predecessor.status <> 'voided' OR predecessor.paid_amount_cents <> 0
    OR predecessor.inbound_shipment_id IS NULL
    OR ROW(NEW.vendor_id,NEW.invoice_number,NEW.inbound_shipment_id,NEW.currency)
      IS DISTINCT FROM ROW(predecessor.vendor_id,predecessor.invoice_number,predecessor.inbound_shipment_id,predecessor.currency)
    OR NEW.status <> 'received' OR NEW.paid_amount_cents <> 0
    OR NEW.approved_at IS NOT NULL OR NEW.approved_by IS NOT NULL
    OR EXISTS(SELECT 1 FROM procurement.ap_payment_allocations WHERE vendor_invoice_id=predecessor.id) THEN
    RAISE EXCEPTION 'Invoice replacement requires a matching voided unpaid shipment invoice without payment history' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_linked_vendor_product_identity_change(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_linked_vendor_product_identity_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  invalid_line_ids TEXT;
BEGIN
  IF NEW.vendor_id IS NOT DISTINCT FROM OLD.vendor_id
    AND NEW.product_id IS NOT DISTINCT FROM OLD.product_id
    AND NEW.product_variant_id IS NOT DISTINCT FROM OLD.product_variant_id
  THEN
    RETURN NEW;
  END IF;

  SELECT string_agg(pol.id::text, ', ' ORDER BY pol.id)
  INTO invalid_line_ids
  FROM procurement.purchase_order_lines pol
  JOIN procurement.purchase_orders po ON po.id = pol.purchase_order_id
  WHERE pol.vendor_product_id = OLD.id
    AND (
      NEW.vendor_id <> po.vendor_id
      OR NEW.product_id <> pol.product_id
      OR (
        NEW.product_variant_id IS NOT NULL
        AND NEW.product_variant_id IS DISTINCT FROM
          COALESCE(pol.expected_receive_variant_id, pol.product_variant_id)
      )
    );

  IF invalid_line_ids IS NOT NULL THEN
    RAISE EXCEPTION
      'Vendor product % identity change would invalidate linked PO lines: %',
      OLD.id,
      invalid_line_ids
      USING
        ERRCODE = '23514',
        HINT = 'Create a new vendor-product mapping instead of reassigning an existing linked mapping.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION guard_linked_vendor_product_identity_change(); Type: COMMENT; Schema: procurement; Owner: -
--

COMMENT ON FUNCTION procurement.guard_linked_vendor_product_identity_change() IS 'Rejects identity reassignment of vendor-product mappings referenced by PO lines.';


--
-- Name: guard_observed_receiving_line_counts(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_observed_receiving_line_counts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.product_id,NEW.product_variant_id,NEW.units_per_variant_snapshot,
      NEW.purchase_order_line_id,NEW.inbound_shipment_line_id,NEW.receiving_order_id)
    IS DISTINCT FROM (OLD.product_id,OLD.product_variant_id,OLD.units_per_variant_snapshot,
      OLD.purchase_order_line_id,OLD.inbound_shipment_line_id,OLD.receiving_order_id)
    AND EXISTS (SELECT 1 FROM procurement.receiving_quarantine_acceptances WHERE receiving_line_id=OLD.id) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Quarantine acceptance source identity is immutable';
  END IF;
  IF (NEW.received_qty,NEW.damaged_qty,NEW.expected_qty,NEW.product_id,NEW.product_variant_id,
      NEW.units_per_variant_snapshot,NEW.purchase_order_line_id,NEW.inbound_shipment_line_id,NEW.receiving_order_id)
    IS DISTINCT FROM (OLD.received_qty,OLD.damaged_qty,OLD.expected_qty,OLD.product_id,OLD.product_variant_id,
      OLD.units_per_variant_snapshot,OLD.purchase_order_line_id,OLD.inbound_shipment_line_id,OLD.receiving_order_id)
    AND EXISTS (SELECT 1 FROM procurement.receiving_quarantine_observations WHERE receiving_line_id=OLD.id) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Observed receiving counts and source identity are immutable; resolve recorded custody explicitly';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_po_line_vendor_product_identity(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_po_line_vendor_product_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  header_vendor_id INTEGER;
  mapping_vendor_id INTEGER;
  mapping_product_id INTEGER;
  mapping_variant_id INTEGER;
  mapping_active INTEGER;
  receive_variant_id INTEGER;
BEGIN
  IF NEW.vendor_product_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.line_type IS DISTINCT FROM 'product' OR NEW.product_id IS NULL THEN
    RAISE EXCEPTION
      'PO line % cannot link vendor product % without a product identity',
      COALESCE(NEW.id::text, '<new>'),
      NEW.vendor_product_id
      USING ERRCODE = '23514';
  END IF;

  SELECT po.vendor_id
  INTO header_vendor_id
  FROM procurement.purchase_orders po
  WHERE po.id = NEW.purchase_order_id;

  IF header_vendor_id IS NULL THEN
    RAISE EXCEPTION
      'PO line % references missing purchase order %',
      COALESCE(NEW.id::text, '<new>'),
      NEW.purchase_order_id
      USING ERRCODE = '23503';
  END IF;

  SELECT
    vp.vendor_id,
    vp.product_id,
    vp.product_variant_id,
    vp.is_active
  INTO
    mapping_vendor_id,
    mapping_product_id,
    mapping_variant_id,
    mapping_active
  FROM procurement.vendor_products vp
  WHERE vp.id = NEW.vendor_product_id;

  IF mapping_vendor_id IS NULL THEN
    RAISE EXCEPTION
      'PO line % references missing vendor product %',
      COALESCE(NEW.id::text, '<new>'),
      NEW.vendor_product_id
      USING ERRCODE = '23503';
  END IF;

  receive_variant_id :=
    COALESCE(NEW.expected_receive_variant_id, NEW.product_variant_id);

  IF mapping_active <> 1
    OR mapping_vendor_id <> header_vendor_id
    OR mapping_product_id <> NEW.product_id
    OR (
      mapping_variant_id IS NOT NULL
      AND mapping_variant_id IS DISTINCT FROM receive_variant_id
    )
  THEN
    RAISE EXCEPTION
      'PO line % vendor product % does not match active vendor/product/receive configuration',
      COALESCE(NEW.id::text, '<new>'),
      NEW.vendor_product_id
      USING
        ERRCODE = '23514',
        DETAIL = format(
          'po_vendor_id=%s line_product_id=%s receive_variant_id=%s mapping_vendor_id=%s mapping_product_id=%s mapping_variant_id=%s mapping_active=%s',
          header_vendor_id,
          NEW.product_id,
          COALESCE(receive_variant_id::text, 'NULL'),
          mapping_vendor_id,
          mapping_product_id,
          COALESCE(mapping_variant_id::text, 'NULL'),
          mapping_active
        );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION guard_po_line_vendor_product_identity(); Type: COMMENT; Schema: procurement; Owner: -
--

COMMENT ON FUNCTION procurement.guard_po_line_vendor_product_identity() IS 'Rejects PO-line supplier links that do not match the active PO vendor, product, and receive configuration.';


--
-- Name: guard_po_vendor_change_for_linked_products(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_po_vendor_change_for_linked_products() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  invalid_line_ids TEXT;
BEGIN
  IF NEW.vendor_id IS NOT DISTINCT FROM OLD.vendor_id THEN
    RETURN NEW;
  END IF;

  SELECT string_agg(pol.id::text, ', ' ORDER BY pol.id)
  INTO invalid_line_ids
  FROM procurement.purchase_order_lines pol
  JOIN procurement.vendor_products vp ON vp.id = pol.vendor_product_id
  WHERE pol.purchase_order_id = OLD.id
    AND pol.vendor_product_id IS NOT NULL
    AND vp.vendor_id <> NEW.vendor_id;

  IF invalid_line_ids IS NOT NULL THEN
    RAISE EXCEPTION
      'Purchase order % vendor change would invalidate linked lines: %',
      OLD.id,
      invalid_line_ids
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION guard_po_vendor_change_for_linked_products(); Type: COMMENT; Schema: procurement; Owner: -
--

COMMENT ON FUNCTION procurement.guard_po_vendor_change_for_linked_products() IS 'Rejects PO vendor changes that would invalidate existing vendor-product provenance.';


