-- Name: guard_purchase_recommendation_update(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_purchase_recommendation_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Purchase recommendation calculation evidence is immutable'
    USING ERRCODE = '23514';
END $$;


--
-- Name: guard_purchasing_evidence_delete(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_purchasing_evidence_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
