--
-- Name: guard_receiving_quarantine_history(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_receiving_quarantine_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP IN ('DELETE','TRUNCATE') THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receiving quarantine history cannot be deleted';
  END IF;
  IF TG_TABLE_NAME='receiving_quarantine_observations' THEN
    IF (to_jsonb(NEW)-ARRAY['awaiting_receipt_qty','received_qty','returned_qty','version'])
      IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['awaiting_receipt_qty','received_qty','returned_qty','version']) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receiving quarantine observation evidence is immutable';
    END IF;
  ELSIF TG_TABLE_NAME='receiving_quarantine_acceptances' THEN
    IF (to_jsonb(NEW)-'status') IS DISTINCT FROM (to_jsonb(OLD)-'status')
      OR OLD.status<>'awaiting_receipt' OR NEW.status NOT IN ('received','cancelled') THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receiving quarantine acceptance permits one terminal disposition only';
    END IF;
  ELSE
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receiving quarantine dispositions are immutable';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_replaced_invoice_evidence(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_replaced_invoice_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE owner_id integer;
BEGIN
  owner_id := CASE WHEN TG_OP='INSERT' THEN NEW.vendor_invoice_id ELSE OLD.vendor_invoice_id END;
  IF EXISTS(SELECT 1 FROM procurement.vendor_invoices child WHERE child.replaces_invoice_id=owner_id)
    OR (TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM procurement.vendor_invoices child WHERE child.replaces_invoice_id=NEW.vendor_invoice_id)) THEN
    RAISE EXCEPTION 'Replaced invoice evidence is immutable' USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_rfq_line_allocation(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_rfq_line_allocation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  recommendation_qty INTEGER;
  recommendation_as_of TIMESTAMPTZ;
  allocated_qty BIGINT;
  baseline_qty INTEGER;
  excess_qty INTEGER;
  recommendation_product_id INTEGER;
  recommendation_variant_id INTEGER;
  recommendation_warehouse_id INTEGER;
  mapping_product_id INTEGER;
  mapping_variant_id INTEGER;
  mapping_vendor_id INTEGER;
  rfq_vendor_id INTEGER;
BEGIN
  IF TG_OP = 'UPDATE' AND (
    NEW.rfq_id IS DISTINCT FROM OLD.rfq_id
    OR NEW.recommendation_line_id IS DISTINCT FROM OLD.recommendation_line_id
    OR NEW.vendor_product_id IS DISTINCT FROM OLD.vendor_product_id
  ) THEN
    RAISE EXCEPTION 'RFQ line sourcing identity is immutable'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE' AND (
    NEW.requested_pieces IS DISTINCT FROM OLD.requested_pieces
    OR NEW.quantity_override_reason IS DISTINCT FROM OLD.quantity_override_reason
    OR NEW.allocation_override_reason IS DISTINCT FROM OLD.allocation_override_reason
    OR NEW.allocation_override_approved_by IS DISTINCT FROM OLD.allocation_override_approved_by
    OR NEW.allocation_override_approved_at IS DISTINCT FROM OLD.allocation_override_approved_at
    OR NEW.allocation_override_baseline_pieces IS DISTINCT FROM OLD.allocation_override_baseline_pieces
    OR NEW.allocation_override_excess_pieces IS DISTINCT FROM OLD.allocation_override_excess_pieces
  ) THEN
    RAISE EXCEPTION 'RFQ line quantity and override evidence are immutable; cancel and replace the line'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE'
     AND OLD.status NOT IN ('draft', 'sent', 'quoted', 'accepted', 'ordered')
     AND NEW.status IN ('draft', 'sent', 'quoted', 'accepted', 'ordered') THEN
    RAISE EXCEPTION 'Inactive RFQ lines cannot be reactivated; create a replacement line'
      USING ERRCODE = '23514';
  END IF;

  SELECT recommended_pieces, product_id, product_variant_id, warehouse_id
    INTO recommendation_qty, recommendation_product_id, recommendation_variant_id, recommendation_warehouse_id
    FROM procurement.purchase_recommendation_lines
   WHERE id = NEW.recommendation_line_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Recommendation line does not exist'
      USING ERRCODE = '23503';
  END IF;

  PERFORM 1
    FROM catalog.products
   WHERE id = recommendation_product_id
   FOR UPDATE;

  SELECT product_id, product_variant_id, vendor_id
    INTO mapping_product_id, mapping_variant_id, mapping_vendor_id
    FROM procurement.vendor_products
   WHERE id = NEW.vendor_product_id;
  SELECT vendor_id INTO rfq_vendor_id
    FROM procurement.request_for_quotes
   WHERE id = NEW.rfq_id;

  IF recommendation_product_id IS DISTINCT FROM mapping_product_id
     OR (mapping_variant_id IS NOT NULL AND recommendation_variant_id IS DISTINCT FROM mapping_variant_id)
     OR mapping_vendor_id IS DISTINCT FROM rfq_vendor_id THEN
    RAISE EXCEPTION 'RFQ line supplier catalog identity does not match the recommendation and RFQ'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'INSERT' AND NEW.status IN ('draft', 'sent', 'quoted', 'accepted', 'ordered') THEN
    SELECT run.as_of INTO recommendation_as_of
      FROM procurement.purchase_recommendation_runs run
      JOIN procurement.purchase_recommendation_lines r ON r.run_id = run.id
     WHERE r.id = NEW.recommendation_line_id;
    IF EXISTS (
      SELECT 1 FROM procurement.rfq_purchase_order_line_links link
      JOIN procurement.request_for_quote_lines prior_rfq ON prior_rfq.id = link.rfq_line_id
      JOIN procurement.purchase_recommendation_lines source ON source.id = prior_rfq.recommendation_line_id
      JOIN procurement.purchase_orders po ON po.id = link.purchase_order_id
      JOIN procurement.purchase_order_lines line ON line.id = link.purchase_order_line_id AND line.purchase_order_id = po.id
      WHERE source.product_id = recommendation_product_id
        AND source.warehouse_id IS NOT DISTINCT FROM recommendation_warehouse_id
        AND po.status NOT IN ('draft', 'pending_approval')
        AND (GREATEST(po.updated_at, line.updated_at) AT TIME ZONE 'UTC') > recommendation_as_of
    ) THEN
      RAISE EXCEPTION 'RFQ_SUPPLY_SNAPSHOT_STALE: generate fresh recommendations after purchase supply changes'
        USING ERRCODE = '23514';
    END IF;

    -- Match rfqPendingSourcingPieces: only uncommitted linked PO remainder is
    -- still a sourcing reservation. Original RFQ quantities remain immutable.
    SELECT COALESCE(SUM(CASE
      WHEN link.id IS NULL AND rfq_line.status IN ('draft', 'sent', 'quoted', 'accepted', 'ordered')
        AND header.status IN ('draft', 'sent', 'partially_quoted', 'quoted') THEN rfq_line.requested_pieces
      WHEN po.status IN ('draft', 'pending_approval') AND line.status IN ('open', 'partially_received')
        THEN GREATEST(line.order_qty - COALESCE(line.received_qty, 0) - COALESCE(line.cancelled_qty, 0), 0)
      ELSE 0 END), 0)
      INTO allocated_qty
      FROM procurement.request_for_quote_lines rfq_line
      JOIN procurement.purchase_recommendation_lines source_recommendation
        ON source_recommendation.id = rfq_line.recommendation_line_id
      JOIN procurement.request_for_quotes header ON header.id = rfq_line.rfq_id
      LEFT JOIN procurement.rfq_purchase_order_line_links link ON link.rfq_line_id = rfq_line.id
      LEFT JOIN procurement.purchase_orders po ON po.id = link.purchase_order_id
      LEFT JOIN procurement.purchase_order_lines line ON line.id = link.purchase_order_line_id AND line.purchase_order_id = po.id
     WHERE source_recommendation.product_id = recommendation_product_id
       AND source_recommendation.warehouse_id IS NOT DISTINCT FROM recommendation_warehouse_id;

    baseline_qty := GREATEST(recommendation_qty - allocated_qty, 0);
    excess_qty := GREATEST(NEW.requested_pieces - baseline_qty, 0);

    IF excess_qty > 0 THEN
      IF NULLIF(BTRIM(NEW.allocation_override_reason), '') IS NULL
         OR NULLIF(BTRIM(NEW.allocation_override_approved_by), '') IS NULL
         OR NEW.allocation_override_approved_at IS NULL THEN
        RAISE EXCEPTION 'RFQ allocation exceeds the recommendation without complete approval evidence'
          USING ERRCODE = '23514';
      END IF;
      IF NEW.allocation_override_baseline_pieces IS DISTINCT FROM baseline_qty
         OR NEW.allocation_override_excess_pieces IS DISTINCT FROM excess_qty THEN
        RAISE EXCEPTION 'RFQ allocation approval does not match the locked recommendation baseline'
          USING ERRCODE = '23514';
      END IF;
    ELSIF NEW.allocation_override_reason IS NOT NULL
       OR NEW.allocation_override_approved_by IS NOT NULL
       OR NEW.allocation_override_approved_at IS NOT NULL
       OR NEW.allocation_override_baseline_pieces IS NOT NULL
       OR NEW.allocation_override_excess_pieces IS NOT NULL THEN
      RAISE EXCEPTION 'RFQ allocation override evidence is only valid for excess sourcing'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  NEW.updated_at := transaction_timestamp();
  RETURN NEW;
END $$;


--
-- Name: guard_rfq_quote_evidence(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_rfq_quote_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'RFQ quote revisions and purchase links are immutable; record a new quote or purchase request'
      USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM procurement.request_for_quote_lines WHERE id = NEW.rfq_line_id AND rfq_id = NEW.rfq_id) THEN
    RAISE EXCEPTION 'RFQ quote line does not belong to its RFQ' USING ERRCODE = '23514';
  END IF;
  IF TG_TABLE_NAME = 'rfq_purchase_order_line_links' THEN
    IF NOT EXISTS (SELECT 1 FROM procurement.purchase_order_lines WHERE id = NEW.purchase_order_line_id AND purchase_order_id = NEW.purchase_order_id) THEN
      RAISE EXCEPTION 'RFQ purchase link does not belong to its purchase order' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_supplier_credit_history(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_supplier_credit_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE source procurement.vendor_invoices%ROWTYPE; credit procurement.supplier_credits%ROWTYPE; invoice procurement.vendor_invoices%ROWTYPE; applied numeric;
BEGIN
 IF TG_OP IN ('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'Supplier credit history cannot be erased' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='supplier_credits' THEN
   IF TG_OP='INSERT' THEN
     SELECT * INTO source FROM procurement.vendor_invoices WHERE id=NEW.source_invoice_id FOR UPDATE;
     IF NEW.replaces_credit_id IS NOT NULL THEN
       IF NOT EXISTS(SELECT 1 FROM procurement.supplier_credits c WHERE c.id=NEW.replaces_credit_id AND c.status='voided' AND c.vendor_id=NEW.vendor_id AND c.supplier_reference=NEW.supplier_reference) THEN
         RAISE EXCEPTION 'Supplier credit replacement needs the exact voided supplier document' USING ERRCODE='23514'; END IF;
     ELSIF EXISTS(SELECT 1 FROM procurement.supplier_credits c WHERE c.vendor_id=NEW.vendor_id AND c.supplier_reference=NEW.supplier_reference) THEN
       RAISE EXCEPTION 'Use explicit supplier credit replacement to retain duplicate reference history' USING ERRCODE='23514'; END IF;
     IF source.id IS NULL OR source.vendor_id<>NEW.vendor_id OR source.currency<>NEW.currency OR source.status NOT IN ('approved','partially_paid','paid') OR NEW.status<>'draft' OR NEW.version<>1 OR NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL
       OR NEW.voided_by IS NOT NULL OR NEW.voided_at IS NOT NULL OR NEW.void_reason IS NOT NULL THEN
       RAISE EXCEPTION 'Supplier credit needs a compatible approved original invoice' USING ERRCODE='23514'; END IF;
   ELSE
     IF NEW.version<>OLD.version+1 OR (NEW.status='draft' AND (NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL))
       OR (NEW.status<>'voided' AND (NEW.voided_by IS NOT NULL OR NEW.voided_at IS NOT NULL OR NEW.void_reason IS NOT NULL)) THEN
       RAISE EXCEPTION 'Supplier credit versions and status history must advance explicitly' USING ERRCODE='23514'; END IF;
     IF ROW(NEW.source_invoice_id,NEW.vendor_id,NEW.source_snapshot,NEW.replaces_credit_id,NEW.supplier_reference,NEW.credit_calendar_date,NEW.total_amount_cents,NEW.currency,NEW.reason,NEW.created_by,NEW.created_at)
       IS DISTINCT FROM ROW(OLD.source_invoice_id,OLD.vendor_id,OLD.source_snapshot,OLD.replaces_credit_id,OLD.supplier_reference,OLD.credit_calendar_date,OLD.total_amount_cents,OLD.currency,OLD.reason,OLD.created_by,OLD.created_at)
       OR (OLD.status='voided' AND NEW IS DISTINCT FROM OLD) OR (OLD.status='approved' AND NEW.status NOT IN ('approved','voided'))
       OR (OLD.approved_at IS NOT NULL AND ROW(NEW.approved_by,NEW.approved_at) IS DISTINCT FROM ROW(OLD.approved_by,OLD.approved_at)) THEN
       RAISE EXCEPTION 'Supplier credit economics and approval history are immutable' USING ERRCODE='23514'; END IF;
     IF NEW.status='approved' AND OLD.status='draft' THEN
       PERFORM procurement.assert_supplier_credit_receipt_source(line.invoice_line_id,line.disposition,line.source_evidence)
         FROM procurement.supplier_credit_lines line WHERE line.supplier_credit_id=NEW.id;
       IF NEW.total_amount_cents IS DISTINCT FROM (SELECT sum(amount_cents) FROM procurement.supplier_credit_lines WHERE supplier_credit_id=NEW.id) THEN
         RAISE EXCEPTION 'Credit document and source lines do not conserve amount' USING ERRCODE='23514'; END IF;
       IF EXISTS(SELECT l.invoice_line_id FROM procurement.supplier_credit_lines l
          JOIN procurement.supplier_credits c ON c.id=l.supplier_credit_id
          JOIN procurement.vendor_invoice_lines il ON il.id=l.invoice_line_id
          WHERE c.source_invoice_id=NEW.source_invoice_id AND (c.status='approved' OR c.id=NEW.id)
          GROUP BY l.invoice_line_id,il.line_total_cents
          HAVING sum(l.amount_cents)>procurement.supplier_invoice_line_credit_capacity(l.invoice_line_id)) THEN
         RAISE EXCEPTION 'Approved credits exceed original source line amount' USING ERRCODE='23514'; END IF;
     END IF;
     IF NEW.status='voided' AND EXISTS(SELECT 1 FROM procurement.supplier_credit_applications a LEFT JOIN procurement.supplier_credit_application_reversals r ON r.application_id=a.id WHERE a.supplier_credit_id=NEW.id AND r.id IS NULL) THEN
       RAISE EXCEPTION 'Reverse active applications before voiding supplier credit' USING ERRCODE='23514'; END IF;
   END IF;
 ELSIF TG_TABLE_NAME='supplier_credit_lines' THEN
   SELECT * INTO credit FROM procurement.supplier_credits WHERE id=NEW.supplier_credit_id FOR UPDATE;
   IF TG_OP='INSERT' THEN
     IF credit.status<>'draft' OR NOT EXISTS(SELECT 1 FROM procurement.vendor_invoice_lines l WHERE l.id=NEW.invoice_line_id AND l.vendor_invoice_id=credit.source_invoice_id)
       OR NEW.source_key IS DISTINCT FROM procurement.supplier_credit_line_source_key(NEW.disposition) THEN
       RAISE EXCEPTION 'Supplier credit line requires a declared original invoice source' USING ERRCODE='23514'; END IF;
     PERFORM procurement.assert_supplier_credit_receipt_source(NEW.invoice_line_id,NEW.disposition,NEW.source_evidence);
   ELSIF ROW(NEW.supplier_credit_id,NEW.invoice_line_id,NEW.amount_cents,NEW.source_key,NEW.disposition,NEW.source_evidence,NEW.created_at) IS DISTINCT FROM ROW(OLD.supplier_credit_id,OLD.invoice_line_id,OLD.amount_cents,OLD.source_key,OLD.disposition,OLD.source_evidence,OLD.created_at) THEN
     RAISE EXCEPTION 'Supplier credit line economics are immutable' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='supplier_credit_applications' THEN
   IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Credit applications are append only' USING ERRCODE='23514'; END IF;
   SELECT * INTO credit FROM procurement.supplier_credits WHERE id=NEW.supplier_credit_id FOR UPDATE;
   SELECT * INTO invoice FROM procurement.vendor_invoices WHERE id=NEW.vendor_invoice_id FOR UPDATE;
   IF credit.id IS NULL OR invoice.id IS NULL OR credit.status<>'approved' OR invoice.status NOT IN ('approved','partially_paid')
     OR credit.vendor_id<>invoice.vendor_id OR credit.currency<>invoice.currency OR NEW.applied_amount_cents NOT BETWEEN 1 AND 9007199254740991 THEN
     RAISE EXCEPTION 'Credit application requires compatible approved document and invoice' USING ERRCODE='23514'; END IF;
   SELECT coalesce(sum(a.applied_amount_cents),0) INTO applied FROM procurement.supplier_credit_applications a LEFT JOIN procurement.supplier_credit_application_reversals r ON r.application_id=a.id WHERE a.supplier_credit_id=credit.id AND r.id IS NULL;
   IF applied+NEW.applied_amount_cents>credit.total_amount_cents OR procurement.supplier_credit_cash_amount(invoice.id)+procurement.supplier_credit_invoice_amount(invoice.id)+NEW.applied_amount_cents>invoice.invoiced_amount_cents THEN
     RAISE EXCEPTION 'Credit application exceeds document or invoice remaining amount' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='supplier_credit_application_reversals' THEN
   IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Credit reversals are append only' USING ERRCODE='23514'; END IF;
   SELECT c.* INTO credit FROM procurement.supplier_credits c JOIN procurement.supplier_credit_applications a ON a.supplier_credit_id=c.id WHERE a.id=NEW.application_id FOR UPDATE OF c;
   IF credit.status<>'approved' THEN RAISE EXCEPTION 'Reverse only an approved credit application' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_supplier_header_cost_reviews(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_supplier_header_cost_reviews() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE entry jsonb; share jsonb; expected numeric; entered numeric:=0; allocated numeric:=0; source_id integer; linked integer[];
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Supplier header approval history cannot be changed or erased' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('inventory.cost_graph'),hashtext('version_1'));
 IF NEW.purchase_order_id IS NOT NULL THEN
  SELECT (-coalesce(po.discount_cents,0)::numeric+coalesce(po.shipping_cost_cents,0)::numeric
    +coalesce((SELECT sum(CASE WHEN line.line_type='product' THEN -coalesce(line.discount_cents,0)
       WHEN line.line_type='tax' THEN 0 ELSE line.line_total_cents END)
       FROM procurement.purchase_order_lines line WHERE line.purchase_order_id=po.id AND line.status<>'cancelled'),0))::numeric*100
    INTO expected FROM procurement.purchase_orders po WHERE po.id=NEW.purchase_order_id FOR SHARE;
  linked:=ARRAY[NEW.purchase_order_id];
 ELSE
  SELECT (invoice.invoiced_amount_cents-coalesce((SELECT sum(line.line_total_cents)
    FROM procurement.vendor_invoice_lines line WHERE line.vendor_invoice_id=invoice.id),0))::numeric*100
    INTO expected FROM procurement.vendor_invoices invoice WHERE invoice.id=NEW.vendor_invoice_id FOR SHARE;
  SELECT coalesce(array_agg(DISTINCT related.purchase_order_id ORDER BY related.purchase_order_id),'{}'::int[]) INTO linked FROM (
    SELECT po.purchase_order_id FROM procurement.vendor_invoice_lines line
    JOIN procurement.purchase_order_lines po ON po.id=line.purchase_order_line_id WHERE line.vendor_invoice_id=NEW.vendor_invoice_id
    UNION SELECT po.purchase_order_id FROM procurement.vendor_invoice_lines line
    JOIN procurement.inbound_freight_costs charge ON charge.id=line.freight_cost_id
    JOIN procurement.inbound_shipment_lines shipment_line ON shipment_line.inbound_shipment_id=charge.inbound_shipment_id
    JOIN procurement.purchase_order_lines po ON po.id=shipment_line.purchase_order_line_id WHERE line.vendor_invoice_id=NEW.vendor_invoice_id
  ) related;
 END IF;
 IF expected IS NULL OR abs(expected)>9007199254740991 OR cardinality(NEW.purchase_order_ids)>500
   OR NEW.purchase_order_ids IS DISTINCT FROM linked THEN
  RAISE EXCEPTION 'Supplier header source is missing or exceeds its complete review limit' USING ERRCODE='23514'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(NEW.entries_json) LOOP
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR jsonb_typeof(entry->'amountMills') IS DISTINCT FROM 'number' OR (entry->>'amountMills') !~ '^-?[0-9]+$'
    OR abs((entry->>'amountMills')::numeric)>9007199254740991 OR (entry->>'amountMills')::numeric%100<>0
    OR coalesce(entry->>'destination','') NOT IN ('product','packaging','landed','excluded','tax')
    OR coalesce(entry->>'method','') NOT IN ('by_value','manual')
    OR coalesce(entry->>'key','') !~ '^[A-Za-z0-9_-]{1,80}$'
    OR coalesce(entry->>'category','') NOT IN ('discount','supplier_freight','other','tax')
    OR (entry->>'category'='discount' AND (entry->>'amountMills')::numeric>0)
    OR (entry->>'category'='tax' AND (entry->>'destination'<>'tax' OR (entry->>'amountMills')::numeric<0)) THEN
   RAISE EXCEPTION 'Supplier header requires exact classified cent amounts' USING ERRCODE='23514'; END IF;
  entered:=entered+(entry->>'amountMills')::numeric;
 END LOOP;
 FOR share IN SELECT value FROM jsonb_array_elements(NEW.after_json) LOOP
  IF jsonb_typeof(share) IS DISTINCT FROM 'object' OR jsonb_typeof(share->'amountMills') IS DISTINCT FROM 'number' OR (share->>'amountMills') !~ '^-?[0-9]+$'
    OR abs((share->>'amountMills')::numeric)>9007199254740991 OR (share->>'amountMills')::numeric%100<>0
    OR jsonb_typeof(share->'lineId') IS DISTINCT FROM 'number' OR (share->>'lineId') !~ '^[1-9][0-9]*$'
    OR (share->>'lineId')::numeric>2147483647 THEN
   RAISE EXCEPTION 'Supplier header requires exact saved line shares' USING ERRCODE='23514'; END IF;
  source_id:=(share->>'lineId')::integer;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.entries_json) original
    WHERE original->>'key'=share->>'key' AND original->>'destination'=share->>'destination'
      AND (share->>'amountMills')::numeric*(original->>'amountMills')::numeric>=0) THEN
   RAISE EXCEPTION 'Header share must retain its reviewed source, sign and destination' USING ERRCODE='23514'; END IF;
  IF share->>'destination'='tax' THEN
   IF jsonb_typeof(share->'taxTypeId') IS DISTINCT FROM 'number' OR NOT EXISTS(SELECT 1 FROM procurement.purchase_tax_types
      WHERE id::text=share->>'taxTypeId' AND treatment=share->>'taxTreatment') THEN
    RAISE EXCEPTION 'Header tax share must retain its configured treatment' USING ERRCODE='23514'; END IF;
  ELSIF share->>'taxTypeId' IS NOT NULL OR share->>'taxTreatment' IS NOT NULL THEN
   RAISE EXCEPTION 'Only tax shares may declare tax treatment' USING ERRCODE='23514';
  END IF;
  IF NEW.purchase_order_id IS NOT NULL THEN
   IF NOT EXISTS(SELECT 1 FROM procurement.purchase_order_lines WHERE id=source_id AND purchase_order_id=NEW.purchase_order_id AND line_type='product' AND status<>'cancelled') THEN
    RAISE EXCEPTION 'Header share belongs to a different PO source' USING ERRCODE='23514'; END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM procurement.vendor_invoice_lines WHERE id=source_id AND vendor_invoice_id=NEW.vendor_invoice_id) THEN
   RAISE EXCEPTION 'Header share belongs to a different invoice source' USING ERRCODE='23514'; END IF;
  allocated:=allocated+(share->>'amountMills')::numeric;
 END LOOP;
 IF (SELECT count(*)<>count(DISTINCT value->>'key') FROM jsonb_array_elements(NEW.entries_json))
   OR (SELECT count(*)<>count(DISTINCT (value->>'key',value->>'lineId')) FROM jsonb_array_elements(NEW.after_json))
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.entries_json) original WHERE (original->>'amountMills')::numeric
     <>coalesce((SELECT sum((value->>'amountMills')::numeric) FROM jsonb_array_elements(NEW.after_json) WHERE value->>'key'=original->>'key'),0)) THEN
  RAISE EXCEPTION 'Each unique header source must conserve its own exact shares' USING ERRCODE='23514'; END IF;
 IF entered<>expected OR allocated<>expected THEN
  RAISE EXCEPTION 'Supplier header entries and line shares must conserve the original document amount' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $_$;


--
-- Name: guard_supplier_header_linked_approval(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_supplier_header_linked_approval() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE purchase_id integer;
BEGIN
 FOREACH purchase_id IN ARRAY NEW.purchase_order_ids LOOP
  IF NOT EXISTS(SELECT 1 FROM procurement.po_events event WHERE event.po_id=purchase_id
    AND event.event_type='supplier_header_costs_approved' AND event.actor_id=NEW.actor_id
    AND event.payload_json->>'headerReviewId'=NEW.id::text
    AND event.payload_json->'preview'->>'previewVersion'=NEW.preview_version
    AND event.payload_json->>'commandKey'=NEW.command_key) THEN
   RAISE EXCEPTION 'Supplier header approval must retain its original linked purchase history' USING ERRCODE='23514'; END IF;
 END LOOP;
 RETURN NULL;
END $$;


--
-- Name: guard_supplier_return_credit_link(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_supplier_return_credit_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE credit_line procurement.supplier_credit_lines%ROWTYPE; credit procurement.supplier_credits%ROWTYPE;
 entitlement procurement.supplier_return_credit_entitlements%ROWTYPE; vendor integer;
BEGIN
 SELECT * INTO STRICT credit_line FROM procurement.supplier_credit_lines WHERE id=NEW.supplier_credit_line_id;
 SELECT * INTO STRICT credit FROM procurement.supplier_credits WHERE id=credit_line.supplier_credit_id;
 SELECT * INTO STRICT entitlement FROM procurement.supplier_return_credit_entitlements WHERE id=NEW.entitlement_id;
 SELECT header.vendor_id INTO STRICT vendor FROM procurement.supplier_return_lines line JOIN procurement.supplier_returns header ON header.id=line.supplier_return_id
  WHERE line.id=entitlement.supplier_return_line_id;
 IF credit.status<>'approved' OR credit.vendor_id<>vendor OR credit.currency<>'USD' OR NEW.amount_cents<>credit_line.amount_cents
 OR credit_line.disposition->>'kind' IS DISTINCT FROM 'accepted_stock_return'
 OR credit_line.disposition->'supplierReturnLineId' IS DISTINCT FROM to_jsonb(entitlement.supplier_return_line_id)
 OR credit_line.disposition->'quantity' IS DISTINCT FROM to_jsonb(entitlement.quantity)
 OR credit_line.disposition->>'component' IS DISTINCT FROM NEW.component
 OR credit_line.source_evidence->'acceptedReturnSource'->'intervals' IS DISTINCT FROM entitlement.intervals
 THEN RAISE EXCEPTION 'Supplier credit link does not match its reviewed returned quantity and amount' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $$;


--
-- Name: guard_supplier_return_credit_review(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_supplier_return_credit_review() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE item jsonb; link procurement.supplier_return_credit_links%ROWTYPE; status text; seen bigint[]:='{}';
 product numeric; packaging numeric; landed numeric;
BEGIN
 PERFORM id FROM procurement.supplier_return_credit_entitlements WHERE id=NEW.entitlement_id FOR UPDATE;
 IF NEW.source_evidence->'entitlementId' IS DISTINCT FROM to_jsonb(NEW.entitlement_id)
 THEN RAISE EXCEPTION 'Return review source must identify its immutable entitlement' USING ERRCODE='23514'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(NEW.assignments) LOOP
  IF jsonb_typeof(item->'creditLinkId') IS DISTINCT FROM 'number'
   OR jsonb_typeof(item->'productCents') IS DISTINCT FROM 'number'
   OR jsonb_typeof(item->'packagingCents') IS DISTINCT FROM 'number'
   OR jsonb_typeof(item->'landedCents') IS DISTINCT FROM 'number'
  THEN RAISE EXCEPTION 'Return credit attribution must use exact integers' USING ERRCODE='23514'; END IF;
  product:=(item->>'productCents')::numeric; packaging:=(item->>'packagingCents')::numeric; landed:=(item->>'landedCents')::numeric;
  IF product<0 OR packaging<0 OR landed<>0 OR product<>trunc(product) OR packaging<>trunc(packaging)
   OR product>9007199254740991 OR packaging>9007199254740991
   OR (item->>'creditLinkId')::numeric<>trunc((item->>'creditLinkId')::numeric)
   OR (item->>'creditLinkId')::bigint=ANY(seen)
  THEN RAISE EXCEPTION 'Return credit attribution must be unique supported goods amounts' USING ERRCODE='23514'; END IF;
  SELECT * INTO link FROM procurement.supplier_return_credit_links WHERE id=(item->>'creditLinkId')::bigint;
  SELECT credit.status INTO status FROM procurement.supplier_credit_lines line JOIN procurement.supplier_credits credit ON credit.id=line.supplier_credit_id
   WHERE line.id=link.supplier_credit_line_id;
  IF link.id IS NULL OR link.entitlement_id<>NEW.entitlement_id OR link.component<>'unassigned' OR status IS DISTINCT FROM 'approved'
   OR product+packaging<>link.amount_cents
  THEN RAISE EXCEPTION 'Return attribution must conserve one current unassigned supplier credit' USING ERRCODE='23514'; END IF;
  seen:=array_append(seen,link.id::bigint);
 END LOOP;
 RETURN NEW;
END; $$;


--
-- Name: guard_supplier_return_entitlement(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_supplier_return_entitlement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE returned inventory.supplier_return_allocations%ROWTYPE; allowed jsonb; part jsonb; claimed numeric; previous_end numeric:=-1;
BEGIN
 SELECT * INTO STRICT returned FROM inventory.supplier_return_allocations WHERE id=NEW.return_allocation_id FOR UPDATE;
 SELECT intervals INTO STRICT allowed FROM inventory.lot_cost_quantity_allocations WHERE id=returned.allocation_id;
 IF returned.supplier_return_line_id<>NEW.supplier_return_line_id OR jsonb_array_length(NEW.intervals)=0
 THEN RAISE EXCEPTION 'Return entitlement requires its exact physical allocation' USING ERRCODE='23514'; END IF;
 claimed:=0;
 FOR part IN SELECT value FROM jsonb_array_elements(NEW.intervals) ORDER BY (value->>'start')::numeric LOOP
  IF jsonb_typeof(part->'start') IS DISTINCT FROM 'number' OR jsonb_typeof(part->'quantity') IS DISTINCT FROM 'number'
   OR (part->>'start')::numeric<0 OR (part->>'start')::numeric<>trunc((part->>'start')::numeric)
   OR (part->>'quantity')::numeric<=0 OR (part->>'quantity')::numeric<>trunc((part->>'quantity')::numeric)
   OR (part->>'start')::numeric<previous_end
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(allowed) source
    WHERE (part->>'start')::numeric>=(source->>'start')::numeric
     AND (part->>'start')::numeric+(part->>'quantity')::numeric<=(source->>'start')::numeric+(source->>'quantity')::numeric)
   OR EXISTS(SELECT 1 FROM procurement.supplier_return_credit_entitlements entitlement,
    LATERAL jsonb_array_elements(entitlement.intervals) occupied WHERE entitlement.return_allocation_id=NEW.return_allocation_id
     AND (part->>'start')::numeric<(occupied->>'start')::numeric+(occupied->>'quantity')::numeric
     AND (occupied->>'start')::numeric<(part->>'start')::numeric+(part->>'quantity')::numeric)
  THEN RAISE EXCEPTION 'Return entitlement overlaps or exceeds immutable returned units' USING ERRCODE='23514'; END IF;
  previous_end:=(part->>'start')::numeric+(part->>'quantity')::numeric;
  claimed:=claimed+(part->>'quantity')::numeric;
 END LOOP;
 IF claimed<>NEW.quantity THEN RAISE EXCEPTION 'Return entitlement quantity does not equal its intervals' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $$;


--
-- Name: guard_supplier_return_line(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_supplier_return_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE header procurement.supplier_returns%ROWTYPE; snapshot jsonb; origin jsonb;
BEGIN
 SELECT * INTO STRICT header FROM procurement.supplier_returns WHERE id=NEW.supplier_return_id;
 -- The immutable report seals the collection. Both inserts take the graph
 -- statement lock, so a concurrent append rechecks after the creator commits.
 -- All original lines are inserted before the report in the owner transaction.
 IF EXISTS(SELECT 1 FROM procurement.supplier_return_reporting_events WHERE supplier_return_id=NEW.supplier_return_id)
 THEN RAISE EXCEPTION 'A reported supplier collection cannot acquire additional source lines' USING ERRCODE='23514'; END IF;
 snapshot:=NEW.source_snapshot; origin:=snapshot->'sourceProof'->'origin';
 IF snapshot->'inventoryLotId' IS DISTINCT FROM to_jsonb(NEW.inventory_lot_id)
 OR snapshot->'inventoryLevelId' IS DISTINCT FROM to_jsonb(NEW.inventory_level_id)
 OR snapshot->'warehouseLocationId' IS DISTINCT FROM to_jsonb(NEW.warehouse_location_id)
 OR snapshot->'warehouseId' IS DISTINCT FROM to_jsonb(NEW.warehouse_id)
 OR snapshot->'productId' IS DISTINCT FROM to_jsonb(NEW.product_id)
 OR snapshot->'productVariantId' IS DISTINCT FROM to_jsonb(NEW.product_variant_id)
 OR snapshot->'quantity' IS DISTINCT FROM to_jsonb(NEW.quantity)
 OR snapshot->'unitsPerVariant' IS DISTINCT FROM to_jsonb(NEW.units_per_variant)
 OR snapshot->'basePieces' IS DISTINCT FROM to_jsonb(NEW.base_pieces)
 OR origin->'vendorId' IS DISTINCT FROM to_jsonb(header.vendor_id)
 OR origin->'inventoryLotId' IS DISTINCT FROM to_jsonb(NEW.origin_lot_id)
 OR origin->'purchaseOrderId' IS DISTINCT FROM to_jsonb(NEW.purchase_order_id)
 OR origin->'purchaseOrderLineId' IS DISTINCT FROM to_jsonb(NEW.purchase_order_line_id)
 OR origin->'receivingOrderId' IS DISTINCT FROM to_jsonb(NEW.receiving_order_id)
 OR origin->'receivingLineId' IS DISTINCT FROM to_jsonb(NEW.receiving_line_id)
 OR NOT EXISTS(SELECT 1 FROM procurement.purchase_order_lines line JOIN procurement.purchase_orders po ON po.id=line.purchase_order_id
   WHERE line.id=NEW.purchase_order_line_id AND po.id=NEW.purchase_order_id AND po.vendor_id=header.vendor_id AND line.product_id=NEW.product_id)
 THEN RAISE EXCEPTION 'Supplier return line does not match its frozen supplier and stock source' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $$;


--
-- Name: guard_supplier_return_report(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_supplier_return_report() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE header procurement.supplier_returns%ROWTYPE;
BEGIN
 SELECT * INTO STRICT header FROM procurement.supplier_returns WHERE id=NEW.supplier_return_id;
 IF NEW.payload->>'eventType' IS DISTINCT FROM 'inventory.supplier_return_recorded'
 OR NEW.payload->'returnId' IS DISTINCT FROM to_jsonb(header.id)
 OR NEW.payload->'vendorId' IS DISTINCT FROM to_jsonb(header.vendor_id)
 OR NEW.payload->>'actorId' IS DISTINCT FROM header.recorded_by
 OR NEW.recorded_at<>header.recorded_at
 THEN RAISE EXCEPTION 'Supplier return report must retain its physical collection identity' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $$;


--
-- Name: guard_supplier_tax_return_credit(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.guard_supplier_tax_return_credit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_TABLE_NAME='supplier_credit_lines' THEN
  PERFORM procurement.assert_supplier_tax_return_credit(NEW.invoice_line_id,NEW.disposition,NEW.source_evidence,NEW.amount_cents,NEW.supplier_credit_id);
 ELSIF NEW.status='approved' AND OLD.status='draft' THEN
  PERFORM procurement.assert_supplier_tax_return_credit(line.invoice_line_id,line.disposition,line.source_evidence,line.amount_cents,NEW.id)
   FROM procurement.supplier_credit_lines line WHERE line.supplier_credit_id=NEW.id;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: lock_ap_payment_graph(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.lock_ap_payment_graph() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('inventory.cost_graph'), hashtext('version_1'));
  RETURN NULL;
END $$;


--
-- Name: lock_shipment_billing_graph(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.lock_shipment_billing_graph() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('inventory.cost_graph'), hashtext('version_1'));
  RETURN NULL;
END $$;


--
-- Name: po_email_document_is_verified(integer, character varying, character varying, character varying, text, character varying); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.po_email_document_is_verified(contract_version integer, document_hash character varying, source_revision character varying, purpose character varying, html_body text, hold_reason character varying) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
  SELECT COALESCE(
    contract_version = 1
    AND document_hash ~ '^[a-f0-9]{64}$'
    AND source_revision ~ '^[a-f0-9]{64}$'
    AND purpose = 'current_copy'
    AND length(html_body) > 0
    AND document_hash = encode(sha256(convert_to(html_body, 'UTF8')), 'hex')
    AND hold_reason IS NULL,
    FALSE
  )
$_$;


--
-- Name: po_email_outbox_document_guard(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.po_email_outbox_document_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.document_contract_version IS DISTINCT FROM OLD.document_contract_version
       OR NEW.document_hash IS DISTINCT FROM OLD.document_hash
       OR NEW.document_source_revision IS DISTINCT FROM OLD.document_source_revision
       OR NEW.document_purpose IS DISTINCT FROM OLD.document_purpose THEN
      RAISE EXCEPTION 'PO email document metadata is immutable' USING ERRCODE = '23514';
    END IF;
    IF OLD.document_hold_reason IS NOT NULL AND
       (NEW.document_hold_reason IS DISTINCT FROM OLD.document_hold_reason
        OR NEW.document_held_at IS DISTINCT FROM OLD.document_held_at) THEN
      RAISE EXCEPTION 'PO email document holds are immutable' USING ERRCODE = '23514';
    END IF;
    IF OLD.status IN ('sent', 'partially_sent') AND
       (NEW.document_hold_reason IS DISTINCT FROM OLD.document_hold_reason
        OR NEW.document_held_at IS DISTINCT FROM OLD.document_held_at) THEN
      RAISE EXCEPTION 'Completed PO email history cannot acquire a document hold' USING ERRCODE = '23514';
    END IF;
  END IF;

  -- Protect old writer/worker paths too, including lease reclamation of an
  -- unsupported processing row. Completion of an already in-flight acceptance
  -- is allowed: a content hold must not erase an actual transport outcome.
  IF TG_OP = 'INSERT' OR
     (NEW.status = 'processing' AND
      (OLD.status IS DISTINCT FROM 'processing'
       OR NEW.lease_token IS DISTINCT FROM OLD.lease_token
       OR NEW.lease_expires_at IS DISTINCT FROM OLD.lease_expires_at
       OR NEW.attempt_count IS DISTINCT FROM OLD.attempt_count)) THEN
    IF NOT procurement.po_email_document_is_verified(
      NEW.document_contract_version, NEW.document_hash, NEW.document_source_revision,
      NEW.document_purpose, NEW.html_body, NEW.document_hold_reason
    ) THEN
      RAISE EXCEPTION 'PO email requires a verified current supplier document' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: po_email_outbox_update_guard(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.po_email_outbox_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.purchase_order_id IS DISTINCT FROM OLD.purchase_order_id
     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
     OR NEW.to_email IS DISTINCT FROM OLD.to_email
     OR NEW.cc_email IS DISTINCT FROM OLD.cc_email
     OR NEW.subject IS DISTINCT FROM OLD.subject
     OR NEW.html_body IS DISTINCT FROM OLD.html_body
     OR NEW.text_body IS DISTINCT FROM OLD.text_body
     OR NEW.message_id IS DISTINCT FROM OLD.message_id
     OR NEW.max_attempts IS DISTINCT FROM OLD.max_attempts
     OR NEW.replay_of_id IS DISTINCT FROM OLD.replay_of_id
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'PO email outbox request snapshots are immutable'
      USING ERRCODE = '23514';
  END IF;

  IF OLD.status IN ('sent', 'partially_sent', 'dead_letter')
     AND NEW.status IS DISTINCT FROM OLD.status THEN
    RAISE EXCEPTION 'PO email outbox terminal states are immutable'
      USING ERRCODE = '23514';
  END IF;

  IF (OLD.status = 'queued' AND NEW.status NOT IN ('queued', 'processing'))
     OR (OLD.status = 'processing' AND NEW.status NOT IN ('processing', 'queued', 'sent', 'partially_sent', 'dead_letter')) THEN
    RAISE EXCEPTION 'Invalid PO email outbox status transition: % -> %', OLD.status, NEW.status
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: preserve_shipment_invoice_association(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.preserve_shipment_invoice_association() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.vendor_invoice_id IS NOT NULL AND (TG_OP='DELETE' OR NEW.vendor_invoice_id IS NULL OR
    (NEW.vendor_invoice_id IS DISTINCT FROM OLD.vendor_invoice_id AND NOT EXISTS (
      SELECT 1 FROM procurement.vendor_invoice_lines WHERE freight_cost_id=OLD.id AND vendor_invoice_id=OLD.vendor_invoice_id))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='shipment_invoice_source_immutable',
      MESSAGE='The recorded shipment invoice association is retained billing evidence.';
  END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;


--
-- Name: preserve_shipment_invoice_line_source(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.preserve_shipment_invoice_line_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.freight_cost_id IS NOT NULL AND (TG_OP = 'DELETE' OR
    ROW(NEW.freight_cost_id,NEW.vendor_invoice_id,NEW.purchase_order_line_id,NEW.product_variant_id)
      IS DISTINCT FROM ROW(OLD.freight_cost_id,OLD.vendor_invoice_id,OLD.purchase_order_line_id,OLD.product_variant_id)) THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='shipment_invoice_source_immutable',
      MESSAGE='Shipment invoice source lines are retained evidence; use the explicit void and replacement workflow.';
  END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;


--
-- Name: protect_cost_report_delivery(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.protect_cost_report_delivery() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP IN ('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'Reporting delivery history cannot be removed' USING ERRCODE='55000'; END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.destination_id IS DISTINCT FROM OLD.destination_id
    OR NEW.source_event_id IS DISTINCT FROM OLD.source_event_id OR NEW.application_id IS DISTINCT FROM OLD.application_id
    OR NEW.purchase_order_id IS DISTINCT FROM OLD.purchase_order_id OR NEW.envelope IS DISTINCT FROM OLD.envelope
    OR NEW.recorded_at IS DISTINCT FROM OLD.recorded_at
    OR (OLD.acknowledgement IS NOT NULL AND NEW IS DISTINCT FROM OLD)
  THEN RAISE EXCEPTION 'Reporting identity, payload and acknowledged history are immutable' USING ERRCODE='55000'; END IF;
  RETURN NEW;
END $$;


--
-- Name: protect_inbound_tracking_identity(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.protect_inbound_tracking_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF ROW(NEW.id, NEW.inbound_shipment_id, NEW.provider, NEW.reference_type, NEW.reference, NEW.carrier_code)
     IS DISTINCT FROM ROW(OLD.id, OLD.inbound_shipment_id, OLD.provider, OLD.reference_type, OLD.reference, OLD.carrier_code) THEN
    RAISE EXCEPTION 'Inbound tracking identity is immutable; pause it and add a corrected reference';
  END IF;
  RETURN NEW;
END $$;


