--

CREATE FUNCTION returns.audit_customer_return_submission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO returns.customer_return_submission_events(channel_id,idempotency_key,before_status,after_status,actor,error_code,occurred_at)
  VALUES(NEW.channel_id,NEW.idempotency_key,CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.status END,
    NEW.status,COALESCE(NEW.lease_actor,NEW.actor),NEW.error_code,NEW.updated_at);
  RETURN NULL;
END $$;


--
-- Name: guard_customer_refund_case(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_refund_case() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target returns.return_cases%ROWTYPE;
  channel_provider varchar(30);
BEGIN
  SELECT * INTO target
  FROM returns.return_cases
  WHERE id = NEW.return_case_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Return Case % does not exist', NEW.return_case_id USING ERRCODE = '23503';
  END IF;

  SELECT provider INTO channel_provider
  FROM channels.channels
  WHERE id = target.channel_id
  FOR SHARE;

  IF target.business_context <> 'retail'
     OR target.channel_id <> NEW.channel_id
     OR channel_provider IS DISTINCT FROM 'shopify'
     OR target.policy_snapshot->>'customerRefundAuthority' IS DISTINCT FROM 'card_shellz'
     OR target.case_status <> 'open'
     OR target.approval_status <> 'approved'
     OR NOT (
       (target.inspection_status = 'not_required'
         AND target.policy_snapshot->>'inspectionRequirement' = 'none'
         AND NOT EXISTS (
           SELECT 1
           FROM returns.return_case_inspections inspection
           WHERE inspection.return_case_id = target.id
         ))
       OR (target.inspection_status = 'approved' AND EXISTS (
         SELECT 1
         FROM returns.return_case_inspections inspection
         WHERE inspection.return_case_id = target.id
           AND inspection.status = 'approved'
           AND inspection.completed_at IS NOT NULL
           AND inspection.completed_by IS NOT NULL
       ))
     )
     OR NOT returns.return_case_disposition_is_complete(target.id)
     OR target.customer_refund_status NOT IN ('pending','failed') THEN
    RAISE EXCEPTION 'Return Case % is not eligible for a customer refund', NEW.return_case_id
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_customer_refund_item_evidence(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_refund_item_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  header returns.return_case_customer_refunds%ROWTYPE;
  item_case_id bigint;
BEGIN
  SELECT * INTO header
  FROM returns.return_case_customer_refunds
  WHERE id = NEW.customer_refund_id
  FOR UPDATE;
  IF NOT FOUND OR header.status <> 'pending' THEN
    RAISE EXCEPTION 'Customer refund % is not accepting item evidence', NEW.customer_refund_id
      USING ERRCODE = '23514';
  END IF;

  SELECT return_case_id INTO item_case_id
  FROM returns.return_case_items
  WHERE id = NEW.return_case_item_id
  FOR SHARE;
  IF NOT FOUND OR item_case_id <> header.return_case_id THEN
    RAISE EXCEPTION 'Customer refund item % does not belong to Return Case %',
      NEW.return_case_item_id, header.return_case_id USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(header.quote->'lines') AS quoted(line)
    WHERE (quoted.line->>'returnCaseItemId')::bigint = NEW.return_case_item_id
      AND quoted.line->>'externalLineItemId' = NEW.external_line_item_id
      AND (quoted.line->>'quantity')::integer = NEW.quantity
      AND (quoted.line->>'subtotalCents')::bigint = NEW.subtotal_cents
      AND (quoted.line->>'taxCents')::bigint = NEW.tax_cents
      AND (quoted.line->>'totalCents')::bigint = NEW.total_cents
  ) THEN
    RAISE EXCEPTION 'Customer refund item evidence does not match the approved quote'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_customer_refund_transaction_evidence(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_refund_transaction_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  header returns.return_case_customer_refunds%ROWTYPE;
BEGIN
  SELECT * INTO header
  FROM returns.return_case_customer_refunds
  WHERE id = NEW.customer_refund_id
  FOR UPDATE;
  IF NOT FOUND OR header.status <> 'pending' THEN
    RAISE EXCEPTION 'Customer refund % is not accepting transaction evidence', NEW.customer_refund_id
      USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(header.quote->'transactions') AS quoted(transaction)
    WHERE (quoted.transaction->>'position')::integer = NEW.position
      AND quoted.transaction->>'parentTransactionId' = NEW.parent_transaction_id
      AND quoted.transaction->>'gateway' = NEW.gateway
      AND (quoted.transaction->>'amountCents')::bigint = NEW.amount_cents
  ) THEN
    RAISE EXCEPTION 'Customer refund transaction evidence does not match the approved quote'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_customer_refund_transition(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_refund_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status <> 'pending' OR NEW.status NOT IN ('completed','failed') THEN
    RAISE EXCEPTION 'Customer refund evidence only permits pending to terminal transition'
      USING ERRCODE = '55000';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.return_case_id IS DISTINCT FROM OLD.return_case_id
     OR NEW.channel_id IS DISTINCT FROM OLD.channel_id
     OR NEW.provider IS DISTINCT FROM OLD.provider
     OR NEW.external_order_id IS DISTINCT FROM OLD.external_order_id
     OR NEW.currency IS DISTINCT FROM OLD.currency
     OR NEW.amount_cents IS DISTINCT FROM OLD.amount_cents
     OR NEW.maximum_refundable_cents IS DISTINCT FROM OLD.maximum_refundable_cents
     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
     OR NEW.quote_hash IS DISTINCT FROM OLD.quote_hash
     OR NEW.quote IS DISTINCT FROM OLD.quote
     OR NEW.notify_customer IS DISTINCT FROM OLD.notify_customer
     OR NEW.requested_by IS DISTINCT FROM OLD.requested_by
     OR NEW.notes IS DISTINCT FROM OLD.notes
     OR NEW.requested_at IS DISTINCT FROM OLD.requested_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Customer refund request evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_customer_return_authorization_graph(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_authorization_graph() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE root_id BIGINT;
BEGIN
  IF TG_TABLE_NAME = 'customer_return_authorizations' THEN root_id := NEW.id;
  ELSE root_id := NEW.authorization_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM returns.customer_return_authorization_lines WHERE authorization_id = root_id)
    OR EXISTS (
      SELECT 1 FROM returns.customer_return_authorization_lines al
      LEFT JOIN returns.customer_return_authorization_allocations aa ON aa.authorization_line_id = al.id
      WHERE al.authorization_id = root_id
      GROUP BY al.id, al.quantity HAVING COALESCE(SUM(aa.quantity), 0) <> al.quantity
    )
    OR NOT EXISTS (SELECT 1 FROM returns.customer_return_authorization_commands WHERE authorization_id = root_id)
    OR NOT EXISTS (SELECT 1 FROM returns.customer_return_authorization_events WHERE authorization_id = root_id)
    OR NOT EXISTS (SELECT 1 FROM returns.customer_return_authorization_outbox WHERE authorization_id = root_id)
  THEN
    RAISE EXCEPTION 'Customer authorization evidence graph is incomplete or unbalanced' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: guard_customer_return_authorization_ownership(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_authorization_ownership() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'customer_return_authorizations' THEN
    IF NOT EXISTS (SELECT 1 FROM oms.oms_orders WHERE id=NEW.oms_order_id AND channel_id=NEW.channel_id) THEN
      RAISE EXCEPTION 'Authorization source channel does not match its OMS order' USING ERRCODE='23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'customer_return_authorization_lines' THEN
    IF NOT EXISTS (SELECT 1 FROM returns.customer_return_authorizations a JOIN oms.oms_order_lines ol ON ol.order_id=a.oms_order_id
      WHERE a.id=NEW.authorization_id AND ol.id=NEW.oms_order_line_id AND ol.external_line_item_id=NEW.external_line_item_id) THEN
      RAISE EXCEPTION 'Authorization line does not match its OMS source' USING ERRCODE='23514';
    END IF;
  ELSE
    IF NEW.source_kind='shopify_purchase' THEN
      IF NOT EXISTS (SELECT 1 FROM returns.customer_return_authorization_lines al
        JOIN returns.customer_return_authorizations a ON a.id=al.authorization_id
        JOIN oms.oms_order_lines ol ON ol.id=al.oms_order_line_id AND ol.order_id=a.oms_order_id
        WHERE al.id=NEW.authorization_line_id AND al.authorization_id=NEW.authorization_id
          AND ol.external_line_item_id=al.external_line_item_id
          AND NEW.delivery_evidence->>'method'='verified_shopify_purchase_v1') THEN
        RAISE EXCEPTION 'Purchase authorization does not match its purchased source' USING ERRCODE='23514';
      END IF;
      RETURN NEW;
    END IF;
    IF (SELECT count(*) FROM returns.customer_return_authorization_lines al
      JOIN returns.customer_return_authorizations a ON a.id=al.authorization_id
      JOIN returns.customer_return_source_items s ON s.oms_order_id=a.oms_order_id
        AND s.oms_order_line_id=al.oms_order_line_id AND s.wms_order_item_id=NEW.wms_order_item_id
      WHERE al.id=NEW.authorization_line_id AND al.authorization_id=NEW.authorization_id) <> 1 THEN
      RAISE EXCEPTION 'Authorization allocation does not match its purchased-line source' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_customer_return_guest_identity(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_guest_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.id,NEW.channel_id,NEW.browser_hash,NEW.input_hash,NEW.email_hash,NEW.oms_order_id,NEW.purchase,NEW.created_at,NEW.expires_at)
    IS DISTINCT FROM (OLD.id,OLD.channel_id,OLD.browser_hash,OLD.input_hash,OLD.email_hash,OLD.oms_order_id,OLD.purchase,OLD.created_at,OLD.expires_at)
    OR NEW.attempts < OLD.attempts
    OR (OLD.verified_at IS NOT NULL AND NEW.verified_at IS DISTINCT FROM OLD.verified_at)
    OR (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at) THEN
    RAISE EXCEPTION 'Guest verification identity cannot change' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_customer_return_intake_graph(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_intake_graph() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE root_id BIGINT;
BEGIN
  IF TG_TABLE_NAME = 'customer_return_parcel_items' THEN
    SELECT authorization_id INTO root_id FROM returns.customer_return_parcels WHERE id = NEW.parcel_id;
  ELSE root_id := NEW.authorization_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM returns.customer_return_intakes WHERE authorization_id = root_id) THEN RETURN NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM returns.customer_return_parcels WHERE authorization_id = root_id)
    OR NOT EXISTS (SELECT 1 FROM returns.customer_return_case_links WHERE authorization_id = root_id)
    OR EXISTS (SELECT 1 FROM returns.return_case_customer_refunds refund
      JOIN returns.customer_return_case_links cl ON cl.case_id=refund.return_case_id WHERE cl.authorization_id=root_id)
    OR (SELECT COUNT(*) FROM returns.customer_return_parcels WHERE authorization_id = root_id) > 20
    OR EXISTS (
      SELECT 1 FROM returns.customer_return_authorization_allocations aa
      LEFT JOIN returns.customer_return_allocation_case_items link ON link.authorization_allocation_id = aa.id
      WHERE aa.authorization_id = root_id AND link.authorization_allocation_id IS NULL
    ) OR EXISTS (
      SELECT 1 FROM returns.customer_return_allocation_case_items link
      JOIN returns.customer_return_authorization_allocations aa ON aa.id = link.authorization_allocation_id
      JOIN returns.customer_return_authorization_lines al ON al.id = aa.authorization_line_id
      JOIN returns.return_case_items ci ON ci.id = link.case_item_id
      JOIN wms.return_items ri ON ri.id = link.wms_return_item_id
      JOIN returns.customer_return_case_links cl ON cl.case_id = ci.return_case_id
      WHERE link.authorization_id = root_id AND (aa.authorization_id <> root_id OR cl.authorization_id <> root_id
        OR ci.wms_return_item_id <> ri.id OR ci.wms_order_item_id IS DISTINCT FROM aa.wms_order_item_id
        OR ri.order_item_id IS DISTINCT FROM aa.wms_order_item_id OR ci.oms_order_line_id <> al.oms_order_line_id
        OR ri.oms_order_line_id <> al.oms_order_line_id OR ri.return_id <> cl.wms_return_id)
    ) OR EXISTS (
      SELECT 1 FROM returns.customer_return_case_links cl
      JOIN returns.return_cases rc ON rc.id = cl.case_id
      JOIN returns.customer_return_authorizations a ON a.id = cl.authorization_id
      JOIN wms.returns wr ON wr.id = cl.wms_return_id
      WHERE cl.authorization_id = root_id AND (rc.wms_return_id <> cl.wms_return_id OR rc.wms_order_id IS DISTINCT FROM cl.wms_order_id
        OR wr.order_id IS DISTINCT FROM cl.wms_order_id OR rc.oms_order_id <> a.oms_order_id OR rc.channel_id <> a.channel_id
        OR (cl.wms_order_id IS NULL AND wr.source_authorization_id IS DISTINCT FROM root_id)
        OR rc.source_provider <> 'customer_portal' OR rc.source_event_type <> 'private_customer_return'
        OR rc.source_event_id <> root_id::text || ':' || COALESCE(cl.wms_order_id::text,'purchase') OR rc.created_at <> a.created_at)
    ) OR EXISTS (
      SELECT ci.id FROM returns.return_case_items ci
      JOIN returns.customer_return_case_links cl ON cl.case_id = ci.return_case_id
      LEFT JOIN returns.customer_return_allocation_case_items link ON link.case_item_id = ci.id
      LEFT JOIN returns.customer_return_authorization_allocations aa ON aa.id = link.authorization_allocation_id
      JOIN wms.return_items ri ON ri.id = ci.wms_return_item_id
      WHERE cl.authorization_id = root_id
      GROUP BY ci.id, ci.quantity, ri.expected_qty HAVING COALESCE(SUM(aa.quantity),0) <> ci.quantity OR ci.quantity <> ri.expected_qty
    ) OR EXISTS (
      SELECT al.id FROM returns.customer_return_authorization_lines al
      LEFT JOIN returns.customer_return_parcel_items pi ON pi.authorization_line_id = al.id
      LEFT JOIN returns.customer_return_parcels p ON p.id = pi.parcel_id
      WHERE al.authorization_id = root_id
      GROUP BY al.id, al.quantity HAVING COALESCE(SUM(pi.quantity),0) <> al.quantity
        OR BOOL_OR(p.authorization_id <> root_id)
    ) OR EXISTS (
      SELECT p.id FROM returns.customer_return_parcels p LEFT JOIN returns.customer_return_parcel_items pi ON pi.parcel_id = p.id
      WHERE p.authorization_id = root_id GROUP BY p.id HAVING COUNT(pi.parcel_id) = 0
    ) THEN
    RAISE EXCEPTION 'Private return intake graph is incomplete or unbalanced' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: guard_customer_return_intake_ownership(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_intake_ownership() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'customer_return_allocation_case_items' THEN
    IF NOT EXISTS (
      SELECT 1 FROM returns.customer_return_authorization_allocations aa
      JOIN returns.customer_return_authorization_lines al ON al.id=aa.authorization_line_id
      JOIN returns.return_case_items ci ON ci.id=NEW.case_item_id
      JOIN returns.customer_return_case_links cl ON cl.case_id=ci.return_case_id
      JOIN wms.return_items ri ON ri.id=NEW.wms_return_item_id
      WHERE aa.id=NEW.authorization_allocation_id AND aa.authorization_id=NEW.authorization_id
        AND cl.authorization_id=NEW.authorization_id AND ci.wms_return_item_id=ri.id
        AND ci.wms_order_item_id IS NOT DISTINCT FROM aa.wms_order_item_id AND ri.order_item_id IS NOT DISTINCT FROM aa.wms_order_item_id
        AND ci.oms_order_line_id=al.oms_order_line_id AND ri.oms_order_line_id=al.oms_order_line_id
        AND ci.external_line_item_id=al.external_line_item_id AND ri.external_line_item_id=al.external_line_item_id
        AND ri.return_id=cl.wms_return_id
    ) THEN RAISE EXCEPTION 'Portal allocation ownership mismatch' USING ERRCODE='23514'; END IF;
  ELSIF TG_TABLE_NAME = 'customer_return_parcel_items' THEN
    IF NOT EXISTS (SELECT 1 FROM returns.customer_return_parcels p
      JOIN returns.customer_return_authorization_lines al ON al.authorization_id=p.authorization_id
      WHERE p.id=NEW.parcel_id AND al.id=NEW.authorization_line_id) THEN
      RAISE EXCEPTION 'Portal parcel line ownership mismatch' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_customer_return_label_attempt(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_label_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Return label attempts cannot be deleted'; END IF;
  IF (NEW.parcel_id,NEW.attempt_number,NEW.idempotency_key,NEW.request_snapshot,NEW.actor,NEW.started_at)
      IS DISTINCT FROM (OLD.parcel_id,OLD.attempt_number,OLD.idempotency_key,OLD.request_snapshot,OLD.actor,OLD.started_at)
    OR (OLD.status IN ('succeeded','failed') AND NEW IS DISTINCT FROM OLD)
    OR (OLD.status='uncertain' AND NEW.status NOT IN ('uncertain','succeeded'))
  THEN RAISE EXCEPTION 'Return label intent and terminal outcome are immutable'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_customer_return_linked_case_identity(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_linked_case_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM returns.customer_return_case_links WHERE case_id = OLD.id)
    AND (NEW.source_provider, NEW.source_event_type, NEW.source_event_id, NEW.oms_order_id, NEW.wms_order_id,
      NEW.wms_return_id, NEW.channel_id, NEW.policy_id, NEW.policy_version, NEW.policy_snapshot, NEW.created_at)
    IS DISTINCT FROM (OLD.source_provider, OLD.source_event_type, OLD.source_event_id, OLD.oms_order_id, OLD.wms_order_id,
      OLD.wms_return_id, OLD.channel_id, OLD.policy_id, OLD.policy_version, OLD.policy_snapshot, OLD.created_at) THEN
    RAISE EXCEPTION 'Portal return case identity is immutable' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_customer_return_linked_wms_identity(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_linked_wms_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM returns.customer_return_allocation_case_items WHERE wms_return_item_id=OLD.id)
    AND (NEW.return_id,NEW.order_item_id,NEW.oms_order_line_id,NEW.external_line_item_id,NEW.expected_qty)
      IS DISTINCT FROM (OLD.return_id,OLD.order_item_id,OLD.oms_order_line_id,OLD.external_line_item_id,OLD.expected_qty) THEN
    RAISE EXCEPTION 'Portal return item identity and entitlement are immutable' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_customer_return_manual_refund(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_manual_refund() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM returns.customer_return_case_links WHERE case_id = NEW.return_case_id) THEN
    RAISE EXCEPTION 'Portal return refunds must be issued manually in Shopify' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_customer_return_parcel_receipt(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_parcel_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE receipt_key BIGINT; root_id BIGINT;
BEGIN
  IF TG_TABLE_NAME='customer_return_parcel_receipts' THEN receipt_key:=NEW.id; ELSE receipt_key:=NEW.receipt_id; END IF;
  SELECT p.authorization_id INTO STRICT root_id FROM returns.customer_return_parcels p
    JOIN returns.customer_return_parcel_receipts r ON r.parcel_id=p.id WHERE r.id=receipt_key;
  IF NOT EXISTS(SELECT 1 FROM returns.customer_return_parcel_receipt_allocations WHERE receipt_id=receipt_key)
    OR NOT EXISTS (SELECT 1 FROM returns.customer_return_parcel_receipts r
      JOIN returns.customer_return_label_attempts label ON label.parcel_id=r.parcel_id AND label.status='succeeded'
      WHERE r.id=receipt_key)
    OR EXISTS (
      SELECT 1 FROM returns.customer_return_parcel_receipt_allocations r
      JOIN returns.customer_return_parcels p ON p.id=r.parcel_id
      JOIN returns.customer_return_authorization_allocations a ON a.id=r.allocation_id
      LEFT JOIN returns.customer_return_parcel_items manifest ON manifest.parcel_id=p.id AND manifest.authorization_line_id=a.authorization_line_id
      LEFT JOIN returns.customer_return_allocation_case_items ci ON ci.authorization_allocation_id=a.id
      WHERE r.receipt_id=receipt_key AND (a.authorization_id<>p.authorization_id OR manifest.parcel_id IS NULL
        OR ci.case_item_id IS DISTINCT FROM r.case_item_id)
    ) OR EXISTS (
      SELECT 1 FROM returns.customer_return_parcel_receipt_allocations r
      JOIN returns.customer_return_authorization_allocations a ON a.id=r.allocation_id
      WHERE a.authorization_id=root_id GROUP BY a.id,a.quantity HAVING sum(r.quantity)>a.quantity
    ) OR EXISTS (
      SELECT 1 FROM returns.customer_return_parcel_receipt_allocations r
      JOIN returns.customer_return_authorization_allocations a ON a.id=r.allocation_id
      JOIN returns.customer_return_parcel_items manifest ON manifest.parcel_id=r.parcel_id AND manifest.authorization_line_id=a.authorization_line_id
      WHERE a.authorization_id=root_id GROUP BY r.parcel_id,a.authorization_line_id,manifest.quantity HAVING sum(r.quantity)>manifest.quantity
    ) OR EXISTS (
      SELECT 1 FROM returns.customer_return_parcel_receipt_allocations r
      JOIN returns.return_case_items ci ON ci.id=r.case_item_id
      JOIN wms.return_items wi ON wi.id=ci.wms_return_item_id
      JOIN returns.customer_return_authorization_allocations a ON a.id=r.allocation_id
      WHERE a.authorization_id=root_id GROUP BY ci.id,wi.received_qty HAVING sum(r.quantity)<>wi.received_qty
    ) THEN
    RAISE EXCEPTION 'Return box receipt provenance or quantity mismatch' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: guard_customer_return_quote_attempt(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_quote_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE parcel_mode TEXT;
BEGIN
  IF TG_OP='UPDATE' THEN
    IF NEW.quote_decision_id IS DISTINCT FROM OLD.quote_decision_id THEN
      RAISE EXCEPTION 'Return label quote linkage is immutable';
    END IF;
    RETURN NEW;
  END IF;
  SELECT selection_mode INTO parcel_mode FROM returns.customer_return_parcels WHERE id=NEW.parcel_id;
  IF parcel_mode='cheapest_eligible' AND NEW.quote_decision_id IS NULL THEN
    RAISE EXCEPTION 'Automatic return label requires a saved quote decision';
  END IF;
  IF NEW.quote_decision_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM returns.customer_return_quote_decisions q
    WHERE q.id=NEW.quote_decision_id AND q.parcel_id=NEW.parcel_id AND q.status='selected'
      AND q.quoted_at<=NEW.started_at AND q.expires_at>NEW.started_at
      AND q.selected_rate->>'carrierId'=NEW.request_snapshot->>'carrierId'
      AND q.selected_rate->>'serviceCode'=NEW.request_snapshot->>'serviceCode'
      AND q.shipment_snapshot=NEW.request_snapshot-ARRAY['carrierId','serviceCode']
  ) THEN RAISE EXCEPTION 'Return label purchase does not match its saved quote decision'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_customer_return_settings_history(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_settings_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN RAISE EXCEPTION 'Return configuration history is append-only'; END; $$;


--
-- Name: guard_customer_return_submission(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_submission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Return submission intent cannot be deleted'; END IF;
  IF TG_OP = 'UPDATE' AND (
    (NEW.channel_id,NEW.idempotency_key,NEW.request_hash,NEW.request_snapshot,NEW.actor,NEW.created_at)
      IS DISTINCT FROM (OLD.channel_id,OLD.idempotency_key,OLD.request_hash,OLD.request_snapshot,OLD.actor,OLD.created_at)
    OR (OLD.status IN ('accepted','rejected') AND NEW IS DISTINCT FROM OLD)
  ) THEN RAISE EXCEPTION 'Return submission intent and terminal outcome are immutable'; END IF;
  IF NEW.status = 'accepted' AND NOT EXISTS (
    SELECT 1 FROM returns.customer_return_authorization_commands c
    WHERE c.channel_id=NEW.channel_id AND c.idempotency_key=NEW.idempotency_key::text
      AND c.authorization_id=NEW.authorization_id AND c.semantic_hash=NEW.request_hash
  ) THEN RAISE EXCEPTION 'Accepted return submission must match its exact authorization'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_customer_return_submission_order(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_submission_order() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.oms_order_id IS DISTINCT FROM OLD.oms_order_id THEN
    RAISE EXCEPTION 'Return submission canonical order is immutable' USING ERRCODE = '23514';
  END IF;
  IF NEW.oms_order_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM oms.oms_orders o
      WHERE o.id = NEW.oms_order_id AND o.channel_id = NEW.channel_id
    ) THEN
      RAISE EXCEPTION 'Return submission source channel does not match its OMS order' USING ERRCODE = '23514';
    END IF;
    IF NEW.authorization_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM returns.customer_return_authorizations a
      WHERE a.id = NEW.authorization_id AND a.channel_id = NEW.channel_id
        AND a.oms_order_id = NEW.oms_order_id
    ) THEN
      RAISE EXCEPTION 'Return submission authorization does not match its OMS order' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_customer_return_workflow_identity(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_customer_return_workflow_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Return workflow intent is retained' USING ERRCODE='23514'; END IF;
  IF (NEW.channel_id,NEW.request_key,NEW.oms_order_id,NEW.request_snapshot,NEW.scope_snapshot,NEW.semantic_hash,NEW.actor,NEW.created_at)
    IS DISTINCT FROM (OLD.channel_id,OLD.request_key,OLD.oms_order_id,OLD.request_snapshot,OLD.scope_snapshot,OLD.semantic_hash,OLD.actor,OLD.created_at)
    OR (OLD.authorization_id IS NOT NULL AND NEW.authorization_id IS DISTINCT FROM OLD.authorization_id) THEN
    RAISE EXCEPTION 'Return workflow identity is immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_purchase_receiving_identity(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_purchase_receiving_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.order_id,NEW.source_authorization_id,NEW.source,NEW.source_event_key)
    IS DISTINCT FROM (OLD.order_id,OLD.source_authorization_id,OLD.source,OLD.source_event_key)
    AND (OLD.source_authorization_id IS NOT NULL OR NEW.source_authorization_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Purchased return receiving provenance is immutable' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_purchase_return_money_snapshot(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_purchase_return_money_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.unit_paid_price_cents IS NULL) IS DISTINCT FROM (NEW.source_line_total_cents IS NULL)
    OR (NEW.unit_paid_price_cents IS NULL AND NOT EXISTS (
      SELECT 1 FROM returns.return_cases rc WHERE rc.id=NEW.return_case_id
        AND rc.source_provider='customer_portal' AND rc.wms_order_id IS NULL AND NEW.wms_order_item_id IS NULL)) THEN
    RAISE EXCEPTION 'Unknown money is permitted only on a purchased-line return with manual Shopify refund authority' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_return_case_inspection_mutation(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_return_case_inspection_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.return_case_id IS DISTINCT FROM OLD.return_case_id
     OR NEW.started_at IS DISTINCT FROM OLD.started_at
     OR NEW.started_by IS DISTINCT FROM OLD.started_by
     OR NEW.notes IS DISTINCT FROM OLD.notes
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION
      'Return case inspection identity and start evidence are immutable'
      USING ERRCODE = '55000';
  END IF;

  IF OLD.status <> 'in_progress' THEN
    RAISE EXCEPTION
      'Completed return case inspections are immutable'
      USING ERRCODE = '55000';
  END IF;

  IF NEW.status NOT IN ('approved', 'rejected', 'cancelled') THEN
    RAISE EXCEPTION
      'An in-progress return case inspection may only transition to a terminal status'
      USING ERRCODE = '55000';
  END IF;

  IF NEW.completed_at IS NULL
     OR NEW.completed_by IS NULL
     OR btrim(NEW.completed_by) = '' THEN
    RAISE EXCEPTION
      'A completed return case inspection requires completion actor and time'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_return_case_mutation(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_return_case_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Return Cases are permanent operational records; DELETE is not allowed'
      USING ERRCODE = '55000';
  END IF;

  IF NEW.case_number IS DISTINCT FROM OLD.case_number
     OR NEW.source_provider IS DISTINCT FROM OLD.source_provider
     OR NEW.source_event_type IS DISTINCT FROM OLD.source_event_type
     OR NEW.source_event_id IS DISTINCT FROM OLD.source_event_id
     OR NEW.business_context IS DISTINCT FROM OLD.business_context
     OR NEW.channel_id IS DISTINCT FROM OLD.channel_id
     OR NEW.vendor_id IS DISTINCT FROM OLD.vendor_id
     OR NEW.store_connection_id IS DISTINCT FROM OLD.store_connection_id
     OR NEW.oms_order_id IS DISTINCT FROM OLD.oms_order_id
     OR NEW.wms_order_id IS DISTINCT FROM OLD.wms_order_id
     OR NEW.wms_return_id IS DISTINCT FROM OLD.wms_return_id
     OR NEW.policy_id IS DISTINCT FROM OLD.policy_id
     OR NEW.policy_version IS DISTINCT FROM OLD.policy_version
     OR NEW.policy_snapshot IS DISTINCT FROM OLD.policy_snapshot
     OR NEW.opened_at IS DISTINCT FROM OLD.opened_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Return Case identity, source linkage, and policy evidence are immutable'
      USING ERRCODE = '55000';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_vendor_settlement_case(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_vendor_settlement_case() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target returns.return_cases%ROWTYPE;
BEGIN
  SELECT * INTO target
  FROM returns.return_cases
  WHERE id = NEW.return_case_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Return Case % does not exist', NEW.return_case_id USING ERRCODE = '23503';
  END IF;
  IF target.business_context <> 'dropship'
     OR target.vendor_id IS DISTINCT FROM NEW.vendor_id
     OR target.policy_snapshot->>'vendorSettlementTrigger' IS DISTINCT FROM 'inspection_approved'
     OR target.case_status <> 'open'
     OR target.approval_status <> 'approved'
     OR target.inspection_status <> 'approved'
     OR NOT EXISTS (
       SELECT 1
       FROM returns.return_case_inspections inspection
       WHERE inspection.return_case_id = target.id
         AND inspection.status = 'approved'
         AND inspection.completed_at IS NOT NULL
         AND inspection.completed_by IS NOT NULL
     )
     OR NOT returns.return_case_disposition_is_complete(target.id)
     OR target.vendor_settlement_status NOT IN ('pending','eligible','failed') THEN
    RAISE EXCEPTION 'Return Case % is not eligible for vendor settlement', NEW.return_case_id
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_vendor_settlement_ledger_evidence(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.guard_vendor_settlement_ledger_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  settlement returns.return_case_vendor_settlements%ROWTYPE;
  ledger dropship.dropship_wallet_ledger%ROWTYPE;
  expected_amount bigint;
  expected_type varchar(40);
BEGIN
  SELECT * INTO settlement
  FROM returns.return_case_vendor_settlements
  WHERE id = NEW.vendor_settlement_id
  FOR UPDATE;
  SELECT * INTO ledger
  FROM dropship.dropship_wallet_ledger
  WHERE id = NEW.wallet_ledger_id
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Dropship wallet ledger entry % does not exist', NEW.wallet_ledger_id
      USING ERRCODE = '23503';
  END IF;

  IF NEW.entry_role = 'credit' THEN
    expected_amount := settlement.gross_credit_cents;
    IF expected_amount <= 0 OR ledger.type NOT IN ('return_credit','insurance_pool_credit') THEN
      RAISE EXCEPTION 'Vendor settlement credit evidence is invalid' USING ERRCODE = '23514';
    END IF;
  ELSE
    expected_amount := -settlement.total_fee_cents;
    expected_type := 'return_fee';
    IF settlement.total_fee_cents <= 0 OR ledger.type <> expected_type THEN
      RAISE EXCEPTION 'Vendor settlement fee evidence is invalid' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF ledger.vendor_id <> settlement.vendor_id
     OR ledger.currency <> settlement.currency
     OR ledger.status <> 'settled'
     OR ledger.amount_cents <> expected_amount
     OR ledger.reference_type <> 'return_case_vendor_settlement'
     OR ledger.reference_id <> (settlement.id::text || ':' || NEW.entry_role)
     OR ledger.idempotency_key <> (settlement.idempotency_key || ':' || NEW.entry_role) THEN
    RAISE EXCEPTION 'Wallet ledger entry % does not match vendor settlement %',
      NEW.wallet_ledger_id, NEW.vendor_settlement_id USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


