--
-- Name: return_case_disposition_is_complete(bigint); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.return_case_disposition_is_complete(target_case_id bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM returns.return_case_items case_item
    JOIN wms.return_items wms_item
      ON wms_item.id = case_item.wms_return_item_id
    WHERE case_item.return_case_id = target_case_id
      AND wms_item.received_qty > 0
  )
  AND NOT EXISTS (
    SELECT 1
    FROM returns.return_case_items case_item
    JOIN wms.return_items wms_item
      ON wms_item.id = case_item.wms_return_item_id
    LEFT JOIN LATERAL (
      SELECT COALESCE(sum(disposition_item.quantity), 0) AS recorded_quantity
      FROM returns.return_case_disposition_items disposition_item
      JOIN returns.return_case_dispositions disposition
        ON disposition.id = disposition_item.disposition_id
       AND disposition.return_case_id = target_case_id
      WHERE disposition_item.return_case_item_id = case_item.id
    ) recorded ON true
    WHERE case_item.return_case_id = target_case_id
      AND (wms_item.received_qty <> wms_item.expected_qty
        OR recorded.recorded_quantity <> wms_item.received_qty)
  );
$$;


--
-- Name: validate_customer_refund_command_evidence(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.validate_customer_refund_command_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'completed'
     AND NOT EXISTS (
       SELECT 1
       FROM returns.return_case_commands command
       WHERE command.return_case_id = NEW.return_case_id
         AND command.command_type = 'issue_customer_refund'
         AND command.idempotency_key = NEW.idempotency_key
         AND command.request_hash = NEW.request_hash
         AND command.actor = NEW.requested_by
         AND (command.response->>'caseId')::bigint = NEW.return_case_id
         AND (command.response->>'customerRefundId')::bigint = NEW.id
         AND command.response->>'provider' = NEW.provider
         AND command.response->>'providerRefundId' = NEW.provider_refund_id
         AND command.response->>'currency' = NEW.currency
         AND (command.response->>'amountCents')::bigint = NEW.amount_cents
     ) THEN
    RAISE EXCEPTION 'Completed customer refund requires matching immutable command evidence'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_customer_refund_evidence(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.validate_customer_refund_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_refund_id bigint := COALESCE(
    (to_jsonb(NEW)->>'customer_refund_id')::bigint,
    (to_jsonb(NEW)->>'id')::bigint,
    (to_jsonb(OLD)->>'customer_refund_id')::bigint,
    (to_jsonb(OLD)->>'id')::bigint
  );
  header returns.return_case_customer_refunds%ROWTYPE;
  item_total bigint;
  transaction_total bigint;
  item_count integer;
  transaction_count integer;
BEGIN
  SELECT * INTO header
  FROM returns.return_case_customer_refunds
  WHERE id = target_refund_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  SELECT COALESCE(SUM(total_cents), 0), COUNT(*)
    INTO item_total, item_count
  FROM returns.return_case_customer_refund_items
  WHERE customer_refund_id = target_refund_id;
  SELECT COALESCE(SUM(amount_cents), 0), COUNT(*)
    INTO transaction_total, transaction_count
  FROM returns.return_case_customer_refund_transactions
  WHERE customer_refund_id = target_refund_id;

  IF item_count = 0 OR transaction_count = 0
     OR item_total <> header.amount_cents
     OR transaction_total <> header.amount_cents
     OR item_count <> jsonb_array_length(header.quote->'lines')
     OR transaction_count <> jsonb_array_length(header.quote->'transactions') THEN
    RAISE EXCEPTION 'Customer refund % line or transaction evidence does not match header amount', target_refund_id
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: validate_return_case_disposition_command(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.validate_return_case_disposition_command() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.command_type = 'record_disposition'
     AND NOT EXISTS (
       SELECT 1
       FROM returns.return_case_dispositions disposition
       WHERE disposition.return_case_id = NEW.return_case_id
         AND disposition.idempotency_key = NEW.idempotency_key
         AND disposition.request_hash = NEW.request_hash
         AND disposition.recorded_by = NEW.actor
     ) THEN
    RAISE EXCEPTION 'Disposition command requires matching immutable disposition evidence'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_return_case_disposition_evidence(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.validate_return_case_disposition_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM returns.return_case_disposition_items item
    WHERE item.disposition_id = NEW.id
  ) THEN
    RAISE EXCEPTION 'A disposition record requires at least one item quantity'
      USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM returns.return_case_commands command
    WHERE command.return_case_id = NEW.return_case_id
      AND command.command_type = 'record_disposition'
      AND command.idempotency_key = NEW.idempotency_key
      AND command.request_hash = NEW.request_hash
      AND command.actor = NEW.recorded_by
  ) THEN
    RAISE EXCEPTION 'Disposition evidence requires a matching idempotent command record'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_return_case_disposition_header(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.validate_return_case_disposition_header() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  persisted_inspection_status varchar(24);
  persisted_inspection_completed_at timestamptz;
  persisted_receipt_received_at timestamp without time zone;
BEGIN
  SELECT wms_return.received_at
  INTO persisted_receipt_received_at
  FROM returns.return_cases return_case
  JOIN wms.returns wms_return
    ON wms_return.id = return_case.wms_return_id
  WHERE return_case.id = NEW.return_case_id
  FOR KEY SHARE OF return_case, wms_return;

  IF NOT FOUND OR persisted_receipt_received_at IS NULL THEN
    RAISE EXCEPTION 'Disposition requires persisted return receipt evidence'
      USING ERRCODE = '23514';
  END IF;

  -- Legacy WMS receipt timestamps are stored as UTC wall-clock values without
  -- timezone metadata. Interpret them explicitly instead of using session TZ.
  IF NEW.recorded_at
       < (persisted_receipt_received_at AT TIME ZONE 'UTC') THEN
    RAISE EXCEPTION 'Disposition evidence cannot predate its return receipt evidence'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.inspection_resolution = 'not_required' THEN
    SELECT return_case.inspection_status
    INTO persisted_inspection_status
    FROM returns.return_cases return_case
    WHERE return_case.id = NEW.return_case_id
    FOR KEY SHARE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Return Case % does not exist', NEW.return_case_id
        USING ERRCODE = '23503';
    END IF;

    IF persisted_inspection_status <> 'not_required' THEN
      RAISE EXCEPTION
        'Disposition without inspection evidence requires a persisted not_required inspection state'
        USING ERRCODE = '23514';
    END IF;
  ELSE
    SELECT inspection.status, inspection.completed_at
    INTO persisted_inspection_status, persisted_inspection_completed_at
    FROM returns.return_case_inspections inspection
    WHERE inspection.id = NEW.inspection_id
      AND inspection.return_case_id = NEW.return_case_id
      AND inspection.completed_at IS NOT NULL
      AND inspection.completed_by IS NOT NULL
      AND btrim(inspection.completed_by) <> ''
    FOR KEY SHARE;

    IF NOT FOUND OR persisted_inspection_status <> NEW.inspection_resolution THEN
      RAISE EXCEPTION
        'Disposition requires matching terminal inspection evidence for the same Return Case'
        USING ERRCODE = '23514';
    END IF;

    IF NEW.recorded_at < persisted_inspection_completed_at THEN
      RAISE EXCEPTION
        'Disposition evidence cannot predate its terminal inspection evidence'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_return_case_disposition_item(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.validate_return_case_disposition_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  received_quantity integer;
  already_recorded_quantity bigint;
BEGIN
  IF EXISTS (
    SELECT 1
    FROM returns.return_case_dispositions disposition
    JOIN returns.return_case_commands command
      ON command.return_case_id = disposition.return_case_id
     AND command.command_type = 'record_disposition'
     AND command.idempotency_key = disposition.idempotency_key
     AND command.request_hash = disposition.request_hash
     AND command.actor = disposition.recorded_by
    WHERE disposition.id = NEW.disposition_id
  ) THEN
    RAISE EXCEPTION
      'Disposition items cannot be appended after immutable command evidence is finalized'
      USING ERRCODE = '23514';
  END IF;

  SELECT wms_item.received_qty
  INTO received_quantity
  FROM returns.return_case_dispositions disposition
  JOIN returns.return_case_items case_item
    ON case_item.id = NEW.return_case_item_id
   AND case_item.return_case_id = disposition.return_case_id
  JOIN wms.return_items wms_item
    ON wms_item.id = case_item.wms_return_item_id
  WHERE disposition.id = NEW.disposition_id
  FOR UPDATE OF wms_item;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'Disposition item must belong to the same Return Case as its disposition header'
      USING ERRCODE = '23503';
  END IF;

  SELECT COALESCE(sum(item.quantity), 0)
  INTO already_recorded_quantity
  FROM returns.return_case_disposition_items item
  WHERE item.return_case_item_id = NEW.return_case_item_id;

  IF already_recorded_quantity + NEW.quantity > received_quantity THEN
    RAISE EXCEPTION
      'Cumulative disposition quantity exceeds the received quantity for Return Case item %',
      NEW.return_case_item_id
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_return_case_financial_command(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.validate_return_case_financial_command() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.command_type = 'issue_customer_refund'
     AND NOT EXISTS (
       SELECT 1
       FROM returns.return_case_customer_refunds refund
       WHERE refund.return_case_id = NEW.return_case_id
         AND refund.status = 'completed'
         AND refund.idempotency_key = NEW.idempotency_key
         AND refund.request_hash = NEW.request_hash
         AND refund.requested_by = NEW.actor
         AND (NEW.response->>'caseId')::bigint = refund.return_case_id
         AND (NEW.response->>'customerRefundId')::bigint = refund.id
         AND NEW.response->>'provider' = refund.provider
         AND NEW.response->>'providerRefundId' = refund.provider_refund_id
         AND NEW.response->>'currency' = refund.currency
         AND (NEW.response->>'amountCents')::bigint = refund.amount_cents
     ) THEN
    RAISE EXCEPTION 'Customer refund command requires matching completed refund evidence'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.command_type = 'settle_vendor_account'
     AND NOT EXISTS (
       SELECT 1
       FROM returns.return_case_vendor_settlements settlement
       WHERE settlement.return_case_id = NEW.return_case_id
         AND settlement.idempotency_key = NEW.idempotency_key
         AND settlement.request_hash = NEW.request_hash
         AND settlement.recorded_by = NEW.actor
         AND (NEW.response->>'caseId')::bigint = settlement.return_case_id
         AND (NEW.response->>'vendorSettlementId')::bigint = settlement.id
         AND (NEW.response->>'vendorId')::integer = settlement.vendor_id
         AND NEW.response->>'currency' = settlement.currency
         AND (NEW.response->>'grossCreditCents')::bigint = settlement.gross_credit_cents
         AND (NEW.response->>'totalFeeCents')::bigint = settlement.total_fee_cents
         AND (NEW.response->>'netSettlementCents')::bigint = settlement.net_settlement_cents
     ) THEN
    RAISE EXCEPTION 'Vendor settlement command requires matching immutable settlement evidence'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_return_case_inventory_treatment_command(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.validate_return_case_inventory_treatment_command() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.command_type = 'apply_inventory_treatment'
     AND NOT EXISTS (
       SELECT 1
       FROM returns.return_case_inventory_treatments treatment
       WHERE treatment.return_case_id = NEW.return_case_id
         AND treatment.idempotency_key = NEW.idempotency_key
         AND treatment.request_hash = NEW.request_hash
         AND treatment.applied_by = NEW.actor
     ) THEN
    RAISE EXCEPTION 'Inventory treatment command requires matching immutable evidence'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_return_case_inventory_treatment_evidence(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.validate_return_case_inventory_treatment_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM returns.return_case_inventory_treatment_items item
    WHERE item.inventory_treatment_id = NEW.id
  ) THEN
    RAISE EXCEPTION 'An inventory treatment requires at least one item'
      USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM returns.return_case_commands command
    WHERE command.return_case_id = NEW.return_case_id
