      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_return_case_inventory_treatment_item(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.validate_return_case_inventory_treatment_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  source_case_id bigint;
  source_return_case_item_id bigint;
  source_treatment varchar(32);
  source_quantity integer;
  source_recorded_at timestamptz;
  treatment_applied_at timestamptz;
  ledger_variant_delta integer;
  ledger_location_id integer;
  ledger_reference_type varchar(30);
  ledger_reference_id varchar(100);
  ledger_inventory_lot_id integer;
  ledger_source_state varchar(20);
  ledger_target_state varchar(20);
  lot_variant_id integer;
  lot_location_id integer;
  lot_qty_on_hand integer;
  lot_qty_received integer;
  lot_qty_consumed integer;
  lot_status varchar(20);
  source_variant_id integer;
BEGIN
  SELECT
    disposition.return_case_id,
    source_item.return_case_item_id,
    source_item.treatment,
    source_item.quantity,
    disposition.recorded_at
  INTO
    source_case_id,
    source_return_case_item_id,
    source_treatment,
    source_quantity,
    source_recorded_at
  FROM returns.return_case_disposition_items source_item
  JOIN returns.return_case_dispositions disposition
    ON disposition.id = source_item.disposition_id
  JOIN returns.return_case_items case_item
    ON case_item.id = source_item.return_case_item_id
  WHERE source_item.id = NEW.disposition_item_id
  FOR KEY SHARE OF source_item, disposition, case_item;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inventory treatment requires an existing disposition item'
      USING ERRCODE = '23503';
  END IF;

  SELECT treatment_header.applied_at
  INTO treatment_applied_at
  FROM returns.return_case_inventory_treatments treatment_header
  WHERE treatment_header.id = NEW.inventory_treatment_id
    AND treatment_header.return_case_id = source_case_id
  FOR KEY SHARE;

  IF NOT FOUND
     OR NEW.return_case_item_id <> source_return_case_item_id
     OR NEW.treatment <> source_treatment
     OR NEW.quantity <> source_quantity THEN
    RAISE EXCEPTION 'Inventory treatment must exactly match its immutable disposition source'
      USING ERRCODE = '23514';
  END IF;

  IF treatment_applied_at < source_recorded_at THEN
    RAISE EXCEPTION 'Inventory treatment cannot predate its immutable disposition source'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.treatment = 'restock_sellable' THEN
    SELECT oms_line.product_variant_id
    INTO source_variant_id
    FROM returns.return_case_items case_item
    JOIN oms.oms_order_lines oms_line
      ON oms_line.id = case_item.oms_order_line_id
    WHERE case_item.id = source_return_case_item_id
    FOR KEY SHARE OF case_item, oms_line;

    IF source_variant_id IS NULL THEN
      RAISE EXCEPTION 'Sellable restock requires a canonical product variant'
        USING ERRCODE = '23514';
    END IF;

    SELECT
      transaction.variant_qty_delta,
      transaction.to_location_id,
      transaction.reference_type,
      transaction.reference_id,
      transaction.inventory_lot_id,
      transaction.source_state,
      transaction.target_state
    INTO
      ledger_variant_delta,
      ledger_location_id,
      ledger_reference_type,
      ledger_reference_id,
      ledger_inventory_lot_id,
      ledger_source_state,
      ledger_target_state
    FROM inventory.inventory_transactions transaction
    WHERE transaction.id = NEW.inventory_transaction_id
      AND transaction.product_variant_id = source_variant_id
      AND transaction.transaction_type = 'return'
      AND transaction.voided_at IS NULL
    FOR KEY SHARE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Sellable inventory transaction evidence is missing'
        USING ERRCODE = '23514';
    END IF;

    SELECT
      lot.product_variant_id,
      lot.warehouse_location_id,
      lot.qty_on_hand,
      lot.qty_received,
      lot.qty_consumed,
      lot.status
    INTO
      lot_variant_id,
      lot_location_id,
      lot_qty_on_hand,
      lot_qty_received,
      lot_qty_consumed,
      lot_status
    FROM inventory.inventory_lots lot
    WHERE lot.id = NEW.inventory_lot_id
    FOR KEY SHARE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Sellable inventory lot evidence is missing'
        USING ERRCODE = '23514';
    END IF;

    IF ledger_variant_delta IS DISTINCT FROM NEW.quantity
       OR ledger_location_id IS DISTINCT FROM NEW.warehouse_location_id
       OR ledger_reference_type IS DISTINCT FROM 'return_inventory_treatment'
       OR ledger_reference_id IS DISTINCT FROM NEW.disposition_item_id::text
       OR ledger_inventory_lot_id IS DISTINCT FROM NEW.inventory_lot_id
       OR ledger_source_state IS DISTINCT FROM 'customer_return'
       OR ledger_target_state IS DISTINCT FROM 'on_hand'
       OR lot_variant_id IS DISTINCT FROM source_variant_id
       OR lot_location_id IS DISTINCT FROM NEW.warehouse_location_id
       OR lot_qty_on_hand IS DISTINCT FROM NEW.quantity
       OR lot_qty_received IS DISTINCT FROM NEW.quantity
       OR lot_qty_consumed IS DISTINCT FROM 0
       OR lot_status IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'Sellable inventory evidence does not match its disposition source'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_vendor_settlement_command_evidence(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.validate_vendor_settlement_command_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM returns.return_case_commands command
    WHERE command.return_case_id = NEW.return_case_id
      AND command.command_type = 'settle_vendor_account'
      AND command.idempotency_key = NEW.idempotency_key
      AND command.request_hash = NEW.request_hash
      AND command.actor = NEW.recorded_by
      AND (command.response->>'caseId')::bigint = NEW.return_case_id
      AND (command.response->>'vendorSettlementId')::bigint = NEW.id
      AND (command.response->>'vendorId')::integer = NEW.vendor_id
      AND command.response->>'currency' = NEW.currency
      AND (command.response->>'grossCreditCents')::bigint = NEW.gross_credit_cents
      AND (command.response->>'totalFeeCents')::bigint = NEW.total_fee_cents
      AND (command.response->>'netSettlementCents')::bigint = NEW.net_settlement_cents
  ) THEN
    RAISE EXCEPTION 'Vendor settlement requires matching immutable command evidence'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_vendor_settlement_ledger_evidence(); Type: FUNCTION; Schema: returns; Owner: -
--

CREATE FUNCTION returns.validate_vendor_settlement_ledger_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_settlement_id bigint := COALESCE(
    (to_jsonb(NEW)->>'vendor_settlement_id')::bigint,
    (to_jsonb(NEW)->>'id')::bigint
  );
  settlement returns.return_case_vendor_settlements%ROWTYPE;
  credit_count integer;
  fee_count integer;
BEGIN
  SELECT * INTO settlement
  FROM returns.return_case_vendor_settlements
  WHERE id = target_settlement_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  SELECT COUNT(*) FILTER (WHERE entry_role = 'credit'),
         COUNT(*) FILTER (WHERE entry_role = 'fee')
    INTO credit_count, fee_count
  FROM returns.return_case_vendor_settlement_ledger_entries
  WHERE vendor_settlement_id = target_settlement_id;

  IF credit_count <> (CASE WHEN settlement.gross_credit_cents > 0 THEN 1 ELSE 0 END)
     OR fee_count <> (CASE WHEN settlement.total_fee_cents > 0 THEN 1 ELSE 0 END) THEN
    RAISE EXCEPTION 'Vendor settlement % wallet evidence is incomplete', target_settlement_id
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: box_available_at(integer, integer, boolean); Type: FUNCTION; Schema: shipping; Owner: -
--

CREATE FUNCTION shipping.box_available_at(p_box integer, p_warehouse integer, p_reviewed boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(
    (SELECT a.available FROM shipping.warehouse_packaging_availability a
      WHERE a.box_id=p_box AND a.warehouse_id=p_warehouse),
    (SELECT CASE WHEN p_reviewed THEN b.availability_reviewed AND EXISTS(
       SELECT 1 FROM shipping.box_warehouse_stock s WHERE s.box_id=b.id AND s.warehouse_id=p_warehouse AND s.is_stocked)
     ELSE (NOT b.availability_reviewed AND NOT EXISTS(SELECT 1 FROM shipping.box_warehouse_stock s WHERE s.box_id=b.id))
       OR EXISTS(SELECT 1 FROM shipping.box_warehouse_stock s WHERE s.box_id=b.id AND s.warehouse_id=p_warehouse AND s.is_stocked)
     END FROM shipping.box_catalog b WHERE b.id=p_box), false)
$$;


--
-- Name: check_fulfillment_routing_method_coherence(); Type: FUNCTION; Schema: shipping; Owner: -
--

CREATE FUNCTION shipping.check_fulfillment_routing_method_coherence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  checked_service_level_id INTEGER;
  revision_snapshot JSONB;
  current_snapshot JSONB;
  current_snapshot_without_capabilities JSONB;
  legacy_current_snapshot JSONB;
  snapshot_has_connection_identity BOOLEAN;
  snapshot_has_capabilities BOOLEAN;
BEGIN
  IF TG_OP = 'DELETE' THEN
    checked_service_level_id := OLD.service_level_id;
  ELSE
    checked_service_level_id := NEW.service_level_id;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM shipping.service_level_methods AS method
    LEFT JOIN shipping.fulfillment_routing_profiles AS profile
      ON profile.service_level_id = method.service_level_id
    WHERE method.service_level_id = checked_service_level_id
      AND method.provider_connection_id IS NOT NULL
      AND (
        profile.current_revision_id IS NULL
        OR method.revision_id IS DISTINCT FROM profile.current_revision_id
      )
  ) THEN
    RAISE EXCEPTION 'scoped fulfillment methods must belong to the profile current revision';
  END IF;

  SELECT revision.methods_snapshot,
         COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'providerConnectionId', method.provider_connection_id,
               'providerConnectionName', connection.name,
               'provider', method.provider,
               'providerAccountId', method.provider_account_id,
               'providerAccountName', method.provider_account_name,
               'carrierCode', method.carrier,
               'carrierName', method.carrier_name,
               'serviceCode', method.service_code,
               'serviceName', method.service_name,
               'domestic', method.domestic,
               'international', method.international,
               'capabilities', method.provider_capabilities,
               'priority', method.priority
             ) ORDER BY method.priority
           ) FILTER (WHERE method.id IS NOT NULL),
           '[]'::jsonb
         ),
         COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'providerConnectionId', method.provider_connection_id,
               'providerConnectionName', connection.name,
               'provider', method.provider,
               'providerAccountId', method.provider_account_id,
               'providerAccountName', method.provider_account_name,
               'carrierCode', method.carrier,
               'carrierName', method.carrier_name,
               'serviceCode', method.service_code,
               'serviceName', method.service_name,
               'domestic', method.domestic,
               'international', method.international,
               'priority', method.priority
             ) ORDER BY method.priority
           ) FILTER (WHERE method.id IS NOT NULL),
           '[]'::jsonb
         ),
         COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'provider', method.provider,
               'providerAccountId', method.provider_account_id,
               'providerAccountName', method.provider_account_name,
               'carrierCode', method.carrier,
               'carrierName', method.carrier_name,
               'serviceCode', method.service_code,
               'serviceName', method.service_name,
               'domestic', method.domestic,
               'international', method.international,
               'priority', method.priority
             ) ORDER BY method.priority
           ) FILTER (WHERE method.id IS NOT NULL),
           '[]'::jsonb
         )
  INTO revision_snapshot,
       current_snapshot,
       current_snapshot_without_capabilities,
       legacy_current_snapshot
  FROM shipping.fulfillment_routing_profiles AS profile
  JOIN shipping.fulfillment_routing_revisions AS revision
    ON revision.id = profile.current_revision_id
   AND revision.service_level_id = profile.service_level_id
   AND revision.revision = profile.revision
  LEFT JOIN shipping.service_level_methods AS method
    ON method.service_level_id = profile.service_level_id
   AND method.provider_connection_id IS NOT NULL
   AND method.is_active = TRUE
  LEFT JOIN shipping.fulfillment_provider_connections AS connection
    ON connection.id = method.provider_connection_id
  WHERE profile.service_level_id = checked_service_level_id
  GROUP BY revision.methods_snapshot;

  snapshot_has_connection_identity := COALESCE(
    jsonb_array_length(revision_snapshot) > 0
    AND (revision_snapshot -> 0) ? 'providerConnectionId',
    FALSE
  );
  snapshot_has_capabilities := COALESCE(
    jsonb_array_length(revision_snapshot) > 0
    AND (revision_snapshot -> 0) ? 'capabilities',
    FALSE
  );
  IF revision_snapshot IS NOT NULL
     AND revision_snapshot IS DISTINCT FROM (
       CASE
         WHEN snapshot_has_connection_identity AND snapshot_has_capabilities
           THEN current_snapshot
         WHEN snapshot_has_connection_identity
           THEN current_snapshot_without_capabilities
         ELSE legacy_current_snapshot
       END
     ) THEN
    RAISE EXCEPTION 'current fulfillment methods must match the immutable revision snapshot';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: guard_active_packaging_suite(); Type: FUNCTION; Schema: shipping; Owner: -
--

CREATE FUNCTION shipping.guard_active_packaging_suite() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.is_active THEN
    PERFORM 1 FROM shipping.box_suites WHERE id=NEW.suite_id AND NOT archived FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'SHIPPING_SUITE_ARCHIVED'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_fulfillment_method_capabilities_write(); Type: FUNCTION; Schema: shipping; Owner: -
--

CREATE FUNCTION shipping.guard_fulfillment_method_capabilities_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.provider = 'legacy_unscoped' THEN
    RETURN NEW;
  END IF;

  -- A historical scoped row may remain capability-unknown while it is left
  -- unchanged or deactivated. It cannot be repurposed or reactivated to bypass
  -- the capability requirement. A capability backfill is allowed by this same
  -- path as long as the route identity and immutable descriptor stay unchanged.
  IF TG_OP = 'UPDATE'
     AND OLD.provider <> 'legacy_unscoped'
     AND OLD.provider_capabilities IS NULL THEN
    IF ROW(
         NEW.id,
         NEW.service_level_id,
         NEW.provider_connection_id,
         NEW.provider,
         NEW.provider_account_id,
         NEW.provider_account_name,
         NEW.carrier,
         NEW.carrier_name,
         NEW.service_code,
         NEW.service_name,
         NEW.priority,
         NEW.domestic,
         NEW.international,
         NEW.revision_id,
         NEW.created_at
       ) IS NOT DISTINCT FROM ROW(
         OLD.id,
         OLD.service_level_id,
         OLD.provider_connection_id,
         OLD.provider,
         OLD.provider_account_id,
         OLD.provider_account_name,
         OLD.carrier,
         OLD.carrier_name,
         OLD.service_code,
         OLD.service_name,
         OLD.priority,
         OLD.domestic,
         OLD.international,
         OLD.revision_id,
         OLD.created_at
       )
       AND (OLD.is_active OR NOT NEW.is_active) THEN
      RETURN NEW;
    END IF;

    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'historical fulfillment method without provider capabilities cannot be repurposed or reactivated',
      SCHEMA = TG_TABLE_SCHEMA,
      TABLE = TG_TABLE_NAME,
      CONSTRAINT = 'shipping_level_method_scoped_capabilities_chk';
  END IF;

  IF NEW.provider_capabilities IS NOT NULL THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION USING
    ERRCODE = '23514',
    MESSAGE = 'scoped fulfillment methods require provider capabilities',
    SCHEMA = TG_TABLE_SCHEMA,
    TABLE = TG_TABLE_NAME,
    CONSTRAINT = 'shipping_level_method_scoped_capabilities_chk';
END;
$$;


--
-- Name: guard_fulfillment_provider_connection_event_write(); Type: FUNCTION; Schema: shipping; Owner: -
--

CREATE FUNCTION shipping.guard_fulfillment_provider_connection_event_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'shipping.fulfillment_provider_connection_events is append-only';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_fulfillment_provider_connection_write(); Type: FUNCTION; Schema: shipping; Owner: -
--

CREATE FUNCTION shipping.guard_fulfillment_provider_connection_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'shipping.fulfillment_provider_connections cannot be deleted';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.revision <> 1 THEN
    RAISE EXCEPTION 'a fulfillment provider connection must start at revision 1';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.id IS DISTINCT FROM OLD.id
    OR NEW.provider IS DISTINCT FROM OLD.provider
    OR NEW.name IS DISTINCT FROM OLD.name
    OR NEW.credential_source IS DISTINCT FROM OLD.credential_source
    OR NEW.credential_ref IS DISTINCT FROM OLD.credential_ref
    OR NEW.system_managed IS DISTINCT FROM OLD.system_managed
    OR NEW.created_by IS DISTINCT FROM OLD.created_by
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR NEW.revision <> OLD.revision + 1
  ) THEN
    RAISE EXCEPTION 'fulfillment provider connection identity is immutable and revision must increment by 1';
  END IF;
  IF TG_OP = 'UPDATE'
     AND NEW.status = 'disabled'
     AND OLD.status <> 'disabled'
     AND EXISTS (
       SELECT 1
       FROM shipping.service_level_methods AS method
       WHERE method.provider_connection_id = OLD.id
         AND method.is_active = TRUE
     ) THEN
    RAISE EXCEPTION 'a fulfillment provider connection used by active routes cannot be disabled';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_fulfillment_provider_credential_write(); Type: FUNCTION; Schema: shipping; Owner: -
--

CREATE FUNCTION shipping.guard_fulfillment_provider_credential_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  source_kind TEXT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'shipping.fulfillment_provider_credentials cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.connection_id IS DISTINCT FROM OLD.connection_id
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
  ) THEN
    RAISE EXCEPTION 'fulfillment provider credential identity is immutable';
  END IF;
  SELECT connection.credential_source
  INTO source_kind
  FROM shipping.fulfillment_provider_connections AS connection
  WHERE connection.id = NEW.connection_id;
  IF source_kind IS DISTINCT FROM 'vault' THEN
    RAISE EXCEPTION 'stored fulfillment credentials require a vault-backed connection';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_fulfillment_routing_profile_write(); Type: FUNCTION; Schema: shipping; Owner: -
--

CREATE FUNCTION shipping.guard_fulfillment_routing_profile_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'shipping.fulfillment_routing_profiles cannot be deleted';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.revision <> 0 THEN
    RAISE EXCEPTION 'a new fulfillment routing profile must start at revision 0';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.service_level_id IS DISTINCT FROM OLD.service_level_id
    OR NEW.revision <> OLD.revision + 1
  ) THEN
    RAISE EXCEPTION 'fulfillment routing profile identity is immutable and revision must increment by 1';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_fulfillment_routing_revision_write(); Type: FUNCTION; Schema: shipping; Owner: -
--

CREATE FUNCTION shipping.guard_fulfillment_routing_revision_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  previous_revision INTEGER;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.revision = 1 THEN
      RETURN NEW;
    END IF;
    SELECT revision
    INTO previous_revision
    FROM shipping.fulfillment_routing_revisions
    WHERE id = NEW.supersedes_revision_id
      AND service_level_id = NEW.service_level_id;
    IF previous_revision IS DISTINCT FROM NEW.revision - 1 THEN
      RAISE EXCEPTION 'fulfillment routing revision must supersede the immediately preceding revision';
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'shipping.fulfillment_routing_revisions is append-only';
END;
$$;


--
-- Name: guard_suite_archive(); Type: FUNCTION; Schema: shipping; Owner: -
--

CREATE FUNCTION shipping.guard_suite_archive() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.archived AND EXISTS (SELECT 1 FROM shipping.packaging_assignments WHERE suite_id=NEW.id AND is_active)
    THEN RAISE EXCEPTION 'SHIPPING_SUITE_IN_USE'; END IF;
  RETURN NEW;
END $$;


--
-- Name: protect_charge_revision(); Type: FUNCTION; Schema: shipping; Owner: -
--

CREATE FUNCTION shipping.protect_charge_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'SHIPPING_CHARGE_HISTORY_IMMUTABLE'; END IF;
  IF NEW.rate_book_id IS DISTINCT FROM OLD.rate_book_id OR NEW.revision IS DISTINCT FROM OLD.revision
    OR NEW.charges IS DISTINCT FROM OLD.charges OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
    OR NEW.actor_id IS DISTINCT FROM OLD.actor_id OR NEW.effective_to IS NULL
    OR NEW.effective_to <= OLD.effective_from
    OR (OLD.effective_to IS NOT NULL AND NEW.effective_to >= OLD.effective_to) THEN
    RAISE EXCEPTION 'SHIPPING_CHARGE_HISTORY_IMMUTABLE';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: reject_configuration_history_change(); Type: FUNCTION; Schema: shipping; Owner: -
--

CREATE FUNCTION shipping.reject_configuration_history_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN RAISE EXCEPTION 'SHIPPING_CONFIGURATION_HISTORY_IMMUTABLE'; END $$;


--
-- Name: reject_shipment_fact_change(); Type: FUNCTION; Schema: shipping; Owner: -
--

CREATE FUNCTION shipping.reject_shipment_fact_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  RAISE EXCEPTION 'shipment facts are add-only: % on %.% is not allowed', TG_OP, TG_TABLE_SCHEMA, TG_TABLE_NAME
    USING ERRCODE = 'restrict_violation';
END;
$$;


--
-- Name: validate_channel_packaging(); Type: FUNCTION; Schema: shipping; Owner: -
--

CREATE FUNCTION shipping.validate_channel_packaging() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('shipping-shared-config'));
  IF EXISTS (
    SELECT 1 FROM shipping.channel_packaging_policies p
    JOIN LATERAL (SELECT p.default_suite_id AS suite_id UNION SELECT o.suite_id
      FROM shipping.channel_packaging_overrides o WHERE o.channel_id=p.channel_id) a ON true
    JOIN shipping.box_suites s ON s.id=a.suite_id
    WHERE s.archived OR (p.requirement='unbranded' AND EXISTS (
      SELECT 1 FROM shipping.box_suite_members m JOIN shipping.box_catalog b ON b.id=m.box_id
      WHERE m.suite_id=s.id AND m.revision=s.current_revision AND b.branding<>'unbranded'))
  ) THEN RAISE EXCEPTION 'SHIPPING_PACKAGING_POLICY_CONFLICT' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END $$;


--
-- Name: assert_fulfillment_node_binding_coherence(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.assert_fulfillment_node_binding_coherence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  affected_node_id integer;
  row_data jsonb;
BEGIN
  row_data := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
  affected_node_id := CASE
    WHEN TG_TABLE_NAME = 'fulfillment_nodes' THEN NULLIF(row_data ->> 'id', '')::integer
    ELSE NULLIF(row_data ->> 'fulfillment_node_id', '')::integer
  END;

  IF EXISTS (
    SELECT 1
    FROM warehouse.fulfillment_nodes AS node
    JOIN warehouse.fulfillment_node_provider_bindings AS binding
      ON binding.fulfillment_node_id = node.id
    WHERE node.id = affected_node_id
      AND node.lifecycle_status = 'retired'
      AND binding.lifecycle_status = 'active'
  ) THEN
    RAISE EXCEPTION 'retired fulfillment node % retains active provider bindings', affected_node_id;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: guard_fulfillment_identity_write(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.guard_fulfillment_identity_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  account_status varchar(20);
  location_status varchar(20);
  node_status varchar(20);
  lock_id integer;
  old_row jsonb := '{}'::jsonb;
  new_row jsonb := '{}'::jsonb;
  old_id integer;
  new_id integer;
  old_provider_account_id integer;
  new_provider_account_id integer;
  old_provider_location_id integer;
  new_provider_location_id integer;
  old_fulfillment_node_id integer;
  new_fulfillment_node_id integer;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    old_row := to_jsonb(OLD);
  END IF;
  IF TG_OP <> 'DELETE' THEN
    new_row := to_jsonb(NEW);
  END IF;

  old_id := NULLIF(old_row ->> 'id', '')::integer;
  new_id := NULLIF(new_row ->> 'id', '')::integer;
  old_provider_account_id := NULLIF(old_row ->> 'provider_account_id', '')::integer;
  new_provider_account_id := NULLIF(new_row ->> 'provider_account_id', '')::integer;
  old_provider_location_id := NULLIF(old_row ->> 'provider_location_id', '')::integer;
  new_provider_location_id := NULLIF(new_row ->> 'provider_location_id', '')::integer;
  old_fulfillment_node_id := NULLIF(old_row ->> 'fulfillment_node_id', '')::integer;
  new_fulfillment_node_id := NULLIF(new_row ->> 'fulfillment_node_id', '')::integer;

  -- Every lifecycle writer acquires the same hierarchy. Draft identity edits
  -- lock both the old and new parents so activation cannot race a re-parent.
  -- Families: provider account -> provider location -> fulfillment node.
  FOR lock_id IN
    SELECT DISTINCT candidate
    FROM unnest(CASE TG_TABLE_NAME
      WHEN 'fulfillment_provider_accounts' THEN ARRAY[
        CASE WHEN TG_OP = 'INSERT' THEN new_id ELSE old_id END,
        CASE WHEN TG_OP = 'UPDATE' THEN new_id END
      ]
      WHEN 'fulfillment_provider_locations' THEN ARRAY[
        CASE WHEN TG_OP = 'INSERT' THEN new_provider_account_id ELSE old_provider_account_id END,
        CASE WHEN TG_OP = 'UPDATE' THEN new_provider_account_id END
      ]
      WHEN 'fulfillment_nodes' THEN ARRAY[
        CASE WHEN TG_OP = 'INSERT' THEN new_provider_account_id ELSE old_provider_account_id END,
        CASE WHEN TG_OP = 'UPDATE' THEN new_provider_account_id END
      ]
      WHEN 'fulfillment_node_provider_bindings' THEN ARRAY[
        CASE WHEN TG_OP = 'INSERT' THEN new_provider_account_id ELSE old_provider_account_id END,
        CASE WHEN TG_OP = 'UPDATE' THEN new_provider_account_id END
      ]
    END) AS candidate
    WHERE candidate IS NOT NULL
    ORDER BY candidate
  LOOP
    PERFORM pg_advisory_xact_lock(918411, lock_id);
  END LOOP;

  IF TG_TABLE_NAME IN (
    'fulfillment_provider_locations', 'fulfillment_nodes', 'fulfillment_node_provider_bindings'
  ) THEN
    FOR lock_id IN
      SELECT DISTINCT candidate
      FROM unnest(CASE TG_TABLE_NAME
        WHEN 'fulfillment_provider_locations' THEN ARRAY[
          CASE WHEN TG_OP = 'INSERT' THEN new_id ELSE old_id END,
          CASE WHEN TG_OP = 'UPDATE' THEN new_id END
        ]
        WHEN 'fulfillment_nodes' THEN ARRAY[
          CASE WHEN TG_OP = 'INSERT' THEN new_provider_location_id ELSE old_provider_location_id END,
          CASE WHEN TG_OP = 'UPDATE' THEN new_provider_location_id END
        ]
        WHEN 'fulfillment_node_provider_bindings' THEN ARRAY[
          CASE WHEN TG_OP = 'INSERT' THEN new_provider_location_id ELSE old_provider_location_id END,
          CASE WHEN TG_OP = 'UPDATE' THEN new_provider_location_id END
        ]
      END) AS candidate
      WHERE candidate IS NOT NULL
      ORDER BY candidate
    LOOP
      PERFORM pg_advisory_xact_lock(918412, lock_id);
    END LOOP;
  END IF;

  IF TG_TABLE_NAME IN ('fulfillment_nodes', 'fulfillment_node_provider_bindings') THEN
    FOR lock_id IN
      SELECT DISTINCT candidate
      FROM unnest(CASE TG_TABLE_NAME
        WHEN 'fulfillment_nodes' THEN ARRAY[
          CASE WHEN TG_OP = 'INSERT' THEN new_id ELSE old_id END,
          CASE WHEN TG_OP = 'UPDATE' THEN new_id END
        ]
        WHEN 'fulfillment_node_provider_bindings' THEN ARRAY[
          CASE WHEN TG_OP = 'INSERT' THEN new_fulfillment_node_id ELSE old_fulfillment_node_id END,
          CASE WHEN TG_OP = 'UPDATE' THEN new_fulfillment_node_id END
        ]
      END) AS candidate
      WHERE candidate IS NOT NULL
      ORDER BY candidate
    LOOP
      PERFORM pg_advisory_xact_lock(918413, lock_id);
    END LOOP;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF new_row ->> 'lifecycle_status' <> 'draft' THEN
      RAISE EXCEPTION '% must be inserted as a draft', TG_TABLE_NAME;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF old_row ->> 'lifecycle_status' = 'draft' THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION '% active or retired identities cannot be deleted', TG_TABLE_NAME;
  END IF;

  IF old_row -> 'id' IS DISTINCT FROM new_row -> 'id'
     OR old_row -> 'created_by' IS DISTINCT FROM new_row -> 'created_by'
     OR old_row -> 'created_at' IS DISTINCT FROM new_row -> 'created_at' THEN
    RAISE EXCEPTION '% durable identity fields are immutable', TG_TABLE_NAME;
  END IF;

  IF old_row ->> 'lifecycle_status' = 'draft'
     AND new_row ->> 'lifecycle_status' = 'draft' THEN
    RETURN NEW;
  END IF;

  IF old_row ->> 'lifecycle_status' = 'draft'
     AND new_row ->> 'lifecycle_status' = 'active' THEN
    IF TG_TABLE_NAME IN ('fulfillment_nodes', 'fulfillment_node_provider_bindings') THEN
      IF (
        new_row - ARRAY['lifecycle_status', 'activated_by', 'activated_at', 'updated_at']
      ) IS DISTINCT FROM (
        old_row - ARRAY['lifecycle_status', 'activated_by', 'activated_at', 'updated_at']
      ) THEN
        RAISE EXCEPTION '% identity cannot change while activating', TG_TABLE_NAME;
      END IF;
    ELSE
      IF (
        new_row - ARRAY['lifecycle_status', 'verified_by', 'verified_at', 'updated_at']
      ) IS DISTINCT FROM (
        old_row - ARRAY['lifecycle_status', 'verified_by', 'verified_at', 'updated_at']
      ) THEN
        RAISE EXCEPTION '% identity cannot change while verifying', TG_TABLE_NAME;
      END IF;
    END IF;

    IF TG_TABLE_NAME = 'fulfillment_provider_locations' THEN
      SELECT lifecycle_status INTO account_status
      FROM warehouse.fulfillment_provider_accounts
      WHERE id = new_provider_account_id
      FOR KEY SHARE;
      IF account_status IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION 'provider location requires an active provider account';
      END IF;
    ELSIF TG_TABLE_NAME = 'fulfillment_node_provider_bindings' THEN
      SELECT lifecycle_status INTO account_status
      FROM warehouse.fulfillment_provider_accounts
      WHERE id = new_provider_account_id
      FOR KEY SHARE;
      SELECT lifecycle_status INTO location_status
      FROM warehouse.fulfillment_provider_locations
      WHERE id = new_provider_location_id
      FOR KEY SHARE;
      SELECT lifecycle_status INTO node_status
      FROM warehouse.fulfillment_nodes
      WHERE id = new_fulfillment_node_id
      FOR KEY SHARE;
      IF account_status IS DISTINCT FROM 'active'
         OR location_status IS DISTINCT FROM 'active'
         OR node_status NOT IN ('draft', 'active') THEN
        RAISE EXCEPTION 'node provider binding requires active provider identity and live node';
      END IF;
    ELSIF TG_TABLE_NAME = 'fulfillment_nodes' THEN
      IF (new_row ->> 'inventory_authority' = 'external_provider'
          OR new_row ->> 'fulfillment_authority' = 'external_provider')
         AND (new_provider_account_id IS NULL OR new_provider_location_id IS NULL) THEN
        RAISE EXCEPTION 'external authority requires one exact provider account and location';
      END IF;
      IF new_row ->> 'inventory_authority' = 'external_provider' AND NOT EXISTS (
        SELECT 1 FROM warehouse.fulfillment_node_provider_bindings
        WHERE fulfillment_node_id = new_id
          AND provider_account_id = new_provider_account_id
          AND provider_location_id = new_provider_location_id
          AND lifecycle_status = 'active' AND capability = 'inventory_observation'
      ) THEN
        RAISE EXCEPTION 'external inventory authority requires an active observation binding';
      END IF;
      IF new_row ->> 'fulfillment_authority' = 'external_provider' AND NOT EXISTS (
        SELECT 1 FROM warehouse.fulfillment_node_provider_bindings
        WHERE fulfillment_node_id = new_id
          AND provider_account_id = new_provider_account_id
          AND provider_location_id = new_provider_location_id
          AND lifecycle_status = 'active' AND capability = 'fulfillment_execution'
      ) THEN
        RAISE EXCEPTION 'external fulfillment authority requires an active execution binding';
      END IF;
      IF (new_row ->> 'inventory_authority' = 'external_provider'
          OR new_row ->> 'fulfillment_authority' = 'external_provider') AND NOT EXISTS (
        SELECT 1 FROM warehouse.fulfillment_node_provider_bindings
        WHERE fulfillment_node_id = new_id
          AND provider_account_id = new_provider_account_id
          AND provider_location_id = new_provider_location_id
          AND lifecycle_status = 'active' AND capability = 'custody_reconciliation'
      ) THEN
        RAISE EXCEPTION 'external authority requires an active custody reconciliation binding';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF old_row ->> 'lifecycle_status' = 'active'
     AND new_row ->> 'lifecycle_status' = 'retired' THEN
    IF (
      new_row - ARRAY['lifecycle_status', 'retired_by', 'retired_at', 'updated_at']
    ) IS DISTINCT FROM (
      old_row - ARRAY['lifecycle_status', 'retired_by', 'retired_at', 'updated_at']
    ) THEN
      RAISE EXCEPTION '% identity cannot change while retiring', TG_TABLE_NAME;
    END IF;

    IF TG_TABLE_NAME = 'fulfillment_provider_accounts' AND EXISTS (
      SELECT 1 FROM warehouse.fulfillment_provider_locations
      WHERE provider_account_id = old_id AND lifecycle_status = 'active'
    ) THEN
      RAISE EXCEPTION 'provider account with active locations cannot be retired';
    ELSIF TG_TABLE_NAME = 'fulfillment_provider_locations' AND EXISTS (
      SELECT 1 FROM warehouse.fulfillment_node_provider_bindings
      WHERE provider_location_id = old_id AND lifecycle_status = 'active'
    ) THEN
      RAISE EXCEPTION 'provider location with active node bindings cannot be retired';
    ELSIF TG_TABLE_NAME = 'fulfillment_node_provider_bindings' AND EXISTS (
      SELECT 1 FROM warehouse.fulfillment_nodes
      WHERE id = old_fulfillment_node_id AND lifecycle_status = 'active'
    ) THEN
      RAISE EXCEPTION 'provider binding cannot retire while its node is active';
    END IF;
    RETURN NEW;
  END IF;

  RAISE EXCEPTION '% lifecycle transition % -> % is not allowed',
    TG_TABLE_NAME, old_row ->> 'lifecycle_status', new_row ->> 'lifecycle_status';
END;
$$;


--
-- Name: guard_used_work_station_location(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.guard_used_work_station_location() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.location_id <> OLD.location_id AND EXISTS (
    SELECT 1 FROM warehouse.work_items WHERE station_id = OLD.id
  ) THEN
    RAISE EXCEPTION 'A station with work history cannot change its physical identity' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_work_item_identity(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.guard_work_item_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RAISE EXCEPTION 'Warehouse work cannot be deleted' USING ERRCODE = '55000';
  END IF;
  IF NEW.id <> OLD.id OR NEW.warehouse_id <> OLD.warehouse_id OR NEW.claim_id <> OLD.claim_id
     OR NEW.claim_operation_id <> OLD.claim_operation_id OR NEW.station_id <> OLD.station_id
     OR NEW.configuration_revision <> OLD.configuration_revision OR NEW.context <> OLD.context THEN
    RAISE EXCEPTION 'Warehouse work routing and owner evidence are immutable' USING ERRCODE = '55000';
  END IF;
  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'Warehouse work requires the next version' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_work_station_location(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.protect_work_station_location() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.warehouse_id IS DISTINCT FROM OLD.warehouse_id AND EXISTS (
    SELECT 1 FROM warehouse.work_stations WHERE location_id = OLD.id
  ) THEN
    RAISE EXCEPTION 'A station location cannot move between warehouses' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: reject_assembly_packing_receipt_mutation(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.reject_assembly_packing_receipt_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Assembly packing handoff receipts are immutable' USING ERRCODE = '55000';
END;
$$;


--
-- Name: reject_work_revision_mutation(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.reject_work_revision_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Warehouse work configuration history is append-only' USING ERRCODE = '55000';
END;
$$;


--
-- Name: validate_work_station_location(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.validate_work_station_location() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE location_warehouse_id integer;
BEGIN
  SELECT warehouse_id INTO location_warehouse_id FROM warehouse.warehouse_locations
    WHERE id = NEW.location_id FOR SHARE;
  IF location_warehouse_id IS DISTINCT FROM NEW.warehouse_id THEN
    RAISE EXCEPTION 'Station location must belong to its warehouse' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW.id <> OLD.id OR NEW.warehouse_id <> OLD.warehouse_id) THEN
    RAISE EXCEPTION 'Station identity cannot move between warehouses' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_oms_wms_authority_item(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.enforce_oms_wms_authority_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  wms_order RECORD;
  oms_line RECORD;
  expected_oms_order_ref TEXT;
  expected_oms_order_id BIGINT;
  active_materialized_quantity INTEGER;
BEGIN
  SELECT
    o.id,
    o.source,
    o.source_table_id,
    o.oms_fulfillment_order_id,
    o.warehouse_status,
    o.cancelled_at,
    o.completed_at
  INTO wms_order
  FROM wms.orders o
  WHERE o.id = NEW.order_id;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  IF COALESCE(wms_order.source, '') NOT IN ('oms', 'shopify', 'ebay')
     OR wms_order.warehouse_status NOT IN ('ready', 'in_progress', 'partially_shipped', 'ready_to_ship')
     OR wms_order.cancelled_at IS NOT NULL
     OR wms_order.completed_at IS NOT NULL
     OR COALESCE(NEW.status, '') IN ('cancelled', 'completed', 'short') THEN
    RETURN NEW;
  END IF;

  IF NEW.oms_order_line_id IS NULL THEN
    RAISE EXCEPTION 'OMS-origin active WMS item % must reference oms_order_line_id', NEW.id
      USING ERRCODE = '23514',
            CONSTRAINT = 'wms_order_items_oms_line_required_authority_chk';
  END IF;

  SELECT
    ol.id,
    ol.order_id,
    ol.authority_fulfillable_quantity
  INTO oms_line
  FROM oms.oms_order_lines ol
  WHERE ol.id = NEW.oms_order_line_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WMS item % references missing OMS order line %', NEW.id, NEW.oms_order_line_id
      USING ERRCODE = '23503',
            CONSTRAINT = 'wms_order_items_oms_order_line_id_fkey';
  END IF;

  expected_oms_order_ref := NULLIF(TRIM(
    CASE
      WHEN wms_order.source = 'shopify' THEN COALESCE(wms_order.source_table_id::text, '')
      ELSE COALESCE(wms_order.oms_fulfillment_order_id::text, '')
    END
  ), '');

  IF expected_oms_order_ref IS NULL OR expected_oms_order_ref !~ '^[0-9]+$' THEN
    RAISE EXCEPTION 'OMS-origin WMS order % has no parseable OMS order reference', NEW.order_id
      USING ERRCODE = '23514',
            CONSTRAINT = 'wms_orders_oms_ref_required_authority_chk';
  END IF;

  expected_oms_order_id := expected_oms_order_ref::BIGINT;

  IF oms_line.order_id <> expected_oms_order_id THEN
    RAISE EXCEPTION 'WMS item % references OMS line % from order %, expected OMS order %',
      NEW.id,
      NEW.oms_order_line_id,
      oms_line.order_id,
      expected_oms_order_id
      USING ERRCODE = '23514',
            CONSTRAINT = 'wms_order_items_oms_line_order_match_chk';
  END IF;

  SELECT COALESCE(SUM(oi.quantity), 0)::int
  INTO active_materialized_quantity
  FROM wms.order_items oi
  JOIN wms.orders o ON o.id = oi.order_id
  WHERE oi.oms_order_line_id = NEW.oms_order_line_id
    AND o.warehouse_status IN ('ready', 'in_progress', 'partially_shipped', 'ready_to_ship')
    AND o.cancelled_at IS NULL
    AND o.completed_at IS NULL
    AND COALESCE(oi.status, '') NOT IN ('cancelled', 'completed', 'short');

  IF active_materialized_quantity > COALESCE(oms_line.authority_fulfillable_quantity, 0) THEN
    RAISE EXCEPTION 'OMS line % over-materialized: active WMS quantity % exceeds authority %',
      NEW.oms_order_line_id,
      active_materialized_quantity,
      oms_line.authority_fulfillable_quantity
      USING ERRCODE = '23514',
            CONSTRAINT = 'wms_order_items_oms_line_authority_qty_chk';
  END IF;

  RETURN NEW;
END $_$;


--
-- Name: enforce_outbound_shipment_item_lineage(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.enforce_outbound_shipment_item_lineage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  shipment_order_id INTEGER;
  authority_order_item_id INTEGER;
  item_order_id INTEGER;
  source_shipment_item RECORD;
  source_candidate_count INTEGER;
  source_inventory_shipped_quantity INTEGER;
  source_item_correction_quantity INTEGER;
BEGIN
  authority_order_item_id := CASE NEW.shipment_item_purpose
    WHEN 'customer_fulfillment' THEN NEW.order_item_id
    WHEN 'replacement' THEN NEW.replacement_for_order_item_id
    ELSE NULL
  END;

  IF NEW.shipment_item_purpose = 'customer_fulfillment'
     AND (
       NEW.order_item_id IS NULL
       OR NEW.replacement_for_order_item_id IS NOT NULL
       OR NEW.correction_for_shipment_item_id IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'Customer fulfillment shipment item % must reference order_item_id only', NEW.id
      USING ERRCODE = '23514',
            CONSTRAINT = 'outbound_shipment_items_purpose_authority_chk';
  ELSIF NEW.shipment_item_purpose = 'replacement'
     AND (
       NEW.order_item_id IS NOT NULL
       OR NEW.replacement_for_order_item_id IS NULL
       OR NEW.correction_for_shipment_item_id IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'Replacement shipment item % must reference replacement_for_order_item_id only', NEW.id
      USING ERRCODE = '23514',
            CONSTRAINT = 'outbound_shipment_items_purpose_authority_chk';
  ELSIF NEW.shipment_item_purpose = 'concession'
     AND (
       NEW.order_item_id IS NOT NULL
       OR NEW.replacement_for_order_item_id IS NOT NULL
       OR NEW.correction_for_shipment_item_id IS NOT NULL
       OR NEW.product_variant_id IS NULL
     ) THEN
    RAISE EXCEPTION 'Concession shipment item % must reference product_variant_id only', NEW.id
      USING ERRCODE = '23514',
            CONSTRAINT = 'outbound_shipment_items_purpose_authority_chk';
  ELSIF NEW.shipment_item_purpose = 'omission_correction'
     AND (
       NEW.order_item_id IS NOT NULL
       OR NEW.replacement_for_order_item_id IS NOT NULL
       OR NEW.correction_for_shipment_item_id IS NULL
       OR NEW.product_variant_id IS NULL
     ) THEN
    RAISE EXCEPTION 'Omission correction shipment item % must reference correction_for_shipment_item_id only', NEW.id
      USING ERRCODE = '23514',
            CONSTRAINT = 'outbound_shipment_items_purpose_authority_chk';
  ELSIF NEW.shipment_item_purpose = 'unclassified'
     AND (
       NEW.order_item_id IS NOT NULL
       OR NEW.replacement_for_order_item_id IS NOT NULL
       OR NEW.correction_for_shipment_item_id IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'Unclassified shipment item % cannot claim order-line authority', NEW.id
      USING ERRCODE = '23514',
            CONSTRAINT = 'outbound_shipment_items_purpose_authority_chk';
  END IF;

  IF COALESCE(NEW.qty, 0) <= 0 THEN
    RAISE EXCEPTION 'Outbound shipment item % qty must be positive', NEW.id
      USING ERRCODE = '23514',
            CONSTRAINT = 'wms_outbound_shipment_items_qty_positive_chk';
  END IF;

  SELECT shipment.order_id
  INTO shipment_order_id
  FROM wms.outbound_shipments shipment
  WHERE shipment.id = NEW.shipment_id;

  IF NEW.shipment_item_purpose = 'omission_correction' THEN
    IF NEW.correction_for_shipment_item_id = NEW.id THEN
      RAISE EXCEPTION 'Omission correction shipment item % cannot correct itself', NEW.id
        USING ERRCODE = '23514',
              CONSTRAINT = 'outbound_shipment_items_purpose_authority_chk';
    END IF;

    SELECT
      source_item.order_item_id,
      source_item.shipment_id,
      source_item.product_variant_id,
      source_item.qty,
      source_item.shipment_item_purpose,
      source_shipment.order_id,
      source_shipment.status
    INTO source_shipment_item
    FROM wms.outbound_shipment_items source_item
    JOIN wms.outbound_shipments source_shipment
      ON source_shipment.id = source_item.shipment_id
    WHERE source_item.id = NEW.correction_for_shipment_item_id
    FOR UPDATE OF source_item;

    IF source_shipment_item.order_item_id IS NULL
       OR source_shipment_item.shipment_item_purpose <> 'customer_fulfillment'
       OR source_shipment_item.product_variant_id IS DISTINCT FROM NEW.product_variant_id
       OR source_shipment_item.order_id IS DISTINCT FROM shipment_order_id
       OR source_shipment_item.status NOT IN ('shipped', 'returned', 'lost') THEN
      RAISE EXCEPTION 'Omission correction shipment item % lacks a terminal customer-fulfillment source line on the same order', NEW.id
        USING ERRCODE = '23514',
              CONSTRAINT = 'outbound_shipment_items_purpose_authority_chk';
    END IF;

    SELECT COUNT(*)::int
    INTO source_candidate_count
    FROM wms.outbound_shipment_items source_candidate
    WHERE source_candidate.shipment_id = source_shipment_item.shipment_id
      AND source_candidate.order_item_id = source_shipment_item.order_item_id
      AND source_candidate.shipment_item_purpose = 'customer_fulfillment'
      AND source_candidate.qty > 0;

    IF source_candidate_count <> 1 THEN
      RAISE EXCEPTION 'Omission correction source shipment item % is ambiguous across % customer-fulfillment lines',
        NEW.correction_for_shipment_item_id,
        source_candidate_count
        USING ERRCODE = '23514',
              CONSTRAINT = 'outbound_shipment_items_omission_source_ambiguity_chk';
    END IF;

    authority_order_item_id := source_shipment_item.order_item_id;

    SELECT COALESCE(SUM(correction_item.qty), 0)::int
    INTO source_item_correction_quantity
    FROM wms.outbound_shipment_items correction_item
    JOIN wms.outbound_shipments correction_shipment
      ON correction_shipment.id = correction_item.shipment_id
    WHERE correction_item.shipment_item_purpose = 'omission_correction'
      AND correction_item.correction_for_shipment_item_id = NEW.correction_for_shipment_item_id
      AND correction_shipment.status NOT IN ('cancelled', 'voided');

    IF source_item_correction_quantity > source_shipment_item.qty THEN
      RAISE EXCEPTION 'Omission correction quantity % exceeds source shipment item % quantity %',
        source_item_correction_quantity,
        NEW.correction_for_shipment_item_id,
        source_shipment_item.qty
        USING ERRCODE = '23514',
              CONSTRAINT = 'outbound_shipment_items_purpose_authority_chk';
    END IF;

    source_inventory_shipped_quantity := inventory.omission_source_posted_quantity(
      source_shipment_item.order_id, source_shipment_item.order_item_id,
      source_shipment_item.shipment_id, NEW.correction_for_shipment_item_id,
      source_shipment_item.product_variant_id, source_shipment_item.qty
    );

    IF source_inventory_shipped_quantity < source_shipment_item.qty THEN
      RAISE EXCEPTION 'Omission correction source shipment item % has only % of % units posted to inventory',
        NEW.correction_for_shipment_item_id,
        source_inventory_shipped_quantity,
        source_shipment_item.qty
        USING ERRCODE = '23514',
              CONSTRAINT = 'outbound_shipment_items_omission_inventory_proof_chk';
    END IF;
  END IF;

  IF authority_order_item_id IS NOT NULL THEN
    SELECT order_item.order_id
    INTO item_order_id
    FROM wms.order_items order_item
    WHERE order_item.id = authority_order_item_id;
  END IF;

  IF shipment_order_id IS NOT NULL
     AND item_order_id IS NOT NULL
     AND shipment_order_id <> item_order_id THEN
    RAISE EXCEPTION 'Shipment item % references order item % from WMS order %, expected %',
      NEW.id,
      authority_order_item_id,
      item_order_id,
      shipment_order_id
      USING ERRCODE = '23514',
            CONSTRAINT = 'wms_outbound_shipment_items_order_match_chk';
  END IF;

  RETURN NEW;
END $$;


--
-- Name: enforce_physical_shipment_item_correction_lineage(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.enforce_physical_shipment_item_correction_lineage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  legacy_source_shipment_item_id INTEGER;
  source_item RECORD;
  correction_quantity INTEGER;
BEGIN
  IF NEW.shipment_item_purpose <> 'omission_correction' THEN
    RETURN NEW;
  END IF;

  IF NEW.correction_for_physical_shipment_item_id = NEW.id THEN
    RAISE EXCEPTION 'Physical omission correction item % cannot correct itself', NEW.id
      USING ERRCODE = '23514',
            CONSTRAINT = 'physical_shipment_items_correction_lineage_chk';
  END IF;

  SELECT legacy_item.correction_for_shipment_item_id
  INTO legacy_source_shipment_item_id
  FROM wms.outbound_shipment_items legacy_item
  WHERE legacy_item.id = NEW.legacy_wms_shipment_item_id
    AND legacy_item.shipment_item_purpose = 'omission_correction';

  IF legacy_source_shipment_item_id IS NULL THEN
    RAISE EXCEPTION 'Physical omission correction item % lacks matching WMS correction authority', NEW.id
      USING ERRCODE = '23514',
            CONSTRAINT = 'physical_shipment_items_correction_lineage_chk';
  END IF;

  SELECT source.id,
         source.physical_shipment_id,
         source.legacy_wms_shipment_item_id,
         source.shipment_item_purpose,
         source.product_variant_id,
         source.sku,
         source.quantity_shipped
  INTO source_item
  FROM wms.physical_shipment_items source
  WHERE source.id = NEW.correction_for_physical_shipment_item_id
  FOR UPDATE;

  IF NOT FOUND
     OR source_item.shipment_item_purpose <> 'customer_fulfillment'
     OR source_item.legacy_wms_shipment_item_id <> legacy_source_shipment_item_id
     OR source_item.physical_shipment_id = NEW.physical_shipment_id
     OR source_item.product_variant_id IS DISTINCT FROM NEW.product_variant_id
     OR UPPER(BTRIM(source_item.sku)) <> UPPER(BTRIM(NEW.sku)) THEN
    RAISE EXCEPTION 'Physical omission correction item % does not match its exact original package line', NEW.id
      USING ERRCODE = '23514',
            CONSTRAINT = 'physical_shipment_items_correction_lineage_chk';
  END IF;

  SELECT COALESCE(SUM(correction.quantity_shipped), 0)::int
  INTO correction_quantity
  FROM wms.physical_shipment_items correction
  WHERE correction.shipment_item_purpose = 'omission_correction'
    AND correction.correction_for_physical_shipment_item_id = NEW.correction_for_physical_shipment_item_id;

  IF correction_quantity > source_item.quantity_shipped THEN
    RAISE EXCEPTION 'Physical omission correction quantity % exceeds original package line % quantity %',
      correction_quantity,
      NEW.correction_for_physical_shipment_item_id,
      source_item.quantity_shipped
      USING ERRCODE = '23514',
            CONSTRAINT = 'physical_shipment_items_correction_quantity_chk';
  END IF;

  RETURN NEW;
END $$;


--
-- Name: guard_declared_package_business_shipment_insert(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.guard_declared_package_business_shipment_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  persisted_event_type VARCHAR(40);
  persisted_label_direction VARCHAR(20);
  persisted_received_at TIMESTAMPTZ;
  persisted_provider_occurred_at TIMESTAMPTZ;
  persisted_is_return_label JSONB;
BEGIN
  SELECT
    event.event_type,
    label.label_direction,
    event.received_at,
    event.provider_occurred_at,
    event.sanitized_payload->'isReturnLabel'
  INTO
    persisted_event_type,
    persisted_label_direction,
    persisted_received_at,
    persisted_provider_occurred_at,
    persisted_is_return_label
  FROM wms.shipping_provider_label_events AS event
  JOIN wms.shipping_provider_labels AS label
    ON label.id = event.shipping_provider_label_id
  WHERE event.id = NEW.recognition_event_id
    AND event.shipping_provider_label_id = NEW.shipping_provider_label_id
  FOR KEY SHARE OF event, label;

  IF persisted_event_type IS NULL THEN
    RAISE EXCEPTION 'declared package business-shipment evidence does not exist'
      USING ERRCODE = '23503';
  END IF;
  IF persisted_event_type <> 'label_observed'
     OR persisted_label_direction <> 'outbound'
     OR persisted_is_return_label IS DISTINCT FROM 'false'::jsonb THEN
    RAISE EXCEPTION 'declared package business shipment requires explicit outbound label evidence'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.business_shipment_recognized_at IS DISTINCT FROM persisted_received_at
     OR NEW.provider_occurred_at IS DISTINCT FROM persisted_provider_occurred_at
     OR NEW.recognition_source <> 'outbound_label_observed' THEN
    RAISE EXCEPTION 'declared package business-shipment fact differs from its evidence'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_package_allocation_effect_outbox_insert(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.guard_package_allocation_effect_outbox_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  persisted_intent_key VARCHAR(500);
  persisted_payload_hash VARCHAR(64);
BEGIN
  SELECT intent.intent_key, intent.payload_hash
    INTO persisted_intent_key, persisted_payload_hash
  FROM wms.package_allocation_effect_intents AS intent
  WHERE intent.id = NEW.package_allocation_effect_intent_id
  FOR KEY SHARE;

  IF persisted_intent_key IS NULL THEN
    RAISE EXCEPTION 'package allocation effect outbox intent does not exist'
      USING ERRCODE = '23503';
  END IF;
  IF NEW.idempotency_key IS DISTINCT FROM persisted_intent_key
     OR NEW.payload_hash IS DISTINCT FROM persisted_payload_hash THEN
    RAISE EXCEPTION 'package allocation effect outbox identity differs from its intent'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_package_allocation_group_projection(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.guard_package_allocation_group_projection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'package allocation groups cannot be deleted'
      USING ERRCODE = '55000';
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.group_key IS DISTINCT FROM OLD.group_key
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'package allocation group identity is immutable'
      USING ERRCODE = '55000';
  END IF;

  IF NEW.current_version <> OLD.current_version + 1 THEN
    RAISE EXCEPTION 'package allocation group current_version must advance by exactly one'
      USING ERRCODE = '40001';
  END IF;

  IF NEW.version_updated_at < OLD.version_updated_at THEN
    RAISE EXCEPTION 'package allocation group version_updated_at cannot move backwards'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_package_allocation_membership_insert(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.guard_package_allocation_membership_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  projected_version INTEGER;
BEGIN
  SELECT current_version
    INTO projected_version
  FROM wms.package_allocation_groups
  WHERE id = NEW.package_allocation_group_id
  FOR UPDATE;

  IF projected_version <> 0 THEN
    RAISE EXCEPTION 'package allocation group membership is sealed after its first plan'
      USING ERRCODE = '55000';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_package_allocation_plan_build(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.guard_package_allocation_plan_build() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  plan_row wms.package_allocation_plans%ROWTYPE;
  projected_version INTEGER;
BEGIN
  IF TG_TABLE_NAME = 'package_allocation_plans' THEN
    plan_row := NEW;
  ELSE
    SELECT *
      INTO plan_row
    FROM wms.package_allocation_plans
    WHERE id = NEW.package_allocation_plan_id;
  END IF;

  SELECT current_version
    INTO projected_version
  FROM wms.package_allocation_groups
  WHERE id = plan_row.package_allocation_group_id
  FOR UPDATE;

  IF projected_version <> plan_row.expected_group_version THEN
    RAISE EXCEPTION 'package allocation plan can only be built against its expected group version'
      USING ERRCODE = '40001';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_picking_command_evidence(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.guard_picking_command_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(NEW.command_key,NEW.order_id,NEW.order_item_id,NEW.request_hash,NEW.request_payload,NEW.before_item,NEW.created_at)
    IS DISTINCT FROM ROW(OLD.command_key,OLD.order_id,OLD.order_item_id,OLD.request_hash,OLD.request_payload,OLD.before_item,OLD.created_at) THEN
    RAISE EXCEPTION 'Picking command intent is immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.physical_receipt IS NOT NULL AND ROW(NEW.physical_receipt,NEW.canonical_request,NEW.committed_at)
    IS DISTINCT FROM ROW(OLD.physical_receipt,OLD.canonical_request,OLD.committed_at) THEN
    RAISE EXCEPTION 'Committed picking evidence is immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.completed_at IS NOT NULL AND ROW(NEW.followup_result,NEW.completed_at)
    IS DISTINCT FROM ROW(OLD.followup_result,OLD.completed_at) THEN
    RAISE EXCEPTION 'Completed picking result is immutable' USING ERRCODE='23514';
  END IF;
  IF NEW.attempt_count < OLD.attempt_count THEN RAISE EXCEPTION 'Picking attempts cannot decrease' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: inherit_order_edit_operation(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.inherit_order_edit_operation() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE source_id bigint; source_channel integer; source_external text; active_operation uuid;
BEGIN
  IF TG_OP='UPDATE' AND OLD.order_edit_operation_id IS NOT NULL
    AND (NEW.source,NEW.oms_fulfillment_order_id,NEW.source_table_id,NEW.channel_id,NEW.external_order_id)
      IS DISTINCT FROM (OLD.source,OLD.oms_fulfillment_order_id,OLD.source_table_id,OLD.channel_id,OLD.external_order_id) THEN
    RAISE EXCEPTION 'Held order identity cannot change during an order edit' USING ERRCODE='23514';
  END IF;
  source_id := CASE
    WHEN NEW.source='oms' AND NEW.oms_fulfillment_order_id ~ '^[0-9]+$' AND length(NEW.oms_fulfillment_order_id)<=18
      THEN NEW.oms_fulfillment_order_id::bigint
    WHEN NEW.source_table_id ~ '^[0-9]+$' AND length(NEW.source_table_id)<=18 THEN NEW.source_table_id::bigint
    ELSE NULL END;
  IF source_id IS NULL THEN RETURN NEW; END IF;
  SELECT channel_id,external_order_id INTO source_channel,source_external FROM oms.oms_orders WHERE id=source_id FOR UPDATE;
  IF NOT FOUND THEN RETURN NEW; END IF;
  SELECT id INTO active_operation FROM oms.order_edit_operations WHERE oms_order_id=source_id
    AND status NOT IN ('completed','recovered','failed','expired')
    AND (status='committing' OR document->>'commitStartedAt' IS NOT NULL
      OR document->>'commitKey' IS NOT NULL OR document->>'refundIntent' IS NOT NULL
      OR document->>'refundStartedAt' IS NOT NULL OR document->>'recoveryStartedAt' IS NOT NULL
      OR EXISTS (SELECT 1 FROM oms.order_edit_paid_projections p WHERE p.operation_id=oms.order_edit_operations.id));
  IF active_operation IS NOT NULL THEN
    IF NEW.channel_id IS DISTINCT FROM source_channel
      OR regexp_replace(COALESCE(NEW.external_order_id,''),'^gid://shopify/Order/','')
        IS DISTINCT FROM regexp_replace(COALESCE(source_external,''),'^gid://shopify/Order/','') THEN
      RAISE EXCEPTION 'Order edit source and warehouse identities differ' USING ERRCODE='23514';
    END IF;
    NEW.order_edit_operation_id := active_operation;
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: invalidate_shipping_package_history(bigint[]); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.invalidate_shipping_package_history(order_ids bigint[]) RETURNS void
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'oms', 'channels', 'wms'
    AS $$
  INSERT INTO wms.shipping_package_history_invalidations(oms_order_id)
  SELECT DISTINCT o.id FROM oms.oms_orders o JOIN channels.channels c ON c.id=o.channel_id
  WHERE o.id=ANY(order_ids) AND c.provider='shopify' AND c.type='internal' ORDER BY o.id;
$$;


--
-- Name: physical_shipment_update_guard(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.physical_shipment_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'physical_shipments is permanent fulfillment evidence; DELETE is not allowed'
      USING ERRCODE = '55000';
  END IF;

  IF NEW.shipping_engine_order_id IS DISTINCT FROM OLD.shipping_engine_order_id
     OR NEW.shipment_request_id IS DISTINCT FROM OLD.shipment_request_id
     OR NEW.provider IS DISTINCT FROM OLD.provider
     OR NEW.provider_physical_shipment_id IS DISTINCT FROM OLD.provider_physical_shipment_id
     OR NEW.tracking_number IS DISTINCT FROM OLD.tracking_number
     OR NEW.carrier IS DISTINCT FROM OLD.carrier
     OR NEW.service_code IS DISTINCT FROM OLD.service_code
     OR NEW.ship_date IS DISTINCT FROM OLD.ship_date
     OR NEW.raw_event_hash IS DISTINCT FROM OLD.raw_event_hash
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Physical shipment identity and dispatch snapshot are immutable'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: protect_applied_label_replacement(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.protect_applied_label_replacement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.state = 'applied' AND (TG_OP = 'DELETE' OR
    (to_jsonb(NEW) - 'projected_at' - 'updated_at') IS DISTINCT FROM (to_jsonb(OLD) - 'projected_at' - 'updated_at')) THEN
    RAISE EXCEPTION 'Applied label replacement identity is immutable' USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END; $$;


--
-- Name: protect_package_reconciliation_work(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.protect_package_reconciliation_work() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.state = 'applied' AND NEW.package_reconciliation_command_id IS DISTINCT FROM OLD.package_reconciliation_command_id
  THEN RAISE EXCEPTION 'Applied reconciliation provenance is immutable' USING ERRCODE = '55000'; END IF;
  RETURN NEW;
END; $$;


