--
-- Name: shipping_package_history_label_orders(bigint); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.shipping_package_history_label_orders(label_id bigint) RETURNS bigint[]
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'wms', 'oms'
    AS $_$
  WITH label AS (SELECT * FROM wms.shipping_provider_labels WHERE id=label_id),
  native_key AS (SELECT (regexp_match(provider_order_key,'^([1-9][0-9]{0,17})-[1-9][0-9]{0,17}$'))[1] AS order_id FROM label),
  existing_links AS (SELECT unnest(oms.customer_action_label_order_ids(label_id)) AS id),
  exact_external AS (SELECT o.id FROM oms.oms_orders o JOIN native_key key
    ON o.external_order_id=key.order_id OR o.external_order_id='gid://shopify/Order/'||key.order_id),
  engine_links AS (SELECT o.id FROM label JOIN wms.outbound_shipments s ON s.shipstation_order_id::text=label.provider_order_id
    JOIN wms.orders wo ON wo.id=s.order_id JOIN oms.oms_orders o ON o.channel_id=wo.channel_id
      AND (o.id=oms.customer_action_wms_order_id(wo.id)
        OR o.external_order_id=wo.external_order_id
        OR 'gid://shopify/Order/'||o.external_order_id=wo.external_order_id))
  SELECT array_agg(DISTINCT id) FROM (SELECT id FROM existing_links UNION SELECT id FROM exact_external UNION SELECT id FROM engine_links) ids;
$_$;


--
-- Name: shipping_package_history_source_changed(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.shipping_package_history_source_changed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'wms', 'oms'
    AS $$
BEGIN
  IF TG_ARGV[0]='order' THEN
    IF TG_OP='UPDATE' AND (to_jsonb(OLD)-'updated_at')=(to_jsonb(NEW)-'updated_at') THEN RETURN NEW; END IF;
    PERFORM wms.invalidate_shipping_package_history(ARRAY[NEW.id]);
  ELSIF TG_ARGV[0]='line' THEN
    IF TG_OP<>'INSERT' THEN PERFORM wms.invalidate_shipping_package_history(ARRAY[OLD.order_id]); END IF;
    IF TG_OP<>'DELETE' THEN PERFORM wms.invalidate_shipping_package_history(ARRAY[NEW.order_id]); END IF;
  ELSIF TG_ARGV[0]='label_event' THEN
    PERFORM wms.invalidate_shipping_package_history(wms.shipping_package_history_label_orders(NEW.shipping_provider_label_id));
  ELSIF TG_ARGV[0]='label' THEN
    IF TG_OP='UPDATE' AND OLD.label_status=NEW.label_status AND OLD.label_direction=NEW.label_direction
      AND OLD.tracking_number=NEW.tracking_number THEN RETURN NEW; END IF;
    PERFORM wms.invalidate_shipping_package_history(wms.shipping_package_history_label_orders(NEW.id));
  ELSIF TG_ARGV[0]='label_link' THEN
    PERFORM wms.invalidate_shipping_package_history(wms.shipping_package_history_label_orders(NEW.shipping_provider_label_id));
  ELSIF TG_ARGV[0]='physical' THEN
    PERFORM wms.invalidate_shipping_package_history(oms.customer_action_physical_order_ids(NEW.id));
  ELSIF TG_ARGV[0]='physical_item' THEN
    PERFORM wms.invalidate_shipping_package_history(oms.customer_action_physical_order_ids(NEW.physical_shipment_id));
  ELSIF TG_ARGV[0]='receipt' THEN
    PERFORM wms.invalidate_shipping_package_history(ARRAY[NEW.oms_order_id]);
  ELSIF TG_ARGV[0]='connection' THEN
    IF TG_OP='UPDATE' AND OLD.shop_domain IS NOT DISTINCT FROM NEW.shop_domain AND OLD.access_token IS NOT DISTINCT FROM NEW.access_token
      AND OLD.api_version IS NOT DISTINCT FROM NEW.api_version THEN RETURN NEW; END IF;
    PERFORM wms.invalidate_shipping_package_history(ARRAY(SELECT id FROM oms.oms_orders WHERE channel_id=NEW.channel_id));
  ELSIF TG_ARGV[0]='channel' THEN
    IF OLD.status IS NOT DISTINCT FROM NEW.status AND OLD.provider IS NOT DISTINCT FROM NEW.provider AND OLD.type IS NOT DISTINCT FROM NEW.type THEN RETURN NEW; END IF;
    PERFORM wms.invalidate_shipping_package_history(ARRAY(SELECT id FROM oms.oms_orders WHERE channel_id=NEW.id));
  ELSE RAISE EXCEPTION 'Unknown shipping package history source';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: validate_label_replacement_conservation(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.validate_label_replacement_conservation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE source_item RECORD; target_item RECORD; old_total bigint; new_total bigint;
BEGIN
  IF NEW.adjustment_kind <> 'provider_label_replacement' THEN RETURN NEW; END IF;
  SELECT item.*, COALESCE(item.legacy_wms_shipment_item_id, item.label_replacement_source_item_id,
    source.source_wms_shipment_item_id) AS source_id INTO source_item
  FROM wms.physical_shipment_items item
  LEFT JOIN wms.package_allocation_entries entry ON entry.id = item.package_allocation_entry_id
  LEFT JOIN wms.package_allocation_source_lines source ON source.id = entry.package_allocation_source_line_id
  WHERE item.id = NEW.physical_shipment_item_id;
  IF NEW.metadata ? 'replacementBatchId' THEN
    IF (NEW.metadata->>'replacementBatchId')::uuid IS DISTINCT FROM NEW.repair_run_id
      OR NEW.quantity_delta <> -source_item.quantity_shipped THEN
      RAISE EXCEPTION 'Repack must consume the exact immutable predecessor quantity' USING ERRCODE = '23514';
    END IF;
    SELECT SUM(-adjustment.quantity_delta) INTO old_total
    FROM wms.physical_shipment_item_quantity_adjustments adjustment
    JOIN wms.physical_shipment_items item ON item.id = adjustment.physical_shipment_item_id
    LEFT JOIN wms.package_allocation_entries entry ON entry.id = item.package_allocation_entry_id
    LEFT JOIN wms.package_allocation_source_lines source ON source.id = entry.package_allocation_source_line_id
    WHERE adjustment.repair_run_id = NEW.repair_run_id AND adjustment.adjustment_kind = 'provider_label_replacement'
      AND COALESCE(item.legacy_wms_shipment_item_id, item.label_replacement_source_item_id, source.source_wms_shipment_item_id) = source_item.source_id
      AND item.fulfillment_plan_line_id = source_item.fulfillment_plan_line_id
      AND item.shipment_request_item_id = source_item.shipment_request_item_id
      AND item.wms_order_item_id = source_item.wms_order_item_id;
    SELECT SUM(item.quantity_shipped) INTO new_total
    FROM wms.physical_shipment_items item
    JOIN wms.ebay_label_replacement_work work ON work.physical_shipment_id = item.physical_shipment_id
    WHERE work.replacement_batch_id = NEW.repair_run_id AND work.state = 'applied'
      AND item.label_replacement_source_item_id = source_item.source_id
      AND item.fulfillment_plan_line_id = source_item.fulfillment_plan_line_id
      AND item.shipment_request_item_id = source_item.shipment_request_item_id
      AND item.wms_order_item_id = source_item.wms_order_item_id;
    IF old_total IS NULL OR new_total IS DISTINCT FROM old_total THEN
      RAISE EXCEPTION 'Repack does not conserve source %, request %', source_item.source_id, source_item.shipment_request_item_id USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  -- Old application releases retain their exact one-to-one transfer contract.
  SELECT item.* INTO target_item FROM wms.physical_shipment_items item
  JOIN wms.ebay_label_replacement_work work ON work.physical_shipment_id = item.physical_shipment_id
  WHERE work.shipping_provider_label_id = (NEW.metadata->>'replacementLabelId')::bigint
    AND work.state = 'applied' AND item.label_replacement_source_item_id = source_item.source_id;
  IF target_item.id IS NULL OR NEW.quantity_delta <> -source_item.quantity_shipped
    OR target_item.quantity_shipped <> source_item.quantity_shipped
    OR target_item.fulfillment_plan_line_id IS DISTINCT FROM source_item.fulfillment_plan_line_id
    OR target_item.wms_order_item_id IS DISTINCT FROM source_item.wms_order_item_id
    OR target_item.shipment_request_item_id IS DISTINCT FROM source_item.shipment_request_item_id THEN
    RAISE EXCEPTION 'Label replacement must conserve exact source allocation %', NEW.physical_shipment_item_id USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: validate_label_replacement_source(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.validate_label_replacement_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE batch_id uuid; old_total bigint; new_total bigint; reconciliation_command_id bigint;
BEGIN
  IF NEW.label_replacement_source_item_id IS NULL THEN RETURN NEW; END IF;
  SELECT package_reconciliation_command_id INTO reconciliation_command_id
    FROM wms.ebay_label_replacement_work WHERE physical_shipment_id = NEW.physical_shipment_id;
  IF reconciliation_command_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM wms.ebay_label_replacement_work work
      JOIN wms.shipping_provider_labels label ON label.id = work.shipping_provider_label_id
      JOIN wms.physical_shipments package ON package.id = work.physical_shipment_id
      JOIN wms.outbound_shipment_items source ON source.id = NEW.label_replacement_source_item_id
      JOIN wms.shipment_request_items request ON request.id = NEW.shipment_request_item_id
      JOIN wms.fulfillment_plan_lines plan_line ON plan_line.id = NEW.fulfillment_plan_line_id
      WHERE work.package_reconciliation_command_id = reconciliation_command_id AND work.state = 'applied'
        AND work.physical_shipment_id = NEW.physical_shipment_id AND source.id = ANY(work.source_item_ids)
        AND source.order_item_id = NEW.wms_order_item_id AND source.shipment_item_purpose = 'customer_fulfillment'
        AND request.fulfillment_plan_line_id = plan_line.id AND request.wms_order_item_id = NEW.wms_order_item_id
        AND request.legacy_wms_shipment_item_id = source.id AND plan_line.wms_order_item_id = NEW.wms_order_item_id
        AND NEW.product_variant_id IS NOT DISTINCT FROM source.product_variant_id
        AND package.provider = label.provider AND package.provider_physical_shipment_id = label.provider_label_id
        AND package.tracking_number = label.tracking_number AND label.label_status = 'active' AND label.label_direction = 'outbound'
    ) THEN RAISE EXCEPTION 'Reconciled physical item requires exact source, request and current label provenance' USING ERRCODE = '23514'; END IF;
    PERFORM oms.validate_package_reconciliation(reconciliation_command_id);
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM wms.ebay_label_replacement_work work
    JOIN wms.shipping_provider_labels label ON label.id = work.shipping_provider_label_id
    JOIN wms.physical_shipments package ON package.id = work.physical_shipment_id
    JOIN wms.outbound_shipment_items source ON source.id = NEW.label_replacement_source_item_id
    JOIN wms.order_items order_item ON order_item.id = source.order_item_id
    JOIN oms.oms_order_lines line ON line.id = order_item.oms_order_line_id
    JOIN oms.oms_orders orders ON orders.id = line.order_id
    JOIN channels.channels channel ON channel.id = orders.channel_id
    WHERE work.state = 'applied' AND work.physical_shipment_id = NEW.physical_shipment_id
      AND source.id = ANY(work.source_item_ids) AND source.qty >= NEW.quantity_shipped
      AND source.order_item_id = NEW.wms_order_item_id
      AND source.shipment_item_purpose = 'customer_fulfillment' AND channel.provider IN ('ebay', 'shopify')
      AND package.provider = label.provider AND package.provider_physical_shipment_id = label.provider_label_id
      AND package.tracking_number = label.tracking_number AND label.label_status = 'active' AND label.label_direction = 'outbound'
  ) THEN
    RAISE EXCEPTION 'Physical item requires exact applied label replacement provenance' USING ERRCODE = '23514';
  END IF;
  SELECT replacement_batch_id INTO batch_id FROM wms.ebay_label_replacement_work WHERE physical_shipment_id = NEW.physical_shipment_id;
  IF batch_id IS NOT NULL THEN
    -- Check the positive side too: an extra target must not commit simply
    -- because no negative-side trigger was fired for its request identity.
    SELECT SUM(-adjustment.quantity_delta) INTO old_total
    FROM wms.physical_shipment_item_quantity_adjustments adjustment
    JOIN wms.physical_shipment_items item ON item.id = adjustment.physical_shipment_item_id
    LEFT JOIN wms.package_allocation_entries entry ON entry.id = item.package_allocation_entry_id
    LEFT JOIN wms.package_allocation_source_lines source ON source.id = entry.package_allocation_source_line_id
    WHERE adjustment.repair_run_id = batch_id AND adjustment.adjustment_kind = 'provider_label_replacement'
      AND COALESCE(item.legacy_wms_shipment_item_id, item.label_replacement_source_item_id, source.source_wms_shipment_item_id) = NEW.label_replacement_source_item_id;
    IF old_total IS NOT NULL THEN
      SELECT SUM(item.quantity_shipped) INTO new_total FROM wms.physical_shipment_items item
      JOIN wms.ebay_label_replacement_work work ON work.physical_shipment_id = item.physical_shipment_id
      WHERE work.replacement_batch_id = batch_id AND work.state = 'applied'
        AND item.label_replacement_source_item_id = NEW.label_replacement_source_item_id;
      IF new_total IS DISTINCT FROM old_total THEN
        RAISE EXCEPTION 'Replacement batch creates additional source quantity' USING ERRCODE = '23514';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: validate_package_allocation_plan_conservation(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.validate_package_allocation_plan_conservation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  affected_plan_id BIGINT;
  affected_group_id BIGINT;
  affected_plan_version INTEGER;
  projected_version INTEGER;
BEGIN
  IF TG_TABLE_NAME = 'package_allocation_groups' THEN
    IF NEW.current_version = 0 THEN
      RETURN NULL;
    END IF;

    SELECT id
      INTO affected_plan_id
    FROM wms.package_allocation_plans
    WHERE package_allocation_group_id = NEW.id
      AND plan_version = NEW.current_version;
  ELSIF TG_TABLE_NAME = 'package_allocation_plans' THEN
    affected_plan_id := NEW.id;
  ELSE
    affected_plan_id := NEW.package_allocation_plan_id;
  END IF;

  SELECT package_allocation_group_id, plan_version
    INTO affected_group_id, affected_plan_version
  FROM wms.package_allocation_plans
  WHERE id = affected_plan_id;

  IF affected_plan_id IS NULL OR affected_group_id IS NULL THEN
    RAISE EXCEPTION 'package allocation group current version has no plan'
      USING
        ERRCODE = '23514',
        CONSTRAINT = 'package_allocation_plan_conservation_chk';
  END IF;

  SELECT current_version
    INTO projected_version
  FROM wms.package_allocation_groups
  WHERE id = affected_group_id;

  IF projected_version <> affected_plan_version THEN
    RAISE EXCEPTION 'package allocation plan is not the group current version'
      USING
        ERRCODE = '23514',
        CONSTRAINT = 'package_allocation_plan_conservation_chk';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM wms.package_allocation_group_source_lines
    WHERE package_allocation_group_id = affected_group_id
  ) THEN
    RAISE EXCEPTION 'package allocation plan group has no source lines'
      USING
        ERRCODE = '23514',
        CONSTRAINT = 'package_allocation_plan_conservation_chk';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM wms.package_allocation_entries
    WHERE package_allocation_plan_id = affected_plan_id
    GROUP BY allocation_key
    HAVING MIN(package_allocation_source_line_id)
      <> MAX(package_allocation_source_line_id)
  ) THEN
    RAISE EXCEPTION 'package allocation key spans multiple source lines'
      USING ERRCODE = '23514',
        CONSTRAINT = 'package_allocation_plan_conservation_chk';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM wms.package_allocation_group_source_lines membership
    JOIN wms.package_allocation_source_lines source_line
      ON source_line.id = membership.package_allocation_source_line_id
    LEFT JOIN LATERAL (
      SELECT COALESCE(SUM(entry.quantity), 0) AS primary_quantity
      FROM wms.package_allocation_entries entry
      WHERE entry.package_allocation_plan_id = affected_plan_id
        AND entry.package_allocation_source_line_id = source_line.id
        AND entry.allocation_kind = 'primary_transfer'
    ) allocation_total ON TRUE
    WHERE membership.package_allocation_group_id = affected_group_id
      AND allocation_total.primary_quantity <> source_line.source_quantity
  ) THEN
    RAISE EXCEPTION 'package allocation primary transfers do not conserve source quantity'
      USING
        ERRCODE = '23514',
        CONSTRAINT = 'package_allocation_plan_conservation_chk';
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: validate_package_reconciliation_adjustment(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.validate_package_reconciliation_adjustment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.adjustment_kind = 'provider_package_reconciliation' THEN
    PERFORM oms.validate_package_reconciliation((NEW.metadata->>'reconciliationCommandId')::bigint);
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: validate_physical_shipment_item_allocation_provenance(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.validate_physical_shipment_item_allocation_provenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  allocation RECORD;
BEGIN
  IF NEW.package_allocation_entry_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT
    entry.quantity,
    entry.target_kind,
    plan.outcome AS plan_outcome,
    plan.plan_version,
    allocation_group.current_version AS group_current_version,
    source.shipment_item_purpose,
    source.shipment_request_item_id,
    source.order_item_id,
    source.replacement_for_order_item_id,
    source.product_variant_id,
    source.sku,
    binding.provider,
    binding.provider_physical_shipment_id,
    physical.provider AS physical_provider,
    physical.provider_physical_shipment_id AS physical_provider_shipment_id
  INTO allocation
  FROM wms.package_allocation_entries AS entry
  JOIN wms.package_allocation_source_lines AS source
    ON source.id = entry.package_allocation_source_line_id
  JOIN wms.package_allocation_plans AS plan
    ON plan.id = entry.package_allocation_plan_id
   AND plan.package_allocation_group_id = entry.package_allocation_group_id
  JOIN wms.package_allocation_groups AS allocation_group
    ON allocation_group.id = entry.package_allocation_group_id
  JOIN wms.package_allocation_package_bindings AS binding
    ON binding.id = entry.package_allocation_package_binding_id
  JOIN wms.physical_shipments AS physical
    ON physical.id = NEW.physical_shipment_id
  WHERE entry.id = NEW.package_allocation_entry_id
  FOR SHARE OF allocation_group;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'Package allocation entry % does not have complete package provenance',
      NEW.package_allocation_entry_id
      USING ERRCODE = '23503';
  END IF;

  IF allocation.target_kind <> 'package'
     OR allocation.plan_outcome <> 'proposed'
     OR allocation.plan_version <> allocation.group_current_version
     OR allocation.quantity <> NEW.quantity_shipped
     OR allocation.shipment_item_purpose <> NEW.shipment_item_purpose
     OR (
       allocation.shipment_request_item_id IS NOT NULL
       AND allocation.shipment_request_item_id IS DISTINCT FROM NEW.shipment_request_item_id
     )
     OR allocation.order_item_id IS DISTINCT FROM NEW.wms_order_item_id
     OR allocation.replacement_for_order_item_id IS DISTINCT FROM NEW.replacement_for_order_item_id
     OR allocation.product_variant_id IS DISTINCT FROM NEW.product_variant_id
     OR allocation.sku IS DISTINCT FROM NEW.sku
     OR LOWER(BTRIM(allocation.provider)) IS DISTINCT FROM LOWER(BTRIM(allocation.physical_provider))
     OR BTRIM(allocation.provider_physical_shipment_id)
          IS DISTINCT FROM BTRIM(allocation.physical_provider_shipment_id) THEN
    RAISE EXCEPTION
      'Physical shipment item does not match package allocation entry %',
      NEW.package_allocation_entry_id
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_physical_shipment_item_quantity_adjustment(); Type: FUNCTION; Schema: wms; Owner: -
--

CREATE FUNCTION wms.validate_physical_shipment_item_quantity_adjustment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  base_quantity INTEGER;
BEGIN
  SELECT item.quantity_shipped
  INTO base_quantity
  FROM wms.physical_shipment_items AS item
  WHERE item.id = NEW.physical_shipment_item_id
  FOR UPDATE;

  IF base_quantity IS NULL THEN
    RAISE EXCEPTION
      'Physical shipment item % does not exist',
      NEW.physical_shipment_item_id
      USING ERRCODE = '23503';
  END IF;

  IF base_quantity + NEW.quantity_delta < 0 THEN
    RAISE EXCEPTION
      'Physical shipment item % correction would make effective quantity negative',
      NEW.physical_shipment_item_id
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


