    track_inventory boolean DEFAULT true,
    inventory_policy character varying(20) DEFAULT 'deny'::character varying,
    shopify_variant_id character varying(100),
    shopify_inventory_item_id character varying(100),
    is_active boolean DEFAULT true NOT NULL,
