    inventory_tracking_override boolean,
    shipping_package_type character varying(30),
    CONSTRAINT product_variants_digital_untracked_chk CHECK (((requires_shipping = true) OR (track_inventory IS FALSE))),
    CONSTRAINT product_variants_internal_only_identity_chk CHECK ((((sales_eligibility)::text = 'sellable'::text) OR ((shopify_variant_id IS NULL) AND (shopify_inventory_item_id IS NULL) AND (COALESCE(dropship_eligible, false) = false)))),
    CONSTRAINT product_variants_max_units_per_package_chk CHECK (((max_units_per_package IS NULL) OR (max_units_per_package > 0))),
    CONSTRAINT product_variants_sales_eligibility_chk CHECK (((sales_eligibility)::text = ANY ((ARRAY['sellable'::character varying, 'internal_only'::character varying])::text[]))),
    CONSTRAINT product_variants_shipping_package_type_check CHECK (((shipping_package_type IS NULL) OR ((shipping_package_type)::text = ANY ((ARRAY['parcel'::character varying, 'letter'::character varying, 'large_envelope'::character varying])::text[])))),
    CONSTRAINT product_variants_single_unit_uom_invariants_chk CHECK ((((uom_type)::text <> ALL ((ARRAY['piece'::character varying, 'each'::character varying])::text[])) OR ((units_per_variant = 1) AND (hierarchy_level = 1) AND (parent_variant_id IS NULL) AND (is_base_unit = true)))),
    CONSTRAINT product_variants_uom_type_chk CHECK (((uom_type)::text = ANY ((ARRAY['piece'::character varying, 'each'::character varying, 'pack'::character varying, 'inner_pack'::character varying, 'case'::character varying, 'skid'::character varying])::text[])))
);


