--
-- Name: shopify_product_connection_commands; Type: TABLE; Schema: catalog; Owner: -
--

CREATE TABLE catalog.shopify_product_connection_commands (
    command_key uuid NOT NULL,
    product_id integer NOT NULL,
    channel_id integer NOT NULL,
    connection_id integer NOT NULL,
    shop_domain text NOT NULL,
    actor text NOT NULL,
    request_hash text NOT NULL,
    preview_hash text NOT NULL,
    mode text NOT NULL,
    request jsonb NOT NULL,
    source_snapshot jsonb NOT NULL,
    review_evidence jsonb NOT NULL,
    create_spec jsonb,
    state text DEFAULT 'pending'::text NOT NULL,
    create_requested boolean DEFAULT false NOT NULL,
    remote_product_id text,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    last_error_code text,
    last_error_message text,
    retryable boolean DEFAULT true NOT NULL,
    resume_attempt_count integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    result jsonb,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT shopify_product_connection_commands_actor_check CHECK (((length(btrim(actor)) >= 1) AND (length(btrim(actor)) <= 200))),
    CONSTRAINT shopify_product_connection_commands_check CHECK (((lease_token IS NULL) = (lease_expires_at IS NULL))),
    CONSTRAINT shopify_product_connection_commands_check1 CHECK (((state = ANY (ARRAY['complete'::text, 'rejected'::text])) = (completed_at IS NOT NULL))),
    CONSTRAINT shopify_product_connection_commands_check2 CHECK (((state <> 'complete'::text) OR ((remote_product_id IS NOT NULL) AND (result IS NOT NULL)))),
    CONSTRAINT shopify_product_connection_commands_check3 CHECK (((mode = 'create'::text) OR ((create_spec IS NULL) AND (create_requested = false)))),
    CONSTRAINT shopify_product_connection_commands_check4 CHECK ((((request ->> 'mode'::text) = mode) AND ((request ->> 'channelId'::text) = (channel_id)::text))),
    CONSTRAINT shopify_product_connection_commands_check5 CHECK ((((source_snapshot #>> '{product,id}'::text[]) = (product_id)::text) AND ((source_snapshot #>> '{channel,id}'::text[]) = (channel_id)::text) AND ((source_snapshot #>> '{channel,connectionId}'::text[]) = (connection_id)::text) AND ((source_snapshot #>> '{channel,shopDomain}'::text[]) = shop_domain))),
    CONSTRAINT shopify_product_connection_commands_check6 CHECK (((mode = 'create'::text) = (create_spec IS NOT NULL))),
    CONSTRAINT shopify_product_connection_commands_create_spec_check CHECK (((create_spec IS NULL) OR (jsonb_typeof(create_spec) = 'object'::text))),
    CONSTRAINT shopify_product_connection_commands_mode_check CHECK ((mode = ANY (ARRAY['create'::text, 'link'::text]))),
    CONSTRAINT shopify_product_connection_commands_preview_hash_check CHECK ((preview_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT shopify_product_connection_commands_remote_product_id_check CHECK (((remote_product_id IS NULL) OR (remote_product_id ~ '^[1-9][0-9]*$'::text))),
    CONSTRAINT shopify_product_connection_commands_request_check CHECK ((jsonb_typeof(request) = 'object'::text)),
    CONSTRAINT shopify_product_connection_commands_request_hash_check CHECK ((request_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT shopify_product_connection_commands_result_check CHECK (((result IS NULL) OR (jsonb_typeof(result) = 'object'::text))),
    CONSTRAINT shopify_product_connection_commands_resume_attempt_count_check CHECK ((resume_attempt_count >= 0)),
    CONSTRAINT shopify_product_connection_commands_review_evidence_check CHECK ((jsonb_typeof(review_evidence) = 'object'::text)),
    CONSTRAINT shopify_product_connection_commands_shop_domain_check CHECK ((shop_domain ~ '^[a-z0-9][a-z0-9-]*\.myshopify\.com$'::text)),
    CONSTRAINT shopify_product_connection_commands_source_snapshot_check CHECK ((jsonb_typeof(source_snapshot) = 'object'::text)),
    CONSTRAINT shopify_product_connection_commands_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'creating'::text, 'configuring'::text, 'mapping'::text, 'publishing'::text, 'complete'::text, 'review'::text, 'rejected'::text])))
);


