    CONSTRAINT shopify_product_connection_events_details_check CHECK ((jsonb_typeof(details) = 'object'::text)),
    CONSTRAINT shopify_product_connection_events_event_type_check CHECK (((length(btrim(event_type)) >= 1) AND (length(btrim(event_type)) <= 100)))
);


