--

CREATE TABLE channels.channel_variant_availability_sync (
    channel_id integer NOT NULL,
    product_variant_id integer NOT NULL,
    desired_active boolean NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    last_synced_quantity integer,
    last_synced_at timestamp with time zone,
    completed_at timestamp with time zone,
    last_error text,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT channel_variant_availability_sync_attempt_chk CHECK ((attempt_count >= 0)),
    CONSTRAINT channel_variant_availability_sync_lease_chk CHECK (((((status)::text = 'processing'::text) AND (lease_token IS NOT NULL) AND (lease_expires_at IS NOT NULL)) OR (((status)::text <> 'processing'::text) AND (lease_token IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT channel_variant_availability_sync_quantity_chk CHECK (((last_synced_quantity IS NULL) OR (last_synced_quantity >= 0))),
    CONSTRAINT channel_variant_availability_sync_revision_chk CHECK ((revision > 0)),
    CONSTRAINT channel_variant_availability_sync_status_chk CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'processing'::character varying, 'retryable'::character varying, 'synced'::character varying])::text[])))
);


--
-- Name: TABLE channel_variant_availability_sync; Type: COMMENT; Schema: channels; Owner: -
--

