    CONSTRAINT ebay_listing_mapping_repairs_after_identity_check CHECK ((jsonb_typeof(after_identity) = 'object'::text)),
    CONSTRAINT ebay_listing_mapping_repairs_before_identity_check CHECK ((jsonb_typeof(before_identity) = 'object'::text)),
    CONSTRAINT ebay_listing_mapping_repairs_before_rows_check CHECK (((jsonb_typeof(before_rows) = 'array'::text) AND ((jsonb_array_length(before_rows) >= 1) AND (jsonb_array_length(before_rows) <= 250)))),
    CONSTRAINT ebay_listing_mapping_repairs_check CHECK (((jsonb_typeof(after_rows) = 'array'::text) AND (jsonb_array_length(after_rows) = jsonb_array_length(before_rows)))),
    CONSTRAINT ebay_listing_mapping_repairs_environment_check CHECK ((environment = ANY (ARRAY['production'::text, 'sandbox'::text]))),
    CONSTRAINT ebay_listing_mapping_repairs_observation_check CHECK ((jsonb_typeof(observation) = 'object'::text)),
