    CONSTRAINT ebay_mapping_publish_admission_preserves_source CHECK (((operation <> 'publish'::text) OR ((before_identity = after_identity) AND (before_rows = after_rows) AND (NOT ((observation ->> 'kind'::text) IS DISTINCT FROM 'unpublished_inspection'::text)))))
);


