--
-- Name: shopify_oauth_authorizations; Type: TABLE; Schema: channels; Owner: -
--

CREATE TABLE channels.shopify_oauth_authorizations (
    operation_id uuid NOT NULL,
    state_hash character varying(64) NOT NULL,
    actor_id character varying NOT NULL,
    session_hash character varying(64) NOT NULL,
    config_fingerprint character varying(64) NOT NULL,
    shop_domain character varying(255) NOT NULL,
    channel_id integer NOT NULL,
    connection_id integer NOT NULL,
    connection_fingerprint character varying(64) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    status character varying(24) DEFAULT 'issued'::character varying NOT NULL,
    attempt_id uuid,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    error_code character varying(100),
    CONSTRAINT shopify_oauth_authorizations_error_chk CHECK (((error_code IS NULL) OR ((error_code)::text ~ '^[A-Z][A-Z0-9_]{0,99}$'::text))),
    CONSTRAINT shopify_oauth_authorizations_expiry_chk CHECK (((expires_at > created_at) AND (expires_at <= (created_at + '00:10:00'::interval)))),
    CONSTRAINT shopify_oauth_authorizations_hashes_chk CHECK ((((state_hash)::text ~ '^[a-f0-9]{64}$'::text) AND ((session_hash)::text ~ '^[a-f0-9]{64}$'::text) AND ((config_fingerprint)::text ~ '^[a-f0-9]{64}$'::text) AND ((connection_fingerprint)::text ~ '^[a-f0-9]{64}$'::text))),
    CONSTRAINT shopify_oauth_authorizations_lifecycle_chk CHECK (((((status)::text = 'issued'::text) AND (attempt_id IS NULL) AND (started_at IS NULL) AND (completed_at IS NULL) AND (error_code IS NULL)) OR (((status)::text = 'exchanging'::text) AND (attempt_id IS NOT NULL) AND (started_at IS NOT NULL) AND (completed_at IS NULL) AND (error_code IS NULL)) OR (((status)::text = 'succeeded'::text) AND (attempt_id IS NOT NULL) AND (started_at IS NOT NULL) AND (completed_at IS NOT NULL) AND (error_code IS NULL)) OR (((status)::text = ANY ((ARRAY['failed'::character varying, 'exchange_unknown'::character varying])::text[])) AND (attempt_id IS NOT NULL) AND (started_at IS NOT NULL) AND (completed_at IS NOT NULL) AND (error_code IS NOT NULL)) OR (((status)::text = 'superseded'::text) AND (completed_at IS NOT NULL) AND (error_code IS NOT NULL) AND (((attempt_id IS NULL) AND (started_at IS NULL)) OR ((attempt_id IS NOT NULL) AND (started_at IS NOT NULL)))))),
    CONSTRAINT shopify_oauth_authorizations_shop_chk CHECK (((shop_domain)::text ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?[.]myshopify[.]com$'::text)),
    CONSTRAINT shopify_oauth_authorizations_status_chk CHECK (((status)::text = ANY ((ARRAY['issued'::character varying, 'exchanging'::character varying, 'succeeded'::character varying, 'exchange_unknown'::character varying, 'failed'::character varying, 'superseded'::character varying])::text[]))),
    CONSTRAINT shopify_oauth_authorizations_times_chk CHECK ((((started_at IS NULL) OR ((started_at >= created_at) AND (started_at < expires_at))) AND ((completed_at IS NULL) OR (completed_at >= COALESCE(started_at, created_at)))))
);


