-- Name: dropship_wallet_policies; Type: TABLE; Schema: dropship; Owner: -
--

CREATE TABLE dropship.dropship_wallet_policies (
    id integer NOT NULL,
    version integer NOT NULL,
    minimum_floor_cents bigint NOT NULL,
    minimum_single_top_up_limit_cents bigint NOT NULL,
    manual_top_up_minimum_cents bigint NOT NULL,
    manual_top_up_maximum_cents bigint NOT NULL,
    default_payment_hold_timeout_minutes integer NOT NULL,
    hold_expiry_warning_minutes integer NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    change_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_actor_type character varying(40) NOT NULL,
    created_by_actor_id character varying(255),
    deactivated_at timestamp with time zone,
    case_tier_minimum_cents bigint NOT NULL,
    advance_fee_bps integer NOT NULL,
    advance_cap_cents bigint NOT NULL,
    tier_change_grace_days integer NOT NULL,
    card_funding_fee_bps integer NOT NULL,
    card_funding_minimum_cents bigint NOT NULL,
    rewards_rate_bank_bps integer NOT NULL,
    rewards_rate_usdc_bps integer NOT NULL,
    rewards_rate_card_bps integer NOT NULL,
    rewards_expiry_days integer,
    CONSTRAINT dropship_wallet_policies_actor_chk CHECK (((created_by_actor_type)::text = ANY ((ARRAY['admin'::character varying, 'system'::character varying])::text[]))),
    CONSTRAINT dropship_wallet_policies_advance_cap_chk CHECK ((advance_cap_cents >= 0)),
    CONSTRAINT dropship_wallet_policies_advance_fee_chk CHECK (((advance_fee_bps >= 0) AND (advance_fee_bps <= 10000))),
    CONSTRAINT dropship_wallet_policies_card_fee_chk CHECK (((card_funding_fee_bps >= 0) AND (card_funding_fee_bps <= 1000))),
    CONSTRAINT dropship_wallet_policies_card_minimum_chk CHECK ((card_funding_minimum_cents > 0)),
    CONSTRAINT dropship_wallet_policies_card_minimum_range_chk CHECK ((card_funding_minimum_cents <= manual_top_up_maximum_cents)),
    CONSTRAINT dropship_wallet_policies_case_tier_chk CHECK ((case_tier_minimum_cents >= minimum_floor_cents)),
    CONSTRAINT dropship_wallet_policies_deactivated_chk CHECK (((is_active AND (deactivated_at IS NULL)) OR ((NOT is_active) AND (deactivated_at IS NOT NULL)))),
    CONSTRAINT dropship_wallet_policies_grace_days_chk CHECK (((tier_change_grace_days >= 0) AND (tier_change_grace_days <= 365))),
    CONSTRAINT dropship_wallet_policies_hold_timeout_chk CHECK (((default_payment_hold_timeout_minutes >= 1) AND (default_payment_hold_timeout_minutes <= 43200))),
    CONSTRAINT dropship_wallet_policies_limit_covers_floor_chk CHECK ((minimum_single_top_up_limit_cents >= minimum_floor_cents)),
    CONSTRAINT dropship_wallet_policies_manual_maximum_chk CHECK ((manual_top_up_maximum_cents > 0)),
    CONSTRAINT dropship_wallet_policies_manual_minimum_chk CHECK ((manual_top_up_minimum_cents > 0)),
    CONSTRAINT dropship_wallet_policies_manual_range_chk CHECK ((manual_top_up_minimum_cents <= manual_top_up_maximum_cents)),
    CONSTRAINT dropship_wallet_policies_minimum_floor_chk CHECK ((minimum_floor_cents > 0)),
    CONSTRAINT dropship_wallet_policies_minimum_limit_chk CHECK ((minimum_single_top_up_limit_cents > 0)),
    CONSTRAINT dropship_wallet_policies_rewards_bank_chk CHECK (((rewards_rate_bank_bps >= 0) AND (rewards_rate_bank_bps <= 1000))),
    CONSTRAINT dropship_wallet_policies_rewards_card_chk CHECK (((rewards_rate_card_bps >= 0) AND (rewards_rate_card_bps <= 1000))),
    CONSTRAINT dropship_wallet_policies_rewards_expiry_chk CHECK (((rewards_expiry_days IS NULL) OR ((rewards_expiry_days >= 1) AND (rewards_expiry_days <= 3650)))),
    CONSTRAINT dropship_wallet_policies_rewards_usdc_chk CHECK (((rewards_rate_usdc_bps >= 0) AND (rewards_rate_usdc_bps <= 1000))),
    CONSTRAINT dropship_wallet_policies_version_chk CHECK ((version > 0)),
    CONSTRAINT dropship_wallet_policies_warning_window_chk CHECK (((hold_expiry_warning_minutes >= 1) AND (hold_expiry_warning_minutes < default_payment_hold_timeout_minutes)))
);


--
-- Name: TABLE dropship_wallet_policies; Type: COMMENT; Schema: dropship; Owner: -
--

COMMENT ON TABLE dropship.dropship_wallet_policies IS 'Versioned, immutable, staff-managed wallet limits. Exactly one active row; an edit is a new version. Retirement (active -> inactive) is the only permitted UPDATE.';


--
-- Name: COLUMN dropship_wallet_policies.minimum_floor_cents; Type: COMMENT; Schema: dropship; Owner: -
--

COMMENT ON COLUMN dropship.dropship_wallet_policies.minimum_floor_cents IS 'Pack tier minimum: the lowest minimum balance any vendor may keep; applies to vendors selling eaches and inner packs (variant type P, B).';


--
-- Name: COLUMN dropship_wallet_policies.case_tier_minimum_cents; Type: COMMENT; Schema: dropship; Owner: -
--

COMMENT ON COLUMN dropship.dropship_wallet_policies.case_tier_minimum_cents IS 'Case tier minimum: vendors with case listings (variant type C) enabled must keep at least this. Never below minimum_floor_cents.';


--
-- Name: COLUMN dropship_wallet_policies.advance_fee_bps; Type: COMMENT; Schema: dropship; Owner: -
--

COMMENT ON COLUMN dropship.dropship_wallet_policies.advance_fee_bps IS 'Service fee, in basis points, on the amount of pending ACH an order is accepted against.';


--
-- Name: COLUMN dropship_wallet_policies.advance_cap_cents; Type: COMMENT; Schema: dropship; Owner: -
--

COMMENT ON COLUMN dropship.dropship_wallet_policies.advance_cap_cents IS 'Global ceiling on the pending-ACH amount an order may be accepted against. Zero means nothing is advanced. dropship_vendor_credit_profiles.advance_cap_override_cents overrides it per vendor.';


--
-- Name: COLUMN dropship_wallet_policies.tier_change_grace_days; Type: COMMENT; Schema: dropship; Owner: -
--

COMMENT ON COLUMN dropship.dropship_wallet_policies.tier_change_grace_days IS 'Days a vendor below a raised tier minimum keeps that tier''s listings before they are unpublished. Zero enforces immediately.';


--
-- Name: COLUMN dropship_wallet_policies.rewards_rate_bank_bps; Type: COMMENT; Schema: dropship; Owner: -
--

COMMENT ON COLUMN dropship.dropship_wallet_policies.rewards_rate_bank_bps IS 'Rewards earned on a settled bank (ACH) transfer, in basis points of the amount credited (migration 0702).';


--
-- Name: COLUMN dropship_wallet_policies.rewards_rate_usdc_bps; Type: COMMENT; Schema: dropship; Owner: -
--

COMMENT ON COLUMN dropship.dropship_wallet_policies.rewards_rate_usdc_bps IS 'Rewards earned on a settled USDC transfer, in basis points of the amount credited (migration 0702).';


--
-- Name: COLUMN dropship_wallet_policies.rewards_rate_card_bps; Type: COMMENT; Schema: dropship; Owner: -
--

COMMENT ON COLUMN dropship.dropship_wallet_policies.rewards_rate_card_bps IS 'Rewards earned on a settled card charge, in basis points of the amount credited; zero at launch (migration 0702).';


--
-- Name: COLUMN dropship_wallet_policies.rewards_expiry_days; Type: COMMENT; Schema: dropship; Owner: -
--

COMMENT ON COLUMN dropship.dropship_wallet_policies.rewards_expiry_days IS 'Days after they are earned that unused rewards points expire; NULL means they never expire. Applies to points earned while this version is in force (migration 0705).';


