--

CREATE TABLE inventory.availability_activation_runs (
    id bigint NOT NULL,
    mode character varying(20) NOT NULL,
    scope character varying(30) DEFAULT 'full_catalog'::character varying NOT NULL,
    state character varying(40) NOT NULL,
    request_hash character varying(64) NOT NULL,
    result_hash character varying(64),
    expected_catalog_input_hash character varying(64) NOT NULL,
    expected_catalog_result_hash character varying(64) NOT NULL,
    captured_catalog_input_hash character varying(64) NOT NULL,
    captured_catalog_result_hash character varying(64) NOT NULL,
    evidence_payload jsonb NOT NULL,
    blocker_codes jsonb DEFAULT '[]'::jsonb NOT NULL,
    idempotency_key character varying(120) NOT NULL,
    reason character varying(1000) NOT NULL,
    requested_by character varying(100) NOT NULL,
    runtime_authority_changed boolean DEFAULT false NOT NULL,
    provider_write_attempted boolean DEFAULT false NOT NULL,
    outbox_enqueued boolean DEFAULT false NOT NULL,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    source_dry_run_id bigint,
    prepared_at timestamp with time zone,
    publication_verified_at timestamp with time zone,
    activated_at timestamp with time zone,
    failed_at timestamp with time zone,
    provider_publication_required boolean DEFAULT false NOT NULL,
    CONSTRAINT availability_activation_runs_actor_chk CHECK ((((char_length(btrim((requested_by)::text)) >= 1) AND (char_length(btrim((requested_by)::text)) <= 100)) AND ((char_length(btrim((reason)::text)) >= 1) AND (char_length(btrim((reason)::text)) <= 1000)) AND ((char_length(btrim((idempotency_key)::text)) >= 1) AND (char_length(btrim((idempotency_key)::text)) <= 120)))),
    CONSTRAINT availability_activation_runs_dry_run_chk CHECK ((((mode)::text <> 'dry_run'::text) OR (((state)::text = ANY ((ARRAY['blocked'::character varying, 'ready_for_publication'::character varying])::text[])) AND (runtime_authority_changed = false) AND (provider_write_attempted = false) AND (outbox_enqueued = false) AND (completed_at IS NOT NULL)))),
    CONSTRAINT availability_activation_runs_evidence_chk CHECK (((jsonb_typeof(evidence_payload) = 'object'::text) AND (jsonb_typeof(blocker_codes) = 'array'::text))),
    CONSTRAINT availability_activation_runs_hash_chk CHECK ((((request_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((result_hash IS NULL) OR ((result_hash)::text ~ '^[0-9a-f]{64}$'::text)) AND ((expected_catalog_input_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((expected_catalog_result_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((captured_catalog_input_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((captured_catalog_result_hash)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT availability_activation_runs_milestone_time_chk CHECK ((((prepared_at IS NULL) OR (prepared_at >= started_at)) AND ((publication_verified_at IS NULL) OR ((prepared_at IS NOT NULL) AND (publication_verified_at >= prepared_at))) AND ((activated_at IS NULL) OR ((publication_verified_at IS NOT NULL) AND (activated_at >= publication_verified_at))) AND ((failed_at IS NULL) OR (failed_at >= started_at)))),
    CONSTRAINT availability_activation_runs_mode_chk CHECK (((mode)::text = ANY ((ARRAY['dry_run'::character varying, 'activation'::character varying, 'rollback'::character varying])::text[]))),
    CONSTRAINT availability_activation_runs_scope_chk CHECK (((scope)::text = 'full_catalog'::text)),
    CONSTRAINT availability_activation_runs_state_chk CHECK (((state)::text = ANY ((ARRAY['validating'::character varying, 'blocked'::character varying, 'ready_for_publication'::character varying, 'publishing'::character varying, 'publication_verified'::character varying, 'activating'::character varying, 'active'::character varying, 'failed'::character varying])::text[]))),
    CONSTRAINT availability_activation_runs_time_chk CHECK (((completed_at IS NULL) OR (completed_at >= started_at)))
);


