    released_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    superseded_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    supersedes_claim_id bigint,
    CONSTRAINT availability_claims_actor_chk CHECK (((btrim((claim_key)::text) <> ''::text) AND (btrim((requested_by)::text) <> ''::text) AND (btrim((reason)::text) <> ''::text))),
    CONSTRAINT availability_claims_authority_chk CHECK ((runtime_authority_revision > 0)),
    CONSTRAINT availability_claims_evidence_chk CHECK (((jsonb_typeof(request_payload) = 'object'::text) AND (jsonb_typeof(plan_payload) = 'object'::text) AND (jsonb_typeof(model_evidence) = 'array'::text) AND ((request_payload ->> 'requestKey'::text) = (claim_key)::text) AND ((plan_payload ->> 'requestKey'::text) = (claim_key)::text) AND ((plan_payload ->> 'status'::text) = (plan_status)::text) AND ((plan_payload ->> 'snapshotFingerprint'::text) = (snapshot_fingerprint)::text))),
    CONSTRAINT availability_claims_hash_chk CHECK ((((request_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((plan_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((snapshot_fingerprint)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT availability_claims_lifecycle_chk CHECK (((((status)::text = 'active'::text) AND (released_at IS NULL) AND (cancelled_at IS NULL) AND (superseded_at IS NULL)) OR (((status)::text = 'released'::text) AND (released_at IS NOT NULL) AND (cancelled_at IS NULL) AND (superseded_at IS NULL)) OR (((status)::text = 'cancelled'::text) AND (cancelled_at IS NOT NULL) AND (superseded_at IS NULL)) OR (((status)::text = 'superseded'::text) AND (superseded_at IS NOT NULL)) OR ((status)::text = 'failed'::text))),
    CONSTRAINT availability_claims_plan_status_chk CHECK (((plan_status)::text = ANY ((ARRAY['satisfied'::character varying, 'partial'::character varying])::text[]))),
    CONSTRAINT availability_claims_revision_chk CHECK ((revision > 0)),
    CONSTRAINT availability_claims_scope_chk CHECK (((((scope_kind)::text = 'network'::text) AND (scope_warehouse_id IS NULL)) OR (((scope_kind)::text = 'warehouse'::text) AND (scope_warehouse_id IS NOT NULL)))),
    CONSTRAINT availability_claims_status_chk CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'released'::character varying, 'cancelled'::character varying, 'superseded'::character varying, 'failed'::character varying])::text[]))),
    CONSTRAINT availability_claims_supersedes_chk CHECK (((supersedes_claim_id IS NULL) OR (supersedes_claim_id <> id)))
);


