    CONSTRAINT availability_runtime_authority_actor_chk CHECK ((((char_length(btrim((changed_by)::text)) >= 1) AND (char_length(btrim((changed_by)::text)) <= 100)) AND ((char_length(btrim((change_reason)::text)) >= 1) AND (char_length(btrim((change_reason)::text)) <= 1000)))),
    CONSTRAINT availability_runtime_authority_revision_chk CHECK ((revision > 0)),
    CONSTRAINT availability_runtime_authority_singleton_chk CHECK ((singleton_key = true)),
