    CONSTRAINT build_orders_status_chk CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'released'::character varying, 'in_progress'::character varying, 'completed'::character varying, 'cancelled'::character varying, 'failed'::character varying])::text[]))),
