    CONSTRAINT channel_exposure_policy_versions_actor_chk CHECK ((((char_length(btrim((created_by)::text)) >= 1) AND (char_length(btrim((created_by)::text)) <= 100)) AND ((change_reason IS NULL) OR ((char_length(btrim((change_reason)::text)) >= 1) AND (char_length(btrim((change_reason)::text)) <= 1000))))),
