    CONSTRAINT channel_exposure_policy_versions_inherit_chk CHECK (((NOT inherit_all) OR (((scope_type)::text <> 'channel'::text) AND (source_fulfillment_node_ids IS NULL) AND (allocation_semantics IS NULL) AND (eligible IS NULL) AND (share_bps IS NULL) AND (holdback_sellable_units IS NULL) AND (max_publish_mode IS NULL) AND (max_publish_sellable_units IS NULL) AND (min_publish_sellable_units IS NULL)))),
    CONSTRAINT channel_exposure_policy_versions_lifecycle_chk CHECK (((((lifecycle_status)::text = 'draft'::text) AND (sealed_by IS NULL) AND (sealed_at IS NULL) AND (retired_by IS NULL) AND (retired_at IS NULL)) OR (((lifecycle_status)::text = 'sealed'::text) AND (sealed_by IS NOT NULL) AND (btrim((sealed_by)::text) <> ''::text) AND (sealed_at IS NOT NULL) AND (retired_by IS NULL) AND (retired_at IS NULL)) OR (((lifecycle_status)::text = 'retired'::text) AND (sealed_by IS NOT NULL) AND (btrim((sealed_by)::text) <> ''::text) AND (sealed_at IS NOT NULL) AND (retired_by IS NOT NULL) AND (btrim((retired_by)::text) <> ''::text) AND (retired_at IS NOT NULL) AND (retired_at >= sealed_at)))),
    CONSTRAINT channel_exposure_policy_versions_predecessor_chk CHECK ((((version = 1) AND (supersedes_policy_id IS NULL)) OR ((version > 1) AND (supersedes_policy_id IS NOT NULL)))),
    CONSTRAINT channel_exposure_policy_versions_quantity_chk CHECK ((((share_bps IS NULL) OR ((share_bps >= 0) AND (share_bps <= 10000))) AND ((holdback_sellable_units IS NULL) OR (holdback_sellable_units >= 0)) AND (((max_publish_mode IS NULL) AND (max_publish_sellable_units IS NULL)) OR (((max_publish_mode)::text = 'unlimited'::text) AND (max_publish_sellable_units IS NULL)) OR (((max_publish_mode)::text = 'units'::text) AND (max_publish_sellable_units IS NOT NULL) AND (max_publish_sellable_units >= 0))) AND ((min_publish_sellable_units IS NULL) OR (min_publish_sellable_units >= 0)))),
    CONSTRAINT channel_exposure_policy_versions_scope_chk CHECK (((((scope_type)::text = 'channel'::text) AND ((scope_key)::text = ('channel:'::text || (channel_id)::text)) AND (product_id IS NULL) AND (product_variant_id IS NULL)) OR (((scope_type)::text = 'product'::text) AND ((scope_key)::text = ((('channel:'::text || (channel_id)::text) || ':product:'::text) || (product_id)::text)) AND (product_id IS NOT NULL) AND (product_variant_id IS NULL)) OR (((scope_type)::text = 'variant'::text) AND ((scope_key)::text = ((('channel:'::text || (channel_id)::text) || ':variant:'::text) || (product_variant_id)::text)) AND (product_id IS NOT NULL) AND (product_variant_id IS NOT NULL)))),
    CONSTRAINT channel_exposure_policy_versions_semantics_chk CHECK (((allocation_semantics IS NULL) OR ((allocation_semantics)::text = ANY ((ARRAY['exposure'::character varying, 'partitioned'::character varying])::text[])))),
    CONSTRAINT channel_exposure_policy_versions_status_chk CHECK (((lifecycle_status)::text = ANY ((ARRAY['draft'::character varying, 'sealed'::character varying, 'retired'::character varying])::text[]))),
    CONSTRAINT channel_exposure_policy_versions_supply_chk CHECK (((source_fulfillment_node_ids IS NULL) OR (((scope_type)::text <> 'channel'::text) AND ((cardinality(source_fulfillment_node_ids) >= 1) AND (cardinality(source_fulfillment_node_ids) <= 100)) AND (array_ndims(source_fulfillment_node_ids) = 1) AND (array_position(source_fulfillment_node_ids, NULL::integer) IS NULL)))),
    CONSTRAINT channel_exposure_policy_versions_value_chk CHECK ((inherit_all OR (source_fulfillment_node_ids IS NOT NULL) OR (allocation_semantics IS NOT NULL) OR (eligible IS NOT NULL) OR (share_bps IS NOT NULL) OR (holdback_sellable_units IS NOT NULL) OR (max_publish_mode IS NOT NULL) OR (min_publish_sellable_units IS NOT NULL))),
    CONSTRAINT channel_exposure_policy_versions_version_chk CHECK ((version > 0))
);


