--

CREATE TABLE inventory.ebay_publication_reconciliation_cycles (
    watch_id bigint NOT NULL,
    revision bigint NOT NULL,
    cycle bigint NOT NULL,
    command_key uuid NOT NULL,
    content_job_id uuid,
    stock_state text NOT NULL,
    error_code text,
    error_message text,
    completed_at timestamp with time zone NOT NULL,
    content_check_kind text,
    content_checked_at timestamp with time zone,
    content_evidence_hash text,
    content_identity_hash text,
    content_proof jsonb,
    CONSTRAINT ebay_publication_reconciliation_cycles_cycle_check CHECK ((cycle > 0)),
    CONSTRAINT ebay_publication_reconciliation_cycles_error_code_check CHECK (((length(error_code) >= 1) AND (length(error_code) <= 100))),
    CONSTRAINT ebay_publication_reconciliation_cycles_error_message_check CHECK ((length(error_message) <= 1000)),
    CONSTRAINT ebay_publication_reconciliation_cycles_revision_check CHECK ((revision > 0)),
    CONSTRAINT ebay_publication_reconciliation_cycles_stock_state_check CHECK ((stock_state = ANY (ARRAY['verified'::text, 'repair_queued'::text, 'blocked'::text]))),
    CONSTRAINT ebay_reconciliation_content_evidence CHECK ((((content_check_kind IS NULL) AND (content_checked_at IS NULL) AND (content_evidence_hash IS NULL) AND (content_identity_hash IS NULL) AND (content_proof IS NULL)) OR ((content_check_kind IS NOT NULL) AND (content_check_kind = ANY (ARRAY['provider_match'::text, 'stock_only'::text])) AND (content_checked_at IS NOT NULL) AND (content_evidence_hash IS NOT NULL) AND (content_identity_hash IS NOT NULL) AND (content_evidence_hash ~ '^[a-f0-9]{64}$'::text) AND (content_identity_hash ~ '^[a-f0-9]{64}$'::text) AND (((content_check_kind = 'provider_match'::text) AND (content_proof IS NULL)) OR ((content_check_kind = 'stock_only'::text) AND (content_proof IS NOT NULL) AND
CASE
    WHEN (jsonb_typeof(content_proof) = 'array'::text) THEN ((jsonb_array_length(content_proof) >= 1) AND (jsonb_array_length(content_proof) <= 250))
    ELSE false
END))))),
    CONSTRAINT ebay_reconciliation_content_outcome CHECK ((((stock_state = 'blocked'::text) AND (content_check_kind IS NULL)) OR ((stock_state <> 'blocked'::text) AND (((content_job_id IS NOT NULL) AND (content_check_kind IS NULL)) OR ((content_job_id IS NULL) AND (content_check_kind IS NOT NULL))))))
);


