--

CREATE TABLE inventory.lot_cost_origins (
    inventory_lot_id integer NOT NULL,
    receiving_line_id integer NOT NULL,
    purchase_order_line_id integer NOT NULL,
    inbound_shipment_line_id integer,
    units_per_variant_snapshot integer NOT NULL,
    received_variant_qty integer NOT NULL,
    purchase_start_base_piece bigint NOT NULL,
    shipment_start_base_piece bigint,
    recorded_by text NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    CONSTRAINT lot_cost_origins_check CHECK (((inbound_shipment_line_id IS NULL) = (shipment_start_base_piece IS NULL))),
    CONSTRAINT lot_cost_origins_purchase_start_base_piece_check CHECK ((purchase_start_base_piece >= 0)),
    CONSTRAINT lot_cost_origins_received_variant_qty_check CHECK ((received_variant_qty > 0)),
    CONSTRAINT lot_cost_origins_recorded_by_check CHECK ((btrim(recorded_by) <> ''::text)),
    CONSTRAINT lot_cost_origins_shipment_start_base_piece_check CHECK ((shipment_start_base_piece >= 0)),
    CONSTRAINT lot_cost_origins_units_per_variant_snapshot_check CHECK ((units_per_variant_snapshot > 0))
);


--
-- Name: effective_lot_cost_origins; Type: VIEW; Schema: inventory; Owner: -
--

CREATE VIEW inventory.effective_lot_cost_origins AS
 SELECT origin.inventory_lot_id,
    origin.receiving_line_id,
    origin.purchase_order_line_id,
    origin.inbound_shipment_line_id,
    COALESCE(amendment.units_per_variant_snapshot, origin.units_per_variant_snapshot) AS units_per_variant_snapshot,
    origin.received_variant_qty,
    COALESCE(amendment.purchase_start_base_piece, origin.purchase_start_base_piece) AS purchase_start_base_piece,
    COALESCE(amendment.shipment_start_base_piece, origin.shipment_start_base_piece) AS shipment_start_base_piece,
    origin.recorded_by,
    origin.recorded_at
   FROM (inventory.lot_cost_origins origin
     LEFT JOIN LATERAL ( SELECT change.amendment_id,
            change.inventory_lot_id,
            change.units_per_variant_snapshot,
            change.purchase_start_base_piece,
            change.shipment_start_base_piece
           FROM inventory.lot_cost_origin_amendments change
          WHERE (change.inventory_lot_id = origin.inventory_lot_id)
          ORDER BY change.amendment_id DESC
         LIMIT 1) amendment ON (true));


