    activated_by character varying(100),
    activated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    destination_kind character varying(30) DEFAULT 'channel_connection'::character varying NOT NULL,
    dropship_store_connection_id integer,
    hold_reason character varying(120),
    held_at timestamp with time zone,
    held_by character varying(100),
    membership_mode character varying(20) DEFAULT 'whole_product'::character varying NOT NULL,
    CONSTRAINT inventory_publication_targets_activation_chk CHECK (((((state)::text = 'disabled'::text) AND (activated_by IS NULL) AND (activated_at IS NULL)) OR (((state)::text = ANY ((ARRAY['preview'::character varying, 'live'::character varying])::text[])) AND (activated_by IS NOT NULL) AND (btrim((activated_by)::text) <> ''::text) AND (activated_at IS NOT NULL)))),
    CONSTRAINT inventory_publication_targets_actor_chk CHECK (((btrim((created_by)::text) <> ''::text) AND ((change_reason IS NULL) OR (btrim((change_reason)::text) <> ''::text)))),
    CONSTRAINT inventory_publication_targets_authority_chk CHECK (((publication_authority)::text = ANY ((ARRAY['echelon'::character varying, 'external_provider'::character varying, 'manual'::character varying])::text[]))),
    CONSTRAINT inventory_publication_targets_destination_chk CHECK (((((destination_kind)::text = 'channel_connection'::text) AND (channel_connection_id IS NOT NULL) AND (dropship_store_connection_id IS NULL)) OR (((destination_kind)::text = 'dropship_store_connection'::text) AND (channel_connection_id IS NULL) AND (dropship_store_connection_id IS NOT NULL)))),
    CONSTRAINT inventory_publication_targets_hold_chk CHECK ((((hold_reason IS NULL) AND (held_at IS NULL) AND (held_by IS NULL)) OR ((hold_reason IS NOT NULL) AND ((hold_reason)::text = btrim((hold_reason)::text)) AND ((hold_reason)::text <> ''::text) AND (held_at IS NOT NULL) AND (held_by IS NOT NULL) AND ((held_by)::text = btrim((held_by)::text)) AND ((held_by)::text <> ''::text)))),
    CONSTRAINT inventory_publication_targets_membership_mode_chk CHECK (((membership_mode)::text = ANY ((ARRAY['whole_product'::character varying, 'explicit'::character varying])::text[]))),
    CONSTRAINT inventory_publication_targets_revision_chk CHECK ((revision > 0)),
    CONSTRAINT inventory_publication_targets_scope_chk CHECK ((((provider_scope_type)::text = ANY ((ARRAY['account'::character varying, 'location'::character varying])::text[])) AND ((char_length(btrim((external_scope_id)::text)) >= 1) AND (char_length(btrim((external_scope_id)::text)) <= 240)))),
    CONSTRAINT inventory_publication_targets_state_chk CHECK (((state)::text = ANY ((ARRAY['disabled'::character varying, 'preview'::character varying, 'live'::character varying])::text[])))
);


