    eligibility_mode character varying(20) NOT NULL,
    definition_hash character varying(64) NOT NULL,
    supersedes_policy_id integer,
    change_reason character varying(1000) NOT NULL,
    idempotency_key character varying(120) NOT NULL,
    request_hash character varying(64) NOT NULL,
    created_by character varying(100) NOT NULL,
    sealed_by character varying(100),
    sealed_at timestamp with time zone,
    retired_by character varying(100),
    retired_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT location_promise_policy_versions_hash_chk CHECK ((((definition_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((request_hash)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT location_promise_policy_versions_lifecycle_chk CHECK (((((lifecycle_status)::text = 'draft'::text) AND (sealed_by IS NULL) AND (sealed_at IS NULL) AND (retired_by IS NULL) AND (retired_at IS NULL)) OR (((lifecycle_status)::text = 'sealed'::text) AND (sealed_by IS NOT NULL) AND (btrim((sealed_by)::text) <> ''::text) AND (sealed_at IS NOT NULL) AND (retired_by IS NULL) AND (retired_at IS NULL)) OR (((lifecycle_status)::text = 'retired'::text) AND (sealed_by IS NOT NULL) AND (btrim((sealed_by)::text) <> ''::text) AND (sealed_at IS NOT NULL) AND (retired_by IS NOT NULL) AND (btrim((retired_by)::text) <> ''::text) AND (retired_at IS NOT NULL) AND (retired_at >= sealed_at)))),
    CONSTRAINT location_promise_policy_versions_mode_chk CHECK (((eligibility_mode)::text = ANY ((ARRAY['inherit'::character varying, 'eligible'::character varying, 'ineligible'::character varying])::text[]))),
    CONSTRAINT location_promise_policy_versions_predecessor_chk CHECK ((((version = 1) AND (supersedes_policy_id IS NULL)) OR ((version > 1) AND (supersedes_policy_id IS NOT NULL)))),
    CONSTRAINT location_promise_policy_versions_reason_chk CHECK (((char_length(btrim((change_reason)::text)) >= 1) AND (char_length(btrim((change_reason)::text)) <= 1000))),
    CONSTRAINT location_promise_policy_versions_status_chk CHECK (((lifecycle_status)::text = ANY ((ARRAY['draft'::character varying, 'sealed'::character varying, 'retired'::character varying])::text[]))),
    CONSTRAINT location_promise_policy_versions_version_chk CHECK ((version > 0))
);


