    CONSTRAINT planner_claim_simulation_runs_hash_chk CHECK ((((request_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((snapshot_fingerprint)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT planner_claim_simulation_runs_nonwriting_chk CHECK ((operational_write_attempted = false)),
    CONSTRAINT planner_claim_simulation_runs_status_chk CHECK (((plan_status)::text = ANY ((ARRAY['satisfied'::character varying, 'partial'::character varying, 'blocked'::character varying])::text[]))),
    CONSTRAINT planner_claim_simulation_runs_time_chk CHECK ((completed_at >= captured_at))
);


