    id integer NOT NULL,
    scope_key character varying(160) NOT NULL,
    scope_type character varying(30) NOT NULL,
    product_variant_id integer,
    warehouse_id integer,
    version integer NOT NULL,
    lifecycle_status character varying(20) DEFAULT 'draft'::character varying NOT NULL,
    policy_mode character varying(30) NOT NULL,
    fixed_units integer,
    days_of_cover_milli_days integer,
    untrusted_demand_fallback_units integer,
    demand_method_version character varying(60),
    definition_hash character varying(64) NOT NULL,
    supersedes_policy_id integer,
    change_reason character varying(1000) NOT NULL,
    idempotency_key character varying(120) NOT NULL,
    request_hash character varying(64) NOT NULL,
    created_by character varying(100) NOT NULL,
    sealed_by character varying(100),
    sealed_at timestamp with time zone,
    retired_by character varying(100),
    retired_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT promise_safety_policy_versions_hash_chk CHECK ((((definition_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((request_hash)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT promise_safety_policy_versions_lifecycle_chk CHECK (((((lifecycle_status)::text = 'draft'::text) AND (sealed_by IS NULL) AND (sealed_at IS NULL) AND (retired_by IS NULL) AND (retired_at IS NULL)) OR (((lifecycle_status)::text = 'sealed'::text) AND (sealed_by IS NOT NULL) AND (btrim((sealed_by)::text) <> ''::text) AND (sealed_at IS NOT NULL) AND (retired_by IS NULL) AND (retired_at IS NULL)) OR (((lifecycle_status)::text = 'retired'::text) AND (sealed_by IS NOT NULL) AND (btrim((sealed_by)::text) <> ''::text) AND (sealed_at IS NOT NULL) AND (retired_by IS NOT NULL) AND (btrim((retired_by)::text) <> ''::text) AND (retired_at IS NOT NULL) AND (retired_at >= sealed_at)))),
    CONSTRAINT promise_safety_policy_versions_mode_chk CHECK ((((policy_mode)::text = ANY ((ARRAY['inherit'::character varying, 'off'::character varying, 'fixed_units'::character varying, 'days_of_cover'::character varying])::text[])) AND (((scope_type)::text <> 'business'::text) OR ((policy_mode)::text <> 'inherit'::text)))),
    CONSTRAINT promise_safety_policy_versions_predecessor_chk CHECK ((((version = 1) AND (supersedes_policy_id IS NULL)) OR ((version > 1) AND (supersedes_policy_id IS NOT NULL)))),
    CONSTRAINT promise_safety_policy_versions_reason_chk CHECK (((char_length(btrim((change_reason)::text)) >= 1) AND (char_length(btrim((change_reason)::text)) <= 1000))),
    CONSTRAINT promise_safety_policy_versions_scope_chk CHECK (((((scope_type)::text = 'business'::text) AND ((scope_key)::text = 'business'::text) AND (product_variant_id IS NULL) AND (warehouse_id IS NULL)) OR (((scope_type)::text = 'network_variant'::text) AND ((scope_key)::text = ('network:variant:'::text || (product_variant_id)::text)) AND (product_variant_id IS NOT NULL) AND (warehouse_id IS NULL)) OR (((scope_type)::text = 'warehouse_variant'::text) AND ((scope_key)::text = ((('warehouse:'::text || (warehouse_id)::text) || ':variant:'::text) || (product_variant_id)::text)) AND (product_variant_id IS NOT NULL) AND (warehouse_id IS NOT NULL)))),
    CONSTRAINT promise_safety_policy_versions_status_chk CHECK (((lifecycle_status)::text = ANY ((ARRAY['draft'::character varying, 'sealed'::character varying, 'retired'::character varying])::text[]))),
    CONSTRAINT promise_safety_policy_versions_value_shape_chk CHECK (((((policy_mode)::text = 'inherit'::text) AND (fixed_units IS NULL) AND (days_of_cover_milli_days IS NULL) AND (untrusted_demand_fallback_units IS NULL) AND (demand_method_version IS NULL)) OR (((policy_mode)::text = 'off'::text) AND (fixed_units IS NULL) AND (days_of_cover_milli_days IS NULL) AND (untrusted_demand_fallback_units IS NULL) AND (demand_method_version IS NULL)) OR (((policy_mode)::text = 'fixed_units'::text) AND (fixed_units IS NOT NULL) AND (fixed_units >= 0) AND (days_of_cover_milli_days IS NULL) AND (untrusted_demand_fallback_units IS NULL) AND (demand_method_version IS NULL)) OR (((policy_mode)::text = 'days_of_cover'::text) AND (fixed_units IS NULL) AND (days_of_cover_milli_days IS NOT NULL) AND (days_of_cover_milli_days > 0) AND (untrusted_demand_fallback_units IS NOT NULL) AND (untrusted_demand_fallback_units >= 0) AND (demand_method_version IS NOT NULL) AND (btrim((demand_method_version)::text) <> ''::text)))),
    CONSTRAINT promise_safety_policy_versions_version_chk CHECK ((version > 0))
);


