    CONSTRAINT quantity_commands_idempotency_key_check CHECK ((length(btrim((idempotency_key)::text)) > 0)),
    CONSTRAINT quantity_commands_kind_check CHECK (((kind)::text = ANY ((ARRAY['opening'::character varying, 'receive'::character varying, 'receipt_reversal'::character varying, 'reserve'::character varying, 'release'::character varying, 'pick'::character varying, 'unpick'::character varying, 'pack'::character varying, 'unpack'::character varying, 'ship'::character varying, 'transfer'::character varying, 'transform'::character varying, 'return'::character varying, 'adjust'::character varying, 'supplier_return'::character varying])::text[]))),
    CONSTRAINT quantity_commands_reason_check CHECK ((length(btrim((reason)::text)) > 0)),
