--
-- Name: quantity_entries; Type: TABLE; Schema: inventory; Owner: -
--

CREATE TABLE inventory.quantity_entries (
    command_id bigint NOT NULL,
    inventory_lot_id integer NOT NULL,
    inventory_level_id integer NOT NULL,
    product_variant_id integer NOT NULL,
    warehouse_location_id integer NOT NULL,
    warehouse_id integer NOT NULL,
    on_hand_delta integer NOT NULL,
    reserved_delta integer NOT NULL,
    picked_delta integer NOT NULL,
    packed_delta integer NOT NULL,
    on_hand_before integer NOT NULL,
    reserved_before integer NOT NULL,
    picked_before integer NOT NULL,
    packed_before integer NOT NULL,
    on_hand_after integer NOT NULL,
    reserved_after integer NOT NULL,
    picked_after integer NOT NULL,
    packed_after integer NOT NULL,
    CONSTRAINT quantity_entries_check CHECK (((reserved_before >= 0) AND (reserved_before <= on_hand_before))),
    CONSTRAINT quantity_entries_check1 CHECK (((reserved_after >= 0) AND (reserved_after <= on_hand_after))),
    CONSTRAINT quantity_entries_check2 CHECK (((on_hand_after)::bigint = ((on_hand_before)::bigint + on_hand_delta))),
    CONSTRAINT quantity_entries_check3 CHECK (((reserved_after)::bigint = ((reserved_before)::bigint + reserved_delta))),
    CONSTRAINT quantity_entries_check4 CHECK (((picked_after)::bigint = ((picked_before)::bigint + picked_delta))),
    CONSTRAINT quantity_entries_check5 CHECK (((packed_after)::bigint = ((packed_before)::bigint + packed_delta))),
    CONSTRAINT quantity_entries_on_hand_after_check CHECK ((on_hand_after >= 0)),
    CONSTRAINT quantity_entries_on_hand_before_check CHECK ((on_hand_before >= 0)),
    CONSTRAINT quantity_entries_packed_after_check CHECK ((packed_after >= 0)),
    CONSTRAINT quantity_entries_packed_before_check CHECK ((packed_before >= 0)),
    CONSTRAINT quantity_entries_picked_after_check CHECK ((picked_after >= 0)),
    CONSTRAINT quantity_entries_picked_before_check CHECK ((picked_before >= 0))
);


