);


--
-- Name: quantity_level_balances; Type: VIEW; Schema: inventory; Owner: -
--

CREATE VIEW inventory.quantity_level_balances AS
 SELECT inventory_level_id,
    product_variant_id,
    warehouse_location_id,
    warehouse_id,
    sum(on_hand_delta) AS on_hand,
    sum(reserved_delta) AS reserved,
    sum(picked_delta) AS picked,
    sum(packed_delta) AS packed
   FROM inventory.quantity_entries
  GROUP BY inventory_level_id, product_variant_id, warehouse_location_id, warehouse_id;


--
-- Name: quantity_lot_balances; Type: VIEW; Schema: inventory; Owner: -
--

CREATE VIEW inventory.quantity_lot_balances AS
 SELECT inventory_lot_id,
    inventory_level_id,
    product_variant_id,
    warehouse_location_id,
    warehouse_id,
    sum(on_hand_delta) AS on_hand,
    sum(reserved_delta) AS reserved,
    sum(picked_delta) AS picked,
    sum(packed_delta) AS packed
   FROM inventory.quantity_entries
  GROUP BY inventory_lot_id, inventory_level_id, product_variant_id, warehouse_location_id, warehouse_id;


