    CONSTRAINT quantity_operation_receipts_check CHECK (((((outcome)::text = 'posted'::text) AND (quantity_command_id IS NOT NULL)) OR (((outcome)::text = 'no_movement'::text) AND (quantity_command_id IS NULL)))),
    CONSTRAINT quantity_operation_receipts_idempotency_key_check CHECK ((length(btrim((idempotency_key)::text)) > 0)),
    CONSTRAINT quantity_operation_receipts_outcome_check CHECK (((outcome)::text = ANY ((ARRAY['posted'::character varying, 'no_movement'::character varying])::text[]))),
    CONSTRAINT quantity_operation_receipts_request_hash_check CHECK (((request_hash)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT quantity_operation_receipts_result_check CHECK ((jsonb_typeof(result) = 'object'::text))
);


--
-- Name: quantity_provider_request_results; Type: TABLE; Schema: inventory; Owner: -
--

CREATE TABLE inventory.quantity_provider_request_results (
    request_id bigint NOT NULL,
    outcome text NOT NULL,
    http_status integer,
    provider_request_id text,
    response_hash text,
    error_codes text[] NOT NULL,
    retry_not_before timestamp with time zone,
    cooldown_scope text,
    recorded_at timestamp with time zone NOT NULL,
    request_terminated boolean,
    CONSTRAINT quantity_provider_finality_requires_response CHECK (((request_terminated IS DISTINCT FROM true) OR ((http_status IS NOT NULL) AND (response_hash IS NOT NULL) AND ((http_status = ANY (ARRAY[200, 201, 204, 207])) OR (((http_status >= 400) AND (http_status <= 599)) AND (http_status <> 408)))))),
    CONSTRAINT quantity_provider_request_results_check CHECK (((outcome <> 'rejected'::text) OR ((http_status IS NOT NULL) AND (response_hash IS NOT NULL)))),
    CONSTRAINT quantity_provider_request_results_check1 CHECK (((retry_not_before IS NULL) OR (retry_not_before >= recorded_at))),
    CONSTRAINT quantity_provider_request_results_check2 CHECK (((retry_not_before IS NULL) = (cooldown_scope IS NULL))),
    CONSTRAINT quantity_provider_request_results_cooldown_scope_check CHECK ((cooldown_scope = ANY (ARRAY['item'::text, 'account'::text]))),
    CONSTRAINT quantity_provider_request_results_error_codes_check CHECK ((cardinality(error_codes) <= 25)),
    CONSTRAINT quantity_provider_request_results_http_status_check CHECK (((http_status >= 100) AND (http_status <= 599))),
    CONSTRAINT quantity_provider_request_results_outcome_check CHECK ((outcome = ANY (ARRAY['completed'::text, 'rejected'::text, 'uncertain'::text]))),
    CONSTRAINT quantity_provider_request_results_provider_request_id_check CHECK (((length(provider_request_id) >= 1) AND (length(provider_request_id) <= 200))),
    CONSTRAINT quantity_provider_request_results_response_hash_check CHECK ((response_hash ~ '^[a-f0-9]{64}$'::text))
);


--
-- Name: COLUMN quantity_provider_request_results.request_terminated; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.quantity_provider_request_results.request_terminated IS 'Validated synchronous provider response has terminated; does not prove successful quantity application. NULL means no finality evidence was retained.';


