--
-- Name: quantity_publication_attempts; Type: TABLE; Schema: inventory; Owner: -
--

CREATE TABLE inventory.quantity_publication_attempts (
    id bigint NOT NULL,
    owner_token uuid NOT NULL,
    owner_kind text NOT NULL,
    gate_epoch bigint NOT NULL,
    scope_key text NOT NULL,
    scope jsonb NOT NULL,
    outbox_id bigint,
    planned_outbox_id bigint,
    affected_scope_keys text[] NOT NULL,
    affected_scopes jsonb NOT NULL,
    planned_outbox_ids bigint[] DEFAULT '{}'::bigint[] NOT NULL,
    state text NOT NULL,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    outcome_hash text,
    error_code text,
    resolution_basis text,
    listing_setup_operation_id character varying(120),
    listing_setup_intent jsonb,
    request_journal_contract jsonb,
    CONSTRAINT publication_request_journal_contract CHECK (((request_journal_contract IS NULL) OR ((((scope ->> 'providerKey'::text) = 'ebay'::text) AND (jsonb_typeof(request_journal_contract) = 'object'::text) AND ((request_journal_contract ->> 'version'::text) = '1'::text) AND ((request_journal_contract ->> 'provider'::text) = 'ebay'::text) AND ((request_journal_contract ->> 'method'::text) = ANY (ARRAY['POST'::text, 'PUT'::text, 'DELETE'::text])) AND ((request_journal_contract ->> 'path'::text) ~ '^/sell/inventory/v1/[^?#[:space:]]+$'::text) AND (length((request_journal_contract ->> 'path'::text)) <= 1024) AND ((request_journal_contract ->> 'requestHash'::text) ~ '^[a-f0-9]{64}$'::text) AND (request_journal_contract ?& ARRAY['version'::text, 'provider'::text, 'method'::text, 'path'::text, 'requestHash'::text])) IS TRUE))),
    CONSTRAINT publication_response_terminal_state CHECK (((resolution_basis IS DISTINCT FROM 'provider_response_terminal'::text) OR (state = 'resolved'::text))),
    CONSTRAINT quantity_publication_attempts_basis CHECK ((resolution_basis = ANY (ARRAY['owner_completion'::text, 'operator_attestation'::text, 'provider_rejection'::text, 'owner_preflight_no_request'::text, 'provider_response_terminal'::text]))),
    CONSTRAINT quantity_publication_attempts_check CHECK (((jsonb_typeof(affected_scopes) = 'array'::text) AND (jsonb_array_length(affected_scopes) = cardinality(affected_scope_keys)))),
    CONSTRAINT quantity_publication_attempts_check1 CHECK (((owner_kind = 'outbox'::text) = (outbox_id IS NOT NULL))),
    CONSTRAINT quantity_publication_attempts_gate_epoch_check CHECK ((gate_epoch >= 0)),
    CONSTRAINT quantity_publication_attempts_no_request_basis CHECK (((state = 'not_sent'::text) = (NOT (resolution_basis IS DISTINCT FROM 'owner_preflight_no_request'::text)))),
    CONSTRAINT quantity_publication_attempts_outcome_hash_check CHECK (((outcome_hash IS NULL) OR (length(outcome_hash) = 64))),
    CONSTRAINT quantity_publication_attempts_owner_kind_chk CHECK ((owner_kind = ANY (ARRAY['legacy'::text, 'outbox'::text, 'listing_setup_zero'::text]))),
    CONSTRAINT quantity_publication_attempts_rejection_basis CHECK (((state = 'rejected'::text) = (NOT (resolution_basis IS DISTINCT FROM 'provider_rejection'::text)))),
    CONSTRAINT quantity_publication_attempts_scope_check CHECK ((jsonb_typeof(scope) = 'object'::text)),
    CONSTRAINT quantity_publication_attempts_scope_key_check CHECK ((length(scope_key) = 64)),
    CONSTRAINT quantity_publication_attempts_setup_owner_chk CHECK (((owner_kind = 'listing_setup_zero'::text) = (listing_setup_operation_id IS NOT NULL))),
    CONSTRAINT quantity_publication_attempts_state CHECK ((state = ANY (ARRAY['running'::text, 'succeeded'::text, 'uncertain'::text, 'resolved'::text, 'rejected'::text, 'not_sent'::text, 'superseded_unknown'::text]))),
    CONSTRAINT quantity_publication_attempts_terminal CHECK (((state = ANY (ARRAY['succeeded'::text, 'resolved'::text, 'rejected'::text, 'not_sent'::text])) = (completed_at IS NOT NULL))),
    CONSTRAINT quantity_publication_setup_intent_check CHECK (((listing_setup_intent IS NULL) OR ((listing_setup_operation_id IS NOT NULL) AND (jsonb_typeof(listing_setup_intent) = 'object'::text))))
);


