    CONSTRAINT transformation_model_versions_operator_input_chk CHECK (((operator_input_hash IS NULL) OR (((origin)::text = 'operator'::text) AND ((operator_input_hash)::text ~ '^[0-9a-f]{64}$'::text)))),
