    CONSTRAINT warehouse_settings_rfq_draft_automation_chk CHECK ((((rfq_draft_automation_mode)::text = ANY ((ARRAY['manual'::character varying, 'preferred_vendor'::character varying])::text[])) AND ((rfq_draft_minimum_confidence)::text = ANY ((ARRAY['high'::character varying, 'medium'::character varying])::text[])) AND ((rfq_draft_maximum_lines_per_run >= 1) AND (rfq_draft_maximum_lines_per_run <= 500))))
);


