    owner_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    admission_completed_at timestamp with time zone,
    admission_error text,
    admission_refusal jsonb,
    next_attempt_at timestamp with time zone NOT NULL,
