    CONSTRAINT channel_sync_batches_admission_error_check CHECK ((length(admission_error) <= 1000)),
    CONSTRAINT channel_sync_batches_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT channel_sync_batches_check CHECK (((jsonb_typeof(destination) = 'object'::text) AND (destination ?& ARRAY['channelId'::text, 'provider'::text, 'connectionId'::text, 'accountId'::text, 'environment'::text, 'marketplaceId'::text]) AND (jsonb_typeof((destination -> 'channelId'::text)) = 'number'::text) AND (((destination ->> 'channelId'::text))::integer = channel_id))),
    CONSTRAINT channel_sync_batches_check1 CHECK (((admission_refusal IS NULL) OR ((admission_completed_at IS NOT NULL) AND (jsonb_typeof(admission_refusal) = 'object'::text) AND (admission_refusal ?& ARRAY['code'::text, 'message'::text]) AND (jsonb_typeof((admission_refusal -> 'code'::text)) = 'string'::text) AND (jsonb_typeof((admission_refusal -> 'message'::text)) = 'string'::text) AND ((length((admission_refusal ->> 'code'::text)) >= 1) AND (length((admission_refusal ->> 'code'::text)) <= 100)) AND ((length((admission_refusal ->> 'message'::text)) >= 1) AND (length((admission_refusal ->> 'message'::text)) <= 1000))))),
    CONSTRAINT channel_sync_batches_check2 CHECK (((lease_token IS NULL) = (lease_until IS NULL))),
    CONSTRAINT channel_sync_batches_check3 CHECK (((admission_completed_at IS NULL) OR (lease_token IS NULL))),
    CONSTRAINT channel_sync_batches_member_count_check CHECK (((member_count >= 0) AND (member_count <= 10000)))
);


