--
-- Name: listing_member_retirement_sources; Type: VIEW; Schema: marketplace; Owner: -
--

CREATE VIEW marketplace.listing_member_retirement_sources AS
 WITH direct_members AS (
         SELECT COALESCE(f.channel_id, l.channel_id) AS channel_id,
            COALESCE(f.product_variant_id, l.product_variant_id) AS variant_id,
            COALESCE(l.external_product_id, f.channel_product_id) AS product_id,
            COALESCE(l.external_variant_id, f.channel_variant_id) AS variant_external_id,
            COALESCE(l.external_sku, f.channel_sku) AS sku,
            f.channel_inventory_item_id AS inventory_id,
            (((l.external_variant_id IS NOT NULL) AND (f.channel_variant_id IS NOT NULL) AND ((l.external_variant_id)::text <> (f.channel_variant_id)::text)) OR ((l.external_product_id IS NOT NULL) AND (f.channel_product_id IS NOT NULL) AND ((l.external_product_id)::text <> (f.channel_product_id)::text)) OR ((l.external_sku IS NOT NULL) AND (f.channel_sku IS NOT NULL) AND ((l.external_sku)::text <> (f.channel_sku)::text))) AS conflict
           FROM (channels.channel_feeds f
             FULL JOIN channels.channel_listings l ON (((l.channel_id = f.channel_id) AND (l.product_variant_id = f.product_variant_id))))
          WHERE (COALESCE(l.external_variant_id, f.channel_variant_id, l.external_product_id, f.channel_product_id, l.external_sku, f.channel_sku) IS NOT NULL)
        ), sources AS (
         SELECT v.id AS product_variant_id,
            v.product_id,
            concat_ws(':'::text, (p.updated_at)::text, (v.updated_at)::text) AS source_revision,
            ((NOT v.is_active) OR (NOT p.is_active) OR ((p.status)::text = 'archived'::text)) AS catalog_archived,
            jsonb_build_object('destinationKind', 'channel_connection', 'connectionId', cc.id, 'channelId', c.id, 'vendorId', NULL::unknown, 'provider', lower((c.provider)::text), 'accountId',
                CASE lower((c.provider)::text)
                    WHEN 'ebay'::text THEN token.external_account_id
                    WHEN 'shopify'::text THEN cc.shop_domain
                    WHEN 'walmart'::text THEN wc.partner_id
                    ELSE NULL::character varying
                END, 'environment', COALESCE(token.environment, wc.environment, 'production'::character varying), 'market',
                CASE lower((c.provider)::text)
                    WHEN 'ebay'::text THEN COALESCE((cc.metadata ->> 'marketplaceId'::text), 'EBAY_US'::text)
                    WHEN 'walmart'::text THEN (COALESCE(wc.market, 'us'::character varying))::text
                    ELSE 'shop'::text
                END, 'productId', v.product_id, 'productVariantId', v.id, 'externalSku', member.sku, 'externalProductId', member.product_id, 'externalVariantId', member.variant_external_id, 'externalInventoryItemId', member.inventory_id, 'identityConflict', COALESCE(member.conflict, false)) AS identity
           FROM ((((((direct_members member
             JOIN catalog.product_variants v ON ((v.id = member.variant_id)))
             JOIN catalog.products p ON ((p.id = v.product_id)))
             JOIN channels.channels c ON ((c.id = member.channel_id)))
             JOIN channels.channel_connections cc ON ((cc.channel_id = c.id)))
             LEFT JOIN ebay.ebay_oauth_tokens token ON (((token.channel_id = c.id) AND (lower((c.provider)::text) = 'ebay'::text) AND ((token.external_account_identity_scheme)::text = 'provider_user_id'::text) AND (token.external_account_verified_at IS NOT NULL))))
             LEFT JOIN channels.walmart_connections wc ON (((wc.connection_id = cc.id) AND (lower((c.provider)::text) = 'walmart'::text))))
        UNION ALL
         SELECT v.id,
            v.product_id,
            concat_ws(':'::text, (p.updated_at)::text, (v.updated_at)::text) AS concat_ws,
            ((NOT v.is_active) OR (NOT p.is_active) OR ((p.status)::text = 'archived'::text)),
            jsonb_build_object('destinationKind', 'dropship_store_connection', 'connectionId', sc.id, 'channelId', NULL::unknown, 'vendorId', sc.vendor_id, 'provider', lower((sc.platform)::text), 'accountId',
                CASE
                    WHEN ((sc.platform)::text = 'shopify'::text) THEN sc.shop_domain
                    ELSE sc.external_account_id
                END, 'environment', COALESCE(sc.provider_environment, 'production'::character varying), 'market',
                CASE
                    WHEN ((sc.platform)::text = 'ebay'::text) THEN COALESCE((((intent.result -> 'listingIntent'::text) -> 'marketplaceConfig'::text) ->> 'marketplaceId'::text), 'EBAY_US'::text)
                    ELSE 'shop'::text
                END, 'productId', v.product_id, 'productVariantId', v.id, 'externalSku', ((intent.result -> 'listingIntent'::text) ->> 'sku'::text), 'externalProductId', l.external_listing_id, 'externalVariantId', l.external_offer_id, 'externalInventoryItemId', NULL::unknown, 'identityConflict', false) AS jsonb_build_object
           FROM ((((dropship.dropship_vendor_listings l
             JOIN dropship.dropship_store_connections sc ON (((sc.id = l.store_connection_id) AND (sc.vendor_id = l.vendor_id))))
             JOIN catalog.product_variants v ON ((v.id = l.product_variant_id)))
             JOIN catalog.products p ON ((p.id = v.product_id)))
             LEFT JOIN LATERAL ( SELECT ji.result
                   FROM (dropship.dropship_listing_push_job_items ji
                     JOIN dropship.dropship_listing_push_jobs j ON ((j.id = ji.job_id)))
                  WHERE ((ji.listing_id = l.id) AND (ji.product_variant_id = v.id) AND (j.store_connection_id = sc.id) AND (j.vendor_id = sc.vendor_id) AND ((ji.status)::text = 'completed'::text) AND ((ji.action)::text = 'push'::text))
                  ORDER BY ji.id DESC
                 LIMIT 1) intent ON (true))
          WHERE ((l.external_listing_id IS NOT NULL) OR (l.external_offer_id IS NOT NULL))
        ), checked_sources AS (
         SELECT sources.product_variant_id,
            sources.product_id,
            sources.source_revision,
            sources.catalog_archived,
            (sources.identity || jsonb_build_object('identityConflict', (((sources.identity ->> 'identityConflict'::text))::boolean OR (count(*) OVER (PARTITION BY (sources.identity ->> 'destinationKind'::text),
                CASE
                    WHEN ((sources.identity ->> 'destinationKind'::text) = 'channel_connection'::text) THEN (sources.identity ->> 'channelId'::text)
                    ELSE (sources.identity ->> 'connectionId'::text)
                END, sources.product_variant_id) > 1) OR (((sources.identity ->> 'externalSku'::text) IS NOT NULL) AND (min(sources.product_variant_id) OVER sku_alias <> max(sources.product_variant_id) OVER sku_alias)) OR (((sources.identity ->> 'externalVariantId'::text) IS NOT NULL) AND (min(sources.product_variant_id) OVER variant_alias <> max(sources.product_variant_id) OVER variant_alias))))) AS identity
           FROM sources
          WINDOW sku_alias AS (PARTITION BY (sources.identity ->> 'provider'::text), (sources.identity ->> 'environment'::text), (sources.identity ->> 'accountId'::text), (sources.identity ->> 'market'::text), (sources.identity ->> 'externalSku'::text)), variant_alias AS (PARTITION BY (sources.identity ->> 'provider'::text), (sources.identity ->> 'environment'::text), (sources.identity ->> 'accountId'::text), (sources.identity ->> 'market'::text), (sources.identity ->> 'externalVariantId'::text))
        )
 SELECT product_variant_id,
    product_id,
    source_revision,
    identity
   FROM checked_sources
  WHERE catalog_archived;


--
-- Name: listing_member_retirements; Type: TABLE; Schema: marketplace; Owner: -
--

CREATE TABLE marketplace.listing_member_retirements (
    id uuid NOT NULL,
    identity_key text NOT NULL,
    identity jsonb NOT NULL,
    source_identity jsonb NOT NULL,
    source_revision text NOT NULL,
    product_id integer NOT NULL,
    product_variant_id integer NOT NULL,
    state text NOT NULL,
    code text,
    message text,
    verified_at timestamp with time zone,
    next_attempt_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    dispatch_status text DEFAULT 'none'::text NOT NULL,
    dispatch_key uuid,
    verification_attempts integer DEFAULT 0 NOT NULL,
    recovery_required boolean DEFAULT false NOT NULL,
    CONSTRAINT listing_member_retirements_check CHECK (((state = 'retired'::text) = (verified_at IS NOT NULL))),
    CONSTRAINT listing_member_retirements_check1 CHECK ((((state = ANY (ARRAY['retired'::text, 'superseded'::text])) OR ((state = 'failed'::text) AND COALESCE((code = 'LISTING_MEMBER_IDENTITY_INVALID'::text), false))) = (next_attempt_at IS NULL))),
    CONSTRAINT listing_member_retirements_check2 CHECK (((((identity ->> 'productId'::text))::integer = product_id) AND (((identity ->> 'productVariantId'::text))::integer = product_variant_id))),
    CONSTRAINT listing_member_retirements_dispatch_status_check CHECK ((dispatch_status = ANY (ARRAY['none'::text, 'unknown'::text, 'accepted'::text, 'authorized'::text]))),
    CONSTRAINT listing_member_retirements_identity_check CHECK ((jsonb_typeof(identity) = 'object'::text)),
    CONSTRAINT listing_member_retirements_identity_key_check CHECK ((identity_key ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT listing_member_retirements_source_identity_check CHECK ((jsonb_typeof(source_identity) = 'object'::text)),
    CONSTRAINT listing_member_retirements_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'retiring'::text, 'retired'::text, 'failed'::text, 'superseded'::text]))),
    CONSTRAINT listing_member_retirements_verification_attempts_check CHECK ((verification_attempts >= 0)),
    CONSTRAINT listing_member_retirements_version_check CHECK ((version > 0))
);


