CREATE TABLE marketplace.listing_publication_members (
    id bigint NOT NULL,
    publication_id bigint NOT NULL,
    scope_id bigint NOT NULL,
    product_id integer NOT NULL,
    product_variant_id integer NOT NULL,
    sku_snapshot character varying(100) NOT NULL,
    disposition character varying(20) NOT NULL,
    reason_code character varying(100),
    external_variant_id character varying(255),
    external_offer_id character varying(255),
    external_inventory_item_id character varying(255),
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT listing_publication_members_disposition_chk CHECK (((disposition)::text = ANY ((ARRAY['included'::character varying, 'excluded'::character varying])::text[]))),
    CONSTRAINT listing_publication_members_external_identity_chk CHECK ((((external_variant_id IS NULL) OR (((external_variant_id)::text = btrim((external_variant_id)::text)) AND ((external_variant_id)::text <> ''::text))) AND ((external_offer_id IS NULL) OR (((external_offer_id)::text = btrim((external_offer_id)::text)) AND ((external_offer_id)::text <> ''::text))) AND ((external_inventory_item_id IS NULL) OR (((external_inventory_item_id)::text = btrim((external_inventory_item_id)::text)) AND ((external_inventory_item_id)::text <> ''::text))))),
    CONSTRAINT listing_publication_members_metadata_chk CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT listing_publication_members_reason_chk CHECK (((((disposition)::text = 'included'::text) AND (reason_code IS NULL)) OR (((disposition)::text = 'excluded'::text) AND (reason_code IS NOT NULL) AND ((reason_code)::text = btrim((reason_code)::text)) AND ((reason_code)::text <> ''::text)))),
    CONSTRAINT listing_publication_members_sku_chk CHECK ((((sku_snapshot)::text = btrim((sku_snapshot)::text)) AND ((sku_snapshot)::text <> ''::text))),
    CONSTRAINT listing_publication_members_time_chk CHECK ((updated_at >= created_at))
);


