-- Name: listing_publications; Type: TABLE; Schema: marketplace; Owner: -
--

CREATE TABLE marketplace.listing_publications (
    id bigint NOT NULL,
    scope_id bigint NOT NULL,
    product_id integer NOT NULL,
    generation integer NOT NULL,
    supersedes_publication_id bigint,
    status character varying(30) NOT NULL,
    desired_state_hash character varying(64) NOT NULL,
    provider_publication_key character varying(255),
    external_listing_id character varying(255),
    external_url text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by_type character varying(20) NOT NULL,
    created_by_id character varying(255) NOT NULL,
    published_at timestamp with time zone,
    verified_at timestamp with time zone,
    retired_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT listing_publications_actor_chk CHECK ((((created_by_type)::text = ANY ((ARRAY['user'::character varying, 'service'::character varying, 'system'::character varying])::text[])) AND ((created_by_id)::text = btrim((created_by_id)::text)) AND ((created_by_id)::text <> ''::text))),
    CONSTRAINT listing_publications_external_identity_chk CHECK ((((provider_publication_key IS NULL) OR (((provider_publication_key)::text = btrim((provider_publication_key)::text)) AND ((provider_publication_key)::text <> ''::text))) AND ((external_listing_id IS NULL) OR (((external_listing_id)::text = btrim((external_listing_id)::text)) AND ((external_listing_id)::text <> ''::text))) AND ((external_url IS NULL) OR (external_listing_id IS NOT NULL)) AND ((published_at IS NULL) OR (external_listing_id IS NOT NULL)))),
    CONSTRAINT listing_publications_generation_chk CHECK ((generation > 0)),
    CONSTRAINT listing_publications_hash_chk CHECK (((desired_state_hash)::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT listing_publications_lifecycle_chk CHECK (((((status)::text = 'planned'::text) AND (provider_publication_key IS NULL) AND (external_listing_id IS NULL) AND (external_url IS NULL) AND (published_at IS NULL) AND (verified_at IS NULL) AND (retired_at IS NULL)) OR (((status)::text = 'staged'::text) AND (verified_at IS NULL) AND (retired_at IS NULL)) OR (((status)::text = 'failed'::text) AND (verified_at IS NULL) AND (retired_at IS NULL)) OR (((status)::text = 'active'::text) AND (external_listing_id IS NOT NULL) AND (published_at IS NOT NULL) AND (verified_at IS NOT NULL) AND (retired_at IS NULL)) OR (((status)::text = ANY ((ARRAY['superseded'::character varying, 'withdrawn'::character varying])::text[])) AND (external_listing_id IS NOT NULL) AND (published_at IS NOT NULL) AND (verified_at IS NOT NULL) AND (retired_at IS NOT NULL)))),
    CONSTRAINT listing_publications_metadata_chk CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT listing_publications_status_chk CHECK (((status)::text = ANY ((ARRAY['planned'::character varying, 'staged'::character varying, 'active'::character varying, 'superseded'::character varying, 'withdrawn'::character varying, 'failed'::character varying])::text[]))),
    CONSTRAINT listing_publications_time_chk CHECK (((updated_at >= created_at) AND ((published_at IS NULL) OR (published_at >= created_at)) AND ((verified_at IS NULL) OR ((published_at IS NOT NULL) AND (verified_at >= published_at))) AND ((retired_at IS NULL) OR ((verified_at IS NOT NULL) AND (retired_at >= verified_at)))))
);


