    CONSTRAINT listing_registrations_evidence_chk CHECK ((jsonb_typeof(evidence) = 'object'::text)),
    CONSTRAINT listing_registrations_hash_chk CHECK ((((request_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((observation_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((desired_state_hash)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT listing_registrations_idempotency_chk CHECK ((((idempotency_key)::text = btrim((idempotency_key)::text)) AND ((idempotency_key)::text <> ''::text))),
