CREATE TABLE marketplace.listing_replacement_events (
    id bigint NOT NULL,
    operation_id bigint NOT NULL,
    sequence integer NOT NULL,
    event_type character varying(100) NOT NULL,
    phase character varying(30) NOT NULL,
    step_id bigint,
    actor_type character varying(20) NOT NULL,
    actor_id character varying(255) NOT NULL,
    from_status character varying(40),
    to_status character varying(40) NOT NULL,
    attempt integer DEFAULT 0 NOT NULL,
    subject_state_version integer NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT listing_replacement_events_actor_chk CHECK ((((actor_type)::text = ANY ((ARRAY['user'::character varying, 'service'::character varying, 'system'::character varying])::text[])) AND ((actor_id)::text = btrim((actor_id)::text)) AND ((actor_id)::text <> ''::text))),
    CONSTRAINT listing_replacement_events_attempt_chk CHECK (((attempt >= 0) AND (subject_state_version > 0))),
    CONSTRAINT listing_replacement_events_evidence_chk CHECK ((jsonb_typeof(evidence) = 'object'::text)),
    CONSTRAINT listing_replacement_events_phase_chk CHECK (((phase)::text = ANY ((ARRAY['preflight'::character varying, 'cutover'::character varying, 'publish'::character varying, 'verify'::character varying, 'switch_mapping'::character varying, 'compensate'::character varying, 'complete'::character varying])::text[]))),
    CONSTRAINT listing_replacement_events_sequence_chk CHECK ((sequence > 0)),
    CONSTRAINT listing_replacement_events_status_chk CHECK ((((step_id IS NULL) AND ((from_status IS NULL) OR ((from_status)::text = ANY ((ARRAY['planned'::character varying, 'running'::character varying, 'compensating'::character varying, 'completed'::character varying, 'failed'::character varying, 'manual_recovery_required'::character varying, 'cancelled'::character varying])::text[]))) AND ((to_status)::text = ANY ((ARRAY['planned'::character varying, 'running'::character varying, 'compensating'::character varying, 'completed'::character varying, 'failed'::character varying, 'manual_recovery_required'::character varying, 'cancelled'::character varying])::text[]))) OR ((step_id IS NOT NULL) AND ((from_status IS NULL) OR ((from_status)::text = ANY ((ARRAY['pending'::character varying, 'running'::character varying, 'succeeded'::character varying, 'failed'::character varying])::text[]))) AND ((to_status)::text = ANY ((ARRAY['pending'::character varying, 'running'::character varying, 'succeeded'::character varying, 'failed'::character varying])::text[]))))),
    CONSTRAINT listing_replacement_events_type_chk CHECK ((((event_type)::text = btrim((event_type)::text)) AND ((event_type)::text ~ '^[a-z][a-z0-9_.:-]{0,99}$'::text)))
);


