--

CREATE TABLE marketplace.listing_replacement_operations (
    id bigint NOT NULL,
    scope_id bigint NOT NULL,
    source_publication_id bigint NOT NULL,
    target_publication_id bigint NOT NULL,
    idempotency_key character varying(200) NOT NULL,
    request_hash character varying(64) NOT NULL,
    desired_state_hash character varying(64) NOT NULL,
    status character varying(40) DEFAULT 'planned'::character varying NOT NULL,
    current_phase character varying(30) DEFAULT 'preflight'::character varying NOT NULL,
    state_version integer DEFAULT 1 NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    attempt_limit integer DEFAULT 5 NOT NULL,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    requested_by_type character varying(20) NOT NULL,
    requested_by_id character varying(255) NOT NULL,
    correlation_id character varying(100),
    error_code character varying(100),
    error_message character varying(2000),
    recovery_context jsonb,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT listing_replacement_operations_actor_chk CHECK ((((requested_by_type)::text = ANY ((ARRAY['user'::character varying, 'service'::character varying, 'system'::character varying])::text[])) AND ((requested_by_id)::text = btrim((requested_by_id)::text)) AND ((requested_by_id)::text <> ''::text))),
    CONSTRAINT listing_replacement_operations_attempt_chk CHECK (((attempt_count >= 0) AND ((attempt_limit >= 1) AND (attempt_limit <= 100)) AND (attempt_count <= attempt_limit) AND (state_version > 0))),
    CONSTRAINT listing_replacement_operations_error_chk CHECK ((((error_code IS NULL) AND (error_message IS NULL)) OR ((error_code IS NOT NULL) AND (btrim((error_code)::text) <> ''::text) AND (error_message IS NOT NULL) AND (btrim((error_message)::text) <> ''::text)))),
    CONSTRAINT listing_replacement_operations_hash_chk CHECK ((((request_hash)::text ~ '^[0-9a-f]{64}$'::text) AND ((desired_state_hash)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT listing_replacement_operations_idempotency_chk CHECK ((((idempotency_key)::text = btrim((idempotency_key)::text)) AND ((idempotency_key)::text <> ''::text))),
