    CONSTRAINT listing_replacement_operations_time_chk CHECK (((updated_at >= created_at) AND ((started_at IS NULL) OR (started_at >= created_at)) AND ((completed_at IS NULL) OR ((completed_at >= created_at) AND ((started_at IS NULL) OR (completed_at >= started_at)))) AND ((lease_expires_at IS NULL) OR (lease_expires_at > updated_at))))
);


