    CONSTRAINT listing_replacement_steps_attempt_chk CHECK (((state_version > 0) AND (attempt_count >= 0) AND ((attempt_limit >= 1) AND (attempt_limit <= 100)) AND (attempt_count <= attempt_limit))),
    CONSTRAINT listing_replacement_steps_error_chk CHECK ((((error_code IS NULL) AND (error_message IS NULL)) OR ((error_code IS NOT NULL) AND (btrim((error_code)::text) <> ''::text) AND (error_message IS NOT NULL) AND (btrim((error_message)::text) <> ''::text)))),
    CONSTRAINT listing_replacement_steps_execution_path_chk CHECK (((execution_path)::text = ANY ((ARRAY['forward'::character varying, 'compensation'::character varying])::text[]))),
    CONSTRAINT listing_replacement_steps_idempotency_chk CHECK ((((idempotency_key)::text = btrim((idempotency_key)::text)) AND ((idempotency_key)::text <> ''::text) AND ((request_hash)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT listing_replacement_steps_key_chk CHECK ((((step_key)::text = btrim((step_key)::text)) AND ((step_key)::text ~ '^[a-z][a-z0-9_.:-]{0,99}$'::text))),
    CONSTRAINT listing_replacement_steps_lifecycle_chk CHECK (((((status)::text = 'pending'::text) AND (attempt_count = 0) AND (started_at IS NULL) AND (completed_at IS NULL) AND (result_evidence IS NULL) AND (error_code IS NULL)) OR (((status)::text = 'running'::text) AND (attempt_count > 0) AND (started_at IS NOT NULL) AND (completed_at IS NULL) AND (result_evidence IS NULL) AND (error_code IS NULL)) OR (((status)::text = 'succeeded'::text) AND (attempt_count > 0) AND (started_at IS NOT NULL) AND (completed_at IS NOT NULL) AND (result_evidence IS NOT NULL) AND (error_code IS NULL)) OR (((status)::text = 'failed'::text) AND (attempt_count > 0) AND (started_at IS NOT NULL) AND (completed_at IS NOT NULL) AND (error_code IS NOT NULL)))),
    CONSTRAINT listing_replacement_steps_path_phase_chk CHECK (((((execution_path)::text = 'forward'::text) AND ((phase)::text = ANY ((ARRAY['preflight'::character varying, 'cutover'::character varying, 'publish'::character varying, 'verify'::character varying, 'switch_mapping'::character varying])::text[]))) OR (((execution_path)::text = 'compensation'::text) AND ((phase)::text = 'compensate'::text)))),
    CONSTRAINT listing_replacement_steps_payload_chk CHECK (((jsonb_typeof(request_payload) = 'object'::text) AND ((result_evidence IS NULL) OR (jsonb_typeof(result_evidence) = 'object'::text)))),
    CONSTRAINT listing_replacement_steps_phase_chk CHECK (((phase)::text = ANY ((ARRAY['preflight'::character varying, 'cutover'::character varying, 'publish'::character varying, 'verify'::character varying, 'switch_mapping'::character varying, 'compensate'::character varying])::text[]))),
    CONSTRAINT listing_replacement_steps_sequence_chk CHECK ((sequence > 0)),
    CONSTRAINT listing_replacement_steps_status_chk CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'running'::character varying, 'succeeded'::character varying, 'failed'::character varying])::text[]))),
    CONSTRAINT listing_replacement_steps_time_chk CHECK (((updated_at >= created_at) AND ((started_at IS NULL) OR (started_at >= created_at)) AND ((completed_at IS NULL) OR ((completed_at >= created_at) AND ((started_at IS NULL) OR (completed_at >= started_at))))))
);


