--
-- Name: member_current_membership; Type: VIEW; Schema: membership; Owner: -
--

CREATE VIEW membership.member_current_membership AS
 SELECT DISTINCT ON (member_id) member_id,
    id AS subscription_id,
    plan_id,
    status,
    billing_interval,
    cycle_ends_at,
    scheduled_plan_id,
    created_at AS updated_at
   FROM membership.member_subscriptions ms
  WHERE (status = ANY (ARRAY['active'::text, 'pending_downgrade'::text, 'pending_cancellation'::text]))
  ORDER BY member_id, created_at DESC;


