    CONSTRAINT plan_billing_options_shopify_sync_status_check CHECK ((shopify_sync_status = ANY (ARRAY['pending'::text, 'in_progress'::text, 'synced'::text, 'not_required'::text, 'failed'::text]))),
    CONSTRAINT plan_billing_options_shopify_sync_versions_check CHECK (((shopify_sync_version >= 1) AND (shopify_synced_version >= 0) AND (shopify_synced_version <= shopify_sync_version))),
    CONSTRAINT plan_billing_options_trial_days_nonnegative_chk CHECK ((trial_days >= 0))
);


