    CONSTRAINT channel_fulfillment_pushes_attempt_chk CHECK (((attempt_count >= 0) AND (max_attempts > 0) AND (attempt_count <= max_attempts))),
    CONSTRAINT channel_fulfillment_pushes_completion_chk CHECK ((((push_status)::text = ANY ((ARRAY['success'::character varying, 'ignored'::character varying, 'dead'::character varying])::text[])) = (completed_at IS NOT NULL))),
    CONSTRAINT channel_fulfillment_pushes_lease_chk CHECK (((((push_status)::text = 'processing'::text) AND (lease_token IS NOT NULL) AND (lease_expires_at IS NOT NULL)) OR (((push_status)::text <> 'processing'::text) AND (lease_token IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT channel_fulfillment_pushes_notification_policy_attempt_check CHECK (((notification_policy_attempt IS NULL) OR (notification_policy_attempt >= 0))),
