    CONSTRAINT channel_fulfillment_pushes_status_chk CHECK (((push_status)::text = ANY ((ARRAY['shadow'::character varying, 'pending'::character varying, 'processing'::character varying, 'retry'::character varying, 'success'::character varying, 'failed'::character varying, 'ignored'::character varying, 'review'::character varying, 'dead'::character varying])::text[]))),
    CONSTRAINT channel_fulfillment_pushes_v1_contract_chk CHECK ((((command_key)::text !~~ 'fulfillment:v1:%'::text) OR ((request_hash IS NOT NULL) AND (NULLIF(btrim((tracking_number)::text), ''::text) IS NOT NULL) AND (NULLIF(btrim((carrier)::text), ''::text) IS NOT NULL) AND ((metadata ->> 'contractVersion'::text) = '1'::text) AND ((push_status)::text <> 'failed'::text))))
);


