--

CREATE TABLE procurement.purchase_forecast_evaluations (
    id integer NOT NULL,
    observation_id integer NOT NULL,
    horizon_days integer NOT NULL,
    evaluation_version integer NOT NULL,
    demand_query_version character varying(80) NOT NULL,
    observed_from timestamp with time zone NOT NULL,
    observed_through_exclusive timestamp with time zone NOT NULL,
    actual_demand_pieces bigint NOT NULL,
    actual_order_count integer NOT NULL,
    actual_active_days integer NOT NULL,
    latest_actual_demand_at timestamp with time zone,
    forecast_demand_micros bigint NOT NULL,
    baseline_demand_micros bigint NOT NULL,
    forecast_absolute_error_micros bigint NOT NULL,
    baseline_absolute_error_micros bigint NOT NULL,
    forecast_bias_micros bigint NOT NULL,
    baseline_bias_micros bigint NOT NULL,
    evidence_snapshot jsonb NOT NULL,
    evaluated_by character varying(255),
    evaluated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    overlay_attribution_version integer DEFAULT 0 NOT NULL,
    overlay_evaluable boolean DEFAULT false NOT NULL,
    overlay_exclusion_reason character varying(64) DEFAULT 'legacy_evaluation'::character varying,
    overlay_contribution_count integer,
    overlay_raw_demand_pieces bigint,
    overlay_weighted_demand_pieces bigint,
    overlay_adjusted_forecast_demand_micros bigint,
    overlay_adjusted_absolute_error_micros bigint,
    overlay_adjusted_bias_micros bigint,
    CONSTRAINT purchase_forecast_evaluations_actual_chk CHECK (((actual_demand_pieces >= 0) AND (actual_order_count >= 0) AND (actual_active_days >= 0))),
    CONSTRAINT purchase_forecast_evaluations_error_chk CHECK (((forecast_absolute_error_micros >= 0) AND (baseline_absolute_error_micros >= 0))),
    CONSTRAINT purchase_forecast_evaluations_horizon_chk CHECK ((horizon_days = ANY (ARRAY[7, 30, 90]))),
    CONSTRAINT purchase_forecast_evaluations_overlay_scoring_chk CHECK ((((overlay_evaluable = false) AND (overlay_attribution_version = 0) AND (overlay_exclusion_reason IS NOT NULL) AND (overlay_contribution_count IS NULL) AND (overlay_raw_demand_pieces IS NULL) AND (overlay_weighted_demand_pieces IS NULL) AND (overlay_adjusted_forecast_demand_micros IS NULL) AND (overlay_adjusted_absolute_error_micros IS NULL) AND (overlay_adjusted_bias_micros IS NULL)) OR ((overlay_evaluable = true) AND (overlay_attribution_version > 0) AND (overlay_exclusion_reason IS NULL) AND (overlay_contribution_count >= 0) AND (overlay_raw_demand_pieces >= 0) AND (overlay_weighted_demand_pieces >= 0) AND (overlay_adjusted_forecast_demand_micros >= 0) AND (overlay_adjusted_absolute_error_micros >= 0) AND (overlay_adjusted_bias_micros IS NOT NULL) AND (overlay_adjusted_forecast_demand_micros = (forecast_demand_micros + (overlay_weighted_demand_pieces * 1000000))) AND (overlay_adjusted_bias_micros = (overlay_adjusted_forecast_demand_micros - (actual_demand_pieces * 1000000))) AND (overlay_adjusted_absolute_error_micros = abs(overlay_adjusted_bias_micros))))),
    CONSTRAINT purchase_forecast_evaluations_prediction_chk CHECK (((forecast_demand_micros >= 0) AND (baseline_demand_micros >= 0))),
    CONSTRAINT purchase_forecast_evaluations_version_chk CHECK ((evaluation_version > 0)),
    CONSTRAINT purchase_forecast_evaluations_window_chk CHECK ((observed_through_exclusive > observed_from))
);


