    CONSTRAINT purchase_forecast_observations_forecast_qty_chk CHECK ((forecast_daily_pieces_micros >= 0)),
    CONSTRAINT purchase_forecast_observations_forward_qty_chk CHECK (((forward_demand_pieces >= 0) AND (forward_demand_raw_pieces >= 0))),
