--

CREATE TABLE procurement.purchase_order_lines (
    id integer NOT NULL,
    purchase_order_id integer NOT NULL,
    line_number integer NOT NULL,
    product_id integer,
    product_variant_id integer,
    vendor_product_id integer,
    sku character varying(100),
    product_name text,
    description text,
    vendor_sku character varying(100),
    unit_of_measure character varying(20),
    units_per_uom integer DEFAULT 1,
    order_qty integer NOT NULL,
    received_qty integer DEFAULT 0,
    damaged_qty integer DEFAULT 0,
    returned_qty integer DEFAULT 0,
    cancelled_qty integer DEFAULT 0,
    unit_cost_cents bigint DEFAULT 0 NOT NULL,
    discount_percent numeric(5,2) DEFAULT 0,
    discount_cents bigint DEFAULT 0,
    tax_rate_percent numeric(5,2) DEFAULT 0,
    tax_cents bigint DEFAULT 0,
    line_total_cents bigint,
    expected_delivery_date timestamp without time zone,
    promised_date timestamp without time zone,
    received_date timestamp without time zone,
    fully_received_date timestamp without time zone,
    last_received_at timestamp without time zone,
    status character varying(20) DEFAULT 'open'::character varying NOT NULL,
    close_short_reason text,
    weight_grams integer,
    notes text,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    unit_cost_mills bigint,
    line_type character varying(20) DEFAULT 'product'::character varying NOT NULL,
    parent_line_id integer,
    total_product_cost_cents bigint DEFAULT 0 NOT NULL,
    packaging_cost_cents bigint DEFAULT 0 NOT NULL,
    expected_receive_variant_id integer,
    expected_receive_units_per_variant integer DEFAULT 1,
    pricing_basis character varying(30) DEFAULT 'legacy_unknown'::character varying NOT NULL,
    pricing_source character varying(30) DEFAULT 'legacy'::character varying NOT NULL,
    purchase_uom character varying(50),
    purchase_uom_quantity integer,
    pieces_per_purchase_uom integer,
    quoted_unit_cost_mills bigint,
    quoted_total_cents bigint,
    pricing_remainder_mills bigint DEFAULT 0 NOT NULL,
    quote_reference character varying(255),
    quoted_at timestamp without time zone,
    quote_valid_until date,
    tax_type_id integer,
    receipt_costing_enabled integer DEFAULT 0 NOT NULL,
    CONSTRAINT po_lines_explicit_pricing_consistency_chk CHECK (((((pricing_basis)::text = 'legacy_unknown'::text) AND ((line_type)::text = 'product'::text) AND (purchase_uom IS NULL) AND (purchase_uom_quantity IS NULL) AND (pieces_per_purchase_uom IS NULL) AND (quoted_unit_cost_mills IS NULL) AND (quoted_total_cents IS NULL) AND (pricing_remainder_mills = 0) AND (quote_reference IS NULL) AND (quoted_at IS NULL) AND (quote_valid_until IS NULL)) OR (((pricing_basis)::text = 'not_applicable'::text) AND ((line_type)::text <> 'product'::text) AND (purchase_uom IS NULL) AND (purchase_uom_quantity IS NULL) AND (pieces_per_purchase_uom IS NULL) AND (quoted_unit_cost_mills IS NULL) AND (quoted_total_cents IS NULL) AND (pricing_remainder_mills = 0) AND (quote_reference IS NULL) AND (quoted_at IS NULL) AND (quote_valid_until IS NULL)) OR (((line_type)::text = 'product'::text) AND (order_qty > 0) AND (unit_cost_mills IS NOT NULL) AND (unit_cost_mills >= 0) AND (unit_cost_cents >= 0) AND (total_product_cost_cents >= 0) AND (packaging_cost_cents >= 0) AND (discount_cents IS NOT NULL) AND (discount_cents >= 0) AND (tax_cents IS NOT NULL) AND (tax_cents >= 0) AND (line_total_cents IS NOT NULL) AND ((((pricing_basis)::text = 'per_piece'::text) AND (purchase_uom IS NULL) AND (purchase_uom_quantity IS NULL) AND (pieces_per_purchase_uom IS NULL) AND (quoted_unit_cost_mills IS NOT NULL) AND (quoted_total_cents IS NULL)) OR (((pricing_basis)::text = 'per_purchase_uom'::text) AND (purchase_uom IS NOT NULL) AND (btrim((purchase_uom)::text) <> ''::text) AND (purchase_uom_quantity IS NOT NULL) AND (purchase_uom_quantity > 0) AND (pieces_per_purchase_uom IS NOT NULL) AND (pieces_per_purchase_uom > 0) AND (quoted_unit_cost_mills IS NOT NULL) AND (quoted_total_cents IS NULL) AND ((order_qty)::bigint = ((purchase_uom_quantity)::bigint * (pieces_per_purchase_uom)::bigint))) OR (((pricing_basis)::text = 'extended_total'::text) AND (purchase_uom IS NULL) AND (purchase_uom_quantity IS NULL) AND (pieces_per_purchase_uom IS NULL) AND (quoted_unit_cost_mills IS NULL) AND (quoted_total_cents IS NOT NULL))) AND ((unit_cost_mills)::numeric = floor(((
CASE pricing_basis
    WHEN 'per_piece'::text THEN ((quoted_unit_cost_mills)::numeric * (order_qty)::numeric)
    WHEN 'per_purchase_uom'::text THEN ((quoted_unit_cost_mills)::numeric * (purchase_uom_quantity)::numeric)
    WHEN 'extended_total'::text THEN ((quoted_total_cents)::numeric * (100)::numeric)
    ELSE NULL::numeric
END / (NULLIF(order_qty, 0))::numeric) + 0.5))) AND (
CASE pricing_basis
    WHEN 'per_piece'::text THEN ((quoted_unit_cost_mills)::numeric * (order_qty)::numeric)
    WHEN 'per_purchase_uom'::text THEN ((quoted_unit_cost_mills)::numeric * (purchase_uom_quantity)::numeric)
    WHEN 'extended_total'::text THEN ((quoted_total_cents)::numeric * (100)::numeric)
    ELSE NULL::numeric
END = (((unit_cost_mills)::numeric * (order_qty)::numeric) + (pricing_remainder_mills)::numeric)) AND ((total_product_cost_cents)::numeric = floor(((
CASE pricing_basis
    WHEN 'per_piece'::text THEN ((quoted_unit_cost_mills)::numeric * (order_qty)::numeric)
    WHEN 'per_purchase_uom'::text THEN ((quoted_unit_cost_mills)::numeric * (purchase_uom_quantity)::numeric)
    WHEN 'extended_total'::text THEN ((quoted_total_cents)::numeric * (100)::numeric)
    ELSE NULL::numeric
END + (50)::numeric) / (100)::numeric))) AND ((unit_cost_cents)::numeric = floor((((unit_cost_mills)::numeric + (50)::numeric) / (100)::numeric))) AND ((line_total_cents)::numeric = ((((total_product_cost_cents)::numeric + (packaging_cost_cents)::numeric) - (discount_cents)::numeric) + (tax_cents)::numeric))))),
    CONSTRAINT po_lines_line_type_chk CHECK (((line_type)::text = ANY ((ARRAY['product'::character varying, 'discount'::character varying, 'fee'::character varying, 'tax'::character varying, 'rebate'::character varying, 'adjustment'::character varying])::text[]))),
    CONSTRAINT po_lines_pricing_basis_chk CHECK (((pricing_basis)::text = ANY ((ARRAY['legacy_unknown'::character varying, 'not_applicable'::character varying, 'per_piece'::character varying, 'per_purchase_uom'::character varying, 'extended_total'::character varying])::text[]))),
    CONSTRAINT po_lines_pricing_source_basis_consistency_chk CHECK (((((pricing_basis)::text = 'legacy_unknown'::text) AND ((pricing_source)::text = 'legacy'::text)) OR (((pricing_basis)::text = 'not_applicable'::text) AND ((pricing_source)::text = ANY ((ARRAY['legacy'::character varying, 'manual'::character varying])::text[]))) OR (((pricing_basis)::text = ANY ((ARRAY['per_piece'::character varying, 'per_purchase_uom'::character varying, 'extended_total'::character varying])::text[])) AND ((pricing_source)::text = 'manual'::text)) OR (((pricing_basis)::text = ANY ((ARRAY['per_piece'::character varying, 'per_purchase_uom'::character varying])::text[])) AND ((pricing_source)::text = ANY ((ARRAY['vendor_catalog'::character varying, 'recommendation'::character varying])::text[])) AND (vendor_product_id IS NOT NULL) AND (quoted_at IS NOT NULL)))),
    CONSTRAINT po_lines_pricing_source_chk CHECK (((pricing_source)::text = ANY ((ARRAY['legacy'::character varying, 'manual'::character varying, 'vendor_catalog'::character varying, 'recommendation'::character varying])::text[]))),
    CONSTRAINT po_lines_quote_dates_consistency_chk CHECK (((quoted_at IS NULL) OR (quote_valid_until IS NULL) OR (quote_valid_until >= (quoted_at)::date))),
    CONSTRAINT po_lines_quote_quantities_positive_chk CHECK ((((purchase_uom_quantity IS NULL) OR (purchase_uom_quantity > 0)) AND ((pieces_per_purchase_uom IS NULL) OR (pieces_per_purchase_uom > 0)))),
    CONSTRAINT po_lines_quoted_amounts_nonnegative_chk CHECK ((((quoted_unit_cost_mills IS NULL) OR (quoted_unit_cost_mills >= 0)) AND ((quoted_total_cents IS NULL) OR (quoted_total_cents >= 0)))),
    CONSTRAINT purchase_order_lines_receipt_costing_enabled_check CHECK ((receipt_costing_enabled = ANY (ARRAY[0, 1])))
);


