    CONSTRAINT purchase_pipeline_job_runs_time_chk CHECK (((heartbeat_at >= started_at) AND ((lease_expires_at IS NULL) OR (lease_expires_at > heartbeat_at)) AND ((finished_at IS NULL) OR (finished_at >= started_at)))),
