CREATE TABLE public.financial_command_recoveries (
    id bigint NOT NULL,
    command_result_id bigint NOT NULL,
    recovery_number integer NOT NULL,
    operator_id character varying(200) NOT NULL,
    reason character varying(1000) NOT NULL,
    prior_attempt_count integer NOT NULL,
    prior_attempt_limit integer NOT NULL,
    prior_error_code character varying(100) NOT NULL,
    prior_error_message character varying(1000) NOT NULL,
    prior_completed_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT financial_command_recoveries_attempts_chk CHECK (((prior_attempt_count > 0) AND (prior_attempt_limit >= prior_attempt_count))),
    CONSTRAINT financial_command_recoveries_error_chk CHECK ((((prior_error_code)::text = btrim((prior_error_code)::text)) AND ((prior_error_code)::text <> ''::text) AND ((prior_error_message)::text = btrim((prior_error_message)::text)) AND ((prior_error_message)::text <> ''::text))),
    CONSTRAINT financial_command_recoveries_number_chk CHECK ((recovery_number > 0)),
    CONSTRAINT financial_command_recoveries_operator_chk CHECK ((((operator_id)::text = btrim((operator_id)::text)) AND ((operator_id)::text <> ''::text))),
    CONSTRAINT financial_command_recoveries_reason_chk CHECK ((((reason)::text = btrim((reason)::text)) AND ((length((reason)::text) >= 10) AND (length((reason)::text) <= 1000))))
);


