-- Name: financial_command_results; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.financial_command_results (
    id bigint NOT NULL,
    actor_type character varying(40) NOT NULL,
    actor_id character varying(200) NOT NULL,
    method character varying(10) NOT NULL,
    route_template character varying(300) NOT NULL,
    resource_key character varying(300) NOT NULL,
    idempotency_key character varying(255) NOT NULL,
    request_hash character varying(64) NOT NULL,
    command_name character varying(120) NOT NULL,
    contract_version integer DEFAULT 1 NOT NULL,
    status character varying(20) DEFAULT 'claimed'::character varying NOT NULL,
    lease_token character varying(100),
    lease_expires_at timestamp with time zone,
    attempt_count integer DEFAULT 1 NOT NULL,
    http_status integer,
    response_body jsonb,
    result_type character varying(100),
    result_id character varying(200),
    next_attempt_at timestamp with time zone,
    last_error_code character varying(100),
    last_error_message character varying(1000),
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    attempt_limit integer DEFAULT 5 NOT NULL,
    recovery_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT financial_command_results_actor_id_chk CHECK ((((actor_id)::text = btrim((actor_id)::text)) AND ((actor_id)::text <> ''::text))),
    CONSTRAINT financial_command_results_actor_type_chk CHECK (((actor_type)::text = ANY ((ARRAY['user'::character varying, 'service'::character varying, 'system'::character varying])::text[]))),
    CONSTRAINT financial_command_results_attempt_count_chk CHECK ((attempt_count > 0)),
    CONSTRAINT financial_command_results_attempt_limit_chk CHECK ((((attempt_limit >= 1) AND (attempt_limit <= 100)) AND (attempt_count <= attempt_limit))),
    CONSTRAINT financial_command_results_command_name_chk CHECK ((((command_name)::text = btrim((command_name)::text)) AND ((command_name)::text ~ '^[a-z][a-z0-9_.:-]*$'::text))),
    CONSTRAINT financial_command_results_contract_version_chk CHECK ((contract_version > 0)),
    CONSTRAINT financial_command_results_idempotency_key_chk CHECK ((((idempotency_key)::text = btrim((idempotency_key)::text)) AND ((idempotency_key)::text <> ''::text))),
    CONSTRAINT financial_command_results_lifecycle_chk CHECK (((((status)::text = 'claimed'::text) AND (lease_token IS NOT NULL) AND (btrim((lease_token)::text) <> ''::text) AND (lease_expires_at IS NOT NULL) AND (next_attempt_at IS NULL) AND (completed_at IS NULL) AND (http_status IS NULL) AND (response_body IS NULL) AND (result_type IS NULL) AND (result_id IS NULL) AND (last_error_code IS NULL) AND (last_error_message IS NULL)) OR (((status)::text = 'succeeded'::text) AND (lease_token IS NULL) AND (lease_expires_at IS NULL) AND (next_attempt_at IS NULL) AND (completed_at IS NOT NULL) AND ((http_status >= 200) AND (http_status <= 299)) AND (response_body IS NOT NULL) AND (last_error_code IS NULL) AND (last_error_message IS NULL)) OR (((status)::text = 'rejected'::text) AND (lease_token IS NULL) AND (lease_expires_at IS NULL) AND (next_attempt_at IS NULL) AND (completed_at IS NOT NULL) AND ((http_status >= 400) AND (http_status <= 499)) AND (response_body IS NOT NULL) AND (result_type IS NULL) AND (result_id IS NULL) AND (last_error_code IS NOT NULL) AND (btrim((last_error_code)::text) <> ''::text) AND (last_error_message IS NOT NULL) AND (btrim((last_error_message)::text) <> ''::text)) OR (((status)::text = 'retryable'::text) AND (lease_token IS NULL) AND (lease_expires_at IS NULL) AND (next_attempt_at IS NOT NULL) AND (completed_at IS NULL) AND (http_status IS NULL) AND (response_body IS NULL) AND (result_type IS NULL) AND (result_id IS NULL) AND (last_error_code IS NOT NULL) AND (btrim((last_error_code)::text) <> ''::text) AND (last_error_message IS NOT NULL) AND (btrim((last_error_message)::text) <> ''::text)) OR (((status)::text = 'dead'::text) AND (lease_token IS NULL) AND (lease_expires_at IS NULL) AND (next_attempt_at IS NULL) AND (completed_at IS NOT NULL) AND (http_status IS NULL) AND (response_body IS NULL) AND (result_type IS NULL) AND (result_id IS NULL) AND (last_error_code IS NOT NULL) AND (btrim((last_error_code)::text) <> ''::text) AND (last_error_message IS NOT NULL) AND (btrim((last_error_message)::text) <> ''::text)))),
    CONSTRAINT financial_command_results_method_chk CHECK (((method)::text = ANY ((ARRAY['POST'::character varying, 'PUT'::character varying, 'PATCH'::character varying, 'DELETE'::character varying])::text[]))),
    CONSTRAINT financial_command_results_recovery_count_chk CHECK (((recovery_count >= 0) AND (recovery_count <= 95))),
    CONSTRAINT financial_command_results_request_hash_chk CHECK (((request_hash)::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT financial_command_results_resource_key_chk CHECK ((((resource_key)::text = btrim((resource_key)::text)) AND ((resource_key)::text <> ''::text))),
    CONSTRAINT financial_command_results_result_identity_chk CHECK ((((result_type IS NULL) AND (result_id IS NULL)) OR (((result_type)::text = btrim((result_type)::text)) AND ((result_type)::text <> ''::text) AND ((result_id)::text = btrim((result_id)::text)) AND ((result_id)::text <> ''::text)))),
    CONSTRAINT financial_command_results_route_template_chk CHECK ((((route_template)::text = btrim((route_template)::text)) AND ((route_template)::text ~~ '/%'::text) AND (POSITION(('?'::text) IN (route_template)) = 0))),
    CONSTRAINT financial_command_results_status_chk CHECK (((status)::text = ANY ((ARRAY['claimed'::character varying, 'succeeded'::character varying, 'rejected'::character varying, 'retryable'::character varying, 'dead'::character varying])::text[]))),
    CONSTRAINT financial_command_results_time_order_chk CHECK (((updated_at >= created_at) AND (expires_at > created_at) AND ((lease_expires_at IS NULL) OR ((lease_expires_at > updated_at) AND (lease_expires_at <= expires_at))) AND ((next_attempt_at IS NULL) OR ((next_attempt_at >= updated_at) AND (next_attempt_at < expires_at))) AND ((completed_at IS NULL) OR ((completed_at >= created_at) AND (completed_at <= updated_at) AND (completed_at < expires_at)))))
);


--
-- Name: TABLE financial_command_results; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.financial_command_results IS 'Durable idempotency, lease, retry, and exact HTTP replay ledger for financial commands.';


--
-- Name: COLUMN financial_command_results.request_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.financial_command_results.request_hash IS 'Lowercase SHA-256 of the canonical HTTP payload identity; excludes internal command name/version so completed results survive compatible deployments.';


--
-- Name: COLUMN financial_command_results.response_body; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.financial_command_results.response_body IS 'Exact JSON response body replayed with http_status for succeeded or rejected commands.';


--
-- Name: COLUMN financial_command_results.last_error_message; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.financial_command_results.last_error_message IS 'Sanitized, bounded operator-safe diagnostic; never store secrets or raw upstream payloads.';


--
-- Name: COLUMN financial_command_results.attempt_limit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.financial_command_results.attempt_limit IS 'Current maximum attempts. Starts at five; each audited operator recovery grants exactly one more.';


--
-- Name: COLUMN financial_command_results.recovery_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.financial_command_results.recovery_count IS 'Number of audited dead-command recoveries granted to this immutable command identity.';


