CREATE TABLE returns.customer_return_authorizations (
    id bigint NOT NULL,
    authorization_number character varying(32) DEFAULT ('RMA-'::text || (nextval('returns.customer_return_authorization_number_seq'::regclass))::text) NOT NULL,
    channel_id integer NOT NULL,
    oms_order_id bigint NOT NULL,
    eligibility_revision character varying(64) NOT NULL,
    policy_snapshot jsonb NOT NULL,
    warehouse_snapshot jsonb NOT NULL,
    actor character varying(255) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT customer_return_authorizations_actor_check CHECK ((btrim((actor)::text) <> ''::text)),
    CONSTRAINT customer_return_authorizations_eligibility_revision_check CHECK (((eligibility_revision)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT customer_return_authorizations_policy_snapshot_check CHECK (((jsonb_typeof(policy_snapshot) = 'object'::text) AND (octet_length((policy_snapshot)::text) <= 65536))),
    CONSTRAINT customer_return_authorizations_warehouse_snapshot_check CHECK (((jsonb_typeof(warehouse_snapshot) = 'object'::text) AND (octet_length((warehouse_snapshot)::text) <= 65536)))
);


