-- Name: return_items; Type: TABLE; Schema: wms; Owner: -
--

CREATE TABLE wms.return_items (
    id bigint NOT NULL,
    return_id bigint NOT NULL,
    order_item_id integer,
    oms_order_line_id bigint,
    external_line_item_id character varying(100),
    sku character varying(100),
    expected_qty integer NOT NULL,
    received_qty integer DEFAULT 0 NOT NULL,
    restock_policy character varying(20),
    location_id character varying(100),
    condition character varying(20),
    status character varying(20) DEFAULT 'expected'::character varying NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT wms_return_items_quantity_chk CHECK (((expected_qty > 0) AND (received_qty >= 0) AND (received_qty <= expected_qty)))
);


--
-- Name: customer_return_claimed_quantities; Type: VIEW; Schema: returns; Owner: -
--

CREATE VIEW returns.customer_return_claimed_quantities AS
 SELECT wms_order_item_id,
    (sum(quantity))::bigint AS claimed_quantity
   FROM ( SELECT aa.wms_order_item_id,
            (aa.quantity)::bigint AS quantity
           FROM returns.customer_return_authorization_allocations aa
        UNION ALL
         SELECT ri.order_item_id,
            (GREATEST(ri.expected_qty, ri.received_qty))::bigint AS "greatest"
           FROM wms.return_items ri
          WHERE ((ri.order_item_id IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM returns.customer_return_allocation_case_items link
                  WHERE (link.wms_return_item_id = ri.id)))))) claims
  GROUP BY wms_order_item_id;


--
-- Name: customer_return_guest_challenges; Type: TABLE; Schema: returns; Owner: -
--

CREATE TABLE returns.customer_return_guest_challenges (
    id uuid NOT NULL,
    channel_id bigint NOT NULL,
    browser_hash text NOT NULL,
    input_hash text NOT NULL,
    email_hash text NOT NULL,
    oms_order_id bigint,
    purchase jsonb,
    created_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    verified_at timestamp with time zone,
    revoked_at timestamp with time zone,
    delivery_token uuid,
    delivery_until timestamp with time zone,
    next_delivery_at timestamp with time zone NOT NULL,
    account_result text,
    CONSTRAINT customer_return_guest_challenges_attempts_check CHECK (((attempts >= 0) AND (attempts <= 5))),
    CONSTRAINT customer_return_guest_challenges_browser_hash_check CHECK ((length(browser_hash) = 43)),
    CONSTRAINT customer_return_guest_challenges_check CHECK ((expires_at > created_at)),
    CONSTRAINT customer_return_guest_challenges_check1 CHECK ((expires_at <= (created_at + '00:10:00'::interval))),
    CONSTRAINT customer_return_guest_challenges_check2 CHECK (((verified_at IS NULL) OR ((verified_at >= created_at) AND (verified_at < expires_at)))),
    CONSTRAINT customer_return_guest_challenges_check3 CHECK (((delivery_token IS NULL) = (delivery_until IS NULL))),
    CONSTRAINT customer_return_guest_challenges_check4 CHECK (((purchase IS NULL) = (oms_order_id IS NULL))),
    CONSTRAINT customer_return_guest_challenges_check5 CHECK (((purchase IS NULL) OR ((jsonb_typeof(purchase) = 'object'::text) AND (((purchase ->> 'channelId'::text))::bigint = channel_id) AND (((purchase ->> 'omsOrderId'::text))::bigint = oms_order_id)))),
    CONSTRAINT customer_return_guest_challenges_email_hash_check CHECK ((length(email_hash) = 43)),
    CONSTRAINT customer_return_guest_challenges_input_hash_check CHECK ((length(input_hash) = 43))
);


