    CONSTRAINT customer_return_quote_decisions_check1 CHECK (((((status)::text = 'selected'::text) AND (quote_result IS NOT NULL) AND (selected_rate IS NOT NULL) AND (error_code IS NULL)) OR (((status)::text = 'failed'::text) AND (selected_rate IS NULL) AND (error_code IS NOT NULL)))),
    CONSTRAINT customer_return_quote_decisions_error_code_check CHECK (((error_code IS NULL) OR ((error_code)::text ~ '^[A-Z0-9_]+$'::text))),
    CONSTRAINT customer_return_quote_decisions_quote_result_check CHECK (((quote_result IS NULL) OR (jsonb_typeof(quote_result) = 'object'::text))),
    CONSTRAINT customer_return_quote_decisions_selected_rate_check CHECK (((selected_rate IS NULL) OR (jsonb_typeof(selected_rate) = 'object'::text))),
    CONSTRAINT customer_return_quote_decisions_settings_snapshot_check CHECK ((jsonb_typeof(settings_snapshot) = 'object'::text)),
    CONSTRAINT customer_return_quote_decisions_settings_version_check CHECK ((settings_version > 0)),
    CONSTRAINT customer_return_quote_decisions_shipment_hash_check CHECK (((shipment_hash)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT customer_return_quote_decisions_shipment_snapshot_check CHECK ((jsonb_typeof(shipment_snapshot) = 'object'::text)),
