    CONSTRAINT customer_return_settings_destination_address_check CHECK ((jsonb_typeof(destination_address) = 'object'::text)),
    CONSTRAINT customer_return_settings_selection_chk CHECK (((((selection_mode)::text = 'fixed_service'::text) AND (carrier_id IS NOT NULL) AND (service_code IS NOT NULL) AND (carrier_rules = '[]'::jsonb)) OR (((selection_mode)::text = 'cheapest_eligible'::text) AND (carrier_id IS NULL) AND (service_code IS NULL) AND (jsonb_typeof(carrier_rules) = 'array'::text) AND ((jsonb_array_length(carrier_rules) >= 1) AND (jsonb_array_length(carrier_rules) <= 100))))),
