--
-- Name: customer_return_source_items; Type: VIEW; Schema: returns; Owner: -
--

CREATE VIEW returns.customer_return_source_items AS
 SELECT oo.id AS oms_order_id,
    ol.id AS oms_order_line_id,
    wi.id AS wms_order_item_id,
    wo.id AS wms_order_id,
    wi.fulfilled_quantity,
    wi.quantity,
        CASE
            WHEN (wi.oms_order_line_id IS NOT NULL) THEN 'canonical'::text
            ELSE 'native_purchased_line'::text
        END AS identity_source
   FROM (((wms.order_items wi
     JOIN wms.orders wo ON ((wo.id = wi.order_id)))
     JOIN oms.oms_orders oo ON ((((wo.oms_fulfillment_order_id)::text = (oo.id)::text) OR ((wo.source_table_id)::text = (oo.id)::text) OR ((wo.channel_id = oo.channel_id) AND ((wo.source)::text = 'shopify'::text) AND (regexp_replace((COALESCE(wo.external_order_id, wo.source_table_id))::text, '^gid://shopify/Order/'::text, ''::text) = regexp_replace((oo.external_order_id)::text, '^gid://shopify/Order/'::text, ''::text))))))
     JOIN oms.oms_order_lines ol ON (((ol.order_id = oo.id) AND ((wi.oms_order_line_id = ol.id) OR ((wi.oms_order_line_id IS NULL) AND (regexp_replace((COALESCE(wi.shopify_line_item_id, wi.source_item_id))::text, '^gid://shopify/LineItem/'::text, ''::text) = regexp_replace((ol.external_line_item_id)::text, '^gid://shopify/LineItem/'::text, ''::text)))))))
  WHERE (((wo.channel_id IS NULL) OR (wo.channel_id = oo.channel_id)) AND ((wo.oms_fulfillment_order_id IS NULL) OR ((wo.oms_fulfillment_order_id)::text = (oo.id)::text)) AND ((wo.source_table_id IS NULL) OR ((wo.source_table_id)::text = (oo.id)::text) OR (regexp_replace((wo.source_table_id)::text, '^gid://shopify/Order/'::text, ''::text) = regexp_replace((oo.external_order_id)::text, '^gid://shopify/Order/'::text, ''::text))) AND ((wo.external_order_id IS NULL) OR (regexp_replace((wo.external_order_id)::text, '^gid://shopify/Order/'::text, ''::text) = regexp_replace((oo.external_order_id)::text, '^gid://shopify/Order/'::text, ''::text))) AND ((wi.shopify_line_item_id IS NULL) OR (regexp_replace((wi.shopify_line_item_id)::text, '^gid://shopify/LineItem/'::text, ''::text) = regexp_replace((ol.external_line_item_id)::text, '^gid://shopify/LineItem/'::text, ''::text))) AND ((wi.oms_order_line_id IS NOT NULL) OR ((wo.oms_fulfillment_order_id)::text = (oo.id)::text) OR (NOT (EXISTS ( SELECT 1
           FROM oms.oms_orders other
          WHERE ((other.channel_id = oo.channel_id) AND (other.id <> oo.id) AND (regexp_replace((other.external_order_id)::text, '^gid://shopify/Order/'::text, ''::text) = regexp_replace((oo.external_order_id)::text, '^gid://shopify/Order/'::text, ''::text))))))));


