-- Name: customer_return_workflows; Type: TABLE; Schema: returns; Owner: -
--

CREATE TABLE returns.customer_return_workflows (
    channel_id integer NOT NULL,
    request_key uuid NOT NULL,
    oms_order_id bigint NOT NULL,
    request_snapshot jsonb NOT NULL,
    scope_snapshot jsonb NOT NULL,
    semantic_hash character varying(64) NOT NULL,
    actor character varying(255) NOT NULL,
    phase character varying(24) NOT NULL,
    reason character varying(64),
    authorization_id bigint,
    failures integer DEFAULT 0 NOT NULL,
    explicit_retry boolean DEFAULT false NOT NULL,
    next_run_at timestamp with time zone NOT NULL,
    lease_token uuid,
    lease_until timestamp with time zone,
    last_error_code character varying(100),
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT customer_return_workflows_actor_check CHECK ((btrim((actor)::text) <> ''::text)),
    CONSTRAINT customer_return_workflows_check CHECK (((lease_token IS NULL) = (lease_until IS NULL))),
    CONSTRAINT customer_return_workflows_check1 CHECK ((((phase)::text <> ALL ((ARRAY['labels'::character varying, 'ready'::character varying])::text[])) OR (authorization_id IS NOT NULL))),
    CONSTRAINT customer_return_workflows_check2 CHECK ((((phase)::text <> 'needs_input'::text) OR (authorization_id IS NULL))),
    CONSTRAINT customer_return_workflows_check3 CHECK ((((phase)::text = ANY ((ARRAY['queued'::character varying, 'preparing'::character varying, 'labels'::character varying, 'ready'::character varying])::text[])) = (reason IS NULL))),
    CONSTRAINT customer_return_workflows_failures_check CHECK (((failures >= 0) AND (failures <= 6))),
    CONSTRAINT customer_return_workflows_phase_check CHECK (((phase)::text = ANY ((ARRAY['queued'::character varying, 'preparing'::character varying, 'labels'::character varying, 'ready'::character varying, 'retryable_failure'::character varying, 'needs_input'::character varying, 'needs_help'::character varying])::text[]))),
    CONSTRAINT customer_return_workflows_reason_check CHECK (((reason IS NULL) OR ((reason)::text = ANY ((ARRAY['RETURN_DETAILS_CHANGED'::character varying, 'RETURN_SHIPPING_UNAVAILABLE'::character varying, 'RETURN_LABEL_RECONCILIATION_REQUIRED'::character varying, 'RETURN_WORKFLOW_TEMPORARY_FAILURE'::character varying, 'RETURN_WORKFLOW_NEEDS_HELP'::character varying])::text[])))),
    CONSTRAINT customer_return_workflows_request_snapshot_check CHECK ((jsonb_typeof(request_snapshot) = 'object'::text)),
    CONSTRAINT customer_return_workflows_scope_snapshot_check CHECK ((jsonb_typeof(scope_snapshot) = 'object'::text)),
    CONSTRAINT customer_return_workflows_semantic_hash_check CHECK (((semantic_hash)::text ~ '^[a-f0-9]{64}$'::text))
);


