--

CREATE TABLE shipping.service_level_methods (
    id integer NOT NULL,
    service_level_id integer NOT NULL,
    carrier character varying(50) NOT NULL,
    service_code character varying(80) NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    provider character varying(80) NOT NULL,
    provider_account_id character varying(120),
    provider_account_name character varying(160),
    carrier_name character varying(160),
    service_name character varying(160),
    priority integer NOT NULL,
    domestic boolean DEFAULT false NOT NULL,
    international boolean DEFAULT false NOT NULL,
    revision_id bigint,
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    provider_connection_id bigint,
    provider_capabilities jsonb,
    CONSTRAINT shipping_level_method_capabilities_chk CHECK (((provider_capabilities IS NULL) OR
CASE
    WHEN (jsonb_typeof(provider_capabilities) = 'object'::text) THEN ((NOT (jsonb_typeof((provider_capabilities -> 'supportsMultiPackage'::text)) IS DISTINCT FROM 'boolean'::text)) AND (NOT (jsonb_typeof((provider_capabilities -> 'supportsReturns'::text)) IS DISTINCT FROM 'boolean'::text)) AND (NOT (jsonb_typeof((provider_capabilities -> 'supportsPrepaidDutiesTaxes'::text)) IS DISTINCT FROM 'boolean'::text)) AND (NOT (jsonb_typeof((provider_capabilities -> 'sendRates'::text)) IS DISTINCT FROM 'boolean'::text)) AND
    CASE
        WHEN (jsonb_typeof((provider_capabilities -> 'displaySchemes'::text)) = 'array'::text) THEN (jsonb_array_length((provider_capabilities -> 'displaySchemes'::text)) <= 20)
        ELSE false
    END)
    ELSE false
END)),
    CONSTRAINT shipping_level_method_identity_chk CHECK (((((provider)::text = 'legacy_unscoped'::text) AND (provider_connection_id IS NULL) AND (provider_account_id IS NULL) AND (revision_id IS NULL)) OR (((provider)::text <> 'legacy_unscoped'::text) AND (provider_connection_id IS NOT NULL) AND (provider_account_id IS NOT NULL) AND (provider_account_name IS NOT NULL) AND (carrier_name IS NOT NULL) AND (service_name IS NOT NULL) AND ((char_length(btrim((carrier)::text)) >= 1) AND (char_length(btrim((carrier)::text)) <= 50)) AND ((char_length(btrim((service_code)::text)) >= 1) AND (char_length(btrim((service_code)::text)) <= 80)) AND ((char_length(btrim((provider_account_id)::text)) >= 1) AND (char_length(btrim((provider_account_id)::text)) <= 120)) AND ((char_length(btrim((provider_account_name)::text)) >= 1) AND (char_length(btrim((provider_account_name)::text)) <= 160)) AND ((char_length(btrim((carrier_name)::text)) >= 1) AND (char_length(btrim((carrier_name)::text)) <= 160)) AND ((char_length(btrim((service_name)::text)) >= 1) AND (char_length(btrim((service_name)::text)) <= 160)) AND (revision_id IS NOT NULL)))),
    CONSTRAINT shipping_level_method_priority_chk CHECK ((priority > 0)),
    CONSTRAINT shipping_level_method_provider_chk CHECK ((((provider)::text = 'legacy_unscoped'::text) OR ((provider)::text ~ '^[a-z][a-z0-9_]{1,79}$'::text)))
);


