--
-- Name: shipped_units_by_order_line; Type: VIEW; Schema: shipping; Owner: -
--

CREATE VIEW shipping.shipped_units_by_order_line AS
 SELECT oms_order_line_id,
    sum(quantity) AS shipped_quantity
   FROM shipping.shipment_items item
  WHERE ((oms_order_line_id IS NOT NULL) AND ((purpose)::text = 'fulfillment'::text) AND (NOT (EXISTS ( SELECT 1
           FROM shipping.shipment_voids voided
          WHERE (voided.shipment_id = item.shipment_id)))))
  GROUP BY oms_order_line_id;


