-- Name: physical_shipment_items; Type: TABLE; Schema: wms; Owner: -
--

CREATE TABLE wms.physical_shipment_items (
    id bigint NOT NULL,
    physical_shipment_id bigint NOT NULL,
    shipment_request_item_id bigint,
    fulfillment_plan_line_id bigint,
    wms_order_item_id integer,
    quantity_shipped integer NOT NULL,
    provider_physical_shipment_line_id character varying(200),
    provider_order_line_id character varying(200),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    legacy_wms_shipment_item_id integer,
    shipment_item_purpose character varying(30) DEFAULT 'customer_fulfillment'::character varying NOT NULL,
    replacement_for_order_item_id integer,
    product_variant_id integer,
    sku character varying(100) NOT NULL,
    correction_for_physical_shipment_item_id bigint,
    package_allocation_entry_id bigint,
    label_replacement_source_item_id integer,
    CONSTRAINT physical_shipment_items_quantity_chk CHECK ((quantity_shipped > 0)),
    CONSTRAINT physical_shipment_items_single_source_provenance_chk CHECK ((num_nonnulls(legacy_wms_shipment_item_id, package_allocation_entry_id, label_replacement_source_item_id) <= 1))
);


--
-- Name: COLUMN physical_shipment_items.package_allocation_entry_id; Type: COMMENT; Schema: wms; Owner: -
--

COMMENT ON COLUMN wms.physical_shipment_items.package_allocation_entry_id IS 'Immutable exact package-allocation provenance for split-safe physical shipment items; mutually exclusive with the legacy whole-line pointer.';


--
-- Name: effective_physical_shipment_items; Type: VIEW; Schema: wms; Owner: -
--

CREATE VIEW wms.effective_physical_shipment_items AS
 SELECT item.id,
    item.physical_shipment_id,
    item.shipment_request_item_id,
    item.fulfillment_plan_line_id,
    item.wms_order_item_id,
    (item.quantity_shipped + COALESCE(adjustment.quantity_delta, 0)) AS quantity_shipped,
    item.provider_physical_shipment_line_id,
    item.provider_order_line_id,
    item.created_at,
    item.legacy_wms_shipment_item_id,
    item.shipment_item_purpose,
    item.replacement_for_order_item_id,
    item.product_variant_id,
    item.sku,
    item.package_allocation_entry_id,
    item.label_replacement_source_item_id
   FROM (wms.physical_shipment_items item
     LEFT JOIN wms.physical_shipment_item_quantity_adjustments adjustment ON ((adjustment.physical_shipment_item_id = item.id)))
  WHERE ((item.quantity_shipped + COALESCE(adjustment.quantity_delta, 0)) > 0);


--
-- Name: VIEW effective_physical_shipment_items; Type: COMMENT; Schema: wms; Owner: -
--

COMMENT ON VIEW wms.effective_physical_shipment_items IS 'Authoritative physical shipment item projection after append-only historical quantity corrections.';


