    CONSTRAINT shipping_provider_label_links_source_chk CHECK ((btrim((source)::text) <> ''::text)),
    CONSTRAINT shipping_provider_label_links_target_chk CHECK ((num_nonnulls(shipment_request_id, shipping_engine_order_id, physical_shipment_id, legacy_wms_shipment_id) = 1))
);


--
-- Name: shipping_provider_label_links_id_seq; Type: SEQUENCE; Schema: wms; Owner: -
--

ALTER TABLE wms.shipping_provider_label_links ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME wms.shipping_provider_label_links_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: shipping_provider_labels; Type: TABLE; Schema: wms; Owner: -
--

CREATE TABLE wms.shipping_provider_labels (
    id bigint NOT NULL,
    provider character varying(40) NOT NULL,
    provider_label_id character varying(200) NOT NULL,
    provider_order_id character varying(200),
    provider_order_key character varying(200),
    tracking_number character varying(200) NOT NULL,
    normalized_tracking_number character varying(200) NOT NULL,
    label_status character varying(30) DEFAULT 'unknown'::character varying NOT NULL,
    carrier character varying(100),
    service_code character varying(100),
    label_created_at timestamp with time zone,
    voided_at timestamp with time zone,
    first_observed_at timestamp with time zone NOT NULL,
    last_observed_at timestamp with time zone NOT NULL,
    last_link_reconciled_at timestamp with time zone,
    next_link_reconcile_at timestamp with time zone,
    link_reconcile_attempts integer DEFAULT 0 NOT NULL,
    source character varying(50) NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    label_direction character varying(20) DEFAULT 'outbound'::character varying NOT NULL,
    CONSTRAINT shipping_provider_labels_direction_chk CHECK (((label_direction)::text = ANY ((ARRAY['outbound'::character varying, 'return'::character varying, 'unknown'::character varying])::text[]))),
    CONSTRAINT shipping_provider_labels_link_attempts_chk CHECK ((link_reconcile_attempts >= 0)),
    CONSTRAINT shipping_provider_labels_normalized_tracking_chk CHECK (((normalized_tracking_number)::text ~ '^[A-Z0-9]+$'::text)),
    CONSTRAINT shipping_provider_labels_observed_range_chk CHECK ((first_observed_at <= last_observed_at)),
    CONSTRAINT shipping_provider_labels_provider_chk CHECK ((btrim((provider)::text) <> ''::text)),
    CONSTRAINT shipping_provider_labels_provider_label_chk CHECK ((btrim((provider_label_id)::text) <> ''::text)),
    CONSTRAINT shipping_provider_labels_source_chk CHECK ((btrim((source)::text) <> ''::text)),
    CONSTRAINT shipping_provider_labels_status_chk CHECK (((label_status)::text = ANY ((ARRAY['active'::character varying, 'voided'::character varying, 'superseded'::character varying, 'unknown'::character varying])::text[]))),
    CONSTRAINT shipping_provider_labels_tracking_chk CHECK ((btrim((tracking_number)::text) <> ''::text)),
    CONSTRAINT shipping_provider_labels_void_shape_chk CHECK ((((label_status)::text <> 'voided'::text) OR (voided_at IS NOT NULL)))
);


--
-- Name: COLUMN shipping_provider_labels.label_direction; Type: COMMENT; Schema: wms; Owner: -
--

COMMENT ON COLUMN wms.shipping_provider_labels.label_direction IS 'Provider-declared transport direction. unknown and return labels cannot authorize outbound fulfillment.';


