ALTER TABLE dropship.dropship_carrier_claims
    ADD CONSTRAINT dropship_carrier_claim_intake_snapshot_chk CHECK (((wms_shipment_id IS NULL) OR ((intake_id IS NOT NULL) AND (currency IS NOT NULL) AND ((currency)::text ~ '^[A-Z]{3}$'::text) AND (carrier IS NOT NULL) AND (btrim((carrier)::text) <> ''::text) AND (tracking_number IS NOT NULL) AND (btrim((tracking_number)::text) <> ''::text) AND (event_type IS NOT NULL) AND ((event_type)::text = ANY ((ARRAY['loss'::character varying, 'misdelivery'::character varying, 'damage'::character varying])::text[])) AND (policy_id IS NOT NULL) AND (carrier_protection_assignment_id IS NOT NULL) AND (shipping_allocation_id IS NOT NULL) AND (policy_snapshot IS NOT NULL) AND (source_snapshot IS NOT NULL) AND (wholesale_cost_snapshot_cents IS NOT NULL) AND (wholesale_cost_snapshot_cents >= 0) AND (shipping_charge_snapshot_cents IS NOT NULL) AND (shipping_charge_snapshot_cents >= 0) AND (calculated_credit_cents IS NOT NULL) AND (calculated_credit_cents >= 0) AND (occurred_at IS NOT NULL) AND (eligible_at IS NOT NULL) AND (idempotency_key IS NOT NULL) AND (btrim((idempotency_key)::text) <> ''::text) AND (request_hash IS NOT NULL) AND ((request_hash)::text ~ '^[0-9a-f]{64}$'::text) AND (actor_type IS NOT NULL) AND ((actor_type)::text = ANY ((ARRAY['admin'::character varying, 'system'::character varying])::text[])) AND (((actor_type)::text <> 'admin'::text) OR ((actor_id IS NOT NULL) AND (btrim((actor_id)::text) <> ''::text)))))) NOT VALID;


