-- Name: order_items wms_order_items_fully_picked_status_chk; Type: CHECK CONSTRAINT; Schema: wms; Owner: -
--

ALTER TABLE wms.order_items
    ADD CONSTRAINT wms_order_items_fully_picked_status_chk CHECK (((COALESCE(requires_shipping, 0) <> 1) OR (COALESCE(quantity, 0) <= 0) OR (COALESCE(picked_quantity, 0) < COALESCE(quantity, 0)) OR ((COALESCE(status, ''::character varying))::text <> ALL ((ARRAY['pending'::character varying, 'in_progress'::character varying])::text[])))) NOT VALID;


--
-- Name: CONSTRAINT wms_order_items_fully_picked_status_chk ON order_items; Type: COMMENT; Schema: wms; Owner: -
--

COMMENT ON CONSTRAINT wms_order_items_fully_picked_status_chk ON wms.order_items IS 'Prevents fully picked shippable lines from returning to an active picker status.';


