CREATE UNIQUE INDEX uq_wms_order_items_active_order_oms_line ON wms.order_items USING btree (order_id, oms_order_line_id) WHERE ((oms_order_line_id IS NOT NULL) AND ((COALESCE(status, ''::character varying))::text <> ALL ((ARRAY['cancelled'::character varying, 'completed'::character varying, 'short'::character varying])::text[])));


--
-- Name: uq_wms_orders_oms_fulfillment_partition_active; Type: INDEX; Schema: wms; Owner: -
--

CREATE UNIQUE INDEX uq_wms_orders_oms_fulfillment_partition_active ON wms.orders USING btree (source, oms_fulfillment_order_id, COALESCE(warehouse_id, 0), fulfillment_partition_key) WHERE (((source)::text = 'oms'::text) AND ((warehouse_status)::text <> ALL ((ARRAY['cancelled'::character varying, 'voided'::character varying])::text[])) AND (oms_fulfillment_order_id IS NOT NULL));


--
-- Name: uq_wms_outbound_shipment_items_shipment_order_item; Type: INDEX; Schema: wms; Owner: -
--

CREATE UNIQUE INDEX uq_wms_outbound_shipment_items_shipment_order_item ON wms.outbound_shipment_items USING btree (shipment_id, order_item_id) WHERE (order_item_id IS NOT NULL);


--
-- Name: uq_wms_reconciliation_exceptions_open_idem; Type: INDEX; Schema: wms; Owner: -
--

CREATE UNIQUE INDEX uq_wms_reconciliation_exceptions_open_idem ON wms.reconciliation_exceptions USING btree (idempotency_key) WHERE ((status)::text = ANY ((ARRAY['open'::character varying, 'acknowledged'::character varying])::text[]));


